(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-043"]={"sura":43,"name_ar":"الزخرف","name_en":"Az-Zukhruf","verses":89,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":89,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=8\" class=\"link\">43:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:8 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=8\" class=\"link\">43:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:8 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=8\" class=\"link\">43:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:8 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=8\" class=\"link\">43:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:8 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=8\" class=\"link\">43:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:8 ஐ பார்க்கவும்"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=8\" class=\"link\">43:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:8 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=8\" class=\"link\">43:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:8 ஐ பார்க்கவும்"},"8":{"html":"<strong>இது மக்காவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\nஅளவற்ற அருளாளன், நிகரற்ற அன்பாளன் அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾حـم</span> - <span class=\"quran-arabic-font text-success\">وَالْكِتَـبِ</span> <span class=\"quran-arabic-font text-success\">الْمُبِينِ﴿</span><br />\r\n<br />\r\n(ஹா-மீம். தெளிவான இவ்வேதத்தின் மீது சத்தியமாக.) இதன் பொருள், இது சொற்களிலும் கருத்திலும் மிகத்தெளிவானது; ஏனெனில் இது மக்களிடையே உரையாடுவதற்கு மிகச் சிறந்த மொழியான அரபு மொழியில் அருளப்பட்டுள்ளது. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّا</span> <span class=\"quran-arabic-font text-success\">جَعَلْنَـهُ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, நாம் அதனை ஆக்கினோம்) அதாவது, அதனை நாம் அருளினோம்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قُرْءَاناً</span> <span class=\"quran-arabic-font text-success\">عَرَبِيّاً﴿</span><br />\r\n<br />\r\n(அரபு மொழியிலான குர்ஆனாக) அதாவது, அரபு மொழியில் தெளிவானதாகவும் ஆற்றல் மிக்கதாகவும் (அருளினோம்).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْقِلُونَ﴿</span><br />\r\n<br />\r\n(நீங்கள் விளங்கிக் கொள்வதற்காக.) இதன் பொருள், நீங்கள் அதனைப் புரிந்து கொண்டு அதன் கருத்துகளைச் சிந்திப்பதற்காக என்பதாகும். இது பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بِلِسَانٍ</span> <span class=\"quran-arabic-font text-success\">عَرَبِىٍّ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(தெளிவான அரபு மொழியில்.) (<a href=\"qurandisp.php?sura=26&ayah=195\" class=\"link\">26:195</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">أُمِّ</span> <span class=\"quran-arabic-font text-success\">الْكِتَـبِ</span> <span class=\"quran-arabic-font text-success\">لَدَيْنَا</span> <span class=\"quran-arabic-font text-success\">لَعَلِىٌّ</span> <span class=\"quran-arabic-font text-success\">حَكِيمٌ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அது நம்மிடமுள்ள மூல நூலில் இருக்கிறது; அது மிக மேலானது, ஞானம் மிக்கது.) இது வானுலகவாசிகளிடம் (மலக்குகளிடம்) குர்ஆனுக்கு இருக்கும் உயர்ந்த அந்தஸ்தை விளக்குகிறது. அதன் மூலம் பூமியில் உள்ள மக்கள் அதனை மதித்து, கண்ணியப்படுத்தி, அதற்குக் கீழ்ப்படிய வேண்டும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِنَّهُ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அது) என்பது குர்ஆனைக் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فِى</span> <span class=\"quran-arabic-font text-success\">أُمِّ</span> <span class=\"quran-arabic-font text-success\">الْكِتَـبِ﴿</span><br />\r\n<br />\r\n(மூல நூலில் இருக்கிறது) அதாவது, அல்-லவ்ஹுல் மஹ்ஃபூள் (பாதுகாக்கப்பட்ட ஏடு) என்பதாகும். இது இப்னு அப்பாஸ் (ரழி) மற்றும் முஜாஹித் ஆகியோரின் கருத்தாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لَدَيْنَا﴿</span><br />\r\n<br />\r\n(நம்மிடத்தில்) என்பது நமது முன்னிலையில் என்று பொருள்படும். இது கத்தாதா மற்றும் பலரின் கருத்தாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لَعَلِىٌّ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக மிக மேலானது) என்பது கண்ணியமும் சிறப்பும் மிக்க அந்தஸ்தைக் குறிக்கிறது. இது கத்தாதா அவர்களின் கருத்தாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾حَكِيمٌ﴿</span><br />\r\n<br />\r\n(ஞானம் மிக்கது) என்றால் எவ்விதக் குழப்பமும் முரண்பாடும் இன்றித் தெளிவாக இருக்கிறது என்று பொருள். இவை யாவும் குர்ஆனின் கண்ணியமான நிலையையும் சிறப்பையும் உணர்த்துகின்றன. அல்லாஹ் வேறோர் இடத்தில் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَقُرْءَانٌ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٌ</span> - <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كِتَـبٍ</span> <span class=\"quran-arabic-font text-success\">مَّكْنُونٍ</span> - <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَمَسُّهُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الْمُطَهَّرُونَ</span> - <span class=\"quran-arabic-font text-success\">تَنزِيلٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّ</span> <span class=\"quran-arabic-font text-success\">الْعَـلَمِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக இது கண்ணியமிக்க குர்ஆன் ஆகும். இது ஒரு பாதுகாக்கப்பட்ட ஏட்டில் உள்ளது. தூய்மையானவர்களைத் தவிர வேறு யாரும் இதனைத் தொடமாட்டார்கள். இது அகிலங்களின் இறைவனிடமிருந்து அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும்.) (<a href=\"qurandisp.php?sura=56&ayah=77\" class=\"link\">56:77</a>-80)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾كَلاَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّهَا</span> <span class=\"quran-arabic-font text-success\">تَذْكِرَةٌ</span> <span class=\"quran-arabic-font text-success\">فَمَن</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">ذَكَرَهُ</span> <span class=\"quran-arabic-font text-success\">فَى</span> <span class=\"quran-arabic-font text-success\">صُحُفٍ</span> <span class=\"quran-arabic-font text-success\">مُّكَرَّمَةٍ</span> <span class=\"quran-arabic-font text-success\">مَّرْفُوعَةٍ</span> <span class=\"quran-arabic-font text-success\">مُّطَهَّرَةٍ</span> <span class=\"quran-arabic-font text-success\">بِأَيْدِى</span> <span class=\"quran-arabic-font text-success\">سَفَرَةٍ</span> <span class=\"quran-arabic-font text-success\">كِرَامٍ</span> <span class=\"quran-arabic-font text-success\">بَرَرَةٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அப்படியல்ல, நிச்சயமாக இது ஒரு நினைவூட்டலாகும். எனவே, விரும்புவோர் இதனை நினைவில் கொள்ளட்டும். இது கண்ணியப்படுத்தப்பட்ட, மிக உயர்ந்த, தூய்மையான ஏடுகளில் உள்ளது. இவை கண்ணியமும் நற்பண்பும் கொண்ட எழுத்தர்களின் (வானவர்களின்) கரங்களால் எழுதப்பட்டவை.) (<a href=\"qurandisp.php?sura=80&ayah=11\" class=\"link\">80:11</a>-16)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَفَنَضْرِبُ</span> <span class=\"quran-arabic-font text-success\">عَنكُمُ</span> <span class=\"quran-arabic-font text-success\">الذِّكْرَ</span> <span class=\"quran-arabic-font text-success\">صَفْحاً</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْماً</span> <span class=\"quran-arabic-font text-success\">مُّسْرِفِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நீங்கள் வரம்பு மீறிய மக்களாக இருப்பதற்காக, இந்த நினைவூட்டலை (குர்ஆனை) உங்களிடமிருந்து நாம் அப்புறப்படுத்தி விடுவோமா?) அதாவது, \"உங்களுக்குக் கட்டளையிடப்பட்டதை நீங்கள் செய்யாதபோது, உங்களைத் தண்டிக்காமல் மன்னித்து விட்டுவிடுவோம் என்று நினைக்கிறீர்களா?\" என்று அல்லாஹ் கேட்கிறான். இது இப்னு அப்பாஸ் (ரழி), அபூ ஸாலிஹ், முஜாஹித் மற்றும் அஸ்-ஸுத்தி ஆகியோரின் கருத்தாகும். இப்னு ஜரீர் அவர்களும் இதனையே விரும்பத்தக்க கருத்தாகக் கொண்டுள்ளார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَفَنَضْرِبُ</span> <span class=\"quran-arabic-font text-success\">عَنكُمُ</span> <span class=\"quran-arabic-font text-success\">الذِّكْرَ</span> <span class=\"quran-arabic-font text-success\">صَفْحاً﴿</span><br />\r\n<br />\r\n(இந்த நினைவூட்டலை (குர்ஆனை) உங்களிடமிருந்து நாம் அப்புறப்படுத்தி விடுவோமா?) கத்தாதா அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் மீது சத்தியமாக, இந்த உம்மத்தின் முன்னோர்கள் அதனை நிராகரித்தபோது குர்ஆன் அப்புறப்படுத்தப்பட்டிருந்தால் அவர்கள் அழிந்து போயிருப்பார்கள். ஆனால் அல்லாஹ் தனது பெருங்கருணையால் அதனைத் தொடர்ந்து அனுப்பி, இருபது ஆண்டுகளுக்கும் மேலாக அல்லது அவன் நாடிய காலம் வரை அவர்களை அதன் பக்கம் அழைத்தான்.\" கத்தாதா அவர்கள் கூறியது மிகச் சரியானது. படைப்புகளின் மீது அல்லாஹ் கொண்டுள்ள கிருபையினாலும் கருணையினாலும், அவர்கள் அதைப் புறக்கணித்து அலட்சியமாக இருந்தபோதிலும், அவர்களைச் சத்தியத்தின் பக்கமும் ஞானமிக்க நினைவூட்டலான குர்ஆனின் பக்கமும் அழைப்பதை அவன் நிறுத்தவில்லை என்பதே அவரது கருத்தின் சாரமாகும். நிச்சயமாக, நேர்வழி பெற வேண்டும் என்று யாருக்கு விதிக்கப்பட்டதோ அவர்கள் இதன் மூலம் நேர்வழி பெறுவதற்காகவும், மற்றவர்களுக்கு எதிராக ஆதாரத்தை நிலைநாட்டுவதற்காகவுமே அல்லாஹ் இதனை அருளினான்.<br />\r\n<br />\r\n<strong>குறைஷிகளின் நிராகரிப்பிற்காக நபிக்கு ஆறுதல்</strong><br />\r\n<br />\r\nபிறகு, மக்களின் நிராகரிப்பினால் கவலையுற்றிருந்த தனது நபியை (ஸல்) அல்லாஹ் தேற்றி, அதனைப் பொறுமையுடன் சகித்துக் கொள்ளுமாறு அவர்களுக்குக் கட்டளையிடுகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَكَمْ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">نَّبِيٍّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْأَوَّلِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(முன்னோர்களிடையே எத்தனையோ நபிமார்களை நாம் அனுப்பி வைத்துள்ளோம்.) அதாவது, முந்தைய சமுதாயங்களிடையே (அனுப்பியுள்ளோம்).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">يَأْتِيهِم</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">نَّبِىٍّ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">يَسْتَهْزِءُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்களிடம் வந்த எந்த ஒரு நபியையும் அவர்கள் ஏளனம் செய்யாமல் இருந்ததில்லை.) அதாவது, அவர்கள் அந்த நபிமார்களைப் பொய்ப்பித்து அவர்களைப் பரிகசித்தனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَأَهْلَكْنَآ</span> <span class=\"quran-arabic-font text-success\">أَشَدَّ</span> <span class=\"quran-arabic-font text-success\">مِنْهُم</span> <span class=\"quran-arabic-font text-success\">بَطْشاً﴿</span><br />\r\n<br />\r\n(பிறகு, இவர்களை விடவும் பெரும் வலிமை மிக்கவர்களை நாம் அழித்தோம்.) இதன் பொருள்: \"முஹம்மதே (ஸல்)! உம்மை நிராகரிக்கும் இவர்களை விடவும் உடல் வலிமையிலும் அதிகாரத்திலும் விஞ்சியிருந்த தூதர்களை நிராகரித்த அந்த முன்னோர்களை நாம் அழித்தோம்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَفَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَسِيرُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">فَيَنظُرُواْ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَاقِبَةُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِمْ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَشَدَّ</span> <span class=\"quran-arabic-font text-success\">قُوَّةً﴿</span><br />\r\n<br />\r\n(இவர்கள் பூமியில் பிரயாணம் செய்து தங்களுக்கு முன்னிருந்தவர்களின் முடிவு என்னவாயிற்று என்பதைப் பார்க்கவில்லையா? அவர்கள் இவர்களை விட எண்ணிக்கையில் அதிகமாகவும், வலிமையில் மிகைத்தவர்களாகவும் இருந்தார்கள்) (<a href=\"qurandisp.php?sura=40&ayah=82\" class=\"link\">40:82</a>). இது போன்று குர்ஆனில் பல வசனங்கள் உள்ளன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَضَى</span> <span class=\"quran-arabic-font text-success\">مَثَلُ</span> <span class=\"quran-arabic-font text-success\">الْأَوَّلِينَ﴿</span><br />\r\n<br />\r\n(மேலும் முன்னோர்களின் உதாரணம் கடந்துவிட்டது.) முஜாஹித் அவர்கள், \"அவர்களின் வாழ்க்கை முறை\" என்றும், கத்தாதா அவர்கள், \"அவர்களின் தண்டனை\" என்றும் கூறினார்கள். மற்றவர்கள், \"அவர்களின் பாடம்\" என்று கூறினார்கள். அதாவது, \"அவர்களுக்குப் பின் வந்த நிராகரிப்பாளர்களுக்கும் அதே கதிதான் ஏற்படும் என்பதற்கு அவர்களை ஒரு படிப்பினையாக ஆக்கினோம்\" என்பதாகும். இந்தச் சூராவின் இறுதியில் வரும் வசனத்தில் கூறப்பட்டிருப்பது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَجَعَلْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">سَلَفاً</span> <span class=\"quran-arabic-font text-success\">وَمَثَلاً</span> <span class=\"quran-arabic-font text-success\">لِّلاٌّخِرِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் நாம் அவர்களை ஒரு முன்மாதிரியாகவும், பிற்கால சந்ததியினருக்கு ஒரு உதாரணமாகவும் ஆக்கினோம்.) (<a href=\"qurandisp.php?sura=43&ayah=56\" class=\"link\">43:56</a>);<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾سُنَّةَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">خَلَتْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">عِبَادِهِ﴿</span><br />\r\n<br />\r\n(இதுவே அல்லாஹ்வின் அடியார்களிடம் அவன் கடைபிடிக்கும் வழியாகும்.) (<a href=\"qurandisp.php?sura=40&ayah=85\" class=\"link\">40:85</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَن</span> <span class=\"quran-arabic-font text-success\">تَجِدَ</span> <span class=\"quran-arabic-font text-success\">لِسُنَّةِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">تَبْدِيلاً﴿</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ்வின் அந்த வழியில் நீர் எவ்வித மாற்றத்தையும் காணமாட்டீர்.) (<a href=\"qurandisp.php?sura=33&ayah=62\" class=\"link\">33:62</a>)<br />\r\n<br />","text":"இது மக்காவில் அருளப்பட்டது\n\r\n\n\r\n﴾بِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ ﴿\n\r\n\n\r\nஅளவற்ற அருளாளன், நிகரற்ற அன்பாளன் அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\n﴾حـم - وَالْكِتَـبِ الْمُبِينِ﴿\n\r\n\n\r\n(ஹா-மீம். தெளிவான இவ்வேதத்தின் மீது சத்தியமாக.) இதன் பொருள், இது சொற்களிலும் கருத்திலும் மிகத்தெளிவானது; ஏனெனில் இது மக்களிடையே உரையாடுவதற்கு மிகச் சிறந்த மொழியான அரபு மொழியில் அருளப்பட்டுள்ளது. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾إِنَّا جَعَلْنَـهُ﴿\n\r\n\n\r\n(நிச்சயமாக, நாம் அதனை ஆக்கினோம்) அதாவது, அதனை நாம் அருளினோம்.\n\r\n\n\r\n﴾قُرْءَاناً عَرَبِيّاً﴿\n\r\n\n\r\n(அரபு மொழியிலான குர்ஆனாக) அதாவது, அரபு மொழியில் தெளிவானதாகவும் ஆற்றல் மிக்கதாகவும் (அருளினோம்).\n\r\n\n\r\n﴾لَعَلَّكُمْ تَعْقِلُونَ﴿\n\r\n\n\r\n(நீங்கள் விளங்கிக் கொள்வதற்காக.) இதன் பொருள், நீங்கள் அதனைப் புரிந்து கொண்டு அதன் கருத்துகளைச் சிந்திப்பதற்காக என்பதாகும். இது பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\n﴾بِلِسَانٍ عَرَبِىٍّ مُّبِينٍ ﴿\n\r\n\n\r\n(தெளிவான அரபு மொழியில்.) (26:195)\n\r\n\n\r\n﴾وَإِنَّهُ فِى أُمِّ الْكِتَـبِ لَدَيْنَا لَعَلِىٌّ حَكِيمٌ ﴿\n\r\n\n\r\n(நிச்சயமாக அது நம்மிடமுள்ள மூல நூலில் இருக்கிறது; அது மிக மேலானது, ஞானம் மிக்கது.) இது வானுலகவாசிகளிடம் (மலக்குகளிடம்) குர்ஆனுக்கு இருக்கும் உயர்ந்த அந்தஸ்தை விளக்குகிறது. அதன் மூலம் பூமியில் உள்ள மக்கள் அதனை மதித்து, கண்ணியப்படுத்தி, அதற்குக் கீழ்ப்படிய வேண்டும்.\n\r\n\n\r\n﴾وَإِنَّهُ﴿\n\r\n\n\r\n(நிச்சயமாக அது) என்பது குர்ஆனைக் குறிக்கிறது.\n\r\n\n\r\n﴾فِى أُمِّ الْكِتَـبِ﴿\n\r\n\n\r\n(மூல நூலில் இருக்கிறது) அதாவது, அல்-லவ்ஹுல் மஹ்ஃபூள் (பாதுகாக்கப்பட்ட ஏடு) என்பதாகும். இது இப்னு அப்பாஸ் (ரழி) மற்றும் முஜாஹித் ஆகியோரின் கருத்தாகும்.\n\r\n\n\r\n﴾لَدَيْنَا﴿\n\r\n\n\r\n(நம்மிடத்தில்) என்பது நமது முன்னிலையில் என்று பொருள்படும். இது கத்தாதா மற்றும் பலரின் கருத்தாகும்.\n\r\n\n\r\n﴾لَعَلِىٌّ﴿\n\r\n\n\r\n(நிச்சயமாக மிக மேலானது) என்பது கண்ணியமும் சிறப்பும் மிக்க அந்தஸ்தைக் குறிக்கிறது. இது கத்தாதா அவர்களின் கருத்தாகும்.\n\r\n\n\r\n﴾حَكِيمٌ﴿\n\r\n\n\r\n(ஞானம் மிக்கது) என்றால் எவ்விதக் குழப்பமும் முரண்பாடும் இன்றித் தெளிவாக இருக்கிறது என்று பொருள். இவை யாவும் குர்ஆனின் கண்ணியமான நிலையையும் சிறப்பையும் உணர்த்துகின்றன. அல்லாஹ் வேறோர் இடத்தில் கூறுவது போல:\n\r\n\n\r\n﴾إِنَّهُ لَقُرْءَانٌ كَرِيمٌ - فِى كِتَـبٍ مَّكْنُونٍ - لاَّ يَمَسُّهُ إِلاَّ الْمُطَهَّرُونَ - تَنزِيلٌ مِّن رَّبِّ الْعَـلَمِينَ ﴿\n\r\n\n\r\n(நிச்சயமாக இது கண்ணியமிக்க குர்ஆன் ஆகும். இது ஒரு பாதுகாக்கப்பட்ட ஏட்டில் உள்ளது. தூய்மையானவர்களைத் தவிர வேறு யாரும் இதனைத் தொடமாட்டார்கள். இது அகிலங்களின் இறைவனிடமிருந்து அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும்.) (56:77-80)\n\r\n\n\r\n﴾كَلاَّ إِنَّهَا تَذْكِرَةٌ فَمَن شَآءَ ذَكَرَهُ فَى صُحُفٍ مُّكَرَّمَةٍ مَّرْفُوعَةٍ مُّطَهَّرَةٍ بِأَيْدِى سَفَرَةٍ كِرَامٍ بَرَرَةٍ ﴿\n\r\n\n\r\n(அப்படியல்ல, நிச்சயமாக இது ஒரு நினைவூட்டலாகும். எனவே, விரும்புவோர் இதனை நினைவில் கொள்ளட்டும். இது கண்ணியப்படுத்தப்பட்ட, மிக உயர்ந்த, தூய்மையான ஏடுகளில் உள்ளது. இவை கண்ணியமும் நற்பண்பும் கொண்ட எழுத்தர்களின் (வானவர்களின்) கரங்களால் எழுதப்பட்டவை.) (80:11-16)\n\r\n\n\r\n﴾أَفَنَضْرِبُ عَنكُمُ الذِّكْرَ صَفْحاً أَن كُنتُمْ قَوْماً مُّسْرِفِينَ ﴿\n\r\n\n\r\n(நீங்கள் வரம்பு மீறிய மக்களாக இருப்பதற்காக, இந்த நினைவூட்டலை (குர்ஆனை) உங்களிடமிருந்து நாம் அப்புறப்படுத்தி விடுவோமா?) அதாவது, \"உங்களுக்குக் கட்டளையிடப்பட்டதை நீங்கள் செய்யாதபோது, உங்களைத் தண்டிக்காமல் மன்னித்து விட்டுவிடுவோம் என்று நினைக்கிறீர்களா?\" என்று அல்லாஹ் கேட்கிறான். இது இப்னு அப்பாஸ் (ரழி), அபூ ஸாலிஹ், முஜாஹித் மற்றும் அஸ்-ஸுத்தி ஆகியோரின் கருத்தாகும். இப்னு ஜரீர் அவர்களும் இதனையே விரும்பத்தக்க கருத்தாகக் கொண்டுள்ளார்.\n\r\n\n\r\n﴾أَفَنَضْرِبُ عَنكُمُ الذِّكْرَ صَفْحاً﴿\n\r\n\n\r\n(இந்த நினைவூட்டலை (குர்ஆனை) உங்களிடமிருந்து நாம் அப்புறப்படுத்தி விடுவோமா?) கத்தாதா அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் மீது சத்தியமாக, இந்த உம்மத்தின் முன்னோர்கள் அதனை நிராகரித்தபோது குர்ஆன் அப்புறப்படுத்தப்பட்டிருந்தால் அவர்கள் அழிந்து போயிருப்பார்கள். ஆனால் அல்லாஹ் தனது பெருங்கருணையால் அதனைத் தொடர்ந்து அனுப்பி, இருபது ஆண்டுகளுக்கும் மேலாக அல்லது அவன் நாடிய காலம் வரை அவர்களை அதன் பக்கம் அழைத்தான்.\" கத்தாதா அவர்கள் கூறியது மிகச் சரியானது. படைப்புகளின் மீது அல்லாஹ் கொண்டுள்ள கிருபையினாலும் கருணையினாலும், அவர்கள் அதைப் புறக்கணித்து அலட்சியமாக இருந்தபோதிலும், அவர்களைச் சத்தியத்தின் பக்கமும் ஞானமிக்க நினைவூட்டலான குர்ஆனின் பக்கமும் அழைப்பதை அவன் நிறுத்தவில்லை என்பதே அவரது கருத்தின் சாரமாகும். நிச்சயமாக, நேர்வழி பெற வேண்டும் என்று யாருக்கு விதிக்கப்பட்டதோ அவர்கள் இதன் மூலம் நேர்வழி பெறுவதற்காகவும், மற்றவர்களுக்கு எதிராக ஆதாரத்தை நிலைநாட்டுவதற்காகவுமே அல்லாஹ் இதனை அருளினான்.\n\r\n\n\r\nகுறைஷிகளின் நிராகரிப்பிற்காக நபிக்கு ஆறுதல்\n\r\n\n\r\nபிறகு, மக்களின் நிராகரிப்பினால் கவலையுற்றிருந்த தனது நபியை (ஸல்) அல்லாஹ் தேற்றி, அதனைப் பொறுமையுடன் சகித்துக் கொள்ளுமாறு அவர்களுக்குக் கட்டளையிடுகிறான்.\n\r\n\n\r\n﴾وَكَمْ أَرْسَلْنَا مِن نَّبِيٍّ فِى الْأَوَّلِينَ ﴿\n\r\n\n\r\n(முன்னோர்களிடையே எத்தனையோ நபிமார்களை நாம் அனுப்பி வைத்துள்ளோம்.) அதாவது, முந்தைய சமுதாயங்களிடையே (அனுப்பியுள்ளோம்).\n\r\n\n\r\n﴾وَمَا يَأْتِيهِم مِّنْ نَّبِىٍّ إِلاَّ كَانُواْ بِهِ يَسْتَهْزِءُونَ ﴿\n\r\n\n\r\n(அவர்களிடம் வந்த எந்த ஒரு நபியையும் அவர்கள் ஏளனம் செய்யாமல் இருந்ததில்லை.) அதாவது, அவர்கள் அந்த நபிமார்களைப் பொய்ப்பித்து அவர்களைப் பரிகசித்தனர்.\n\r\n\n\r\n﴾فَأَهْلَكْنَآ أَشَدَّ مِنْهُم بَطْشاً﴿\n\r\n\n\r\n(பிறகு, இவர்களை விடவும் பெரும் வலிமை மிக்கவர்களை நாம் அழித்தோம்.) இதன் பொருள்: \"முஹம்மதே (ஸல்)! உம்மை நிராகரிக்கும் இவர்களை விடவும் உடல் வலிமையிலும் அதிகாரத்திலும் விஞ்சியிருந்த தூதர்களை நிராகரித்த அந்த முன்னோர்களை நாம் அழித்தோம்.\"\n\r\n\n\r\n﴾أَفَلَمْ يَسِيرُواْ فِى الْأَرْضِ فَيَنظُرُواْ كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِن قَبْلِهِمْ كَانُواْ أَكْثَرَ مِنْهُمْ وَأَشَدَّ قُوَّةً﴿\n\r\n\n\r\n(இவர்கள் பூமியில் பிரயாணம் செய்து தங்களுக்கு முன்னிருந்தவர்களின் முடிவு என்னவாயிற்று என்பதைப் பார்க்கவில்லையா? அவர்கள் இவர்களை விட எண்ணிக்கையில் அதிகமாகவும், வலிமையில் மிகைத்தவர்களாகவும் இருந்தார்கள்) (40:82). இது போன்று குர்ஆனில் பல வசனங்கள் உள்ளன.\n\r\n\n\r\n﴾وَمَضَى مَثَلُ الْأَوَّلِينَ﴿\n\r\n\n\r\n(மேலும் முன்னோர்களின் உதாரணம் கடந்துவிட்டது.) முஜாஹித் அவர்கள், \"அவர்களின் வாழ்க்கை முறை\" என்றும், கத்தாதா அவர்கள், \"அவர்களின் தண்டனை\" என்றும் கூறினார்கள். மற்றவர்கள், \"அவர்களின் பாடம்\" என்று கூறினார்கள். அதாவது, \"அவர்களுக்குப் பின் வந்த நிராகரிப்பாளர்களுக்கும் அதே கதிதான் ஏற்படும் என்பதற்கு அவர்களை ஒரு படிப்பினையாக ஆக்கினோம்\" என்பதாகும். இந்தச் சூராவின் இறுதியில் வரும் வசனத்தில் கூறப்பட்டிருப்பது போல:\n\r\n\n\r\n﴾فَجَعَلْنَـهُمْ سَلَفاً وَمَثَلاً لِّلاٌّخِرِينَ ﴿\n\r\n\n\r\n(மேலும் நாம் அவர்களை ஒரு முன்மாதிரியாகவும், பிற்கால சந்ததியினருக்கு ஒரு உதாரணமாகவும் ஆக்கினோம்.) (43:56);\n\r\n\n\r\n﴾سُنَّةَ اللَّهِ الَّتِى قَدْ خَلَتْ فِى عِبَادِهِ﴿\n\r\n\n\r\n(இதுவே அல்லாஹ்வின் அடியார்களிடம் அவன் கடைபிடிக்கும் வழியாகும்.) (40:85).\n\r\n\n\r\n﴾وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلاً﴿\n\r\n\n\r\n(மேலும் அல்லாஹ்வின் அந்த வழியில் நீர் எவ்வித மாற்றத்தையும் காணமாட்டீர்.) (33:62)"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=14\" class=\"link\">43:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:14 ஐ பார்க்கவும்"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=14\" class=\"link\">43:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:14 ஐ பார்க்கவும்"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=14\" class=\"link\">43:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:14 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=14\" class=\"link\">43:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:14 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=14\" class=\"link\">43:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:14 ஐ பார்க்கவும்"},"14":{"html":"<strong>அல்லாஹ்வே படைப்பாளன் என இணைவைப்பாளர்கள் ஒப்புக்கொள்ளுதலும், அதற்கான மேலதிகச் சான்றுகளும்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: \"முஹம்மதே (ஸல்)! அல்லாஹ்வுக்கு இணையாகப் பிறரை வணங்கும் இந்த இணைவைப்பாளர்களிடம் நீர், <span class=\"quran-arabic-font text-success\">﴾مَّنْ</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">لَيَقُولُنَّ</span> <span class=\"quran-arabic-font text-success\">خَلَقَهُنَّ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيمُ﴿</span><br />\r\n<br />\r\n('வானங்களையும் பூமியையும் படைத்தவன் யார்?' என்று) கேட்டால், 'யாவற்றையும் மிகைத்தவனும், அனைத்தையும் அறிந்தவனுமாகிய அல்லாஹ்வே அவற்றைப் படைத்தான்' என்று அவர்கள் நிச்சயமாகக் கூறுவார்கள்.\" அதாவது, அனைத்தையும் படைத்தவன் அல்லாஹ் ஒருவனே என்பதையும், அவனுக்குப் பங்காளிகளோ துணையோ இல்லை என்பதையும் அவர்கள் ஒப்புக்கொள்கிறார்கள். இருப்பினும், அவர்கள் அவனுடன் சிலைகளையும் பொய்யான தெய்வங்களையும் வணங்குகிறார்கள். <span class=\"quran-arabic-font text-success\">﴾الَّذِى</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">مَهْداً﴿</span><br />\r\n<br />\r\n(அவனே பூமியை உங்களுக்கு ஒரு விரிப்பாகவும், தொட்டிலாகவும் ஆக்கினான்,) அதாவது, நீங்கள் அதில் பயணம் செய்யவும், அதன் மீது நிற்கவும், உறங்கவும், நடக்கவும் ஏதுவாக அதனை மென்மையாகவும், நிலையானதாகவும், உறுதியானதாகவும் அவன் ஆக்கினான். அது தண்ணீருக்கு மேல் படைக்கப்பட்டிருந்தாலும், அது அசையாமல் இருப்பதற்காக மலைகளைக் கொண்டு அவன் அதனைப் பலப்படுத்தினான். <span class=\"quran-arabic-font text-success\">﴾وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">سُبُلاً﴿</span><br />\r\n<br />\r\n(அதில் உங்களுக்குப் பாதைகளையும் ஆக்கினான்,) அதாவது மலைகளுக்கும் பள்ளத்தாக்குகளுக்கும் இடையே உள்ள பாதைகள். <span class=\"quran-arabic-font text-success\">﴾لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تَهْتَدُونَ﴿</span><br />\r\n<br />\r\n(நீங்கள் வழியறிந்து செல்வதற்காக.) அதாவது ஒரு நகரத்திலிருந்து மற்றொரு நகரத்திற்கும், ஒரு பகுதியிலிருந்து மற்றொரு பகுதிக்கும், ஒரு நாட்டிலிருந்து மற்றொரு நாட்டிற்கும் நீங்கள் மேற்கொள்ளும் பயணங்களில் வழியறிந்து செல்வதற்காக. <span class=\"quran-arabic-font text-success\">﴾وَالَّذِى</span> <span class=\"quran-arabic-font text-success\">نَزَّلَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ</span> <span class=\"quran-arabic-font text-success\">مَآءً</span> <span class=\"quran-arabic-font text-success\">بِقَدَرٍ﴿</span><br />\r\n<br />\r\n(அவனே வானத்திலிருந்து குறிப்பிட்ட அளவுப்படி மழையை இறக்கினான்,) அதாவது உங்கள் பயிர்களுக்கும், கனிகளுக்கும், உங்களுக்கும் உங்கள் கால்நடைகளுக்கும் தேவையான குடிநீருக்கு ஏற்ப (அளவாக இறக்கினான்). <span class=\"quran-arabic-font text-success\">﴾فَأَنشَرْنَا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">بَلْدَةً</span> <span class=\"quran-arabic-font text-success\">مَّيْتاً﴿</span><br />\r\n<br />\r\n(பின்னர், அதைக் கொண்டு வறண்ட நிலத்தை நாம் உயிர்ப்பிக்கிறோம்,) அதாவது தரிசு நிலம்; அதன் மீது நீர் விழும்போது அது உயிர் பெற்று செழிப்படைகிறது, மேலும் அது அனைத்து வகையான அழகான தாவரங்களையும் வெளிப்படுத்துகிறது. பூமியை உயிர்ப்பிப்பதைப் பற்றிக் குறிப்பிடுவதன் மூலம், மனிதர்கள் மரணித்த பிறகு மறுமை நாளில் அவர்களது உடல்களை அல்லாஹ் எவ்வாறு மீண்டும் உயிர்ப்பிப்பான் என்பதை அவன் சுட்டிக்காட்டுகிறான். <span class=\"quran-arabic-font text-success\">﴾كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">تُخْرَجُونَ﴿</span><br />\r\n<br />\r\n(இவ்வாறே நீங்களும் மறுமையில் வெளிப்படுத்தப்படுவீர்கள்.) பின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَالَّذِى</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">الْأَزْوَاجَ</span> <span class=\"quran-arabic-font text-success\">كُلَّهَا﴿</span><br />\r\n<br />\r\n(அவனே ஜோடிகள் அனைத்தையும் படைத்தான்) அதாவது பூமியில் வளரக்கூடிய அனைத்து வகையான தாவரங்கள், பயிர்கள், கனிகள், மலர்கள் மற்றும் அனைத்து வகையான விலங்குகளிலும் ஜோடிகளைப் படைத்தான். <span class=\"quran-arabic-font text-success\">﴾وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْفُلْكِ﴿</span><br />\r\n<br />\r\n(மேலும் உங்களுக்காகக் கப்பல்களையும் ஆக்கினான்) அல்லது நீர்வழிப் போக்குவரத்து சாதனங்களை, <span class=\"quran-arabic-font text-success\">﴾وَالْأَنْعَامِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَرْكَبُونَ﴿</span><br />\r\n<br />\r\n(நீங்கள் சவாரி செய்யும் கால்நடைகளையும் ஆக்கினான்.) அதாவது அவற்றை அவன் உங்களுக்கு வசப்படுத்திக் கொடுத்து, அவற்றின் இறைச்சியை உண்ணவும், அதன் பாலைப் பருகவும், அவற்றின் முதுகில் சவாரி செய்யவும் உங்களுக்கு எளிதாக்கினான். அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾لِتَسْتَوُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ظُهُورِهِ﴿</span><br />\r\n<br />\r\n(அவற்றின் முதுகுகளின் மீது நீங்கள் அமர்வதற்காக,) அதாவது வசதியாகவும் பாதுகாப்பாகவும் அமர்வதற்கு, <span class=\"quran-arabic-font text-success\">﴾عَلَى</span> <span class=\"quran-arabic-font text-success\">ظُهُورِهِ﴿</span><br />\r\n<br />\r\n(அவற்றின் முதுகுகளின் மீது) அதாவது இத்தகைய விலங்குகளின் முதுகுகளின் மீது. <span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">تَذْكُرُواْ</span> <span class=\"quran-arabic-font text-success\">نِعْمَةَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكُمْ﴿</span><br />\r\n<br />\r\n(பின்னர் உங்கள் இறைவனின் அருட்கொடையை நீங்கள் நினைவுகூர வேண்டும்) அதாவது இந்த விலங்குகள் உங்களுக்கு வசப்படுத்திக் கொடுக்கப்பட்டதன் மூலம் கிடைத்த அருட்கொடையை. <span class=\"quran-arabic-font text-success\">﴾إِذَا</span> <span class=\"quran-arabic-font text-success\">اسْتَوَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">وَتَقُولُواْ</span> <span class=\"quran-arabic-font text-success\">سُبْحَانَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">سَخَّرَ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مُقْرِنِينَ﴿</span><br />\r\n<br />\r\n(நீங்கள் அவற்றின் மீது அமர்ந்ததும், \"எங்களுக்கு இதனை வசப்படுத்தித் தந்தவன் தூய்மையானவன்; இதற்குச் சக்தி பெற்றவர்களாக நாங்கள் இருக்கவில்லை\" என்று கூற வேண்டும்.) அதாவது, அல்லாஹ் இவற்றை நமக்கு வசப்படுத்திக் கொடுத்திருக்காவிட்டால், நமது சொந்த வலிமையால் இதனைச் செய்திருக்க முடியாது. இப்னு அப்பாஸ் (ரழி), கதாதா (ரஹ்), அஸ்-ஸுத்தி (ரஹ்) மற்றும் இப்னு ஸைத் (ரஹ்) ஆகியோர் கூறினார்கள்: \"இதை நாங்களாகவே செய்திருக்க முடியாது.\" <span class=\"quran-arabic-font text-success\">﴾وَإِنَّآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّنَا</span> <span class=\"quran-arabic-font text-success\">لَمُنقَلِبُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும், நிச்சயமாக நாம் நம்முடைய இறைவனிடமே திரும்பிச் செல்பவர்கள்.) அதாவது, 'மரணத்திற்குப் பிறகு நாம் அவனிடமே திரும்புவோம், நமது இறுதி இலக்கும் அவனிடமே உள்ளது.' இந்த வசனத்தில், உலகப் பயணங்களைப் பற்றிய குறிப்பு, மறுமைப் பயணத்தின் மீது கவனத்தை ஈர்க்கிறது. உலகத் தேவைகளுக்கான தயாரிப்பு, மறுமைக்கான தயாரிப்பின் முக்கியத்துவத்தை உணர்த்துவது போல - அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَتَزَوَّدُواْ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">خَيْرَ</span> <span class=\"quran-arabic-font text-success\">الزَّادِ</span> <span class=\"quran-arabic-font text-success\">التَّقْوَى﴿</span><br />\r\n<br />\r\n(பயணத்திற்காகத் தேவையானவற்றைத் தயார் செய்து கொள்ளுங்கள்; நிச்சயமாகத் தயாரிப்புகளில் மிகச் சிறந்தது தக்வா இறையச்சம் ஆகும்) (<a href=\"qurandisp.php?sura=2&ayah=197\" class=\"link\">2:197</a>). மேலும் உலக ஆடைகளைப் பற்றிய குறிப்பு, மறுமையின் ஆடையின் பக்கம் கவனத்தை ஈர்க்கப் பயன்படுகிறது: <span class=\"quran-arabic-font text-success\">﴾وَرِيشًا</span> <span class=\"quran-arabic-font text-success\">وَلِبَاسُ</span> <span class=\"quran-arabic-font text-success\">التَّقْوَى</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ﴿</span><br />\r\n<br />\r\n(அலங்காரமாகவும்; ஆனால் தக்வா எனும் ஆடையே மிகவும் மேலானது) (<a href=\"qurandisp.php?sura=7&ayah=26\" class=\"link\">7:26</a>).<br />\r\n<br />\r\nஇமாம் அஹ்மத் (ரஹ்) அவர்கள் அறிவிக்கிறார்கள்: அலி பின் ரபீஆ (ரஹ்) அவர்கள் கூறினார்கள்: அலி (ரழி) அவர்களிடம் சவாரி செய்வதற்காக ஒரு மிருகம் கொண்டு வரப்பட்டது. அவர்கள் தமது காலை அங்கவடியில் வைத்தபோது \"பிஸ்மில்லாஹ்\" (அல்லாஹ்வின் பெயரால்) என்று கூறினார்கள். அதன் மீது ஏறி அமர்ந்ததும், \"அல்ஹம்துலில்லாஹ்\" (புகழ் அனைத்தும் அல்லாஹ்வுக்கே) என்று கூறினார்கள். பிறகு, \"சுப்ஹானல்லதீ சக்கரா லனா ஹாதா வமா குன்னா லஹு முக்ரினீன்\" என்று ஓதினார்கள். பிறகு, மும்முறை \"அல்ஹம்துலில்லாஹ்\" என்றும், மும்முறை \"அல்லாஹு அக்பர்\" என்றும் கூறினார்கள். பிறகு, \"சுப்ஹானக இன்னீ ழலம்ன்து நஃப்ஸீ ஃபக்ஃபிர்லீ ஃபஇன்னஹு லாயக்ஃபிருத் துனூப இல்லா அன்த்த\" (நீ தூயவன்; நிச்சயமாக நான் எனக்கே அநீதி இழைத்துக் கொண்டேன். எனவே, என்னை மன்னித்தருள்வாயாக! நிச்சயமாக உன்னைத் தவிர பாவங்களை மன்னிப்பவர் வேறு யாரும் இல்லை) என்று கூறினார்கள். பின்னர் சிரித்தார்கள். (இதைப் பார்த்த நான்,) \"முஃமின்களின் தளபதியே! நீங்கள் ஏன் சிரித்தீர்கள்?\" என்று கேட்டேன். அதற்கு அவர்கள், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் நான் செய்தவாறே செய்தார்கள்; பின்னர் சிரித்தார்கள். நான், 'அல்லாஹ்வின் தூதரே! நீங்கள் ஏன் சிரித்தீர்கள்?' என்று கேட்டேன். அதற்கு அவர்கள், 'நிச்சயமாக உமது இறைவன் தனது அடியான், \"இறைவா! என் பாவங்களை மன்னிப்பாயாக\" என்று கூறுவதைக் கண்டு வியப்படைகிறான். (ஏனெனில்,) என்னைத் தவிர பாவங்களை மன்னிப்பவர் வேறு யாருமில்லை என்பதை அவன் அறிந்துள்ளான்' என்று கூறினார்கள்.\" (அபூ தாவூத், திர்மிதி மற்றும் நஸாயீ)<br />\r\n<br />","text":"அல்லாஹ்வே படைப்பாளன் என இணைவைப்பாளர்கள் ஒப்புக்கொள்ளுதலும், அதற்கான மேலதிகச் சான்றுகளும்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: \"முஹம்மதே (ஸல்)! அல்லாஹ்வுக்கு இணையாகப் பிறரை வணங்கும் இந்த இணைவைப்பாளர்களிடம் நீர், ﴾مَّنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ خَلَقَهُنَّ الْعَزِيزُ الْعَلِيمُ﴿\n\r\n\n\r\n('வானங்களையும் பூமியையும் படைத்தவன் யார்?' என்று) கேட்டால், 'யாவற்றையும் மிகைத்தவனும், அனைத்தையும் அறிந்தவனுமாகிய அல்லாஹ்வே அவற்றைப் படைத்தான்' என்று அவர்கள் நிச்சயமாகக் கூறுவார்கள்.\" அதாவது, அனைத்தையும் படைத்தவன் அல்லாஹ் ஒருவனே என்பதையும், அவனுக்குப் பங்காளிகளோ துணையோ இல்லை என்பதையும் அவர்கள் ஒப்புக்கொள்கிறார்கள். இருப்பினும், அவர்கள் அவனுடன் சிலைகளையும் பொய்யான தெய்வங்களையும் வணங்குகிறார்கள். ﴾الَّذِى جَعَلَ لَكُمُ الْأَرْضَ مَهْداً﴿\n\r\n\n\r\n(அவனே பூமியை உங்களுக்கு ஒரு விரிப்பாகவும், தொட்டிலாகவும் ஆக்கினான்,) அதாவது, நீங்கள் அதில் பயணம் செய்யவும், அதன் மீது நிற்கவும், உறங்கவும், நடக்கவும் ஏதுவாக அதனை மென்மையாகவும், நிலையானதாகவும், உறுதியானதாகவும் அவன் ஆக்கினான். அது தண்ணீருக்கு மேல் படைக்கப்பட்டிருந்தாலும், அது அசையாமல் இருப்பதற்காக மலைகளைக் கொண்டு அவன் அதனைப் பலப்படுத்தினான். ﴾وَجَعَلَ لَكُمْ فِيهَا سُبُلاً﴿\n\r\n\n\r\n(அதில் உங்களுக்குப் பாதைகளையும் ஆக்கினான்,) அதாவது மலைகளுக்கும் பள்ளத்தாக்குகளுக்கும் இடையே உள்ள பாதைகள். ﴾لَعَلَّكُمْ تَهْتَدُونَ﴿\n\r\n\n\r\n(நீங்கள் வழியறிந்து செல்வதற்காக.) அதாவது ஒரு நகரத்திலிருந்து மற்றொரு நகரத்திற்கும், ஒரு பகுதியிலிருந்து மற்றொரு பகுதிக்கும், ஒரு நாட்டிலிருந்து மற்றொரு நாட்டிற்கும் நீங்கள் மேற்கொள்ளும் பயணங்களில் வழியறிந்து செல்வதற்காக. ﴾وَالَّذِى نَزَّلَ مِنَ السَّمَآءِ مَآءً بِقَدَرٍ﴿\n\r\n\n\r\n(அவனே வானத்திலிருந்து குறிப்பிட்ட அளவுப்படி மழையை இறக்கினான்,) அதாவது உங்கள் பயிர்களுக்கும், கனிகளுக்கும், உங்களுக்கும் உங்கள் கால்நடைகளுக்கும் தேவையான குடிநீருக்கு ஏற்ப (அளவாக இறக்கினான்). ﴾فَأَنشَرْنَا بِهِ بَلْدَةً مَّيْتاً﴿\n\r\n\n\r\n(பின்னர், அதைக் கொண்டு வறண்ட நிலத்தை நாம் உயிர்ப்பிக்கிறோம்,) அதாவது தரிசு நிலம்; அதன் மீது நீர் விழும்போது அது உயிர் பெற்று செழிப்படைகிறது, மேலும் அது அனைத்து வகையான அழகான தாவரங்களையும் வெளிப்படுத்துகிறது. பூமியை உயிர்ப்பிப்பதைப் பற்றிக் குறிப்பிடுவதன் மூலம், மனிதர்கள் மரணித்த பிறகு மறுமை நாளில் அவர்களது உடல்களை அல்லாஹ் எவ்வாறு மீண்டும் உயிர்ப்பிப்பான் என்பதை அவன் சுட்டிக்காட்டுகிறான். ﴾كَذَلِكَ تُخْرَجُونَ﴿\n\r\n\n\r\n(இவ்வாறே நீங்களும் மறுமையில் வெளிப்படுத்தப்படுவீர்கள்.) பின்னர் அல்லாஹ் கூறுகிறான்: ﴾وَالَّذِى خَلَقَ الْأَزْوَاجَ كُلَّهَا﴿\n\r\n\n\r\n(அவனே ஜோடிகள் அனைத்தையும் படைத்தான்) அதாவது பூமியில் வளரக்கூடிய அனைத்து வகையான தாவரங்கள், பயிர்கள், கனிகள், மலர்கள் மற்றும் அனைத்து வகையான விலங்குகளிலும் ஜோடிகளைப் படைத்தான். ﴾وَجَعَلَ لَكُمْ مِّنَ الْفُلْكِ﴿\n\r\n\n\r\n(மேலும் உங்களுக்காகக் கப்பல்களையும் ஆக்கினான்) அல்லது நீர்வழிப் போக்குவரத்து சாதனங்களை, ﴾وَالْأَنْعَامِ مَا تَرْكَبُونَ﴿\n\r\n\n\r\n(நீங்கள் சவாரி செய்யும் கால்நடைகளையும் ஆக்கினான்.) அதாவது அவற்றை அவன் உங்களுக்கு வசப்படுத்திக் கொடுத்து, அவற்றின் இறைச்சியை உண்ணவும், அதன் பாலைப் பருகவும், அவற்றின் முதுகில் சவாரி செய்யவும் உங்களுக்கு எளிதாக்கினான். அல்லாஹ் கூறுகிறான்: ﴾لِتَسْتَوُواْ عَلَى ظُهُورِهِ﴿\n\r\n\n\r\n(அவற்றின் முதுகுகளின் மீது நீங்கள் அமர்வதற்காக,) அதாவது வசதியாகவும் பாதுகாப்பாகவும் அமர்வதற்கு, ﴾عَلَى ظُهُورِهِ﴿\n\r\n\n\r\n(அவற்றின் முதுகுகளின் மீது) அதாவது இத்தகைய விலங்குகளின் முதுகுகளின் மீது. ﴾ثُمَّ تَذْكُرُواْ نِعْمَةَ رَبِّكُمْ﴿\n\r\n\n\r\n(பின்னர் உங்கள் இறைவனின் அருட்கொடையை நீங்கள் நினைவுகூர வேண்டும்) அதாவது இந்த விலங்குகள் உங்களுக்கு வசப்படுத்திக் கொடுக்கப்பட்டதன் மூலம் கிடைத்த அருட்கொடையை. ﴾إِذَا اسْتَوَيْتُمْ عَلَيْهِ وَتَقُولُواْ سُبْحَانَ الَّذِى سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ﴿\n\r\n\n\r\n(நீங்கள் அவற்றின் மீது அமர்ந்ததும், \"எங்களுக்கு இதனை வசப்படுத்தித் தந்தவன் தூய்மையானவன்; இதற்குச் சக்தி பெற்றவர்களாக நாங்கள் இருக்கவில்லை\" என்று கூற வேண்டும்.) அதாவது, அல்லாஹ் இவற்றை நமக்கு வசப்படுத்திக் கொடுத்திருக்காவிட்டால், நமது சொந்த வலிமையால் இதனைச் செய்திருக்க முடியாது. இப்னு அப்பாஸ் (ரழி), கதாதா (ரஹ்), அஸ்-ஸுத்தி (ரஹ்) மற்றும் இப்னு ஸைத் (ரஹ்) ஆகியோர் கூறினார்கள்: \"இதை நாங்களாகவே செய்திருக்க முடியாது.\" ﴾وَإِنَّآ إِلَى رَبِّنَا لَمُنقَلِبُونَ ﴿\n\r\n\n\r\n(மேலும், நிச்சயமாக நாம் நம்முடைய இறைவனிடமே திரும்பிச் செல்பவர்கள்.) அதாவது, 'மரணத்திற்குப் பிறகு நாம் அவனிடமே திரும்புவோம், நமது இறுதி இலக்கும் அவனிடமே உள்ளது.' இந்த வசனத்தில், உலகப் பயணங்களைப் பற்றிய குறிப்பு, மறுமைப் பயணத்தின் மீது கவனத்தை ஈர்க்கிறது. உலகத் தேவைகளுக்கான தயாரிப்பு, மறுமைக்கான தயாரிப்பின் முக்கியத்துவத்தை உணர்த்துவது போல - அல்லாஹ் கூறுகிறான்: ﴾وَتَزَوَّدُواْ فَإِنَّ خَيْرَ الزَّادِ التَّقْوَى﴿\n\r\n\n\r\n(பயணத்திற்காகத் தேவையானவற்றைத் தயார் செய்து கொள்ளுங்கள்; நிச்சயமாகத் தயாரிப்புகளில் மிகச் சிறந்தது தக்வா இறையச்சம் ஆகும்) (2:197). மேலும் உலக ஆடைகளைப் பற்றிய குறிப்பு, மறுமையின் ஆடையின் பக்கம் கவனத்தை ஈர்க்கப் பயன்படுகிறது: ﴾وَرِيشًا وَلِبَاسُ التَّقْوَى ذَلِكَ خَيْرٌ﴿\n\r\n\n\r\n(அலங்காரமாகவும்; ஆனால் தக்வா எனும் ஆடையே மிகவும் மேலானது) (7:26).\n\r\n\n\r\nஇமாம் அஹ்மத் (ரஹ்) அவர்கள் அறிவிக்கிறார்கள்: அலி பின் ரபீஆ (ரஹ்) அவர்கள் கூறினார்கள்: அலி (ரழி) அவர்களிடம் சவாரி செய்வதற்காக ஒரு மிருகம் கொண்டு வரப்பட்டது. அவர்கள் தமது காலை அங்கவடியில் வைத்தபோது \"பிஸ்மில்லாஹ்\" (அல்லாஹ்வின் பெயரால்) என்று கூறினார்கள். அதன் மீது ஏறி அமர்ந்ததும், \"அல்ஹம்துலில்லாஹ்\" (புகழ் அனைத்தும் அல்லாஹ்வுக்கே) என்று கூறினார்கள். பிறகு, \"சுப்ஹானல்லதீ சக்கரா லனா ஹாதா வமா குன்னா லஹு முக்ரினீன்\" என்று ஓதினார்கள். பிறகு, மும்முறை \"அல்ஹம்துலில்லாஹ்\" என்றும், மும்முறை \"அல்லாஹு அக்பர்\" என்றும் கூறினார்கள். பிறகு, \"சுப்ஹானக இன்னீ ழலம்ன்து நஃப்ஸீ ஃபக்ஃபிர்லீ ஃபஇன்னஹு லாயக்ஃபிருத் துனூப இல்லா அன்த்த\" (நீ தூயவன்; நிச்சயமாக நான் எனக்கே அநீதி இழைத்துக் கொண்டேன். எனவே, என்னை மன்னித்தருள்வாயாக! நிச்சயமாக உன்னைத் தவிர பாவங்களை மன்னிப்பவர் வேறு யாரும் இல்லை) என்று கூறினார்கள். பின்னர் சிரித்தார்கள். (இதைப் பார்த்த நான்,) \"முஃமின்களின் தளபதியே! நீங்கள் ஏன் சிரித்தீர்கள்?\" என்று கேட்டேன். அதற்கு அவர்கள், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் நான் செய்தவாறே செய்தார்கள்; பின்னர் சிரித்தார்கள். நான், 'அல்லாஹ்வின் தூதரே! நீங்கள் ஏன் சிரித்தீர்கள்?' என்று கேட்டேன். அதற்கு அவர்கள், 'நிச்சயமாக உமது இறைவன் தனது அடியான், \"இறைவா! என் பாவங்களை மன்னிப்பாயாக\" என்று கூறுவதைக் கண்டு வியப்படைகிறான். (ஏனெனில்,) என்னைத் தவிர பாவங்களை மன்னிப்பவர் வேறு யாருமில்லை என்பதை அவன் அறிந்துள்ளான்' என்று கூறினார்கள்.\" (அபூ தாவூத், திர்மிதி மற்றும் நஸாயீ)"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=20\" class=\"link\">43:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:20 ஐ பார்க்கவும்"},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=20\" class=\"link\">43:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:20 ஐ பார்க்கவும்"},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=20\" class=\"link\">43:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:20 ஐ பார்க்கவும்"},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=20\" class=\"link\">43:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:20 ஐ பார்க்கவும்"},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=20\" class=\"link\">43:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:20 ஐ பார்க்கவும்"},"20":{"html":"<strong>இணைவைப்பாளர்கள் அல்லாஹ்வுக்குச் சந்ததிகள் இருப்பதாகக் கற்பனை செய்ததைக் கண்டித்தல்</strong><br />\r\n<br />\r\nஇணைவைப்பாளர்கள் தங்களின் கால்நடைகளில் ஒரு பகுதியைத் தங்களின் போலி தெய்வங்களுக்கும், மற்றொரு பகுதியை அல்லாஹ்வுக்கும் ஒதுக்கியபோது அவர்கள் செய்த பொய்களையும் இட்டுக்கட்டுதல்களையும் பற்றி அல்லாஹ் இங்கு குறிப்பிடுகிறான். இதனை அல்குர்ஆனின் அன்ஆம் அத்தியாயத்தில் (ஸூரத்துல் அன்ஆம்) பின்வருமாறு விவரிக்கிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَجَعَلُواْ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">ذَرَأَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْحَرْثِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَنْعَامِ</span> <span class=\"quran-arabic-font text-success\">نَصِيباً</span> <span class=\"quran-arabic-font text-success\">فَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">بِزَعْمِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَهَـذَا</span> <span class=\"quran-arabic-font text-success\">لِشُرَكَآئِنَا</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">لِشُرَكَآئِهِمْ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">يَصِلُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">يَصِلُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">شُرَكَآئِهِمْ</span> <span class=\"quran-arabic-font text-success\">سَآءَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَحْكُمُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"அல்லாஹ் படைத்த விளைச்சலிலும் கால்நடைகளிலும் அவனுக்கு ஒரு பங்கை அவர்கள் ஒதுக்கி, அவர்களின் வீண் எண்ணப்படி, 'இது அல்லாஹ்வுக்குரியது; இது எங்களது தெய்வங்களுக்கு (கூட்டாளிகளுக்கு) உரியது' என்றும் கூறுகின்றனர். அவர்களின் தெய்வங்களுக்குரிய பங்கு அல்லாஹ்வைச் சென்றடைவதில்லை; ஆனால் அல்லாஹ்வுக்குரிய பங்கு அவர்களின் தெய்வங்களைச் சென்றடைகிறது. அவர்கள் செய்யும் இத்தீர்ப்பு மிகவும் கெட்டது!\") (<a href=\"qurandisp.php?sura=6&ayah=136\" class=\"link\">6:136</a>). அதுபோலவே, ஆண் மற்றும் பெண் ஆகிய இரு வகை சந்ததிகளில், தங்களின் பார்வையில் தாழ்ந்ததாகக் கருதிய பெண் குழந்தைகளை அல்லாஹ்வுக்கு அவர்கள் ஒதுக்கினார்கள். இதனை அல்லாஹ் இவ்வாறு கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَلَكُمُ</span> <span class=\"quran-arabic-font text-success\">الذَّكَرُ</span> <span class=\"quran-arabic-font text-success\">وَلَهُ</span> <span class=\"quran-arabic-font text-success\">الْأُنثَى</span> - <span class=\"quran-arabic-font text-success\">تِلْكَ</span> <span class=\"quran-arabic-font text-success\">إِذاً</span> <span class=\"quran-arabic-font text-success\">قِسْمَةٌ</span> <span class=\"quran-arabic-font text-success\">ضِيزَى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"உங்களுக்கு ஆண் பிள்ளைகளும் அவனுக்குப் பெண் பிள்ளைகளுமா? அப்படியாயின், இது மிகவும் அநீதியான பங்கீடாகும்!\") (<a href=\"qurandisp.php?sura=53&ayah=21\" class=\"link\">53:21</a>-22). மேலும் அல்லாஹ் இங்கு கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَجَعَلُواْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عِبَادِهِ</span> <span class=\"quran-arabic-font text-success\">جُزْءًا</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْإِنسَانَ</span> <span class=\"quran-arabic-font text-success\">لَكَفُورٌ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٌ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஆயினும், அவர்கள் அவனுடைய அடியார்களில் ஒரு பகுதியை அவனுக்கு (சந்ததியாக) ஆக்குகின்றனர். நிச்சயமாக மனிதன் தெளிவான நன்றிகெட்டவன்!) பிறகு அவன் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَمِ</span> <span class=\"quran-arabic-font text-success\">اتَّخَذَ</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">يَخْلُقُ</span> <span class=\"quran-arabic-font text-success\">بَنَاتٍ</span> <span class=\"quran-arabic-font text-success\">وَأَصْفَاكُم</span> <span class=\"quran-arabic-font text-success\">بِالْبَنِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அல்லது தான் படைப்பவற்றிலிருந்து அவன் பெண் பிள்ளைகளைத் தனக்கென எடுத்துக்கொண்டு, உங்களுக்கு ஆண் பிள்ளைகளைத் தேர்ந்தெடுத்துக் கொடுத்தானா?) இது அவர்களை மிகக் கடுமையாகக் கண்டிப்பதாகும். அல்லாஹ் மேலும் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">بُشِّرَ</span> <span class=\"quran-arabic-font text-success\">أَحَدُهُم</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">ضَرَبَ</span> <span class=\"quran-arabic-font text-success\">لِلرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">مَثَلاً</span> <span class=\"quran-arabic-font text-success\">ظَلَّ</span> <span class=\"quran-arabic-font text-success\">وَجْهُهُ</span> <span class=\"quran-arabic-font text-success\">مُسْوَدّاً</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">كَظِيمٌ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அளவற்ற அருளாளனுக்கு எதனை அவர்கள் உவமையாகக் கூறுகிறார்களோ (பெண் குழந்தை), அத்தகைய ஒரு குழந்தையைப் பற்றி அவர்களில் ஒருவனுக்கு நற்செய்தி சொல்லப்பட்டால், அவன் துக்கம் நிறைந்தவனாக அவனது முகம் கறுத்துவிடுகிறது!) அதாவது, அல்லாஹ்வுக்குச் சொந்தமென அவர்கள் கூறும் பெண் குழந்தை தனக்குப் பிறந்திருப்பதாக ஒருவனுக்குச் செய்தி கிடைத்தால், அவன் அதனை வெறுக்கிறான். அந்தச் செய்தி அவனை அந்தளவுக்குக் கவலையடையச் செய்கிறது. அந்த வெட்கத்தினால் அவன் மக்களிடமிருந்து ஒதுங்கி வாழ்கிறான். தாம் இவ்வளவு வெறுக்கும் ஒரு விஷயத்தை அவர்கள் எப்படி அல்லாஹ்வுக்குச் சாட்ட முடியும் என்று அல்லாஹ் கேட்கிறான்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَوَمَن</span> <span class=\"quran-arabic-font text-success\">يُنَشَّأُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْحِلْيَةِ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْخِصَامِ</span> <span class=\"quran-arabic-font text-success\">غَيْرُ</span> <span class=\"quran-arabic-font text-success\">مُبِينٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஆபரணங்களால் அலங்கரிக்கப்பட்டு வளர்க்கப்படும், மேலும் விவாதங்களின் போது தனது கருத்தைத் தெளிவாக முன்வைக்க இயலாத ஒருவரையா (அல்லாஹ்வுக்குப் பிள்ளையாகக் கருதுகின்றனர்)?) அதாவது, பெண்கள் இயல்பாகவே ஏதோ ஒரு குறையுள்ளவர்களாகக் கருதப்படுகிறார்கள்; அதனை அவர்கள் சிறுவயது முதலே ஆபரணங்கள் மற்றும் அலங்காரங்கள் மூலம் ஈடு செய்கிறார்கள். மேலும், ஒரு விவாதம் ஏற்படும்போது அவர்களால் தங்களைத் தெளிவாகத் தற்காத்துப் பேச இயலாது. அப்படியிருக்க, இவர்களை எப்படி அல்லாஹ்வுக்குச் சாட்ட முடியும்?<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَجَعَلُواْ</span> <span class=\"quran-arabic-font text-success\">الْمَلَائِكَةَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">عِبَادُ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">إِنَاثاً﴿</span><br />\r\n<br />\r\n(மேலும், அளவற்ற அருளாளனின் அடியார்களாகிய வானவர்களை அவர்கள் பெண்களாகக் கருதுகின்றனர்.) அதாவது, வானவர்களைப் பற்றி அவர்கள் அவ்வாறுதான் நம்புகிறார்கள். ஆனால் அல்லாஹ் அதனைக் கண்டித்து கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَشَهِدُواْ</span> <span class=\"quran-arabic-font text-success\">خَلْقَهُمْ﴿</span><br />\r\n<br />\r\n(அவர்கள் படைக்கப்பட்டதை இவர்கள் நேரில் பார்த்தார்களா?) அதாவது, அல்லாஹ் அவர்களைப் பெண்களாகப் படைப்பதை இவர்கள் கண்டார்களா?<br />\r\n<span class=\"quran-arabic-font text-success\">﴾سَتُكْتَبُ</span> <span class=\"quran-arabic-font text-success\">شَهَادَتُهُمْ﴿</span><br />\r\n<br />\r\n(அவர்களது இச்சாட்சியம் பதிவு செய்யப்படும்), <span class=\"quran-arabic-font text-success\">﴾وَيُسْأَلُونَ﴿</span><br />\r\n<br />\r\n(மேலும் அவர்கள் விசாரிக்கப்படுவார்கள்!) அதாவது, மறுமை நாளில் இது குறித்து அவர்கள் விசாரிக்கப்படுவார்கள். இது ஒரு கடுமையான எச்சரிக்கையும் அச்சுறுத்தலுமாகும்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">عَبَدْنَاهُمْ﴿</span><br />\r\n<br />\r\n(மேலும் அவர்கள் கூறினர்: \"அளவற்ற அருளாளன் நாடியிருந்தால், நாங்கள் அவர்களை வணங்கியிருக்க மாட்டோம்.\") அதாவது, \"அல்லாஹ் நாடியிருந்தால், வானவர்களின் உருவங்களாகிய - அதாவது அல்லாஹ்வின் பெண் பிள்ளைகளாகிய - இந்தச் சிலைகளை நாம் வணங்குவதைத் தடுத்திருப்பான்; அவனுக்கு இது தெரியும், அவன் இதனை அங்கீகரிக்கிறான்\" என்று அவர்கள் கூறினார்கள். இவ்வாறு கூறுவதன் மூலம் அவர்கள் பல வகையான தவறுகளைச் செய்தார்கள்:<br />\r\n<br />\r\nமுதலாவது: அல்லாஹ்வுக்குச் சந்ததிகள் இருப்பதாகக் கூறினார்கள் - அவன் இத்தகு குறைகளிலிருந்து மிகத் தூய்மையானவனும் உயர்ந்தவனுமாவான்.<br />\r\n<br />\r\nஇரண்டாவது: அவன் ஆண் பிள்ளைகளை விடுத்து பெண் பிள்ளைகளைத் தேர்ந்தெடுத்ததாகக் கூறினார்கள்; மேலும் அளவற்ற அருளாளனின் அடியார்களான வானவர்களைப் பெண்களாக்கினார்கள்.<br />\r\n<br />\r\nமூன்றாவது: அல்லாஹ்விடமிருந்து எந்த ஆதாரமோ, சான்றோ அல்லது அனுமதியோ இன்றி அவர்களை வணங்கினார்கள். இது வெறும் யூகங்கள், மனோ இச்சைகள், முன்னோர்களைப் பின்பற்றுதல் மற்றும் அறியாமையின் அடிப்படையிலேயே அமைந்தது. அல்லாஹ்வின் விதியைத் தங்களுக்குச் சாதகமாக ஒரு சாக்காகப் பயன்படுத்தினார்கள். இவர்களின் இந்த வாதமே இவர்களது அறியாமையை வெளிப்படுத்தியது.<br />\r\n<br />\r\nநான்காவது: அல்லாஹ் அவர்களை இதற்காகக் கடுமையாகக் கண்டித்தான். ஏனெனில், அவன் தூதர்களை அனுப்பி வேதங்களை அருளிய காலத்திலிருந்தே, எவ்வித இணை துணையுமின்றி அவனை மட்டுமே வணங்க வேண்டும் என்பதே அவனது கட்டளையாக இருந்தது. அவனைத் தவிர வேறு எதனையும் வணங்குவது தடை செய்யப்பட்டிருந்தது. அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">بَعَثْنَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">أُمَّةٍ</span> <span class=\"quran-arabic-font text-success\">رَّسُولاً</span> <span class=\"quran-arabic-font text-success\">أَنِ</span> <span class=\"quran-arabic-font text-success\">اعْبُدُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَاجْتَنِبُواْ</span> <span class=\"quran-arabic-font text-success\">الطَّاغُوتَ</span> <span class=\"quran-arabic-font text-success\">فَمِنْهُم</span> <span class=\"quran-arabic-font text-success\">مَّنْ</span> <span class=\"quran-arabic-font text-success\">هَدَى</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">وَمِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّنْ</span> <span class=\"quran-arabic-font text-success\">حَقَّتْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">الضَّلَالَةُ</span> <span class=\"quran-arabic-font text-success\">فَسِيرُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">فَانظُرُواْ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَاقِبَةُ</span> <span class=\"quran-arabic-font text-success\">الْمُكَذِّبِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"அல்லாஹ்வை வணங்குங்கள், ஷைத்தானைத் (தீய சக்திகளைத்) தவிர்ந்து கொள்ளுங்கள்\" என்று போதிப்பதற்காக ஒவ்வொரு சமுதாயத்திற்கும் ஒரு தூதரை நாம் அனுப்பினோம். அவர்களில் அல்லாஹ் நேர்வழி காட்டியவர்களும் உண்டு; வழிகேடு உறுதியானவர்களும் உண்டு. எனவே, பூமியில் பயணம் செய்து, (சத்தியத்தை) மறுத்தவர்களின் முடிவு என்னவானது என்று பாருங்கள்.) (<a href=\"qurandisp.php?sura=16&ayah=36\" class=\"link\">16:36</a>)<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاسْأَلْ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِكَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رُّسُلِنَآ</span> <span class=\"quran-arabic-font text-success\">أَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">آلِهَةً</span> <span class=\"quran-arabic-font text-success\">يُعْبَدُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(உமக்கு முன் நாம் அனுப்பிய நம்முடைய தூதர்களிடம் கேளும்: \"அளவற்ற அருளாளனைத் தவிர வணங்கப்பட வேண்டிய வேறு தெய்வங்களை நாம் ஏற்படுத்தினோமா?\") (<a href=\"qurandisp.php?sura=43&ayah=45\" class=\"link\">43:45</a>)<br />\r\n<br />\r\nமேலும் இந்த வசனத்தில் இவர்களுடைய இந்த வாதத்தைக் குறிப்பிட்ட பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مَّا</span> <span class=\"quran-arabic-font text-success\">لَهُم</span> <span class=\"quran-arabic-font text-success\">بِذَلِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عِلْمٍ﴿</span><br />\r\n<br />\r\n(அவர்களுக்கு அது பற்றி எந்த அறிவும் இல்லை.) அதாவது, அவர்கள் சொல்வதன் உண்மை குறித்தோ, அவர்கள் முன்வைக்கும் வாதங்கள் குறித்தோ அவர்களுக்கு அறிவு இல்லை.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِنْ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">يَخْرُصُونَ﴿</span><br />\r\n<br />\r\n(அவர்கள் வெறும் பொய்யையே கூறுகின்றனர்!) அதாவது, அவர்கள் கற்பனையான பொய்களையே இட்டுக்கட்டுகின்றனர்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مَّا</span> <span class=\"quran-arabic-font text-success\">لَهُم</span> <span class=\"quran-arabic-font text-success\">بِذَلِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عِلْمٍ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">يَخْرُصُونَ﴿</span><br />\r\n<br />\r\n(அவர்களுக்கு அது பற்றி எந்த அறிவும் இல்லை. அவர்கள் வெறும் பொய்யையே கூறுகின்றனர்!) முஜாஹித் அவர்கள் கூறினார்கள், \"அவர்கள் பொய் சொல்கிறார்கள்.\"<br />\r\n<br />","text":"இணைவைப்பாளர்கள் அல்லாஹ்வுக்குச் சந்ததிகள் இருப்பதாகக் கற்பனை செய்ததைக் கண்டித்தல்\n\r\n\n\r\nஇணைவைப்பாளர்கள் தங்களின் கால்நடைகளில் ஒரு பகுதியைத் தங்களின் போலி தெய்வங்களுக்கும், மற்றொரு பகுதியை அல்லாஹ்வுக்கும் ஒதுக்கியபோது அவர்கள் செய்த பொய்களையும் இட்டுக்கட்டுதல்களையும் பற்றி அல்லாஹ் இங்கு குறிப்பிடுகிறான். இதனை அல்குர்ஆனின் அன்ஆம் அத்தியாயத்தில் (ஸூரத்துல் அன்ஆம்) பின்வருமாறு விவரிக்கிறான்:\n\r\n﴾وَجَعَلُواْ لِلَّهِ مِمَّا ذَرَأَ مِنَ الْحَرْثِ وَالْأَنْعَامِ نَصِيباً فَقَالُواْ هَـذَا لِلَّهِ بِزَعْمِهِمْ وَهَـذَا لِشُرَكَآئِنَا فَمَا كَانَ لِشُرَكَآئِهِمْ فَلاَ يَصِلُ إِلَى اللَّهِ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَى شُرَكَآئِهِمْ سَآءَ مَا يَحْكُمُونَ ﴿\n\r\n\n\r\n(\"அல்லாஹ் படைத்த விளைச்சலிலும் கால்நடைகளிலும் அவனுக்கு ஒரு பங்கை அவர்கள் ஒதுக்கி, அவர்களின் வீண் எண்ணப்படி, 'இது அல்லாஹ்வுக்குரியது; இது எங்களது தெய்வங்களுக்கு (கூட்டாளிகளுக்கு) உரியது' என்றும் கூறுகின்றனர். அவர்களின் தெய்வங்களுக்குரிய பங்கு அல்லாஹ்வைச் சென்றடைவதில்லை; ஆனால் அல்லாஹ்வுக்குரிய பங்கு அவர்களின் தெய்வங்களைச் சென்றடைகிறது. அவர்கள் செய்யும் இத்தீர்ப்பு மிகவும் கெட்டது!\") (6:136). அதுபோலவே, ஆண் மற்றும் பெண் ஆகிய இரு வகை சந்ததிகளில், தங்களின் பார்வையில் தாழ்ந்ததாகக் கருதிய பெண் குழந்தைகளை அல்லாஹ்வுக்கு அவர்கள் ஒதுக்கினார்கள். இதனை அல்லாஹ் இவ்வாறு கூறுகிறான்:\n\r\n﴾أَلَكُمُ الذَّكَرُ وَلَهُ الْأُنثَى - تِلْكَ إِذاً قِسْمَةٌ ضِيزَى ﴿\n\r\n\n\r\n(\"உங்களுக்கு ஆண் பிள்ளைகளும் அவனுக்குப் பெண் பிள்ளைகளுமா? அப்படியாயின், இது மிகவும் அநீதியான பங்கீடாகும்!\") (53:21-22). மேலும் அல்லாஹ் இங்கு கூறுகிறான்:\n\r\n﴾وَجَعَلُواْ لَهُ مِنْ عِبَادِهِ جُزْءًا إِنَّ الْإِنسَانَ لَكَفُورٌ مُّبِينٌ ﴿\n\r\n\n\r\n(ஆயினும், அவர்கள் அவனுடைய அடியார்களில் ஒரு பகுதியை அவனுக்கு (சந்ததியாக) ஆக்குகின்றனர். நிச்சயமாக மனிதன் தெளிவான நன்றிகெட்டவன்!) பிறகு அவன் கூறுகிறான்:\n\r\n﴾أَمِ اتَّخَذَ مِمَّا يَخْلُقُ بَنَاتٍ وَأَصْفَاكُم بِالْبَنِينَ ﴿\n\r\n\n\r\n(அல்லது தான் படைப்பவற்றிலிருந்து அவன் பெண் பிள்ளைகளைத் தனக்கென எடுத்துக்கொண்டு, உங்களுக்கு ஆண் பிள்ளைகளைத் தேர்ந்தெடுத்துக் கொடுத்தானா?) இது அவர்களை மிகக் கடுமையாகக் கண்டிப்பதாகும். அல்லாஹ் மேலும் கூறுகிறான்:\n\r\n﴾وَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحْمَـنِ مَثَلاً ظَلَّ وَجْهُهُ مُسْوَدّاً وَهُوَ كَظِيمٌ ﴿\n\r\n\n\r\n(அளவற்ற அருளாளனுக்கு எதனை அவர்கள் உவமையாகக் கூறுகிறார்களோ (பெண் குழந்தை), அத்தகைய ஒரு குழந்தையைப் பற்றி அவர்களில் ஒருவனுக்கு நற்செய்தி சொல்லப்பட்டால், அவன் துக்கம் நிறைந்தவனாக அவனது முகம் கறுத்துவிடுகிறது!) அதாவது, அல்லாஹ்வுக்குச் சொந்தமென அவர்கள் கூறும் பெண் குழந்தை தனக்குப் பிறந்திருப்பதாக ஒருவனுக்குச் செய்தி கிடைத்தால், அவன் அதனை வெறுக்கிறான். அந்தச் செய்தி அவனை அந்தளவுக்குக் கவலையடையச் செய்கிறது. அந்த வெட்கத்தினால் அவன் மக்களிடமிருந்து ஒதுங்கி வாழ்கிறான். தாம் இவ்வளவு வெறுக்கும் ஒரு விஷயத்தை அவர்கள் எப்படி அல்லாஹ்வுக்குச் சாட்ட முடியும் என்று அல்லாஹ் கேட்கிறான்.\n\r\n﴾أَوَمَن يُنَشَّأُ فِى الْحِلْيَةِ وَهُوَ فِى الْخِصَامِ غَيْرُ مُبِينٍ ﴿\n\r\n\n\r\n(ஆபரணங்களால் அலங்கரிக்கப்பட்டு வளர்க்கப்படும், மேலும் விவாதங்களின் போது தனது கருத்தைத் தெளிவாக முன்வைக்க இயலாத ஒருவரையா (அல்லாஹ்வுக்குப் பிள்ளையாகக் கருதுகின்றனர்)?) அதாவது, பெண்கள் இயல்பாகவே ஏதோ ஒரு குறையுள்ளவர்களாகக் கருதப்படுகிறார்கள்; அதனை அவர்கள் சிறுவயது முதலே ஆபரணங்கள் மற்றும் அலங்காரங்கள் மூலம் ஈடு செய்கிறார்கள். மேலும், ஒரு விவாதம் ஏற்படும்போது அவர்களால் தங்களைத் தெளிவாகத் தற்காத்துப் பேச இயலாது. அப்படியிருக்க, இவர்களை எப்படி அல்லாஹ்வுக்குச் சாட்ட முடியும்?\n\r\n﴾وَجَعَلُواْ الْمَلَائِكَةَ الَّذِينَ هُمْ عِبَادُ الرَّحْمَـنِ إِنَاثاً﴿\n\r\n\n\r\n(மேலும், அளவற்ற அருளாளனின் அடியார்களாகிய வானவர்களை அவர்கள் பெண்களாகக் கருதுகின்றனர்.) அதாவது, வானவர்களைப் பற்றி அவர்கள் அவ்வாறுதான் நம்புகிறார்கள். ஆனால் அல்லாஹ் அதனைக் கண்டித்து கூறுகிறான்:\n\r\n﴾أَشَهِدُواْ خَلْقَهُمْ﴿\n\r\n\n\r\n(அவர்கள் படைக்கப்பட்டதை இவர்கள் நேரில் பார்த்தார்களா?) அதாவது, அல்லாஹ் அவர்களைப் பெண்களாகப் படைப்பதை இவர்கள் கண்டார்களா?\n\r\n﴾سَتُكْتَبُ شَهَادَتُهُمْ﴿\n\r\n\n\r\n(அவர்களது இச்சாட்சியம் பதிவு செய்யப்படும்), ﴾وَيُسْأَلُونَ﴿\n\r\n\n\r\n(மேலும் அவர்கள் விசாரிக்கப்படுவார்கள்!) அதாவது, மறுமை நாளில் இது குறித்து அவர்கள் விசாரிக்கப்படுவார்கள். இது ஒரு கடுமையான எச்சரிக்கையும் அச்சுறுத்தலுமாகும்.\n\r\n﴾وَقَالُواْ لَوْ شَآءَ الرَّحْمَـنُ مَا عَبَدْنَاهُمْ﴿\n\r\n\n\r\n(மேலும் அவர்கள் கூறினர்: \"அளவற்ற அருளாளன் நாடியிருந்தால், நாங்கள் அவர்களை வணங்கியிருக்க மாட்டோம்.\") அதாவது, \"அல்லாஹ் நாடியிருந்தால், வானவர்களின் உருவங்களாகிய - அதாவது அல்லாஹ்வின் பெண் பிள்ளைகளாகிய - இந்தச் சிலைகளை நாம் வணங்குவதைத் தடுத்திருப்பான்; அவனுக்கு இது தெரியும், அவன் இதனை அங்கீகரிக்கிறான்\" என்று அவர்கள் கூறினார்கள். இவ்வாறு கூறுவதன் மூலம் அவர்கள் பல வகையான தவறுகளைச் செய்தார்கள்:\n\r\n\n\r\nமுதலாவது: அல்லாஹ்வுக்குச் சந்ததிகள் இருப்பதாகக் கூறினார்கள் - அவன் இத்தகு குறைகளிலிருந்து மிகத் தூய்மையானவனும் உயர்ந்தவனுமாவான்.\n\r\n\n\r\nஇரண்டாவது: அவன் ஆண் பிள்ளைகளை விடுத்து பெண் பிள்ளைகளைத் தேர்ந்தெடுத்ததாகக் கூறினார்கள்; மேலும் அளவற்ற அருளாளனின் அடியார்களான வானவர்களைப் பெண்களாக்கினார்கள்.\n\r\n\n\r\nமூன்றாவது: அல்லாஹ்விடமிருந்து எந்த ஆதாரமோ, சான்றோ அல்லது அனுமதியோ இன்றி அவர்களை வணங்கினார்கள். இது வெறும் யூகங்கள், மனோ இச்சைகள், முன்னோர்களைப் பின்பற்றுதல் மற்றும் அறியாமையின் அடிப்படையிலேயே அமைந்தது. அல்லாஹ்வின் விதியைத் தங்களுக்குச் சாதகமாக ஒரு சாக்காகப் பயன்படுத்தினார்கள். இவர்களின் இந்த வாதமே இவர்களது அறியாமையை வெளிப்படுத்தியது.\n\r\n\n\r\nநான்காவது: அல்லாஹ் அவர்களை இதற்காகக் கடுமையாகக் கண்டித்தான். ஏனெனில், அவன் தூதர்களை அனுப்பி வேதங்களை அருளிய காலத்திலிருந்தே, எவ்வித இணை துணையுமின்றி அவனை மட்டுமே வணங்க வேண்டும் என்பதே அவனது கட்டளையாக இருந்தது. அவனைத் தவிர வேறு எதனையும் வணங்குவது தடை செய்யப்பட்டிருந்தது. அல்லாஹ் கூறுகிறான்:\n\r\n﴾وَلَقَدْ بَعَثْنَا فِى كُلِّ أُمَّةٍ رَّسُولاً أَنِ اعْبُدُواْ اللَّهَ وَاجْتَنِبُواْ الطَّاغُوتَ فَمِنْهُم مَّنْ هَدَى اللَّهُ وَمِنْهُمْ مَّنْ حَقَّتْ عَلَيْهِ الضَّلَالَةُ فَسِيرُواْ فِى الْأَرْضِ فَانظُرُواْ كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ ﴿\n\r\n\n\r\n(\"அல்லாஹ்வை வணங்குங்கள், ஷைத்தானைத் (தீய சக்திகளைத்) தவிர்ந்து கொள்ளுங்கள்\" என்று போதிப்பதற்காக ஒவ்வொரு சமுதாயத்திற்கும் ஒரு தூதரை நாம் அனுப்பினோம். அவர்களில் அல்லாஹ் நேர்வழி காட்டியவர்களும் உண்டு; வழிகேடு உறுதியானவர்களும் உண்டு. எனவே, பூமியில் பயணம் செய்து, (சத்தியத்தை) மறுத்தவர்களின் முடிவு என்னவானது என்று பாருங்கள்.) (16:36)\n\r\n﴾وَاسْأَلْ مَنْ أَرْسَلْنَا مِن قَبْلِكَ مِن رُّسُلِنَآ أَجَعَلْنَا مِن دُونِ الرَّحْمَـنِ آلِهَةً يُعْبَدُونَ ﴿\n\r\n\n\r\n(உமக்கு முன் நாம் அனுப்பிய நம்முடைய தூதர்களிடம் கேளும்: \"அளவற்ற அருளாளனைத் தவிர வணங்கப்பட வேண்டிய வேறு தெய்வங்களை நாம் ஏற்படுத்தினோமா?\") (43:45)\n\r\n\n\r\nமேலும் இந்த வசனத்தில் இவர்களுடைய இந்த வாதத்தைக் குறிப்பிட்ட பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n﴾مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ﴿\n\r\n\n\r\n(அவர்களுக்கு அது பற்றி எந்த அறிவும் இல்லை.) அதாவது, அவர்கள் சொல்வதன் உண்மை குறித்தோ, அவர்கள் முன்வைக்கும் வாதங்கள் குறித்தோ அவர்களுக்கு அறிவு இல்லை.\n\r\n﴾وَإِنْ هُمْ إِلاَّ يَخْرُصُونَ﴿\n\r\n\n\r\n(அவர்கள் வெறும் பொய்யையே கூறுகின்றனர்!) அதாவது, அவர்கள் கற்பனையான பொய்களையே இட்டுக்கட்டுகின்றனர்.\n\r\n﴾مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلاَّ يَخْرُصُونَ﴿\n\r\n\n\r\n(அவர்களுக்கு அது பற்றி எந்த அறிவும் இல்லை. அவர்கள் வெறும் பொய்யையே கூறுகின்றனர்!) முஜாஹித் அவர்கள் கூறினார்கள், \"அவர்கள் பொய் சொல்கிறார்கள்.\""},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=25\" class=\"link\">43:25</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:25 ஐ பார்க்கவும்"},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=25\" class=\"link\">43:25</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:25 ஐ பார்க்கவும்"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=25\" class=\"link\">43:25</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:25 ஐ பார்க்கவும்"},"24":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=25\" class=\"link\">43:25</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:25 ஐ பார்க்கவும்"},"25":{"html":"<strong>இணைவைப்பவர்களிடம் எந்த ஆதாரமும் இல்லை</strong><br />\r\n<br />\r\nஅல்லாஹ்வைத் தவிர மற்றவர்களை வணங்குவதற்கு எவ்வித ஆதாரமும் சான்றும் இல்லாத நிலையில், அவ்வாறு செய்யும் இணைவைப்பவர்களை அல்லாஹ் கண்டிக்கிறான். <span class=\"quran-arabic-font text-success\">﴾أَمْ</span> <span class=\"quran-arabic-font text-success\">آتَيْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">كِتَابًا</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِ﴿</span><br />\r\n<br />\r\n(அல்லது இதற்கு முன்னர் நாம் அவர்களுக்கு ஏதேனும் ஒரு வேதத்தை வழங்கியுள்ளோமா?) அதாவது, அவர்கள் இணைவைக்கத் தொடங்குவதற்கு முன்பாக. <span class=\"quran-arabic-font text-success\">﴾فَهُم</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مُسْتَمْسِكُونَ﴿</span><br />\r\n<br />\r\n(அதனை அவர்கள் உறுதியாகப் பற்றிக்கொண்டிருக்கிறார்களா?) அதாவது, அவர்கள் செய்து கொண்டிருக்கும் காரியங்களுக்கு ஆதரவாக. ஆனால், உண்மை அவ்வாறில்லை. இது பின்வரும் வசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾أَمْ</span> <span class=\"quran-arabic-font text-success\">أَنزَلْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">سُلْطَانًا</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">يَتَكَلَّمُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">يُشْرِكُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அல்லது அவர்கள் இணைவைப்பவை பற்றிப் பேசக்கூடிய ஓர் ஆதாரத்தை (வேதத்தை) நாம் அவர்களுக்கு இறக்கியுள்ளோமா?) (<a href=\"qurandisp.php?sura=30&ayah=35\" class=\"link\">30:35</a>) அதாவது, அவ்வாறு எதுவும் நடக்கவில்லை. பிறகு அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾بَلْ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">وَجَدْنَآ</span> <span class=\"quran-arabic-font text-success\">ءَابَآءَنَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أُمَّةٍ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">آثَارِهِم</span> <span class=\"quran-arabic-font text-success\">مُّهْتَدُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மாறாக அவர்கள் கூறுகிறார்கள்: \"நிச்சயமாக நாங்கள் எங்கள் மூதாதையரை ஒரு குறிப்பிட்ட வழியிலும் மார்க்கத்திலும் (உம்மத்) கண்டோம்; நாங்கள் அவர்களின் அடிச்சுவடுகளையே பின்பற்றி வழிகாட்டப்படுகிறோம்.\") அதாவது, ஒரு குறிப்பிட்ட உம்மத் அல்லது வழியை (மார்க்கத்தை)ப் பின்பற்றிய தங்கள் தந்தைமார்களையும் மூதாதையர்களையும் கண்மூடித்தனமாகப் பின்பற்றுவதைத் தவிர, இணைவைப்பதில் அவர்களுக்கு வேறு எந்த அடிப்படையும் இல்லை. 'உம்மத்' என்ற வார்த்தை இதே போன்ற பொருளில் வேறோர் இடத்திலும் பயன்படுத்தப்பட்டுள்ளது. அங்கு அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَذِهِ</span> <span class=\"quran-arabic-font text-success\">أُمَّتُكُمْ</span> <span class=\"quran-arabic-font text-success\">أُمَّةً</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةً﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, உங்களுடைய இந்த மார்க்கம் (உம்மத்) ஒரே மார்க்கம்தான்) (<a href=\"qurandisp.php?sura=23&ayah=52\" class=\"link\">23:52</a>). மேலும் அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾وَإِنَّا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">آثَارِهِم﴿</span><br />\r\n<br />\r\n(நாங்கள் அவர்களின் அடிச்சுவடுகளிலேயே) அதாவது அவர்களுக்குப் பின்னால் <span class=\"quran-arabic-font text-success\">﴾مُّهْتَدُونَ﴿</span><br />\r\n<br />\r\n(நாங்கள் வழிகாட்டப்படுகிறோம்). இது எவ்வித ஆதாரமும் இல்லாத அவர்களின் வெற்றுக் கூற்றாகும். தூதர்களை நிராகரித்த கடந்த கால சமூகங்களில் இவர்களைப் போன்றவர்கள் ஏற்கனவே கூறியவற்றையே இந்த மக்களும் கூறுகிறார்கள் என்பதை அல்லாஹ் சுட்டிக்காட்டுகிறான். அவர்களின் இதயங்களும் பேச்சுகளும் ஒன்றுபோலவே இருக்கின்றன. <span class=\"quran-arabic-font text-success\">﴾كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَتَى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّسُولٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">سَـحِرٌ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مَجْنُونٌ</span> - <span class=\"quran-arabic-font text-success\">أَتَوَاصَوْاْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">طَاغُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இவ்வாறே, அவர்களுக்கு முன் வாழ்ந்தவர்களிடம் எந்தத் தூதர் வந்தபோதும், அவர்கள் \"இவர் ஒரு சூனியக்காரர் அல்லது ஒரு பைத்தியக்காரர்!\" என்று கூறாமல் இருக்கவில்லை. இதனை அவர்கள் (ஒருவருக்கொருவர்) வஸிய்யத் செய்து சென்றார்களா? இல்லை, அவர்களே வரம்பு மீறிய கூட்டத்தினராக இருக்கின்றனர்!) (<a href=\"qurandisp.php?sura=51&ayah=52\" class=\"link\">51:52</a>-53). மேலும் அல்லாஹ் இங்கே கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَكَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِكَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قَرْيَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">نَّذِيرٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">مُتْرَفُوهَآ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">وَجَدْنَآ</span> <span class=\"quran-arabic-font text-success\">ءَابَآءَنَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أُمَّةٍ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">آثَارِهِم</span> <span class=\"quran-arabic-font text-success\">مُّقْتَدُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் இவ்வாறே, உமக்கு முன்னர் எந்த ஊருக்கும் நாம் ஓர் எச்சரிக்கையாளரை அனுப்பியபோதெல்லாம், அங்கிருந்த வசதிபடைத்தவர்கள், \"நிச்சயமாக நாங்கள் எங்கள் மூதாதையரை ஒரு மார்க்கத்தில் கண்டோம்; நிச்சயமாக நாங்கள் அவர்களின் அடிச்சுவடுகளையே பின்பற்றுவோம்\" என்று கூறாமல் இருக்கவில்லை.) பிறகு அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾قُلْ﴿</span><br />\r\n<br />\r\n(கூறுவீராக) -- முஹம்மதே (ஸல்)! இந்த இணைவைப்பாளர்களிடம் -- <span class=\"quran-arabic-font text-success\">﴾أَوَلَوْ</span> <span class=\"quran-arabic-font text-success\">جِئْتُكُمْ</span> <span class=\"quran-arabic-font text-success\">بِأَهْدَى</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">وَجَدتُّمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">ءَابَآءَكُمْ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">بِمَآ</span> <span class=\"quran-arabic-font text-success\">أُرْسِلْتُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">كَافِرُونَ﴿</span><br />\r\n<br />\r\n(\"உங்கள் மூதாதையர் எதைப் பின்பற்றிக் கொண்டிருந்தார்களோ, அதைவிடச் சிறந்த வழிகாட்டுதலை நான் உங்களிடம் கொண்டு வந்தாலும் (நீங்கள் இதையே கூறுவீர்களா)?\" அதற்கு அவர்கள், \"நிச்சயமாக நீங்கள் எதைக் கொண்டு அனுப்பப்பட்டுள்ளீர்களோ, அதை நாங்கள் நிராகரிக்கிறோம்\" என்று கூறினார்கள்.) 'நீர் கொண்டு வந்தவை சத்தியம் என்பதை அவர்கள் உறுதியாக அறிந்திருந்தாலும், அவர்களின் தீய எண்ணங்கள் காரணமாகவும், சத்தியத்தின் மீதும் சத்தியத்தைப் பின்பற்றுபவர்கள் மீதும் அவர்கள் கொண்டுள்ள கர்வத்தின் காரணமாகவும் அதனைப் பின்பற்ற மாட்டார்கள்.' <span class=\"quran-arabic-font text-success\">﴾فَانتَقَمْنَا</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ﴿</span><br />\r\n<br />\r\n(ஆகவே, நாம் அவர்களைப் பழிவாங்கினோம்) அதாவது, நிராகரித்த சமூகங்கள் மீது பல்வேறு வகையான தண்டனைகளை இறக்கினான். இதனை அந்தச் சமூகங்களின் வரலாறுகளில் அல்லாஹ் விவரித்துள்ளான். <span class=\"quran-arabic-font text-success\">﴾فَانظُرْ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَاقِبَةُ</span> <span class=\"quran-arabic-font text-success\">الْمُكَذِّبِينَ﴿</span><br />\r\n<br />\r\n(ஆகவே, பொய்யாக்கியவர்களின் முடிவு என்னவாயிற்று என்று பாரும்) அதாவது, அவர்களுக்கு என்ன நேர்ந்தது என்பதையும், அவர்கள் எவ்வாறு அழிக்கப்பட்டார்கள் என்பதையும், அல்லாஹ் இறைநம்பிக்கையாளர்களை எவ்வாறு காப்பாற்றினான் என்பதையும் பாருங்கள்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"இணைவைப்பவர்களிடம் எந்த ஆதாரமும் இல்லை\n\r\n\n\r\nஅல்லாஹ்வைத் தவிர மற்றவர்களை வணங்குவதற்கு எவ்வித ஆதாரமும் சான்றும் இல்லாத நிலையில், அவ்வாறு செய்யும் இணைவைப்பவர்களை அல்லாஹ் கண்டிக்கிறான். ﴾أَمْ آتَيْنَاهُمْ كِتَابًا مِّن قَبْلِهِ﴿\n\r\n\n\r\n(அல்லது இதற்கு முன்னர் நாம் அவர்களுக்கு ஏதேனும் ஒரு வேதத்தை வழங்கியுள்ளோமா?) அதாவது, அவர்கள் இணைவைக்கத் தொடங்குவதற்கு முன்பாக. ﴾فَهُم بِهِ مُسْتَمْسِكُونَ﴿\n\r\n\n\r\n(அதனை அவர்கள் உறுதியாகப் பற்றிக்கொண்டிருக்கிறார்களா?) அதாவது, அவர்கள் செய்து கொண்டிருக்கும் காரியங்களுக்கு ஆதரவாக. ஆனால், உண்மை அவ்வாறில்லை. இது பின்வரும் வசனத்தைப் போன்றது: ﴾أَمْ أَنزَلْنَا عَلَيْهِمْ سُلْطَانًا فَهُوَ يَتَكَلَّمُ بِمَا كَانُواْ بِهِ يُشْرِكُونَ ﴿\n\r\n\n\r\n(அல்லது அவர்கள் இணைவைப்பவை பற்றிப் பேசக்கூடிய ஓர் ஆதாரத்தை (வேதத்தை) நாம் அவர்களுக்கு இறக்கியுள்ளோமா?) (30:35) அதாவது, அவ்வாறு எதுவும் நடக்கவில்லை. பிறகு அல்லாஹ் கூறுகிறான்: ﴾بَلْ قَالُواْ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم مُّهْتَدُونَ ﴿\n\r\n\n\r\n(மாறாக அவர்கள் கூறுகிறார்கள்: \"நிச்சயமாக நாங்கள் எங்கள் மூதாதையரை ஒரு குறிப்பிட்ட வழியிலும் மார்க்கத்திலும் (உம்மத்) கண்டோம்; நாங்கள் அவர்களின் அடிச்சுவடுகளையே பின்பற்றி வழிகாட்டப்படுகிறோம்.\") அதாவது, ஒரு குறிப்பிட்ட உம்மத் அல்லது வழியை (மார்க்கத்தை)ப் பின்பற்றிய தங்கள் தந்தைமார்களையும் மூதாதையர்களையும் கண்மூடித்தனமாகப் பின்பற்றுவதைத் தவிர, இணைவைப்பதில் அவர்களுக்கு வேறு எந்த அடிப்படையும் இல்லை. 'உம்மத்' என்ற வார்த்தை இதே போன்ற பொருளில் வேறோர் இடத்திலும் பயன்படுத்தப்பட்டுள்ளது. அங்கு அல்லாஹ் கூறுகிறான்: ﴾إِنَّ هَذِهِ أُمَّتُكُمْ أُمَّةً وَاحِدَةً﴿\n\r\n\n\r\n(நிச்சயமாக, உங்களுடைய இந்த மார்க்கம் (உம்மத்) ஒரே மார்க்கம்தான்) (23:52). மேலும் அவர்கள் கூறினார்கள்: ﴾وَإِنَّا عَلَى آثَارِهِم﴿\n\r\n\n\r\n(நாங்கள் அவர்களின் அடிச்சுவடுகளிலேயே) அதாவது அவர்களுக்குப் பின்னால் ﴾مُّهْتَدُونَ﴿\n\r\n\n\r\n(நாங்கள் வழிகாட்டப்படுகிறோம்). இது எவ்வித ஆதாரமும் இல்லாத அவர்களின் வெற்றுக் கூற்றாகும். தூதர்களை நிராகரித்த கடந்த கால சமூகங்களில் இவர்களைப் போன்றவர்கள் ஏற்கனவே கூறியவற்றையே இந்த மக்களும் கூறுகிறார்கள் என்பதை அல்லாஹ் சுட்டிக்காட்டுகிறான். அவர்களின் இதயங்களும் பேச்சுகளும் ஒன்றுபோலவே இருக்கின்றன. ﴾كَذَلِكَ مَآ أَتَى الَّذِينَ مِن قَبْلِهِمْ مِّن رَّسُولٍ إِلاَّ قَالُواْ سَـحِرٌ أَوْ مَجْنُونٌ - أَتَوَاصَوْاْ بِهِ بَلْ هُمْ قَوْمٌ طَاغُونَ ﴿\n\r\n\n\r\n(இவ்வாறே, அவர்களுக்கு முன் வாழ்ந்தவர்களிடம் எந்தத் தூதர் வந்தபோதும், அவர்கள் \"இவர் ஒரு சூனியக்காரர் அல்லது ஒரு பைத்தியக்காரர்!\" என்று கூறாமல் இருக்கவில்லை. இதனை அவர்கள் (ஒருவருக்கொருவர்) வஸிய்யத் செய்து சென்றார்களா? இல்லை, அவர்களே வரம்பு மீறிய கூட்டத்தினராக இருக்கின்றனர்!) (51:52-53). மேலும் அல்லாஹ் இங்கே கூறுகிறான்: ﴾وَكَذَلِكَ مَآ أَرْسَلْنَا مِن قَبْلِكَ فِى قَرْيَةٍ مِّن نَّذِيرٍ إِلاَّ قَالَ مُتْرَفُوهَآ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم مُّقْتَدُونَ ﴿\n\r\n\n\r\n(மேலும் இவ்வாறே, உமக்கு முன்னர் எந்த ஊருக்கும் நாம் ஓர் எச்சரிக்கையாளரை அனுப்பியபோதெல்லாம், அங்கிருந்த வசதிபடைத்தவர்கள், \"நிச்சயமாக நாங்கள் எங்கள் மூதாதையரை ஒரு மார்க்கத்தில் கண்டோம்; நிச்சயமாக நாங்கள் அவர்களின் அடிச்சுவடுகளையே பின்பற்றுவோம்\" என்று கூறாமல் இருக்கவில்லை.) பிறகு அவன் கூறுகிறான்: ﴾قُلْ﴿\n\r\n\n\r\n(கூறுவீராக) -- முஹம்மதே (ஸல்)! இந்த இணைவைப்பாளர்களிடம் -- ﴾أَوَلَوْ جِئْتُكُمْ بِأَهْدَى مِمَّا وَجَدتُّمْ عَلَيْهِ ءَابَآءَكُمْ قَالُواْ إِنَّا بِمَآ أُرْسِلْتُمْ بِهِ كَافِرُونَ﴿\n\r\n\n\r\n(\"உங்கள் மூதாதையர் எதைப் பின்பற்றிக் கொண்டிருந்தார்களோ, அதைவிடச் சிறந்த வழிகாட்டுதலை நான் உங்களிடம் கொண்டு வந்தாலும் (நீங்கள் இதையே கூறுவீர்களா)?\" அதற்கு அவர்கள், \"நிச்சயமாக நீங்கள் எதைக் கொண்டு அனுப்பப்பட்டுள்ளீர்களோ, அதை நாங்கள் நிராகரிக்கிறோம்\" என்று கூறினார்கள்.) 'நீர் கொண்டு வந்தவை சத்தியம் என்பதை அவர்கள் உறுதியாக அறிந்திருந்தாலும், அவர்களின் தீய எண்ணங்கள் காரணமாகவும், சத்தியத்தின் மீதும் சத்தியத்தைப் பின்பற்றுபவர்கள் மீதும் அவர்கள் கொண்டுள்ள கர்வத்தின் காரணமாகவும் அதனைப் பின்பற்ற மாட்டார்கள்.' ﴾فَانتَقَمْنَا مِنْهُمْ﴿\n\r\n\n\r\n(ஆகவே, நாம் அவர்களைப் பழிவாங்கினோம்) அதாவது, நிராகரித்த சமூகங்கள் மீது பல்வேறு வகையான தண்டனைகளை இறக்கினான். இதனை அந்தச் சமூகங்களின் வரலாறுகளில் அல்லாஹ் விவரித்துள்ளான். ﴾فَانظُرْ كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ﴿\n\r\n\n\r\n(ஆகவே, பொய்யாக்கியவர்களின் முடிவு என்னவாயிற்று என்று பாரும்) அதாவது, அவர்களுக்கு என்ன நேர்ந்தது என்பதையும், அவர்கள் எவ்வாறு அழிக்கப்பட்டார்கள் என்பதையும், அல்லாஹ் இறைநம்பிக்கையாளர்களை எவ்வாறு காப்பாற்றினான் என்பதையும் பாருங்கள்."},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=35\" class=\"link\">43:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:35 ஐ பார்க்கவும்"},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=35\" class=\"link\">43:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:35 ஐ பார்க்கவும்"},"28":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=35\" class=\"link\">43:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:35 ஐ பார்க்கவும்"},"29":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=35\" class=\"link\">43:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:35 ஐ பார்க்கவும்"},"30":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=35\" class=\"link\">43:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:35 ஐ பார்க்கவும்"},"31":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=35\" class=\"link\">43:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:35 ஐ பார்க்கவும்"},"32":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=35\" class=\"link\">43:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:35 ஐ பார்க்கவும்"},"33":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=35\" class=\"link\">43:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:35 ஐ பார்க்கவும்"},"34":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=35\" class=\"link\">43:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:35 ஐ பார்க்கவும்"},"35":{"html":"<strong>இப்ராஹீம் (அலை) அவர்களின் ஏகத்துவப் பிரகடனம்</strong><br />\r\n<br />\r\nஅல்லாஹ் தனது அடியாரும், தூதரும், உற்ற நண்பரும் (கலீல்), ஏகத்துவவாதிகளின் தலைவரும், அவருக்குப் பின் வந்த அனைத்து நபிமார்களின் தந்தையுமான இப்ராஹீம் (அலை) அவர்களைப் பற்றி நமக்குக் கூறுகிறான். குறைஷியர் இவருடைய வம்சாவளியில் வந்தவர்கள் என்பதோடு, தாங்கள் இவருடைய மார்க்கத்தைப் பின்பற்றுவதாகவும் வாதிட்டனர். அவர் தன் தந்தையும் அவரது சமூகத்தாரும் சிலைகளை வணங்குவதை விட்டு விலகி இவ்வாறு கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذْ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">إِبْرَاهِيمُ</span> <span class=\"quran-arabic-font text-success\">لِأَبِيهِ</span> <span class=\"quran-arabic-font text-success\">وَقَوْمِهِ</span> <span class=\"quran-arabic-font text-success\">إِنَّنِى</span> <span class=\"quran-arabic-font text-success\">بَرَآءٌ</span> <span class=\"quran-arabic-font text-success\">مِّمَّا</span> <span class=\"quran-arabic-font text-success\">تَعْبُدُونَ</span> - <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">فَطَرَنِى</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">سَيَهْدِينِ</span> <span class=\"quran-arabic-font text-success\">وَجَعَلَهَا</span> <span class=\"quran-arabic-font text-success\">كَلِمَةً</span> <span class=\"quran-arabic-font text-success\">بَاقِيَةً</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">عَقِبِهِ</span><br />\r\n<br />\r\n(\"நிச்சயமாக, நீங்கள் வணங்குபவற்றை விட்டும் நான் விலகிக் கொண்டேன்; என்னைப் படைத்தவனைத் தவிர. நிச்சயமாக அவன் எனக்கு நேர்வழி காட்டுவான்.\" மேலும், அவர் இதனைத் தன் சந்ததியினரிடையே நிலைத்திருக்கும் ஒரு வார்த்தையாக ஆக்கினார்கள்.) 'அந்த வார்த்தை' என்பது எவ்வித இணையுமின்றி அல்லாஹ்வை மட்டும் வணங்குவதையும், அவனைத் தவிர மற்ற அனைத்து தெய்வங்களையும் நிராகரிப்பதையும் குறிக்கிறது; அதாவது 'லா இலாஹ இல்லல்லாஹ்'. அல்லாஹ்வினால் நேர்வழி காட்டப்பட்ட தன் சந்ததியினர் பின்பற்றுவதற்காக ஒரு முன்மாதிரியாக இந்த வார்த்தையை அவர் விட்டுச் சென்றார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَعَلَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَرْجِعُونَ</span><br />\r\n<br />\r\n(அவர்கள் திரும்பி வரும் பொருட்டு.) அதாவது, இந்த வார்த்தையின் பக்கம் அவர்கள் திரும்பி வருவதற்காக. இக்ரிமா, முஜாஹித், அத்-தஹ்ஹாக், கதாதா, அஸ்-ஸுத்தீ மற்றும் பலர் இந்த வசனத்திற்கு விளக்கமளிக்கும்போது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلَهَا</span> <span class=\"quran-arabic-font text-success\">كَلِمَةً</span> <span class=\"quran-arabic-font text-success\">بَاقِيَةً</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">عَقِبِهِ</span><br />\r\n<br />\r\n(மேலும் அவர் அதைத் தன் சந்ததியினரிடையே நிலைத்திருக்கும் ஒரு வார்த்தையாக ஆக்கினார்கள்,) \"இதன் பொருள் 'லா இலாஹ இல்லல்லாஹ்' என்பதாகும். இன்றும் அவரது சந்ததியினரிடையே இதைக் கூறுபவர்கள் இருந்து கொண்டே இருக்கிறார்கள்\" என்று கூறியுள்ளனர். இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்தும் இது போன்ற ஒரு கருத்து அறிவிக்கப்பட்டுள்ளது. இப்னு ஜைத் (ரஹ்) அவர்கள், \"இது 'இஸ்லாத்தின் வார்த்தை'யைக் குறிக்கும்\" என்று கூறினார்கள். இதுவும் மேற்கண்ட அறிஞர்கள் குறிப்பிட்ட அதே கருத்தையே குறிக்கிறது.<br />\r\n<br />\r\n<strong>மக்காவாசிகள் எவ்வாறு தூதரைப் புறக்கணித்து அவரை எதிர்த்தார்கள்; அதற்கு அல்லாஹ்வின் பதில்</strong><br />\r\n<br />\r\nஅல்லாஹ் மேலும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">مَتَّعْتُ</span> <span class=\"quran-arabic-font text-success\">هَـؤُلاَءِ</span><br />\r\n<br />\r\n(மாறாக, இவர்களுக்கு வழங்கினேன்) அதாவது இந்த இணைவைப்பாளர்களுக்கு,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَءَابَآءَهُمْ</span><br />\r\n<br />\r\n(மற்றும் அவர்களுடைய தந்தையர்களுக்கும்) அதாவது, அவர்கள் தங்கள் வழிகேட்டிலேயே நீண்ட காலம் வாழ்ந்தார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">جَآءَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">وَرَسُولٌ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٌ</span><br />\r\n<br />\r\n(சத்தியமும், தெளிவுபடுத்தும் ஒரு தூதரும் அவர்களிடம் வரும் வரை.) அதாவது, அந்தத் தூதரின் செய்தியும் அவரது எச்சரிக்கையும் மிகத் தெளிவாக இருந்தது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَمَّا</span> <span class=\"quran-arabic-font text-success\">جَآءَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">سِحْرٌ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">كَافِرُونَ</span><br />\r\n<br />\r\n(சத்தியம் அவர்களிடம் வந்தபோது, அவர்கள்: \"இது ஒரு சூனியம்; நிச்சயமாக நாங்கள் இதனை நிராகரிக்கிறோம்\" என்று கூறினார்கள்.) அதாவது, அவர்கள் கர்வத்துடனும் பிடிவாதத்துடனும் நடந்து கொண்டனர். பொறாமை, வரம்புமீறல் மற்றும் நிராகரிப்பின் காரணமாக அவரைப் புறக்கணித்தனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالُواْ</span><br />\r\n<br />\r\n(மேலும் அவர்கள் கூறுகிறார்கள்) அதாவது, அல்லாஹ் அவருக்கு வஹீ (இறைச்செய்தி)யாக அருளியதை ஆட்சேபித்து அவர்கள் கூறியதாவது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَوْلاَ</span> <span class=\"quran-arabic-font text-success\">نُزِّلَ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَجُلٍ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْقَرْيَتَيْنِ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٍ</span><br />\r\n<br />\r\n(இந்த குர்ஆன், இவ்விரு ஊர்களிலுள்ள ஏதேனும் ஒரு பெரிய மனிதர் மீது இறக்கப்பட்டிருக்க வேண்டாமா?) அதாவது, இவர்களின் பார்வையில் கண்ணியமிக்கவர்களாகவும் பிரமுகர்களாகவும் இருந்த மக்கா அல்லது தாஇஃப் நகரங்களில் உள்ள ஒரு மனிதர் மீது இந்த குர்ஆன் ஏன் வஹீ (இறைச்செய்தி)யாக அருளப்படவில்லை? என்று கேட்டனர். இது இப்னு அப்பாஸ் (ரழி), இக்ரிமா, முஹம்மது பின் கஅப் அல்-குரழீ, கதாதா, அஸ்-ஸுத்தீ மற்றும் இப்னு ஜைத் ஆகியோரின் கருத்தாகும். பல தஃப்ஸீர் அறிஞர்கள், குறைஷியர் இதன் மூலம் அல்-வலீத் பின் அல்-முஃகீரா மற்றும் உர்வா பின் மஸ்ஊத் அத்-தகஃபீ ஆகியோரையே குறிப்பிட்டதாகக் கூறுகின்றனர். வெளிப்படையான பொருள் என்னவென்றால், அவர்கள் இவ்விரு நகரங்களில் ஏதேனும் ஒன்றிலிருந்து ஒரு பெரிய மனிதரைக் குறிப்பிட்டனர் என்பதாகும். அவர்களின் இந்த நிராகரிப்பிற்கு அல்லாஹ் இவ்வாறு பதிலளிக்கிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَقْسِمُونَ</span> <span class=\"quran-arabic-font text-success\">رَحْمَةَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span><br />\r\n<br />\r\n(உமது இறைவனின் அருளை இவர்களா பங்கிடுகிறார்கள்?) அதாவது, இவ்விஷயத்தில் தீர்மானிக்கும் அதிகாரம் அவர்களுக்கு இல்லை; அது அல்லாஹ்விடமே உள்ளது. தனது தூதுத்துவச் செய்தியை யாரிடம் ஒப்படைக்க வேண்டும் என்பதை அல்லாஹ்வே நன்கறிவான். உள்ளத்தாலும் ஆன்மாவாலும் மிகவும் தூய்மையான, கண்ணியமான வம்சாவளியைச் சேர்ந்த ஒருவருக்கே தவிர அவன் இதனை வஹீ (இறைச்செய்தி)யாக அருள மாட்டான். பிறகு, தனது படைப்பினங்களுக்கு செல்வம், வாழ்வாதாரம், அறிவு, புரிதல் மற்றும் பிற வெளிப்படையான, மறைவான ஆற்றல்களை வழங்குவதில் தான் வேறுபடுத்தி வைத்திருப்பதை அல்லாஹ் சுட்டிக்காட்டுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">قَسَمْنَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّعِيشَتَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَرَفَعْنَا</span> <span class=\"quran-arabic-font text-success\">بَعْضَهُمْ</span> <span class=\"quran-arabic-font text-success\">فَوْقَ</span> <span class=\"quran-arabic-font text-success\">بَعْضٍ</span> <span class=\"quran-arabic-font text-success\">دَرَجَاتٍ</span><br />\r\n<br />\r\n(இவ்வுலக வாழ்வில் அவர்களின் வாழ்வாதாரத்தை நாமே அவர்களுக்கு இடையே பங்கிட்டுள்ளோம். மேலும், அவர்களில் ஒருவர் மற்றவரை ஊழியராக ஆக்கிக் கொள்ளும் பொருட்டு, அவர்களில் சிலரை வேறு சிலரை விடத் தரங்களில் நாம் உயர்த்தியுள்ளோம்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِّيَتَّخِذَ</span> <span class=\"quran-arabic-font text-success\">بَعْضُهُم</span> <span class=\"quran-arabic-font text-success\">بَعْضاً</span> <span class=\"quran-arabic-font text-success\">سُخْرِيّاً</span><br />\r\n<br />\r\n(சிலர் சிலரை வேலைக்கு அமர்த்திக் கொள்வதற்காக.) ஒருவருக்கொருவர் தேவைப்படுவதால் ஒருவர் மற்றவரைப் பணியில் அமர்த்திக் கொள்கின்றனர் என்று அஸ்-ஸுத்தீ போன்றோர் விளக்குகின்றனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَرَحْمَةُ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">مِّمَّا</span> <span class=\"quran-arabic-font text-success\">يَجْمَعُونَ</span><br />\r\n<br />\r\n(ஆனால் உமது இறைவனின் அருள், அவர்கள் சேகரித்து வைத்திருப்பதை விட மிகச் சிறந்தது.) அதாவது, அல்லாஹ் தனது படைப்பினங்களுக்கு வழங்கும் அருளானது, அவர்கள் பெற்றுள்ள உலகச் செல்வங்களையும் வசதிகளையும் விட மேலானது.<br />\r\n<br />\r\n<strong>செல்வம் இறைவனின் திருப்திக்கான அடையாளம் அல்ல</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْلاَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَكُونَ</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">أُمَّةً</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةً</span><br />\r\n<br />\r\n(மனிதர்கள் அனைவரும் (நிராகரிப்பில்) ஒரே சமுதாயமாக ஆகிவிடுவார்கள் என்பது இல்லையெனில்,) அதாவது, 'செல்வம் கொடுப்பது, நாம் அந்த நபரை நேசிப்பதற்கான அடையாளம் என்று அறியாத மக்கள் கருதி, செல்வத்திற்காக அனைவரும் நிராகரிப்பில் ஒன்றிணைந்து விடுவார்கள் என்ற அச்சம் இல்லையெனில்' (நாங்கள் அவர்களுக்குப் பெரும் வசதிகளைச் செய்திருப்போம்). இது இப்னு அப்பாஸ் (ரழி), அல்-ஹஸன், கதாதா, அஸ்-ஸுத்தீ மற்றும் பலரின் கருத்தாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">لِمَن</span> <span class=\"quran-arabic-font text-success\">يَكْفُرُ</span> <span class=\"quran-arabic-font text-success\">بِالرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">لِبُيُوتِهِمْ</span> <span class=\"quran-arabic-font text-success\">سُقُفاً</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">فِضَّةٍ</span> <span class=\"quran-arabic-font text-success\">وَمَعَارِجَ</span><br />\r\n<br />\r\n(அளவற்ற அருளாளனை நிராகரிப்பவர்களின் வீடுகளுக்கு வெள்ளியாலான கூரைகளையும், அவர்கள் ஏறிச் செல்லும் ஏணிகளையும் நாம் ஆக்கியிருப்போம்.) அதாவது வெள்ளியாலான ஏணிகள் மற்றும் படிக்கட்டுகள். இது இப்னு அப்பாஸ் (ரழி), முஜாஹித், கதாதா, அஸ்-ஸுத்தீ, இப்னு ஜைத் மற்றும் பலரின் கருத்தாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَلَيْهَا</span> <span class=\"quran-arabic-font text-success\">يَظْهَرُونَ</span> <span class=\"quran-arabic-font text-success\">وَلِبُيُوتِهِمْ</span> <span class=\"quran-arabic-font text-success\">أَبْوَاباً</span><br />\r\n<br />\r\n(அதன் மூலம் அவர்கள் ஏறிச் செல்வார்கள்.) அதாவது மேலே செல்வார்கள். மேலும் அவர்களின் வீடுகளுக்கு வாசல்களையும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَسُرُراً</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا</span> <span class=\"quran-arabic-font text-success\">يَتَّكِئُونَ</span><br />\r\n<br />\r\n(மற்றும் அவர்கள் சாய்ந்து அமரும் கட்டில்களையும் சிம்மாசனங்களையும் நாம் ஆக்கியிருப்போம்.) இவை அனைத்தும் வெள்ளியால் செய்யப்பட்டிருக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَزُخْرُفاً</span><br />\r\n<br />\r\n(மற்றும் பல அலங்காரங்களையும்) அதாவது தங்கத்தினால் ஆனவற்றையும் வழங்கியிருப்போம். இது இப்னு அப்பாஸ் (ரழி), கதாதா, அஸ்-ஸுத்தீ மற்றும் இப்னு ஜைத் ஆகியோரின் கருத்தாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لَمَّا</span> <span class=\"quran-arabic-font text-success\">مَتَاعُ</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span><br />\r\n<br />\r\n(ஆயினும் இவை அனைத்தும் இவ்வுலக வாழ்வின் அற்ப இன்பங்களே தவிர வேறில்லை.) அதாவது, இவை அனைத்தும் அல்லாஹ்விடம் எவ்வித மதிப்பும் இல்லாத, அழியக்கூடிய உலகிற்குரியவை. அவர்களின் நற்செயல்களுக்கான கூலியை இவ்வுலகிலேயே சுகபோகங்களாக அவன் அவசரப்படுத்தி வழங்கிவிடுகிறான். அதனால் அவர்கள் மறுமைக்கு வரும்போது, அல்லாஹ்விடம் கூலி பெறுவதற்கு அவர்களிடம் நன்மைகள் எதுவும் இருக்காது என்று ஸஹீஹான ஹதீஸில் கூறப்பட்டுள்ளது. மற்றொரு ஹதீஸில்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">تَزِنُ</span> <span class=\"quran-arabic-font text-success\">عِنْدَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">جَنَاحَ</span> <span class=\"quran-arabic-font text-success\">بَعُوضَةٍ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">سَقَى</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">كَافِرًا</span> <span class=\"quran-arabic-font text-success\">شَرْبَةَ</span> <span class=\"quran-arabic-font text-success\">مَاء</span>»<br />\r\n<br />\r\n(இவ்வுலகம் அல்லாஹ்விடம் ஒரு கொசுவின் இறக்கை அளவுக்கேனும் மதிப்புடையதாக இருந்திருக்குமானால், அவன் ஒரு நிராகரிப்பாளனுக்கு ஒரு மிடறு தண்ணீரைக் கூட கொடுத்திருக்க மாட்டான்.) அல்-பஃகவீ இதன் அறிவிப்பாளர் தொடரைப் பதிவு செய்துள்ளார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالاٌّخِرَةُ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">لِلْمُتَّقِينَ</span><br />\r\n<br />\r\n(மேலும், மறுமை உமது இறைவனிடம் (தக்வா எனும்) இறையச்சம் உடையவர்களுக்கு மட்டுமே உரியது.) அதாவது, அது அவர்களுக்கு மட்டுமே உரித்தானதாகும்; அதில் வேறு எவருக்கும் பங்கில்லை. உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தம் மனைவியரை விட்டுப் பிரிந்து தனிமையில் இருந்தபோது அவர்களைச் சந்திக்கச் சென்றார்கள். அப்போது நபி (ஸல்) அவர்கள் ஒரு கரடுமுரடான பாயில் படுத்திருப்பதையும், அது அவர்களின் விலாப்புறத்தில் தழும்புகளை ஏற்படுத்தி இருப்பதையும் கண்டு உமர் (ரழி) அவர்களின் கண்கள் கலங்கின. \"அல்லாஹ்வின் தூதரே! பாரசீக மன்னர் கிஸ்ராவும் ரோமானிய மன்னர் கைஸரும் சகல வசதிகளுடன் இருக்கிறார்கள். ஆனால் நீங்கள் அல்லாஹ்வின் படைப்பிலேயே சிறந்தவராக இருந்தும் இந்த நிலையில் இருக்கிறீர்களே!\" என்று கூறினார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் நிமிர்ந்து அமர்ந்து:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَوَفِي</span> <span class=\"quran-arabic-font text-success\">شَكٍّ</span> <span class=\"quran-arabic-font text-success\">أَنْتَ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">ابْنَ</span> <span class=\"quran-arabic-font text-success\">الْخَطَّابِ؟</span>»<br />\r\n<br />\r\n(கத்தாபின் மகனே! நீர் இன்னும் சந்தேகத்திலா இருக்கிறீர்?) என்று கேட்டுவிட்டு, பிறகு கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أُولئِكَ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">عُجِّلَتْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">طَيِّبَاتُهُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">حَيَاتِهِمُ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span>»<br />\r\n<br />\r\n(அவர்கள், தங்களுக்குரிய நற்பலன்களை இவ்வுலக வாழ்விலேயே அவசரமாகப் பெற்றுக்கொண்ட ஒரு கூட்டத்தினர்.) மற்றொரு அறிவிப்பில்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَمَا</span> <span class=\"quran-arabic-font text-success\">تَرْضَى</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تَكُونَ</span> <span class=\"quran-arabic-font text-success\">لَهُمُ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَلَنَا</span> <span class=\"quran-arabic-font text-success\">الْاخِرَة</span>»<br />\r\n<br />\r\n(இவ்வுலகம் அவர்களுக்கும் மறுமை நமக்கும் என்பதில் உமக்குத் திருப்தி இல்லையா?) என்று கேட்டார்கள். புகாரி மற்றும் முஸ்லிம் உள்ளிட்ட நூல்களில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறியதாகப் பதிவாகியுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَشْرَبُوا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">آنِيَةِ</span> <span class=\"quran-arabic-font text-success\">الذَّهَبِ</span> <span class=\"quran-arabic-font text-success\">وَالْفِضَّةِ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَأْكُلُوا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">صِحَافِهَا،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهَا</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَلَنَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْاخِرَة</span>»<br />\r\n<br />\r\n(நீங்கள் தங்கம் மற்றும் வெள்ளிப் பாத்திரங்களில் பருகாதீர்கள்; அவற்றால் ஆன தட்டுகளில் உண்ணாதீர்கள். ஏனெனில் அவை இவ்வுலகில் அவர்களுக்கும், மறுமையில் நமக்கும் உரியவை.) இவ்வுலகம் அற்பமானது என்பதால்தான் அல்லாஹ் இவைகளை அவர்களுக்கு வழங்கியுள்ளான். அத்-திர்மிதீ மற்றும் இப்னு மாஜா ஆகியோரின் பதிவில், அபூ ஹாஸிம் வழியாக ஸஹ்ல் பின் ஸஅத் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">كَانَتِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">تَزِنُ</span> <span class=\"quran-arabic-font text-success\">عِنْدَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">جَنَاحَ</span> <span class=\"quran-arabic-font text-success\">بَعُوضَةٍ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">سَقَى</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">كَافِرًا</span> <span class=\"quran-arabic-font text-success\">شَرْبَةَ</span> <span class=\"quran-arabic-font text-success\">مَاءٍ</span> <span class=\"quran-arabic-font text-success\">أَبَدًا</span>»<br />\r\n<br />\r\n(அல்லாஹ்விடம் இவ்வுலகம் ஒரு கொசுவின் இறக்கையளவு மதிப்புடையதாக இருந்திருந்தால், அவன் ஒரு நிராகரிப்பாளனுக்கு ஒருபோதும் ஒரு மிடறு தண்ணீரைக் கூட கொடுத்திருக்க மாட்டான்.)\" இமாம் திர்மிதீ இதனை \"ஹஸன் ஸஹீஹ்\" என்று குறிப்பிட்டுள்ளார்.<br />\r\n<br />","text":"இப்ராஹீம் (அலை) அவர்களின் ஏகத்துவப் பிரகடனம்\n\r\n\n\r\nஅல்லாஹ் தனது அடியாரும், தூதரும், உற்ற நண்பரும் (கலீல்), ஏகத்துவவாதிகளின் தலைவரும், அவருக்குப் பின் வந்த அனைத்து நபிமார்களின் தந்தையுமான இப்ராஹீம் (அலை) அவர்களைப் பற்றி நமக்குக் கூறுகிறான். குறைஷியர் இவருடைய வம்சாவளியில் வந்தவர்கள் என்பதோடு, தாங்கள் இவருடைய மார்க்கத்தைப் பின்பற்றுவதாகவும் வாதிட்டனர். அவர் தன் தந்தையும் அவரது சமூகத்தாரும் சிலைகளை வணங்குவதை விட்டு விலகி இவ்வாறு கூறினார்கள்:\n\r\n\n\r\nوَإِذْ قَالَ إِبْرَاهِيمُ لِأَبِيهِ وَقَوْمِهِ إِنَّنِى بَرَآءٌ مِّمَّا تَعْبُدُونَ - إِلاَّ الَّذِى فَطَرَنِى فَإِنَّهُ سَيَهْدِينِ وَجَعَلَهَا كَلِمَةً بَاقِيَةً فِى عَقِبِهِ\n\r\n\n\r\n(\"நிச்சயமாக, நீங்கள் வணங்குபவற்றை விட்டும் நான் விலகிக் கொண்டேன்; என்னைப் படைத்தவனைத் தவிர. நிச்சயமாக அவன் எனக்கு நேர்வழி காட்டுவான்.\" மேலும், அவர் இதனைத் தன் சந்ததியினரிடையே நிலைத்திருக்கும் ஒரு வார்த்தையாக ஆக்கினார்கள்.) 'அந்த வார்த்தை' என்பது எவ்வித இணையுமின்றி அல்லாஹ்வை மட்டும் வணங்குவதையும், அவனைத் தவிர மற்ற அனைத்து தெய்வங்களையும் நிராகரிப்பதையும் குறிக்கிறது; அதாவது 'லா இலாஹ இல்லல்லாஹ்'. அல்லாஹ்வினால் நேர்வழி காட்டப்பட்ட தன் சந்ததியினர் பின்பற்றுவதற்காக ஒரு முன்மாதிரியாக இந்த வார்த்தையை அவர் விட்டுச் சென்றார்கள்.\n\r\n\n\r\nلَعَلَّهُمْ يَرْجِعُونَ\n\r\n\n\r\n(அவர்கள் திரும்பி வரும் பொருட்டு.) அதாவது, இந்த வார்த்தையின் பக்கம் அவர்கள் திரும்பி வருவதற்காக. இக்ரிமா, முஜாஹித், அத்-தஹ்ஹாக், கதாதா, அஸ்-ஸுத்தீ மற்றும் பலர் இந்த வசனத்திற்கு விளக்கமளிக்கும்போது:\n\r\n\n\r\nوَجَعَلَهَا كَلِمَةً بَاقِيَةً فِى عَقِبِهِ\n\r\n\n\r\n(மேலும் அவர் அதைத் தன் சந்ததியினரிடையே நிலைத்திருக்கும் ஒரு வார்த்தையாக ஆக்கினார்கள்,) \"இதன் பொருள் 'லா இலாஹ இல்லல்லாஹ்' என்பதாகும். இன்றும் அவரது சந்ததியினரிடையே இதைக் கூறுபவர்கள் இருந்து கொண்டே இருக்கிறார்கள்\" என்று கூறியுள்ளனர். இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்தும் இது போன்ற ஒரு கருத்து அறிவிக்கப்பட்டுள்ளது. இப்னு ஜைத் (ரஹ்) அவர்கள், \"இது 'இஸ்லாத்தின் வார்த்தை'யைக் குறிக்கும்\" என்று கூறினார்கள். இதுவும் மேற்கண்ட அறிஞர்கள் குறிப்பிட்ட அதே கருத்தையே குறிக்கிறது.\n\r\n\n\r\nமக்காவாசிகள் எவ்வாறு தூதரைப் புறக்கணித்து அவரை எதிர்த்தார்கள்; அதற்கு அல்லாஹ்வின் பதில்\n\r\n\n\r\nஅல்லாஹ் மேலும் கூறுகிறான்:\n\r\n\n\r\nبَلْ مَتَّعْتُ هَـؤُلاَءِ\n\r\n\n\r\n(மாறாக, இவர்களுக்கு வழங்கினேன்) அதாவது இந்த இணைவைப்பாளர்களுக்கு,\n\r\n\n\r\nوَءَابَآءَهُمْ\n\r\n\n\r\n(மற்றும் அவர்களுடைய தந்தையர்களுக்கும்) அதாவது, அவர்கள் தங்கள் வழிகேட்டிலேயே நீண்ட காலம் வாழ்ந்தார்கள்.\n\r\n\n\r\nحَتَّى جَآءَهُمُ الْحَقُّ وَرَسُولٌ مُّبِينٌ\n\r\n\n\r\n(சத்தியமும், தெளிவுபடுத்தும் ஒரு தூதரும் அவர்களிடம் வரும் வரை.) அதாவது, அந்தத் தூதரின் செய்தியும் அவரது எச்சரிக்கையும் மிகத் தெளிவாக இருந்தது.\n\r\n\n\r\nوَلَمَّا جَآءَهُمُ الْحَقُّ قَالُواْ هَـذَا سِحْرٌ وَإِنَّا بِهِ كَافِرُونَ\n\r\n\n\r\n(சத்தியம் அவர்களிடம் வந்தபோது, அவர்கள்: \"இது ஒரு சூனியம்; நிச்சயமாக நாங்கள் இதனை நிராகரிக்கிறோம்\" என்று கூறினார்கள்.) அதாவது, அவர்கள் கர்வத்துடனும் பிடிவாதத்துடனும் நடந்து கொண்டனர். பொறாமை, வரம்புமீறல் மற்றும் நிராகரிப்பின் காரணமாக அவரைப் புறக்கணித்தனர்.\n\r\n\n\r\nوَقَالُواْ\n\r\n\n\r\n(மேலும் அவர்கள் கூறுகிறார்கள்) அதாவது, அல்லாஹ் அவருக்கு வஹீ (இறைச்செய்தி)யாக அருளியதை ஆட்சேபித்து அவர்கள் கூறியதாவது:\n\r\n\n\r\nلَوْلاَ نُزِّلَ هَـذَا الْقُرْءَانُ عَلَى رَجُلٍ مِّنَ الْقَرْيَتَيْنِ عَظِيمٍ\n\r\n\n\r\n(இந்த குர்ஆன், இவ்விரு ஊர்களிலுள்ள ஏதேனும் ஒரு பெரிய மனிதர் மீது இறக்கப்பட்டிருக்க வேண்டாமா?) அதாவது, இவர்களின் பார்வையில் கண்ணியமிக்கவர்களாகவும் பிரமுகர்களாகவும் இருந்த மக்கா அல்லது தாஇஃப் நகரங்களில் உள்ள ஒரு மனிதர் மீது இந்த குர்ஆன் ஏன் வஹீ (இறைச்செய்தி)யாக அருளப்படவில்லை? என்று கேட்டனர். இது இப்னு அப்பாஸ் (ரழி), இக்ரிமா, முஹம்மது பின் கஅப் அல்-குரழீ, கதாதா, அஸ்-ஸுத்தீ மற்றும் இப்னு ஜைத் ஆகியோரின் கருத்தாகும். பல தஃப்ஸீர் அறிஞர்கள், குறைஷியர் இதன் மூலம் அல்-வலீத் பின் அல்-முஃகீரா மற்றும் உர்வா பின் மஸ்ஊத் அத்-தகஃபீ ஆகியோரையே குறிப்பிட்டதாகக் கூறுகின்றனர். வெளிப்படையான பொருள் என்னவென்றால், அவர்கள் இவ்விரு நகரங்களில் ஏதேனும் ஒன்றிலிருந்து ஒரு பெரிய மனிதரைக் குறிப்பிட்டனர் என்பதாகும். அவர்களின் இந்த நிராகரிப்பிற்கு அல்லாஹ் இவ்வாறு பதிலளிக்கிறான்:\n\r\n\n\r\nأَهُمْ يَقْسِمُونَ رَحْمَةَ رَبِّكَ\n\r\n\n\r\n(உமது இறைவனின் அருளை இவர்களா பங்கிடுகிறார்கள்?) அதாவது, இவ்விஷயத்தில் தீர்மானிக்கும் அதிகாரம் அவர்களுக்கு இல்லை; அது அல்லாஹ்விடமே உள்ளது. தனது தூதுத்துவச் செய்தியை யாரிடம் ஒப்படைக்க வேண்டும் என்பதை அல்லாஹ்வே நன்கறிவான். உள்ளத்தாலும் ஆன்மாவாலும் மிகவும் தூய்மையான, கண்ணியமான வம்சாவளியைச் சேர்ந்த ஒருவருக்கே தவிர அவன் இதனை வஹீ (இறைச்செய்தி)யாக அருள மாட்டான். பிறகு, தனது படைப்பினங்களுக்கு செல்வம், வாழ்வாதாரம், அறிவு, புரிதல் மற்றும் பிற வெளிப்படையான, மறைவான ஆற்றல்களை வழங்குவதில் தான் வேறுபடுத்தி வைத்திருப்பதை அல்லாஹ் சுட்டிக்காட்டுகிறான்:\n\r\n\n\r\nنَحْنُ قَسَمْنَا بَيْنَهُمْ مَّعِيشَتَهُمْ فِى الْحَيَوةِ الدُّنْيَا وَرَفَعْنَا بَعْضَهُمْ فَوْقَ بَعْضٍ دَرَجَاتٍ\n\r\n\n\r\n(இவ்வுலக வாழ்வில் அவர்களின் வாழ்வாதாரத்தை நாமே அவர்களுக்கு இடையே பங்கிட்டுள்ளோம். மேலும், அவர்களில் ஒருவர் மற்றவரை ஊழியராக ஆக்கிக் கொள்ளும் பொருட்டு, அவர்களில் சிலரை வேறு சிலரை விடத் தரங்களில் நாம் உயர்த்தியுள்ளோம்.)\n\r\n\n\r\nلِّيَتَّخِذَ بَعْضُهُم بَعْضاً سُخْرِيّاً\n\r\n\n\r\n(சிலர் சிலரை வேலைக்கு அமர்த்திக் கொள்வதற்காக.) ஒருவருக்கொருவர் தேவைப்படுவதால் ஒருவர் மற்றவரைப் பணியில் அமர்த்திக் கொள்கின்றனர் என்று அஸ்-ஸுத்தீ போன்றோர் விளக்குகின்றனர்.\n\r\n\n\r\nوَرَحْمَةُ رَبِّكَ خَيْرٌ مِّمَّا يَجْمَعُونَ\n\r\n\n\r\n(ஆனால் உமது இறைவனின் அருள், அவர்கள் சேகரித்து வைத்திருப்பதை விட மிகச் சிறந்தது.) அதாவது, அல்லாஹ் தனது படைப்பினங்களுக்கு வழங்கும் அருளானது, அவர்கள் பெற்றுள்ள உலகச் செல்வங்களையும் வசதிகளையும் விட மேலானது.\n\r\n\n\r\nசெல்வம் இறைவனின் திருப்திக்கான அடையாளம் அல்ல\n\r\n\n\r\nوَلَوْلاَ أَن يَكُونَ النَّاسُ أُمَّةً وَاحِدَةً\n\r\n\n\r\n(மனிதர்கள் அனைவரும் (நிராகரிப்பில்) ஒரே சமுதாயமாக ஆகிவிடுவார்கள் என்பது இல்லையெனில்,) அதாவது, 'செல்வம் கொடுப்பது, நாம் அந்த நபரை நேசிப்பதற்கான அடையாளம் என்று அறியாத மக்கள் கருதி, செல்வத்திற்காக அனைவரும் நிராகரிப்பில் ஒன்றிணைந்து விடுவார்கள் என்ற அச்சம் இல்லையெனில்' (நாங்கள் அவர்களுக்குப் பெரும் வசதிகளைச் செய்திருப்போம்). இது இப்னு அப்பாஸ் (ரழி), அல்-ஹஸன், கதாதா, அஸ்-ஸுத்தீ மற்றும் பலரின் கருத்தாகும்.\n\r\n\n\r\nلَّجَعَلْنَا لِمَن يَكْفُرُ بِالرَّحْمَـنِ لِبُيُوتِهِمْ سُقُفاً مِّن فِضَّةٍ وَمَعَارِجَ\n\r\n\n\r\n(அளவற்ற அருளாளனை நிராகரிப்பவர்களின் வீடுகளுக்கு வெள்ளியாலான கூரைகளையும், அவர்கள் ஏறிச் செல்லும் ஏணிகளையும் நாம் ஆக்கியிருப்போம்.) அதாவது வெள்ளியாலான ஏணிகள் மற்றும் படிக்கட்டுகள். இது இப்னு அப்பாஸ் (ரழி), முஜாஹித், கதாதா, அஸ்-ஸுத்தீ, இப்னு ஜைத் மற்றும் பலரின் கருத்தாகும்.\n\r\n\n\r\nعَلَيْهَا يَظْهَرُونَ وَلِبُيُوتِهِمْ أَبْوَاباً\n\r\n\n\r\n(அதன் மூலம் அவர்கள் ஏறிச் செல்வார்கள்.) அதாவது மேலே செல்வார்கள். மேலும் அவர்களின் வீடுகளுக்கு வாசல்களையும்,\n\r\n\n\r\nوَسُرُراً عَلَيْهَا يَتَّكِئُونَ\n\r\n\n\r\n(மற்றும் அவர்கள் சாய்ந்து அமரும் கட்டில்களையும் சிம்மாசனங்களையும் நாம் ஆக்கியிருப்போம்.) இவை அனைத்தும் வெள்ளியால் செய்யப்பட்டிருக்கும்.\n\r\n\n\r\nوَزُخْرُفاً\n\r\n\n\r\n(மற்றும் பல அலங்காரங்களையும்) அதாவது தங்கத்தினால் ஆனவற்றையும் வழங்கியிருப்போம். இது இப்னு அப்பாஸ் (ரழி), கதாதா, அஸ்-ஸுத்தீ மற்றும் இப்னு ஜைத் ஆகியோரின் கருத்தாகும்.\n\r\n\n\r\nوَإِن كُلُّ ذَلِكَ لَمَّا مَتَاعُ الْحَيَوةِ الدُّنْيَا\n\r\n\n\r\n(ஆயினும் இவை அனைத்தும் இவ்வுலக வாழ்வின் அற்ப இன்பங்களே தவிர வேறில்லை.) அதாவது, இவை அனைத்தும் அல்லாஹ்விடம் எவ்வித மதிப்பும் இல்லாத, அழியக்கூடிய உலகிற்குரியவை. அவர்களின் நற்செயல்களுக்கான கூலியை இவ்வுலகிலேயே சுகபோகங்களாக அவன் அவசரப்படுத்தி வழங்கிவிடுகிறான். அதனால் அவர்கள் மறுமைக்கு வரும்போது, அல்லாஹ்விடம் கூலி பெறுவதற்கு அவர்களிடம் நன்மைகள் எதுவும் இருக்காது என்று ஸஹீஹான ஹதீஸில் கூறப்பட்டுள்ளது. மற்றொரு ஹதீஸில்:\n\r\n\n\r\n«لَوْ أَنَّ الدُّنْيَا تَزِنُ عِنْدَ اللهِ جَنَاحَ بَعُوضَةٍ مَا سَقَى مِنْهَا كَافِرًا شَرْبَةَ مَاء»\n\r\n\n\r\n(இவ்வுலகம் அல்லாஹ்விடம் ஒரு கொசுவின் இறக்கை அளவுக்கேனும் மதிப்புடையதாக இருந்திருக்குமானால், அவன் ஒரு நிராகரிப்பாளனுக்கு ஒரு மிடறு தண்ணீரைக் கூட கொடுத்திருக்க மாட்டான்.) அல்-பஃகவீ இதன் அறிவிப்பாளர் தொடரைப் பதிவு செய்துள்ளார்.\n\r\n\n\r\nوَالاٌّخِرَةُ عِندَ رَبِّكَ لِلْمُتَّقِينَ\n\r\n\n\r\n(மேலும், மறுமை உமது இறைவனிடம் (தக்வா எனும்) இறையச்சம் உடையவர்களுக்கு மட்டுமே உரியது.) அதாவது, அது அவர்களுக்கு மட்டுமே உரித்தானதாகும்; அதில் வேறு எவருக்கும் பங்கில்லை. உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தம் மனைவியரை விட்டுப் பிரிந்து தனிமையில் இருந்தபோது அவர்களைச் சந்திக்கச் சென்றார்கள். அப்போது நபி (ஸல்) அவர்கள் ஒரு கரடுமுரடான பாயில் படுத்திருப்பதையும், அது அவர்களின் விலாப்புறத்தில் தழும்புகளை ஏற்படுத்தி இருப்பதையும் கண்டு உமர் (ரழி) அவர்களின் கண்கள் கலங்கின. \"அல்லாஹ்வின் தூதரே! பாரசீக மன்னர் கிஸ்ராவும் ரோமானிய மன்னர் கைஸரும் சகல வசதிகளுடன் இருக்கிறார்கள். ஆனால் நீங்கள் அல்லாஹ்வின் படைப்பிலேயே சிறந்தவராக இருந்தும் இந்த நிலையில் இருக்கிறீர்களே!\" என்று கூறினார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் நிமிர்ந்து அமர்ந்து:\n\r\n\n\r\n«أَوَفِي شَكٍّ أَنْتَ يَا ابْنَ الْخَطَّابِ؟»\n\r\n\n\r\n(கத்தாபின் மகனே! நீர் இன்னும் சந்தேகத்திலா இருக்கிறீர்?) என்று கேட்டுவிட்டு, பிறகு கூறினார்கள்:\n\r\n\n\r\n«أُولئِكَ قَوْمٌ عُجِّلَتْ لَهُمْ طَيِّبَاتُهُمْ فِي حَيَاتِهِمُ الدُّنْيَا»\n\r\n\n\r\n(அவர்கள், தங்களுக்குரிய நற்பலன்களை இவ்வுலக வாழ்விலேயே அவசரமாகப் பெற்றுக்கொண்ட ஒரு கூட்டத்தினர்.) மற்றொரு அறிவிப்பில்:\n\r\n\n\r\n«أَمَا تَرْضَى أَنْ تَكُونَ لَهُمُ الدُّنْيَا وَلَنَا الْاخِرَة»\n\r\n\n\r\n(இவ்வுலகம் அவர்களுக்கும் மறுமை நமக்கும் என்பதில் உமக்குத் திருப்தி இல்லையா?) என்று கேட்டார்கள். புகாரி மற்றும் முஸ்லிம் உள்ளிட்ட நூல்களில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறியதாகப் பதிவாகியுள்ளது:\n\r\n\n\r\n«لَا تَشْرَبُوا فِي آنِيَةِ الذَّهَبِ وَالْفِضَّةِ، وَلَا تَأْكُلُوا فِي صِحَافِهَا، فَإِنَّهَا لَهُمْ فِي الدُّنْيَا وَلَنَا فِي الْاخِرَة»\n\r\n\n\r\n(நீங்கள் தங்கம் மற்றும் வெள்ளிப் பாத்திரங்களில் பருகாதீர்கள்; அவற்றால் ஆன தட்டுகளில் உண்ணாதீர்கள். ஏனெனில் அவை இவ்வுலகில் அவர்களுக்கும், மறுமையில் நமக்கும் உரியவை.) இவ்வுலகம் அற்பமானது என்பதால்தான் அல்லாஹ் இவைகளை அவர்களுக்கு வழங்கியுள்ளான். அத்-திர்மிதீ மற்றும் இப்னு மாஜா ஆகியோரின் பதிவில், அபூ ஹாஸிம் வழியாக ஸஹ்ல் பின் ஸஅத் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَوْ كَانَتِ الدُّنْيَا تَزِنُ عِنْدَ اللهِ جَنَاحَ بَعُوضَةٍ مَا سَقَى مِنْهَا كَافِرًا شَرْبَةَ مَاءٍ أَبَدًا»\n\r\n\n\r\n(அல்லாஹ்விடம் இவ்வுலகம் ஒரு கொசுவின் இறக்கையளவு மதிப்புடையதாக இருந்திருந்தால், அவன் ஒரு நிராகரிப்பாளனுக்கு ஒருபோதும் ஒரு மிடறு தண்ணீரைக் கூட கொடுத்திருக்க மாட்டான்.)\" இமாம் திர்மிதீ இதனை \"ஹஸன் ஸஹீஹ்\" என்று குறிப்பிட்டுள்ளார்."},"36":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=45\" class=\"link\">43:45</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:45 ஐ பார்க்கவும்"},"37":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=45\" class=\"link\">43:45</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:45 ஐ பார்க்கவும்"},"38":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=45\" class=\"link\">43:45</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:45 ஐ பார்க்கவும்"},"39":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=45\" class=\"link\">43:45</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:45 ஐ பார்க்கவும்"},"40":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=45\" class=\"link\">43:45</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:45 ஐ பார்க்கவும்"},"41":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=45\" class=\"link\">43:45</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:45 ஐ பார்க்கவும்"},"42":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=45\" class=\"link\">43:45</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:45 ஐ பார்க்கவும்"},"43":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=45\" class=\"link\">43:45</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:45 ஐ பார்க்கவும்"},"44":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=45\" class=\"link\">43:45</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:45 ஐ பார்க்கவும்"},"45":{"html":"<strong>அர்-ரஹ்மானைப் புறக்கணிப்பவனுக்கு ஷைத்தான் தோழனாவான்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَن</span> <span class=\"quran-arabic-font text-success\">يَعْشُ﴿</span><br />\r\n<br />\r\n(யஃஷு (யார் குருட்டுத்தனமாகப் புறக்கணிக்கிறாரோ)) என்பதன் பொருள், யார் வேண்டுமென்றே அலட்சியப்படுத்திப் புறக்கணிக்கிறாரோ என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾عَن</span> <span class=\"quran-arabic-font text-success\">ذِكْرِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ﴿</span><br />\r\n<br />\r\n(மிக்க கருணையாளனின் நினைவிலிருந்து,) 'அல்-அஷா' (யஃஷு என்பதன் மூலச்சொல்) என்பது பார்வைக் குறைபாட்டைக் குறிக்கிறது; இங்கே அகப்பார்வையின் பலவீனம் நாடப்பட்டுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾نُقَيِّضْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">شَيْطَاناً</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">قَرِينٌ﴿</span><br />\r\n<br />\r\n(அவனுக்கு ஒரு ஷைத்தானை நாம் ஏற்படுத்துகிறோம்; அவன் அவனுக்கு ஒரு கரீனாக (நெருங்கிய தோழனாக) இருப்பான்.) இது பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَن</span> <span class=\"quran-arabic-font text-success\">يُشَاقِقِ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَبَيَّنَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الْهُدَى﴿</span><br />\r\n<br />\r\n(எவர் தனக்கு நேர்வழி தெளிவாக்கப்பட்ட பின்னரும், இத்தூதரை விட்டுப் பிரிந்து அவருக்கு மாறு செய்கிறாரோ) (<a href=\"qurandisp.php?sura=4&ayah=115\" class=\"link\">4:115</a>),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">زَاغُواْ</span> <span class=\"quran-arabic-font text-success\">أَزَاغَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">قُلُوبَهُمْ﴿</span><br />\r\n<br />\r\n(அவர்கள் வழிகேட்டிலேயே நிலைத்திருந்தபோது, அல்லாஹ் அவர்களுடைய உள்ளங்களை நேர்வழியை விட்டுத் திருப்பிவிட்டான்) (<a href=\"qurandisp.php?sura=61&ayah=5\" class=\"link\">61:5</a>), மற்றும்<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَيَّضْنَا</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">قُرَنَآءَ</span> <span class=\"quran-arabic-font text-success\">فَزَيَّنُواْ</span> <span class=\"quran-arabic-font text-success\">لَهُم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيهِمْ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">خَلْفَهُمْ﴿</span><br />\r\n<br />\r\n(அவர்களுக்காக நாம் சில நெருங்கிய தோழர்களை ஏற்படுத்தினோம்; அவர்கள் அவர்களுக்கு முன்னால் உள்ளவற்றையும், அவர்களுக்குப் பின்னால் உள்ளவற்றையும் அழகாகக் காட்டினார்கள்) (<a href=\"qurandisp.php?sura=41&ayah=25\" class=\"link\">41:25</a>). அல்லாஹ் இங்கே கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَيَصُدُّونَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">السَّبِيلِ</span> <span class=\"quran-arabic-font text-success\">وَيَحْسَبُونَ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُم</span> <span class=\"quran-arabic-font text-success\">مُّهْتَدُونَ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">جَآءَنَا﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அந்த ஷைத்தான்கள் அவர்களை நேர்வழியிலிருந்து தடுக்கிறார்கள்; ஆனால் அவர்களோ தாங்கள் நேர்வழியில் இருப்பதாகவே எண்ணுகிறார்கள்! இறுதியாக அவன் நம்மிடம் வரும்போது,) அதாவது, உண்மையான நேர்வழியை வேண்டுமென்றே அலட்சியப்படுத்தும் இந்த மனிதனுக்கு, அவனை வழிகெடுக்கவும் நரகத்தின் பாதையைக் காட்டவும் ஒரு ஷைத்தானை நாம் சாட்டுகிறோம். மறுமை நாளில் அவன் அல்லாஹ்விடம் வரும்போது, தனக்குத் தோழனாக நியமிக்கப்பட்ட ஷைத்தானைப் பற்றி இவ்வாறு முறையிடுவான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">لَيْتَ</span> <span class=\"quran-arabic-font text-success\">بَيْنِي</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَكَ</span> <span class=\"quran-arabic-font text-success\">بُعْدَ</span> <span class=\"quran-arabic-font text-success\">الْمَشْرِقَيْنِ</span> <span class=\"quran-arabic-font text-success\">فَبِئْسَ</span> <span class=\"quran-arabic-font text-success\">الْقَرِينُ﴿</span><br />\r\n<br />\r\n(அவன் கூறுவான்: \"அந்தோ! எனக்கும் உனக்கும் இடையில் இரு கிழக்குத் திசைகளின் தொலைவு இருந்திருக்கக் கூடாதா? நீ மிக மோசமான தோழன்!\") அவர்களில் சிலர் (<span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">جَاءَانَا</span>) (அவர்கள் இருவரும் நம்மிடம் வரும்போது) என்று ஓதினார்கள். இது தோழனான ஷைத்தானையும், அவனுடன் இருந்தவனையும் குறிக்கிறது. பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَن</span> <span class=\"quran-arabic-font text-success\">يَنفَعَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">إِذ</span> <span class=\"quran-arabic-font text-success\">ظَّلَمْتُمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">مُشْتَرِكُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நீங்கள் அநீதி இழைத்ததன் காரணமாக, இன்றைய தினம் நீங்கள் இருவரும் வேதனையில் பங்காளிகளாக இருப்பது உங்களுக்கு எவ்விதப் பயனும் அளிக்காது.) அதாவது, 'நீங்கள் இருவரும் நரகத்தில் ஒன்றாக இருப்பது உங்களுக்குச் சிறிதும் உதவாது, நீங்கள் இருவருமே நோவினைமிக்க வேதனையைப் பகிர்ந்து கொள்வீர்கள்.' அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَفَأَنتَ</span> <span class=\"quran-arabic-font text-success\">تُسْمِعُ</span> <span class=\"quran-arabic-font text-success\">الصُّمَّ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">تَهْدِى</span> <span class=\"quran-arabic-font text-success\">الْعُمْىَ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ضَلَـلٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(செவிடர்களை நீர் கேட்கச் செய்ய முடியுமா? அல்லது பார்வையற்றவர்களுக்கும், தெளிவான வழிகேட்டில் இருப்பவர்களுக்கும் நீர் நேர்வழி காட்ட முடியுமா?) அதாவது, 'அது உம்முடைய பொறுப்பில் இல்லை. உமது கடமையெல்லாம் செய்தியை எத்தி வைப்பதே தவிர, அவர்களுக்கு நேர்வழி காட்டுவது அல்ல. அல்லாஹ் தான் நாடியவர்களுக்கு நேர்வழி காட்டுகிறான், தான் நாடியவர்களை வழிகேட்டில் விடுகிறான்; அவன் செய்வதில் ஞானமிக்கவனும் நீதியுள்ளவனும் ஆவான்.'<br />\r\n<br />\r\n<strong>அல்லாஹ்வின் தூதரின் எதிரிகள் மீது அவனுடைய பழிவாங்கல் நிச்சயமாக நிறைவேறும்</strong><br />\r\n<br />\r\nஅல்லாஹ் மேலும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَإِمَّا</span> <span class=\"quran-arabic-font text-success\">نَذْهَبَنَّ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّا</span> <span class=\"quran-arabic-font text-success\">مِنْهُم</span> <span class=\"quran-arabic-font text-success\">مُّنتَقِمُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(உம்மை நாம் (மரணத்தின் மூலம்) எடுத்துக்கொண்டாலும், நிச்சயமாக நாம் அவர்களிடமிருந்து பழிவாங்குவோம்.) அதாவது, 'நீர் இவ்வுலகை விட்டு மறைந்தாலும் சரி, நாம் நிச்சயமாக அவர்களைத் தண்டித்துப் பழிவாங்குவோம்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَوْ</span> <span class=\"quran-arabic-font text-success\">نُرِيَنَّكَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">وَعَدْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">مُّقْتَدِرُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அல்லது அவர்களுக்கு நாம் வாக்களித்த (தண்டனையை) உமக்குக் காட்டுவோம்; நிச்சயமாக நாம் அவர்கள் மீது முழு ஆற்றல் உடையவர்கள்.) அதாவது, 'இவை இரண்டையும் செய்ய நாம் ஆற்றல் பெற்றிருக்கிறோம்.' ஆனால் அல்லாஹ் தனது தூதரை (ஸல்), அவர்களின் எதிரிகள் தாழ்வுறுவதைக் கண்டு அவர்கள் (ஸல்) மகிழ்ச்சியடையும் வரையிலும், அவர்கள் மீதும் அவர்களின் செல்வங்கள் மீதும் அவர்களுக்கு (ஸல்) அதிகாரத்தையும் வெற்றியையும் வழங்கும் வரையிலும் அவர்களை (ஸல்) மரணிக்கச் செய்யவில்லை. இது அஸ்-ஸுத்தியின் கருத்தாகும், மேலும் இப்னு ஜரீர் இக்கருத்தையே விரும்பினார்.<br />\r\n<br />\r\n<strong>குர்ஆனைப் பற்றிப்பிடிப்பதற்கான ஊக்கம்</strong><br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَاسْتَمْسِكْ</span> <span class=\"quran-arabic-font text-success\">بِالَّذِى</span> <span class=\"quran-arabic-font text-success\">أُوحِىَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">صِرَاطٍ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقِيمٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எனவே உமக்கு வஹீ (இறைச்செய்தி)யாக அருளப்பட்டதை உறுதியாகப் பற்றிக்கொள்ளும்; நிச்சயமாக நீர் நேர்வழியில் இருக்கிறீர்.) அதாவது, உமது உள்ளத்தில் இறக்கப்பட்ட குர்ஆனை உறுதியாகப் பற்றிக்கொள்ளும்; ஏனெனில் அது சத்தியமாகும், அது காட்டும் வழி உண்மையானது. அது இன்பங்கள் நிறைந்த சொர்க்கத்திற்கும், நிலையான நன்மைகளுக்கும் இட்டுச் செல்லும் நேர்வழியாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَذِكْرٌ</span> <span class=\"quran-arabic-font text-success\">لَّكَ</span> <span class=\"quran-arabic-font text-success\">وَلِقَوْمِكَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக இது உமக்கும் உம்முடைய மக்களுக்கும் ஒரு திக்ர் ஆகும்.) இதன் பொருள் 'இது உமக்கும் உமது மக்களுக்கும் ஒரு கண்ணியமாகும்' என்று இப்னு அப்பாஸ் (ரழி), முஜாஹித், கத்தாதா, அஸ்-ஸுத்தி மற்றும் இப்னு ஸைத் ஆகியோர் கூறியுள்ளனர். இது அவர்களின் மொழியிலேயே வஹீ (இறைச்செய்தி)யாக அருளப்பட்டதால் அவர்களுக்குக் கிடைத்த கண்ணியமாகும். எனவே மனிதர்களிலேயே அதைச் சிறந்த முறையில் புரிந்துகொள்ளும் தகுதி உடையவர்கள் அவர்களே. அதன் கட்டளைகளைக் கடைப்பிடிப்பதில் அவர்கள் மற்றவர்களை விட அதிக உறுதியுடன் இருக்க வேண்டும். அவர்களில் சிறந்தவர்களான முஹாஜிரீன்களும், அவர்களைப் பின்பற்றியவர்களும் அவ்வாறே இருந்தார்கள். மேலும் இத்தொடருக்கு, 'இது உமக்கும் உமது மக்களுக்கும் ஒரு நினைவூட்டலாக அருளப்பட்டது' என்றும் பொருள் கூறப்பட்டுள்ளது. அவர்கள் மட்டும் இங்கே குறிப்பிடப்படுவது மற்றவர்களைத் தவிர்ப்பதற்காக அல்ல. இது பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَنزَلْنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">كِتَـباً</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">ذِكْرُكُمْ</span> <span class=\"quran-arabic-font text-success\">أَفَلاَ</span> <span class=\"quran-arabic-font text-success\">تَعْقِلُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் உங்களுக்கு ஒரு வேதத்தை இறக்கியுள்ளோம்; அதில் உங்களைப் பற்றிய நினைவூட்டல் (கண்ணியம்) இருக்கிறது. நீங்கள் சிந்தித்துப் பார்க்க வேண்டாமா?) (<a href=\"qurandisp.php?sura=21&ayah=10\" class=\"link\">21:10</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَنذِرْ</span> <span class=\"quran-arabic-font text-success\">عَشِيرَتَكَ</span> <span class=\"quran-arabic-font text-success\">الْأَقْرَبِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(உமது நெருங்கிய உறவினர்களை நீர் எச்சரிப்பீராக) (<a href=\"qurandisp.php?sura=26&ayah=214\" class=\"link\">26:214</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَسَوْفَ</span> <span class=\"quran-arabic-font text-success\">تُسْأَلُونَ﴿</span><br />\r\n<br />\r\n(நீங்கள் விசாரிக்கப்படுவீர்கள்.) அதாவது, 'இந்தக் குர்ஆனைப் பற்றியும், அதன்படி நீங்கள் எவ்வாறு செயல்பட்டீர்கள், அதற்கு உங்களின் பதில் என்னவாக இருந்தது என்பது குறித்தும் நீங்கள் விசாரிக்கப்படுவீர்கள்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاسْأَلْ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِكَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رُّسُلِنَآ</span> <span class=\"quran-arabic-font text-success\">أَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">ءَالِهَةً</span> <span class=\"quran-arabic-font text-success\">يُعْبَدُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(உமக்கு முன்னர் நாம் அனுப்பிய நம்முடைய தூதர்களிடம் நீர் கேட்பீராக: \"மிக்க கருணையாளனைத் தவிர வணங்கப்பட வேண்டிய வேறு தெய்வங்களை நாம் ஏற்படுத்தியிருக்கிறோமா?\") அதாவது, 'எல்லாத் தூதர்களும் நீர் அழைப்பதைப் போலவே, எந்தவொரு இணையுமின்றி அல்லாஹ்வை மட்டுமே வணங்குமாறு தங்கள் மக்களை அழைத்தனர்; சிலைகளையும் போலித் தெய்வங்களையும் வணங்குவதை அவர்கள் தடுத்தனர்.' இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">بَعَثْنَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">أُمَّةٍ</span> <span class=\"quran-arabic-font text-success\">رَّسُولاً</span> <span class=\"quran-arabic-font text-success\">أَنِ</span> <span class=\"quran-arabic-font text-success\">اعْبُدُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَاجْتَنِبُواْ</span> <span class=\"quran-arabic-font text-success\">الطَّاغُوتَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் ஒவ்வொரு சமூகத்திலும் ஒரு தூதரை அனுப்பினோம்: \"அல்லாஹ்வையே வணங்குங்கள், தாகூத்களை (போலித் தெய்வங்களைத்) தவிர்த்துக் கொள்ளுங்கள்\" என்று அவர் பிரகடனம் செய்தார்.) (<a href=\"qurandisp.php?sura=16&ayah=36\" class=\"link\">16:36</a>) அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள், (<span class=\"quran-arabic-font text-success\">وَاسْأَلِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">قَبْلَكَ</span> (<span class=\"quran-arabic-font text-success\">مِنْ</span>) <span class=\"quran-arabic-font text-success\">رُسُلِنَا</span>) (உமக்கு முன்னர் நாம் யாரிடம் தூதர்களை அனுப்பினோமோ அவர்களிடம் கேட்பீராக) என்று ஓதியதாக முஜாஹித் கூறுகிறார். இது மிஃராஜ் இரவில் பைத்துல் முகத்தஸில் நபிமார்களுடன் அவர்கள் (ஸல்) ஒன்று சேர்ந்தபோது நிகழ்ந்தது என்று கத்தாதா, அத்-தஹ்ஹாக் மற்றும் அஸ்-ஸுத்தி ஆகியோர் கூறியுள்ளனர். இப்னு ஜரீர் (ரஹ்) அவர்கள், 'நீர் கேட்பீராக' என்று கூறப்பட்டிருந்தாலும், அவர்கள் (ஸல்) கேட்டதாக எந்தச் செய்தியும் வரவில்லை என்று கூறுகிறார். இருப்பினும், இது மாற்று ஓதுதல் முறையை விட ஒரு விளக்கமாகவே தோன்றுகிறது. அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />","text":"அர்-ரஹ்மானைப் புறக்கணிப்பவனுக்கு ஷைத்தான் தோழனாவான்\n\r\n\n\r\n﴾وَمَن يَعْشُ﴿\n\r\n\n\r\n(யஃஷு (யார் குருட்டுத்தனமாகப் புறக்கணிக்கிறாரோ)) என்பதன் பொருள், யார் வேண்டுமென்றே அலட்சியப்படுத்திப் புறக்கணிக்கிறாரோ என்பதாகும்.\n\r\n\n\r\n﴾عَن ذِكْرِ الرَّحْمَـنِ﴿\n\r\n\n\r\n(மிக்க கருணையாளனின் நினைவிலிருந்து,) 'அல்-அஷா' (யஃஷு என்பதன் மூலச்சொல்) என்பது பார்வைக் குறைபாட்டைக் குறிக்கிறது; இங்கே அகப்பார்வையின் பலவீனம் நாடப்பட்டுள்ளது.\n\r\n\n\r\n﴾نُقَيِّضْ لَهُ شَيْطَاناً فَهُوَ لَهُ قَرِينٌ﴿\n\r\n\n\r\n(அவனுக்கு ஒரு ஷைத்தானை நாம் ஏற்படுத்துகிறோம்; அவன் அவனுக்கு ஒரு கரீனாக (நெருங்கிய தோழனாக) இருப்பான்.) இது பின்வரும் வசனங்களைப் போன்றது:\n\r\n\n\r\n﴾وَمَن يُشَاقِقِ الرَّسُولَ مِن بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدَى﴿\n\r\n\n\r\n(எவர் தனக்கு நேர்வழி தெளிவாக்கப்பட்ட பின்னரும், இத்தூதரை விட்டுப் பிரிந்து அவருக்கு மாறு செய்கிறாரோ) (4:115),\n\r\n\n\r\n﴾فَلَمَّا زَاغُواْ أَزَاغَ اللَّهُ قُلُوبَهُمْ﴿\n\r\n\n\r\n(அவர்கள் வழிகேட்டிலேயே நிலைத்திருந்தபோது, அல்லாஹ் அவர்களுடைய உள்ளங்களை நேர்வழியை விட்டுத் திருப்பிவிட்டான்) (61:5), மற்றும்\n\r\n\n\r\n﴾وَقَيَّضْنَا لَهُمْ قُرَنَآءَ فَزَيَّنُواْ لَهُم مَّا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ﴿\n\r\n\n\r\n(அவர்களுக்காக நாம் சில நெருங்கிய தோழர்களை ஏற்படுத்தினோம்; அவர்கள் அவர்களுக்கு முன்னால் உள்ளவற்றையும், அவர்களுக்குப் பின்னால் உள்ளவற்றையும் அழகாகக் காட்டினார்கள்) (41:25). அல்லாஹ் இங்கே கூறுகிறான்:\n\r\n\n\r\n﴾وَإِنَّهُمْ لَيَصُدُّونَهُمْ عَنِ السَّبِيلِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ حَتَّى إِذَا جَآءَنَا﴿\n\r\n\n\r\n(நிச்சயமாக அந்த ஷைத்தான்கள் அவர்களை நேர்வழியிலிருந்து தடுக்கிறார்கள்; ஆனால் அவர்களோ தாங்கள் நேர்வழியில் இருப்பதாகவே எண்ணுகிறார்கள்! இறுதியாக அவன் நம்மிடம் வரும்போது,) அதாவது, உண்மையான நேர்வழியை வேண்டுமென்றே அலட்சியப்படுத்தும் இந்த மனிதனுக்கு, அவனை வழிகெடுக்கவும் நரகத்தின் பாதையைக் காட்டவும் ஒரு ஷைத்தானை நாம் சாட்டுகிறோம். மறுமை நாளில் அவன் அல்லாஹ்விடம் வரும்போது, தனக்குத் தோழனாக நியமிக்கப்பட்ட ஷைத்தானைப் பற்றி இவ்வாறு முறையிடுவான்:\n\r\n\n\r\n﴾قَالَ يَا لَيْتَ بَيْنِي وَبَيْنَكَ بُعْدَ الْمَشْرِقَيْنِ فَبِئْسَ الْقَرِينُ﴿\n\r\n\n\r\n(அவன் கூறுவான்: \"அந்தோ! எனக்கும் உனக்கும் இடையில் இரு கிழக்குத் திசைகளின் தொலைவு இருந்திருக்கக் கூடாதா? நீ மிக மோசமான தோழன்!\") அவர்களில் சிலர் (حَتَّى إِذَا جَاءَانَا) (அவர்கள் இருவரும் நம்மிடம் வரும்போது) என்று ஓதினார்கள். இது தோழனான ஷைத்தானையும், அவனுடன் இருந்தவனையும் குறிக்கிறது. பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾وَلَن يَنفَعَكُمُ الْيَوْمَ إِذ ظَّلَمْتُمْ أَنَّكُمْ فِى الْعَذَابِ مُشْتَرِكُونَ ﴿\n\r\n\n\r\n(நீங்கள் அநீதி இழைத்ததன் காரணமாக, இன்றைய தினம் நீங்கள் இருவரும் வேதனையில் பங்காளிகளாக இருப்பது உங்களுக்கு எவ்விதப் பயனும் அளிக்காது.) அதாவது, 'நீங்கள் இருவரும் நரகத்தில் ஒன்றாக இருப்பது உங்களுக்குச் சிறிதும் உதவாது, நீங்கள் இருவருமே நோவினைமிக்க வேதனையைப் பகிர்ந்து கொள்வீர்கள்.' அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾أَفَأَنتَ تُسْمِعُ الصُّمَّ أَوْ تَهْدِى الْعُمْىَ وَمَن كَانَ فِى ضَلَـلٍ مُّبِينٍ ﴿\n\r\n\n\r\n(செவிடர்களை நீர் கேட்கச் செய்ய முடியுமா? அல்லது பார்வையற்றவர்களுக்கும், தெளிவான வழிகேட்டில் இருப்பவர்களுக்கும் நீர் நேர்வழி காட்ட முடியுமா?) அதாவது, 'அது உம்முடைய பொறுப்பில் இல்லை. உமது கடமையெல்லாம் செய்தியை எத்தி வைப்பதே தவிர, அவர்களுக்கு நேர்வழி காட்டுவது அல்ல. அல்லாஹ் தான் நாடியவர்களுக்கு நேர்வழி காட்டுகிறான், தான் நாடியவர்களை வழிகேட்டில் விடுகிறான்; அவன் செய்வதில் ஞானமிக்கவனும் நீதியுள்ளவனும் ஆவான்.'\n\r\n\n\r\nஅல்லாஹ்வின் தூதரின் எதிரிகள் மீது அவனுடைய பழிவாங்கல் நிச்சயமாக நிறைவேறும்\n\r\n\n\r\nஅல்லாஹ் மேலும் கூறுகிறான்:\n\r\n\n\r\n﴾فَإِمَّا نَذْهَبَنَّ بِكَ فَإِنَّا مِنْهُم مُّنتَقِمُونَ ﴿\n\r\n\n\r\n(உம்மை நாம் (மரணத்தின் மூலம்) எடுத்துக்கொண்டாலும், நிச்சயமாக நாம் அவர்களிடமிருந்து பழிவாங்குவோம்.) அதாவது, 'நீர் இவ்வுலகை விட்டு மறைந்தாலும் சரி, நாம் நிச்சயமாக அவர்களைத் தண்டித்துப் பழிவாங்குவோம்.'\n\r\n\n\r\n﴾أَوْ نُرِيَنَّكَ الَّذِى وَعَدْنَـهُمْ فَإِنَّا عَلَيْهِمْ مُّقْتَدِرُونَ ﴿\n\r\n\n\r\n(அல்லது அவர்களுக்கு நாம் வாக்களித்த (தண்டனையை) உமக்குக் காட்டுவோம்; நிச்சயமாக நாம் அவர்கள் மீது முழு ஆற்றல் உடையவர்கள்.) அதாவது, 'இவை இரண்டையும் செய்ய நாம் ஆற்றல் பெற்றிருக்கிறோம்.' ஆனால் அல்லாஹ் தனது தூதரை (ஸல்), அவர்களின் எதிரிகள் தாழ்வுறுவதைக் கண்டு அவர்கள் (ஸல்) மகிழ்ச்சியடையும் வரையிலும், அவர்கள் மீதும் அவர்களின் செல்வங்கள் மீதும் அவர்களுக்கு (ஸல்) அதிகாரத்தையும் வெற்றியையும் வழங்கும் வரையிலும் அவர்களை (ஸல்) மரணிக்கச் செய்யவில்லை. இது அஸ்-ஸுத்தியின் கருத்தாகும், மேலும் இப்னு ஜரீர் இக்கருத்தையே விரும்பினார்.\n\r\n\n\r\nகுர்ஆனைப் பற்றிப்பிடிப்பதற்கான ஊக்கம்\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்;\n\r\n\n\r\n﴾فَاسْتَمْسِكْ بِالَّذِى أُوحِىَ إِلَيْكَ إِنَّكَ عَلَى صِرَاطٍ مُّسْتَقِيمٍ ﴿\n\r\n\n\r\n(எனவே உமக்கு வஹீ (இறைச்செய்தி)யாக அருளப்பட்டதை உறுதியாகப் பற்றிக்கொள்ளும்; நிச்சயமாக நீர் நேர்வழியில் இருக்கிறீர்.) அதாவது, உமது உள்ளத்தில் இறக்கப்பட்ட குர்ஆனை உறுதியாகப் பற்றிக்கொள்ளும்; ஏனெனில் அது சத்தியமாகும், அது காட்டும் வழி உண்மையானது. அது இன்பங்கள் நிறைந்த சொர்க்கத்திற்கும், நிலையான நன்மைகளுக்கும் இட்டுச் செல்லும் நேர்வழியாகும்.\n\r\n\n\r\n﴾وَإِنَّهُ لَذِكْرٌ لَّكَ وَلِقَوْمِكَ﴿\n\r\n\n\r\n(நிச்சயமாக இது உமக்கும் உம்முடைய மக்களுக்கும் ஒரு திக்ர் ஆகும்.) இதன் பொருள் 'இது உமக்கும் உமது மக்களுக்கும் ஒரு கண்ணியமாகும்' என்று இப்னு அப்பாஸ் (ரழி), முஜாஹித், கத்தாதா, அஸ்-ஸுத்தி மற்றும் இப்னு ஸைத் ஆகியோர் கூறியுள்ளனர். இது அவர்களின் மொழியிலேயே வஹீ (இறைச்செய்தி)யாக அருளப்பட்டதால் அவர்களுக்குக் கிடைத்த கண்ணியமாகும். எனவே மனிதர்களிலேயே அதைச் சிறந்த முறையில் புரிந்துகொள்ளும் தகுதி உடையவர்கள் அவர்களே. அதன் கட்டளைகளைக் கடைப்பிடிப்பதில் அவர்கள் மற்றவர்களை விட அதிக உறுதியுடன் இருக்க வேண்டும். அவர்களில் சிறந்தவர்களான முஹாஜிரீன்களும், அவர்களைப் பின்பற்றியவர்களும் அவ்வாறே இருந்தார்கள். மேலும் இத்தொடருக்கு, 'இது உமக்கும் உமது மக்களுக்கும் ஒரு நினைவூட்டலாக அருளப்பட்டது' என்றும் பொருள் கூறப்பட்டுள்ளது. அவர்கள் மட்டும் இங்கே குறிப்பிடப்படுவது மற்றவர்களைத் தவிர்ப்பதற்காக அல்ல. இது பின்வரும் வசனங்களைப் போன்றது:\n\r\n\n\r\n﴾لَقَدْ أَنزَلْنَآ إِلَيْكُمْ كِتَـباً فِيهِ ذِكْرُكُمْ أَفَلاَ تَعْقِلُونَ ﴿\n\r\n\n\r\n(நிச்சயமாக நாம் உங்களுக்கு ஒரு வேதத்தை இறக்கியுள்ளோம்; அதில் உங்களைப் பற்றிய நினைவூட்டல் (கண்ணியம்) இருக்கிறது. நீங்கள் சிந்தித்துப் பார்க்க வேண்டாமா?) (21:10)\n\r\n\n\r\n﴾وَأَنذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ﴿\n\r\n\n\r\n(உமது நெருங்கிய உறவினர்களை நீர் எச்சரிப்பீராக) (26:214)\n\r\n\n\r\n﴾وَسَوْفَ تُسْأَلُونَ﴿\n\r\n\n\r\n(நீங்கள் விசாரிக்கப்படுவீர்கள்.) அதாவது, 'இந்தக் குர்ஆனைப் பற்றியும், அதன்படி நீங்கள் எவ்வாறு செயல்பட்டீர்கள், அதற்கு உங்களின் பதில் என்னவாக இருந்தது என்பது குறித்தும் நீங்கள் விசாரிக்கப்படுவீர்கள்.'\n\r\n\n\r\n﴾وَاسْأَلْ مَنْ أَرْسَلْنَا مِن قَبْلِكَ مِن رُّسُلِنَآ أَجَعَلْنَا مِن دُونِ الرَّحْمَـنِ ءَالِهَةً يُعْبَدُونَ ﴿\n\r\n\n\r\n(உமக்கு முன்னர் நாம் அனுப்பிய நம்முடைய தூதர்களிடம் நீர் கேட்பீராக: \"மிக்க கருணையாளனைத் தவிர வணங்கப்பட வேண்டிய வேறு தெய்வங்களை நாம் ஏற்படுத்தியிருக்கிறோமா?\") அதாவது, 'எல்லாத் தூதர்களும் நீர் அழைப்பதைப் போலவே, எந்தவொரு இணையுமின்றி அல்லாஹ்வை மட்டுமே வணங்குமாறு தங்கள் மக்களை அழைத்தனர்; சிலைகளையும் போலித் தெய்வங்களையும் வணங்குவதை அவர்கள் தடுத்தனர்.' இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\n﴾وَلَقَدْ بَعَثْنَا فِى كُلِّ أُمَّةٍ رَّسُولاً أَنِ اعْبُدُواْ اللَّهَ وَاجْتَنِبُواْ الطَّاغُوتَ﴿\n\r\n\n\r\n(நிச்சயமாக நாம் ஒவ்வொரு சமூகத்திலும் ஒரு தூதரை அனுப்பினோம்: \"அல்லாஹ்வையே வணங்குங்கள், தாகூத்களை (போலித் தெய்வங்களைத்) தவிர்த்துக் கொள்ளுங்கள்\" என்று அவர் பிரகடனம் செய்தார்.) (16:36) அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள், (وَاسْأَلِ الَّذِينَ أَرْسَلْنَا إِلَيْهِمْ قَبْلَكَ (مِنْ) رُسُلِنَا) (உமக்கு முன்னர் நாம் யாரிடம் தூதர்களை அனுப்பினோமோ அவர்களிடம் கேட்பீராக) என்று ஓதியதாக முஜாஹித் கூறுகிறார். இது மிஃராஜ் இரவில் பைத்துல் முகத்தஸில் நபிமார்களுடன் அவர்கள் (ஸல்) ஒன்று சேர்ந்தபோது நிகழ்ந்தது என்று கத்தாதா, அத்-தஹ்ஹாக் மற்றும் அஸ்-ஸுத்தி ஆகியோர் கூறியுள்ளனர். இப்னு ஜரீர் (ரஹ்) அவர்கள், 'நீர் கேட்பீராக' என்று கூறப்பட்டிருந்தாலும், அவர்கள் (ஸல்) கேட்டதாக எந்தச் செய்தியும் வரவில்லை என்று கூறுகிறார். இருப்பினும், இது மாற்று ஓதுதல் முறையை விட ஒரு விளக்கமாகவே தோன்றுகிறது. அல்லாஹ்வே மிக அறிந்தவன்."},"46":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=50\" class=\"link\">43:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:50 ஐ பார்க்கவும்"},"47":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=50\" class=\"link\">43:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:50 ஐ பார்க்கவும்"},"48":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=50\" class=\"link\">43:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:50 ஐ பார்க்கவும்"},"49":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=50\" class=\"link\">43:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:50 ஐ பார்க்கவும்"},"50":{"html":"<strong>மூஸா (அலை) அவர்கள் தவ்ஹீத் எனும் ஏகத்துவச் செய்தியுடன் ஃபிர்அவ்னிடமும் அவனது பிரதானிகளிடமும் அனுப்பப்பட்டார்கள்</strong><br />\r\n<br />\r\nஇங்கே அல்லாஹ் தனது அடியாரும் தூதருமான மூஸா (அலை) அவர்களைப் பற்றியும், அவர்களை ஃபிர்அவ்னிடமும் அவனது பிரதானிகளிடமும் எவ்வாறு அனுப்பினான் என்பதைப் பற்றியும் நமக்குக் கூறுகிறான். அதாவது, எகிப்தியர்கள் மற்றும் பனூ இஸ்ராயீல்கள் மத்தியில் இருந்த அவனது ஆளுநர்கள், அமைச்சர்கள், தலைவர்கள் மற்றும் பின்பற்றுபவர்களிடம் மூஸா (அலை) அவர்களை அனுப்பினான். அல்லாஹ் ஒருவனையே வணங்கவும், அவனுக்கு எதனையும் இணையாக்கக் கூடாது என்றும் அவர்களை அழைக்கவும், அல்லாஹ்வைத் தவிர வேறு எதையும் வணங்குவதை விட்டும் அவர்களைத் தடுக்கவும் அவன் அவர்களை அனுப்பினான். மூஸா (அலை) அவர்களின் கை மற்றும் கைத்தடி போன்ற வலிமையான அத்தாட்சிகளுடனும், மேலும் பெருவெள்ளம், வெட்டுக்கிளிகள், பேன்கள் (கும்மல்), தவளைகள் மற்றும் இரத்தம் போன்ற பிற அத்தாட்சிகளுடனும், அவர்களுடைய பயிர்கள் மற்றும் உயிர்களின் இழப்புடனும் அவர்களை அல்லாஹ் அனுப்பினான். இவையெல்லாம் இருந்தபோதிலும், அவர்கள் ஆணவம் கொண்டு, பிடிவாதமாக அவரைப் பின்பற்ற மறுத்தார்கள்; அவரது செய்தியை நிராகரித்துக் கேலி செய்ததோடு, அச்செய்தியைக் கொண்டு வந்த மூஸா (அலை) அவர்களைப் பார்த்துச் சிரித்தார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">نُرِيِهِم</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">ءَايَةٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هِىَ</span> <span class=\"quran-arabic-font text-success\">أَكْبَرُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أُخْتِهَا</span> <span class=\"quran-arabic-font text-success\">وَأَخَذْنَـهُم</span> <span class=\"quran-arabic-font text-success\">بِالْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">لَعَلَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَرْجِعُونَ﴿</span><br />\r\n<br />\r\n(நாம் அவர்களுக்குக் காட்டிய ஒவ்வோர் அத்தாட்சியும் அதற்கு முந்தையதை விடப் பெரியதாகவே இருந்தது; அவர்கள் (பாவத்திலிருந்து) மீள்வதற்காக நாம் அவர்களை வேதனையைக் கொண்டு பிடித்தோம்.) இருப்பினும், அவர்கள் தங்கள் பாவம், வழிகேடு, அறியாமை மற்றும் குழப்பத்தைக் கைவிடவில்லை. இந்த அத்தாட்சிகளில் ஒன்று அவர்களிடம் வரும்போதெல்லாம், அவர்கள் மூஸா (அலை) அவர்களிடம் சென்று கெஞ்சிக் கூறுவார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">السَّاحِرُ﴿</span><br />\r\n<br />\r\n(\"ஓ சூனியக்காரரே!...\") அதாவது, \"நிபுணரே\" அல்லது \"அறிஞரே\" என்று பொருள் - இது இப்னு ஜரீர் அவர்களின் கருத்தாகும். அக்காலத்து அறிஞர்கள் சூனியக்காரர்களாகவே இருந்தார்கள், மேலும் அக்காலத்தில் சூனியம் என்பது அவர்களால் இழிவான ஒன்றாகக் கருதப்படவில்லை. எனவே, இது அவர்கள் தரப்பிலிருந்து செய்யப்பட்ட அவமதிப்பு அல்ல. அவர்கள் தேவையுள்ள நிலையில் இருந்ததால், மூஸா (அலை) அவர்களை அவமதிப்பது அவர்களுக்குப் பொருத்தமானதாக இருந்திருக்காது. அவர்கள் கருதியபடி, இது அவர்களைக் கௌரவிப்பதற்காகப் பயன்படுத்தப்பட்ட ஒரு சொல்லாகும். ஒவ்வொரு சந்தர்ப்பத்திலும், தங்களுக்கு ஏற்பட்டுள்ள வேதனை நீக்கப்பட்டால், அவர்கள் மீது ஈமான் (நம்பிக்கை) கொள்வதாகவும், பனூ இஸ்ராயீல்களை அவர்களுடன் செல்ல அனுமதிப்பதாகவும் மூஸா (அலை) அவர்களிடம் வாக்குறுதி அளித்தார்கள். ஆனால் ஒவ்வொரு முறையும் அவர்கள் தங்கள் வாக்கை மீறினார்கள்.<br />\r\n<br />\r\nஇது பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَأَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمُ</span> <span class=\"quran-arabic-font text-success\">الطُّوفَانَ</span> <span class=\"quran-arabic-font text-success\">وَالْجَرَادَ</span> <span class=\"quran-arabic-font text-success\">وَالْقُمَّلَ</span> <span class=\"quran-arabic-font text-success\">وَالضَّفَادِعَ</span> <span class=\"quran-arabic-font text-success\">وَالدَّمَ</span> <span class=\"quran-arabic-font text-success\">ءَايَـتٍ</span> <span class=\"quran-arabic-font text-success\">مُّفَصَّلَاتٍ</span> <span class=\"quran-arabic-font text-success\">فَاسْتَكْبَرُواْ</span> <span class=\"quran-arabic-font text-success\">وَكَانُواْ</span> <span class=\"quran-arabic-font text-success\">قَوْماً</span> <span class=\"quran-arabic-font text-success\">مُّجْرِمِينَ</span> - <span class=\"quran-arabic-font text-success\">وَلَمَّا</span> <span class=\"quran-arabic-font text-success\">وَقَعَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمُ</span> <span class=\"quran-arabic-font text-success\">الرِّجْزُ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">ادْعُ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">رَبَّكَ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">عَهِدَ</span> <span class=\"quran-arabic-font text-success\">عِندَكَ</span> <span class=\"quran-arabic-font text-success\">لَئِن</span> <span class=\"quran-arabic-font text-success\">كَشَفْتَ</span> <span class=\"quran-arabic-font text-success\">عَنَّا</span> <span class=\"quran-arabic-font text-success\">الرِّجْزَ</span> <span class=\"quran-arabic-font text-success\">لَنُؤْمِنَنَّ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">وَلَنُرْسِلَنَّ</span> <span class=\"quran-arabic-font text-success\">مَعَكَ</span> <span class=\"quran-arabic-font text-success\">بَنِي</span> <span class=\"quran-arabic-font text-success\">إِسْرَائِيلَ</span> - <span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">كَشَفْنَا</span> <span class=\"quran-arabic-font text-success\">عَنْهُمُ</span> <span class=\"quran-arabic-font text-success\">الرِّجْزَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">أَجَلٍ</span> <span class=\"quran-arabic-font text-success\">هُم</span> <span class=\"quran-arabic-font text-success\">بَـلِغُوهُ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">يَنكُثُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எனவே, அவர்கள் மீது பெருவெள்ளம், வெட்டுக்கிளிகள், பேன்கள் (கும்மல்), தவளைகள் மற்றும் இரத்தம் ஆகியவற்றைத் தெளிவான அத்தாட்சிகளாக நாம் அனுப்பினோம்; அப்போதும் அவர்கள் ஆணவம் கொண்டனர், மேலும் அவர்கள் குற்றவாளிகளான மக்களாகவே இருந்தார்கள். வேதனை அவர்களைத் தாக்கியபோது, அவர்கள் கூறினார்கள்: \"ஓ மூஸாவே! உமது இறைவன் உமக்கு அளித்துள்ள வாக்குறுதியின்படி எங்களுக்காக அவனிடம் பிரார்த்தனை செய்வீராக. நீர் எங்களிடமிருந்து இந்த வேதனையை நீக்கினால், நாங்கள் நிச்சயமாக உம்மை ஈமான் கொள்வோம், மேலும் பனூ இஸ்ராயீல்களை உம்முடன் செல்ல அனுமதிப்போம்.\" ஆனால், அவர்கள் அடைய வேண்டிய ஒரு குறிப்பிட்ட தவணை வரை அவர்களிடமிருந்து வேதனையை நாம் நீக்கியபோது, இதோ! அவர்கள் தங்கள் வாக்குறுதியை மீறினார்கள்!) (<a href=\"qurandisp.php?sura=7&ayah=133\" class=\"link\">7:133</a>-135)<br />\r\n<br />","text":"மூஸா (அலை) அவர்கள் தவ்ஹீத் எனும் ஏகத்துவச் செய்தியுடன் ஃபிர்அவ்னிடமும் அவனது பிரதானிகளிடமும் அனுப்பப்பட்டார்கள்\n\r\n\n\r\nஇங்கே அல்லாஹ் தனது அடியாரும் தூதருமான மூஸா (அலை) அவர்களைப் பற்றியும், அவர்களை ஃபிர்அவ்னிடமும் அவனது பிரதானிகளிடமும் எவ்வாறு அனுப்பினான் என்பதைப் பற்றியும் நமக்குக் கூறுகிறான். அதாவது, எகிப்தியர்கள் மற்றும் பனூ இஸ்ராயீல்கள் மத்தியில் இருந்த அவனது ஆளுநர்கள், அமைச்சர்கள், தலைவர்கள் மற்றும் பின்பற்றுபவர்களிடம் மூஸா (அலை) அவர்களை அனுப்பினான். அல்லாஹ் ஒருவனையே வணங்கவும், அவனுக்கு எதனையும் இணையாக்கக் கூடாது என்றும் அவர்களை அழைக்கவும், அல்லாஹ்வைத் தவிர வேறு எதையும் வணங்குவதை விட்டும் அவர்களைத் தடுக்கவும் அவன் அவர்களை அனுப்பினான். மூஸா (அலை) அவர்களின் கை மற்றும் கைத்தடி போன்ற வலிமையான அத்தாட்சிகளுடனும், மேலும் பெருவெள்ளம், வெட்டுக்கிளிகள், பேன்கள் (கும்மல்), தவளைகள் மற்றும் இரத்தம் போன்ற பிற அத்தாட்சிகளுடனும், அவர்களுடைய பயிர்கள் மற்றும் உயிர்களின் இழப்புடனும் அவர்களை அல்லாஹ் அனுப்பினான். இவையெல்லாம் இருந்தபோதிலும், அவர்கள் ஆணவம் கொண்டு, பிடிவாதமாக அவரைப் பின்பற்ற மறுத்தார்கள்; அவரது செய்தியை நிராகரித்துக் கேலி செய்ததோடு, அச்செய்தியைக் கொண்டு வந்த மூஸா (அலை) அவர்களைப் பார்த்துச் சிரித்தார்கள்.\n\r\n\n\r\n﴾وَمَا نُرِيِهِم مِّنْ ءَايَةٍ إِلاَّ هِىَ أَكْبَرُ مِنْ أُخْتِهَا وَأَخَذْنَـهُم بِالْعَذَابِ لَعَلَّهُمْ يَرْجِعُونَ﴿\n\r\n\n\r\n(நாம் அவர்களுக்குக் காட்டிய ஒவ்வோர் அத்தாட்சியும் அதற்கு முந்தையதை விடப் பெரியதாகவே இருந்தது; அவர்கள் (பாவத்திலிருந்து) மீள்வதற்காக நாம் அவர்களை வேதனையைக் கொண்டு பிடித்தோம்.) இருப்பினும், அவர்கள் தங்கள் பாவம், வழிகேடு, அறியாமை மற்றும் குழப்பத்தைக் கைவிடவில்லை. இந்த அத்தாட்சிகளில் ஒன்று அவர்களிடம் வரும்போதெல்லாம், அவர்கள் மூஸா (அலை) அவர்களிடம் சென்று கெஞ்சிக் கூறுவார்கள்:\n\r\n\n\r\n﴾وَقَالُواْ يَا أَيُّهَا السَّاحِرُ﴿\n\r\n\n\r\n(\"ஓ சூனியக்காரரே!...\") அதாவது, \"நிபுணரே\" அல்லது \"அறிஞரே\" என்று பொருள் - இது இப்னு ஜரீர் அவர்களின் கருத்தாகும். அக்காலத்து அறிஞர்கள் சூனியக்காரர்களாகவே இருந்தார்கள், மேலும் அக்காலத்தில் சூனியம் என்பது அவர்களால் இழிவான ஒன்றாகக் கருதப்படவில்லை. எனவே, இது அவர்கள் தரப்பிலிருந்து செய்யப்பட்ட அவமதிப்பு அல்ல. அவர்கள் தேவையுள்ள நிலையில் இருந்ததால், மூஸா (அலை) அவர்களை அவமதிப்பது அவர்களுக்குப் பொருத்தமானதாக இருந்திருக்காது. அவர்கள் கருதியபடி, இது அவர்களைக் கௌரவிப்பதற்காகப் பயன்படுத்தப்பட்ட ஒரு சொல்லாகும். ஒவ்வொரு சந்தர்ப்பத்திலும், தங்களுக்கு ஏற்பட்டுள்ள வேதனை நீக்கப்பட்டால், அவர்கள் மீது ஈமான் (நம்பிக்கை) கொள்வதாகவும், பனூ இஸ்ராயீல்களை அவர்களுடன் செல்ல அனுமதிப்பதாகவும் மூஸா (அலை) அவர்களிடம் வாக்குறுதி அளித்தார்கள். ஆனால் ஒவ்வொரு முறையும் அவர்கள் தங்கள் வாக்கை மீறினார்கள்.\n\r\n\n\r\nஇது பின்வரும் வசனங்களைப் போன்றது:\n\r\n\n\r\n﴾فَأَرْسَلْنَا عَلَيْهِمُ الطُّوفَانَ وَالْجَرَادَ وَالْقُمَّلَ وَالضَّفَادِعَ وَالدَّمَ ءَايَـتٍ مُّفَصَّلَاتٍ فَاسْتَكْبَرُواْ وَكَانُواْ قَوْماً مُّجْرِمِينَ - وَلَمَّا وَقَعَ عَلَيْهِمُ الرِّجْزُ قَالُواْ يَا مُوسَى ادْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ لَئِن كَشَفْتَ عَنَّا الرِّجْزَ لَنُؤْمِنَنَّ لَكَ وَلَنُرْسِلَنَّ مَعَكَ بَنِي إِسْرَائِيلَ - فَلَمَّا كَشَفْنَا عَنْهُمُ الرِّجْزَ إِلَى أَجَلٍ هُم بَـلِغُوهُ إِذَا هُمْ يَنكُثُونَ ﴿\n\r\n\n\r\n(எனவே, அவர்கள் மீது பெருவெள்ளம், வெட்டுக்கிளிகள், பேன்கள் (கும்மல்), தவளைகள் மற்றும் இரத்தம் ஆகியவற்றைத் தெளிவான அத்தாட்சிகளாக நாம் அனுப்பினோம்; அப்போதும் அவர்கள் ஆணவம் கொண்டனர், மேலும் அவர்கள் குற்றவாளிகளான மக்களாகவே இருந்தார்கள். வேதனை அவர்களைத் தாக்கியபோது, அவர்கள் கூறினார்கள்: \"ஓ மூஸாவே! உமது இறைவன் உமக்கு அளித்துள்ள வாக்குறுதியின்படி எங்களுக்காக அவனிடம் பிரார்த்தனை செய்வீராக. நீர் எங்களிடமிருந்து இந்த வேதனையை நீக்கினால், நாங்கள் நிச்சயமாக உம்மை ஈமான் கொள்வோம், மேலும் பனூ இஸ்ராயீல்களை உம்முடன் செல்ல அனுமதிப்போம்.\" ஆனால், அவர்கள் அடைய வேண்டிய ஒரு குறிப்பிட்ட தவணை வரை அவர்களிடமிருந்து வேதனையை நாம் நீக்கியபோது, இதோ! அவர்கள் தங்கள் வாக்குறுதியை மீறினார்கள்!) (7:133-135)"},"51":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=56\" class=\"link\">43:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:56 ஐ பார்க்கவும்"},"52":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=56\" class=\"link\">43:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:56 ஐ பார்க்கவும்"},"53":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=56\" class=\"link\">43:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:56 ஐ பார்க்கவும்"},"54":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=56\" class=\"link\">43:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:56 ஐ பார்க்கவும்"},"55":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=56\" class=\"link\">43:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:56 ஐ பார்க்கவும்"},"56":{"html":"<strong>ஃபிர்அவ்ன் தன் மக்களுக்கு ஆற்றிய உரையும், அல்லாஹ் அவனைத் தண்டித்த விதமும்</strong><br />\r\n<br />\r\nஃபிர்அவ்ன் தனது கிளர்ச்சியிலும் நிராகரிப்பிலும் எவ்வாறு பிடிவாதமாகத் தொடர்ந்தான் என்பதை அல்லாஹ் நமக்குக் கூறுகிறான். அவன் தனது மக்களைத் திரட்டி, எகிப்தின் மீதான தனது ஆதிக்கத்தைப் பற்றிப் பெருமையடித்தபடி அவர்களிடம் பேசினான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">مُلْكُ</span> <span class=\"quran-arabic-font text-success\">مِصْرَ</span> <span class=\"quran-arabic-font text-success\">وَهَذِهِ</span> <span class=\"quran-arabic-font text-success\">الْأَنْهَارُ</span> <span class=\"quran-arabic-font text-success\">تَجْرِي</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">تَحْتِي</span><br />\r\n<br />\r\n(எகிப்தின் ஆட்சி எனக்குரியது அல்லவா? இதோ இந்த ஆறுகள் எனக்குக் கீழே ஓடிக்கொண்டிருக்கின்றன) கத்தாதா அவர்கள் கூறினார்கள்: \"அவர்களிடம் தோட்டங்களும் ஆறுகளும் ஓடிக்கொண்டிருந்தன.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَلَا</span> <span class=\"quran-arabic-font text-success\">تُبْصِرُونَ</span><br />\r\n<br />\r\n(நீங்கள் பார்க்கவில்லையா?) அதாவது, \"எனது வலிமையையும் அதிகாரத்தையும் நீங்கள் பார்க்கவில்லையா?\" என்று அவன் கேட்டான். இதன் மூலம் மூஸா (அலை) அவர்களும் அவர்களைப் பின்பற்றியவர்களும் ஏழைகள் மற்றும் பலவீனமானவர்கள் என்று அவன் மறைமுகமாகக் குறிப்பிட்டான். இது பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَحَشَرَ</span> <span class=\"quran-arabic-font text-success\">فَنَادَى</span> - <span class=\"quran-arabic-font text-success\">فَقَالَ</span> <span class=\"quran-arabic-font text-success\">أَنَاْ</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمُ</span> <span class=\"quran-arabic-font text-success\">الْأَعْلَى</span> - <span class=\"quran-arabic-font text-success\">فَأَخَذَهُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">نَكَالَ</span> <span class=\"quran-arabic-font text-success\">الْآخِرَةِ</span> <span class=\"quran-arabic-font text-success\">وَالْأُولَى</span><br />\r\n<br />\r\n(பிறகு அவன் (தனது மக்களை) ஒன்றுதிரட்டி உரக்கக் கூறினான்: \"நானே உங்கள் மிக உயர்ந்த இறைவன்.\" ஆகவே, அல்லாஹ் அவனை இம்மை மற்றும் மறுமையின் தண்டனையால் பிடித்துக்கொண்டான்.) (<a href=\"qurandisp.php?sura=79&ayah=23\" class=\"link\">79:23</a>-25)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">مَهِينٌ</span><br />\r\n<br />\r\n(இழிவான இவரை விட நான் சிறந்தவன் அல்லவா?) அஸ்-ஸுத்தி அவர்கள் கூறினார்கள்: \"நிச்சயமாக இழிவான இவரை விட நான் சிறந்தவன் என்று அவன் கூறினான்.\" பஸ்ராவின் சில இலக்கண அறிஞர்கள், ஃபிர்அவ்ன் - அவன் மீது அல்லாஹ்வின் சாபம் உண்டாகட்டும் - தான் மூஸா (அலை) அவர்களை விடச் சிறந்தவன் என்று கூறியதாகக் குறிப்பிட்டுள்ளனர். ஆனால் இது ஒரு தெளிவான பொய்யாகும்; மறுமை நாள் வரை அவன் மீது தொடர்ச்சியான சாபங்கள் உண்டாகட்டும். மூஸா (அலை) அவர்களை 'இழிவானவர்' என்று குறிப்பிட்டதன் மூலம் - சுஃப்யான் அவர்கள் கூறியது போல் - 'முக்கியத்துவமற்றவர்' என்பதையே அவன் கருதினான். கத்தாதா மற்றும் அஸ்-ஸுத்தி ஆகியோர், \"அவன் பலவீனமானவர் என்றே கருதினான்\" என்று கூறினர். இப்னு ஜரீர் அவர்கள் கூறுகையில், \"அவருக்கு எந்த அதிகாரமோ, வலிமையோ அல்லது செல்வமோ இல்லை என்று அவன் கருதினான்\" என்றார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَكَادُ</span> <span class=\"quran-arabic-font text-success\">يُبِينُ</span><br />\r\n<br />\r\n(மேலும் இவரால் தனது கருத்தைத் தெளிவாக வெளிப்படுத்தவும் முடியவில்லை) அதாவது, அவரால் தெளிவாகப் பேச முடியாது, அவர் திக்கிப் பேசுவார் என்று அவன் கூறினான். மூஸா (அலை) அவர்களை \"இழிவானவர்\" என்று ஃபிர்அவ்ன் வர்ணித்தது முற்றிலும் பொய்யாகும்; மாறாக, உடல் ரீதியாகவும், ஒழுக்க ரீதியாகவும், மார்க்க ரீதியாகவும் தகுதியற்றவனும் இழிவானவனும் அவன்தான். மூஸா (அலை) அவர்களோ கண்ணியமானவர், உண்மையானவர், நேர்மையானவர் மற்றும் தூயவர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَكَادُ</span> <span class=\"quran-arabic-font text-success\">يُبِينُ</span><br />\r\n<br />\r\n(மேலும் இவரால் தனது கருத்தைத் தெளிவாக வெளிப்படுத்தவும் முடியவில்லை). இதுவும் ஒரு பொய்யே. மூஸா (அலை) அவர்கள் குழந்தையாக இருந்தபோது நெருப்புக்கரியால் அவரது நாவிற்குப் பாதிப்பு ஏற்பட்டிருந்தது உண்மைதான். எனினும், அவர்கள் சொல்வதை மற்றவர்கள் புரிந்துகொள்வதற்காக, தனது நாவிலுள்ள முடிச்சை அவிழ்த்துவிடுமாறு அல்லாஹ்விடம் அவர்கள் வேண்டினார்கள். அல்லாஹ்வும் அவர்களது பிரார்த்தனையை ஏற்று இவ்வாறு கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أُوتِيتَ</span> <span class=\"quran-arabic-font text-success\">سُؤْلَكَ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span><br />\r\n<br />\r\n(மூஸாவே! உமது கோரிக்கை நிறைவேற்றப்பட்டது) (<a href=\"qurandisp.php?sura=20&ayah=36\" class=\"link\">20:36</a>). அல்-ஹஸன் அல்-பஸ்ரி அவர்கள் குறிப்பிட்டது போல, அவர் நீக்குமாறு கேட்காத ஏதேனும் சிறு குறைபாடு எஞ்சியிருந்திருக்கலாம். அல்லது, தனது தூதுத்துவத்தை (Message) எடுத்துரைப்பதற்குத் தடையாக இருந்ததை மட்டும் நீக்குமாறு அவர் கேட்டிருக்கலாம். ஒரு மனிதருக்கு அவரது கட்டுப்பாட்டில் இல்லாத உடல் ரீதியான குறைகளுக்காக அவரைப் பழி கூற முடியாது. ஃபிர்அவ்னுக்கு இதைப் புரிந்து கொள்ளும் அறிவு இருந்தும், அறியாமையிலும் முட்டாள்தனத்திலும் இருந்த தனது மக்களைக் குழப்பி வழிகெடுக்க அவன் விரும்பினான். எனவே அவன் இவ்வாறு கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلَوْلَا</span> <span class=\"quran-arabic-font text-success\">أُلْقِيَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">أَسْوِرَةٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">ذَهَبٍ</span><br />\r\n<br />\r\n(அப்படியானால் அவருக்கு ஏன் தங்கக் காப்புகள் அணிவிக்கப்படவில்லை?) அதாவது, கைகளில் அணியப்படும் ஆபரணங்கள். இது இப்னு அப்பாஸ் (ரழி), கத்தாதா மற்றும் பலரது கருத்தாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">جَاءَ</span> <span class=\"quran-arabic-font text-success\">مَعَهُ</span> <span class=\"quran-arabic-font text-success\">الْمَلَائِكَةُ</span> <span class=\"quran-arabic-font text-success\">مُقْتَرِنِينَ</span><br />\r\n<br />\r\n(அல்லது அவருடன் வானவர்கள் அணிவகுத்து வர வேண்டாமா?) அதாவது, அவருக்குச் சேவை செய்யவும், அவர் உண்மையைத்தான் கூறுகிறார் என்று சாட்சி கூறவும் வானவர்கள் வரவேண்டாமா என்று கேட்டான். அவன் வெளிப்படையான தோற்றங்களை மட்டுமே பார்த்தான்; அவன் கவனித்ததை விடவும் மிகத் தெளிவான ஆழமான உண்மைகளை அவன் புரிந்துகொள்ளவில்லை. அவன் அதைச் சிந்தித்திருந்தால் புரிந்திருக்கும். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاسْتَخَفَّ</span> <span class=\"quran-arabic-font text-success\">قَوْمَهُ</span> <span class=\"quran-arabic-font text-success\">فَأَطَاعُوهُ</span><br />\r\n<br />\r\n(இவ்வாறு அவன் தனது மக்களை முட்டாளாக்கினான், அவர்களும் அவனுக்குக் கீழ்ப்படிந்தார்கள்.) அதாவது, அவன் அவர்களைக் குழப்பி வழிகேட்டின் பக்கம் அழைத்தான், அவர்களும் அவனுக்குப் பதிலளித்தனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">كَانُوا</span> <span class=\"quran-arabic-font text-success\">قَوْمًا</span> <span class=\"quran-arabic-font text-success\">فَاسِقِينَ</span><br />\r\n<br />\r\n(நிச்சயமாக, அவர்கள் வரம்பு மீறிய பாவம் செய்யும் சமூகமாக இருந்தனர்.) பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">آسَفُونَا</span> <span class=\"quran-arabic-font text-success\">انتَقَمْنَا</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">فَأَغْرَقْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْمَعِينَ</span><br />\r\n<br />\r\n(அவர்கள் நமக்குக் கோபமூட்டியபோது, நாம் அவர்களைத் தண்டித்தோம்; மேலும் அவர்கள் அனைவரையும் மூழ்கடித்தோம்.) \"அவர்கள் நமக்குக் கோபமூட்டியபோது\" என்பதற்கு \"அவர்கள் நமது கோபத்தைத் தூண்டினார்கள்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அலீ பின் அபீ தல்ஹா அறிவிக்கிறார்கள். அத்-தஹ்ஹாக் அவர்கள், \"அவர்கள் நம்மைக் கோபப்படுத்தினார்கள்\" என்று கூறினார்கள். இதுவே இப்னு அப்பாஸ் (ரழி), முஜாஹித், இக்ரிமா, ஸயீத் பின் ஜுபைர், முஹம்மது பின் கஅப் அல்-குரழீ, கத்தாதா, அஸ்-ஸுத்தி மற்றும் பிற தஃப்ஸீர் அறிஞர்களின் கருத்தாகும். இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளதாவது: உக்பா பின் ஆமிர் (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">رَأَيْتَ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">تَبَارَكَ</span> <span class=\"quran-arabic-font text-success\">وَتَعَالَى</span> <span class=\"quran-arabic-font text-success\">يُعْطِي</span> <span class=\"quran-arabic-font text-success\">الْعَبْدَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَشَاءُ،</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">مُقِيمٌ</span> <span class=\"quran-arabic-font text-success\">عَلى</span> <span class=\"quran-arabic-font text-success\">مَعَاصِيهِ،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">اسْتِدْرَاجٌ</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">لَه</span>»<br />\r\n<br />\r\n(ஒரு அடியார் பாவங்களில் மூழ்கியிருக்கும் போதே, அவருக்கு விருப்பமானவற்றை அல்லாஹ் வழங்கி வருவதை நீங்கள் கண்டால், அது அல்லாஹ் அவரை மெல்ல மெல்ல அழிவை நோக்கி இழுத்துச் செல்கிறான் என்று பொருளாகும்.) பிறகு அவர்கள் இந்த வசனத்தை ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">آسَفُونَا</span> <span class=\"quran-arabic-font text-success\">انتَقَمْنَا</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">فَأَغْرَقْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْمَعِينَ</span><br />\r\n<br />\r\n(அவர்கள் நமக்குக் கோபமூட்டியபோது, நாம் அவர்களைத் தண்டித்தோம்; மேலும் அவர்கள் அனைவரையும் மூழ்கடித்தோம்.) தாரிக் பின் ஷிஹாப் அவர்கள் கூறியதாக அறிவிக்கப்படுகிறது: \"நான் அப்துல்லாஹ் (ரழி) அவர்களுடன் இருந்தபோது திடீர் மரணம் பற்றிப் பேசப்பட்டது. அதற்கு அவர்கள், 'இது முஃமினுக்கு (இறைநம்பிக்கையாளருக்கு) ஒரு நிம்மதியாகும், காஃபிருக்கு (நிராகரிப்பவருக்கு) அது வருத்தத்தின் ஆதாரமாகும்' என்று கூறிவிட்டு, இந்த வசனத்தை ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">آسَفُونَا</span> <span class=\"quran-arabic-font text-success\">انتَقَمْنَا</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">فَأَغْرَقْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْمَعِينَ</span><br />\r\n<br />\r\n(அவர்கள் நமக்குக் கோபமூட்டியபோது, நாம் அவர்களைத் தண்டித்தோம்; மேலும் அவர்கள் அனைவரையும் மூழ்கடித்தோம்.)\" உமர் பின் அப்துல்-அஜீஸ் அவர்கள் கூறினார்கள்: \"தண்டனை என்பது அலட்சியத்துடன் வருவதை நான் கண்டேன். அதாவது இந்த வசனத்தின்படி:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">آسَفُونَا</span> <span class=\"quran-arabic-font text-success\">انتَقَمْنَا</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">فَأَغْرَقْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْمَعِينَ</span><br />\r\n<br />\r\n(அவர்கள் நமக்குக் கோபமூட்டியபோது, நாம் அவர்களைத் தண்டித்தோம்; மேலும் அவர்கள் அனைவரையும் மூழ்கடித்தோம்).\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَجَعَلْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">سَلَفًا</span> <span class=\"quran-arabic-font text-success\">وَمَثَلًا</span> <span class=\"quran-arabic-font text-success\">لِّلْآخِرِينَ</span><br />\r\n<br />\r\n(மேலும் நாம் அவர்களை முன்மாதிரியாகவும், பிற்காலத்தவர்களுக்கு ஒரு படிப்பினையாகவும் ஆக்கினோம்.) அபூ மிஜ்லஸ் அவர்கள் கூறினார்கள்: \"அவர்கள் செய்ததைப் போலவே செய்பவர்களுக்கு அவர்கள் ஒரு முன்மாதிரி.\" அவரும் முஜாஹித் அவர்களும் கூறுகையில், \"அதாவது, அவர்களுக்குப் பின் வருபவர்களுக்கு ஒரு படிப்பினையாக ஆக்கினோம்\" என்றார்கள். அல்லாஹ்வே நேர்வழி காட்டுபவன்; அவனிடமே மீளுதல் உண்டு.<br />\r\n<br />","text":"ஃபிர்அவ்ன் தன் மக்களுக்கு ஆற்றிய உரையும், அல்லாஹ் அவனைத் தண்டித்த விதமும்\n\r\n\n\r\nஃபிர்அவ்ன் தனது கிளர்ச்சியிலும் நிராகரிப்பிலும் எவ்வாறு பிடிவாதமாகத் தொடர்ந்தான் என்பதை அல்லாஹ் நமக்குக் கூறுகிறான். அவன் தனது மக்களைத் திரட்டி, எகிப்தின் மீதான தனது ஆதிக்கத்தைப் பற்றிப் பெருமையடித்தபடி அவர்களிடம் பேசினான்.\n\r\n\n\r\nأَلَيْسَ لِي مُلْكُ مِصْرَ وَهَذِهِ الْأَنْهَارُ تَجْرِي مِن تَحْتِي\n\r\n\n\r\n(எகிப்தின் ஆட்சி எனக்குரியது அல்லவா? இதோ இந்த ஆறுகள் எனக்குக் கீழே ஓடிக்கொண்டிருக்கின்றன) கத்தாதா அவர்கள் கூறினார்கள்: \"அவர்களிடம் தோட்டங்களும் ஆறுகளும் ஓடிக்கொண்டிருந்தன.\"\n\r\n\n\r\nأَفَلَا تُبْصِرُونَ\n\r\n\n\r\n(நீங்கள் பார்க்கவில்லையா?) அதாவது, \"எனது வலிமையையும் அதிகாரத்தையும் நீங்கள் பார்க்கவில்லையா?\" என்று அவன் கேட்டான். இதன் மூலம் மூஸா (அலை) அவர்களும் அவர்களைப் பின்பற்றியவர்களும் ஏழைகள் மற்றும் பலவீனமானவர்கள் என்று அவன் மறைமுகமாகக் குறிப்பிட்டான். இது பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\nفَحَشَرَ فَنَادَى - فَقَالَ أَنَاْ رَبُّكُمُ الْأَعْلَى - فَأَخَذَهُ اللَّهُ نَكَالَ الْآخِرَةِ وَالْأُولَى\n\r\n\n\r\n(பிறகு அவன் (தனது மக்களை) ஒன்றுதிரட்டி உரக்கக் கூறினான்: \"நானே உங்கள் மிக உயர்ந்த இறைவன்.\" ஆகவே, அல்லாஹ் அவனை இம்மை மற்றும் மறுமையின் தண்டனையால் பிடித்துக்கொண்டான்.) (79:23-25)\n\r\n\n\r\nأَمْ أَنَا خَيْرٌ مِّنْ هَذَا الَّذِي هُوَ مَهِينٌ\n\r\n\n\r\n(இழிவான இவரை விட நான் சிறந்தவன் அல்லவா?) அஸ்-ஸுத்தி அவர்கள் கூறினார்கள்: \"நிச்சயமாக இழிவான இவரை விட நான் சிறந்தவன் என்று அவன் கூறினான்.\" பஸ்ராவின் சில இலக்கண அறிஞர்கள், ஃபிர்அவ்ன் - அவன் மீது அல்லாஹ்வின் சாபம் உண்டாகட்டும் - தான் மூஸா (அலை) அவர்களை விடச் சிறந்தவன் என்று கூறியதாகக் குறிப்பிட்டுள்ளனர். ஆனால் இது ஒரு தெளிவான பொய்யாகும்; மறுமை நாள் வரை அவன் மீது தொடர்ச்சியான சாபங்கள் உண்டாகட்டும். மூஸா (அலை) அவர்களை 'இழிவானவர்' என்று குறிப்பிட்டதன் மூலம் - சுஃப்யான் அவர்கள் கூறியது போல் - 'முக்கியத்துவமற்றவர்' என்பதையே அவன் கருதினான். கத்தாதா மற்றும் அஸ்-ஸுத்தி ஆகியோர், \"அவன் பலவீனமானவர் என்றே கருதினான்\" என்று கூறினர். இப்னு ஜரீர் அவர்கள் கூறுகையில், \"அவருக்கு எந்த அதிகாரமோ, வலிமையோ அல்லது செல்வமோ இல்லை என்று அவன் கருதினான்\" என்றார்கள்.\n\r\n\n\r\nوَلَا يَكَادُ يُبِينُ\n\r\n\n\r\n(மேலும் இவரால் தனது கருத்தைத் தெளிவாக வெளிப்படுத்தவும் முடியவில்லை) அதாவது, அவரால் தெளிவாகப் பேச முடியாது, அவர் திக்கிப் பேசுவார் என்று அவன் கூறினான். மூஸா (அலை) அவர்களை \"இழிவானவர்\" என்று ஃபிர்அவ்ன் வர்ணித்தது முற்றிலும் பொய்யாகும்; மாறாக, உடல் ரீதியாகவும், ஒழுக்க ரீதியாகவும், மார்க்க ரீதியாகவும் தகுதியற்றவனும் இழிவானவனும் அவன்தான். மூஸா (அலை) அவர்களோ கண்ணியமானவர், உண்மையானவர், நேர்மையானவர் மற்றும் தூயவர்.\n\r\n\n\r\nوَلَا يَكَادُ يُبِينُ\n\r\n\n\r\n(மேலும் இவரால் தனது கருத்தைத் தெளிவாக வெளிப்படுத்தவும் முடியவில்லை). இதுவும் ஒரு பொய்யே. மூஸா (அலை) அவர்கள் குழந்தையாக இருந்தபோது நெருப்புக்கரியால் அவரது நாவிற்குப் பாதிப்பு ஏற்பட்டிருந்தது உண்மைதான். எனினும், அவர்கள் சொல்வதை மற்றவர்கள் புரிந்துகொள்வதற்காக, தனது நாவிலுள்ள முடிச்சை அவிழ்த்துவிடுமாறு அல்லாஹ்விடம் அவர்கள் வேண்டினார்கள். அல்லாஹ்வும் அவர்களது பிரார்த்தனையை ஏற்று இவ்வாறு கூறினான்:\n\r\n\n\r\nقَدْ أُوتِيتَ سُؤْلَكَ يَا مُوسَى\n\r\n\n\r\n(மூஸாவே! உமது கோரிக்கை நிறைவேற்றப்பட்டது) (20:36). அல்-ஹஸன் அல்-பஸ்ரி அவர்கள் குறிப்பிட்டது போல, அவர் நீக்குமாறு கேட்காத ஏதேனும் சிறு குறைபாடு எஞ்சியிருந்திருக்கலாம். அல்லது, தனது தூதுத்துவத்தை (Message) எடுத்துரைப்பதற்குத் தடையாக இருந்ததை மட்டும் நீக்குமாறு அவர் கேட்டிருக்கலாம். ஒரு மனிதருக்கு அவரது கட்டுப்பாட்டில் இல்லாத உடல் ரீதியான குறைகளுக்காக அவரைப் பழி கூற முடியாது. ஃபிர்அவ்னுக்கு இதைப் புரிந்து கொள்ளும் அறிவு இருந்தும், அறியாமையிலும் முட்டாள்தனத்திலும் இருந்த தனது மக்களைக் குழப்பி வழிகெடுக்க அவன் விரும்பினான். எனவே அவன் இவ்வாறு கூறினான்:\n\r\n\n\r\nفَلَوْلَا أُلْقِيَ عَلَيْهِ أَسْوِرَةٌ مِّن ذَهَبٍ\n\r\n\n\r\n(அப்படியானால் அவருக்கு ஏன் தங்கக் காப்புகள் அணிவிக்கப்படவில்லை?) அதாவது, கைகளில் அணியப்படும் ஆபரணங்கள். இது இப்னு அப்பாஸ் (ரழி), கத்தாதா மற்றும் பலரது கருத்தாகும்.\n\r\n\n\r\nأَوْ جَاءَ مَعَهُ الْمَلَائِكَةُ مُقْتَرِنِينَ\n\r\n\n\r\n(அல்லது அவருடன் வானவர்கள் அணிவகுத்து வர வேண்டாமா?) அதாவது, அவருக்குச் சேவை செய்யவும், அவர் உண்மையைத்தான் கூறுகிறார் என்று சாட்சி கூறவும் வானவர்கள் வரவேண்டாமா என்று கேட்டான். அவன் வெளிப்படையான தோற்றங்களை மட்டுமே பார்த்தான்; அவன் கவனித்ததை விடவும் மிகத் தெளிவான ஆழமான உண்மைகளை அவன் புரிந்துகொள்ளவில்லை. அவன் அதைச் சிந்தித்திருந்தால் புரிந்திருக்கும். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَاسْتَخَفَّ قَوْمَهُ فَأَطَاعُوهُ\n\r\n\n\r\n(இவ்வாறு அவன் தனது மக்களை முட்டாளாக்கினான், அவர்களும் அவனுக்குக் கீழ்ப்படிந்தார்கள்.) அதாவது, அவன் அவர்களைக் குழப்பி வழிகேட்டின் பக்கம் அழைத்தான், அவர்களும் அவனுக்குப் பதிலளித்தனர்.\n\r\n\n\r\nإِنَّهُمْ كَانُوا قَوْمًا فَاسِقِينَ\n\r\n\n\r\n(நிச்சயமாக, அவர்கள் வரம்பு மீறிய பாவம் செய்யும் சமூகமாக இருந்தனர்.) பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَلَمَّا آسَفُونَا انتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَاهُمْ أَجْمَعِينَ\n\r\n\n\r\n(அவர்கள் நமக்குக் கோபமூட்டியபோது, நாம் அவர்களைத் தண்டித்தோம்; மேலும் அவர்கள் அனைவரையும் மூழ்கடித்தோம்.) \"அவர்கள் நமக்குக் கோபமூட்டியபோது\" என்பதற்கு \"அவர்கள் நமது கோபத்தைத் தூண்டினார்கள்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அலீ பின் அபீ தல்ஹா அறிவிக்கிறார்கள். அத்-தஹ்ஹாக் அவர்கள், \"அவர்கள் நம்மைக் கோபப்படுத்தினார்கள்\" என்று கூறினார்கள். இதுவே இப்னு அப்பாஸ் (ரழி), முஜாஹித், இக்ரிமா, ஸயீத் பின் ஜுபைர், முஹம்மது பின் கஅப் அல்-குரழீ, கத்தாதா, அஸ்-ஸுத்தி மற்றும் பிற தஃப்ஸீர் அறிஞர்களின் கருத்தாகும். இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளதாவது: உக்பா பின் ஆமிர் (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِذَا رَأَيْتَ اللهَ تَبَارَكَ وَتَعَالَى يُعْطِي الْعَبْدَ مَا يَشَاءُ، وَهُوَ مُقِيمٌ عَلى مَعَاصِيهِ، فَإِنَّمَا ذَلِكَ اسْتِدْرَاجٌ مِنْهُ لَه»\n\r\n\n\r\n(ஒரு அடியார் பாவங்களில் மூழ்கியிருக்கும் போதே, அவருக்கு விருப்பமானவற்றை அல்லாஹ் வழங்கி வருவதை நீங்கள் கண்டால், அது அல்லாஹ் அவரை மெல்ல மெல்ல அழிவை நோக்கி இழுத்துச் செல்கிறான் என்று பொருளாகும்.) பிறகு அவர்கள் இந்த வசனத்தை ஓதினார்கள்:\n\r\n\n\r\nفَلَمَّا آسَفُونَا انتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَاهُمْ أَجْمَعِينَ\n\r\n\n\r\n(அவர்கள் நமக்குக் கோபமூட்டியபோது, நாம் அவர்களைத் தண்டித்தோம்; மேலும் அவர்கள் அனைவரையும் மூழ்கடித்தோம்.) தாரிக் பின் ஷிஹாப் அவர்கள் கூறியதாக அறிவிக்கப்படுகிறது: \"நான் அப்துல்லாஹ் (ரழி) அவர்களுடன் இருந்தபோது திடீர் மரணம் பற்றிப் பேசப்பட்டது. அதற்கு அவர்கள், 'இது முஃமினுக்கு (இறைநம்பிக்கையாளருக்கு) ஒரு நிம்மதியாகும், காஃபிருக்கு (நிராகரிப்பவருக்கு) அது வருத்தத்தின் ஆதாரமாகும்' என்று கூறிவிட்டு, இந்த வசனத்தை ஓதினார்கள்:\n\r\n\n\r\nفَلَمَّا آسَفُونَا انتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَاهُمْ أَجْمَعِينَ\n\r\n\n\r\n(அவர்கள் நமக்குக் கோபமூட்டியபோது, நாம் அவர்களைத் தண்டித்தோம்; மேலும் அவர்கள் அனைவரையும் மூழ்கடித்தோம்.)\" உமர் பின் அப்துல்-அஜீஸ் அவர்கள் கூறினார்கள்: \"தண்டனை என்பது அலட்சியத்துடன் வருவதை நான் கண்டேன். அதாவது இந்த வசனத்தின்படி:\n\r\n\n\r\nفَلَمَّا آسَفُونَا انتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَاهُمْ أَجْمَعِينَ\n\r\n\n\r\n(அவர்கள் நமக்குக் கோபமூட்டியபோது, நாம் அவர்களைத் தண்டித்தோம்; மேலும் அவர்கள் அனைவரையும் மூழ்கடித்தோம்).\"\n\r\n\n\r\nفَجَعَلْنَاهُمْ سَلَفًا وَمَثَلًا لِّلْآخِرِينَ\n\r\n\n\r\n(மேலும் நாம் அவர்களை முன்மாதிரியாகவும், பிற்காலத்தவர்களுக்கு ஒரு படிப்பினையாகவும் ஆக்கினோம்.) அபூ மிஜ்லஸ் அவர்கள் கூறினார்கள்: \"அவர்கள் செய்ததைப் போலவே செய்பவர்களுக்கு அவர்கள் ஒரு முன்மாதிரி.\" அவரும் முஜாஹித் அவர்களும் கூறுகையில், \"அதாவது, அவர்களுக்குப் பின் வருபவர்களுக்கு ஒரு படிப்பினையாக ஆக்கினோம்\" என்றார்கள். அல்லாஹ்வே நேர்வழி காட்டுபவன்; அவனிடமே மீளுதல் உண்டு."},"57":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=65\" class=\"link\">43:65</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:65 ஐ பார்க்கவும்"},"58":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=65\" class=\"link\">43:65</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:65 ஐ பார்க்கவும்"},"59":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=65\" class=\"link\">43:65</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:65 ஐ பார்க்கவும்"},"60":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=65\" class=\"link\">43:65</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:65 ஐ பார்க்கவும்"},"61":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=65\" class=\"link\">43:65</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:65 ஐ பார்க்கவும்"},"62":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=65\" class=\"link\">43:65</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:65 ஐ பார்க்கவும்"},"63":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=65\" class=\"link\">43:65</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:65 ஐ பார்க்கவும்"},"64":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=65\" class=\"link\">43:65</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:65 ஐ பார்க்கவும்"},"65":{"html":"<strong>மர்யமின் மகன் விஷயத்தில் குறைஷிகளின் ஏளனமும், அல்லாஹ்விடம் அவருக்குள்ள உண்மையான அந்தஸ்தும்</strong><br />\r\n<br />\r\nகுறைஷிகள் எவ்வாறு தங்களது இறைநிராகரிப்பிலும், பிடிவாதமான தர்க்கங்களிலும் நிலைத்திருந்தனர் என்பதை அல்லாஹ் நமக்குக் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَمَّا</span> <span class=\"quran-arabic-font text-success\">ضُرِبَ</span> <span class=\"quran-arabic-font text-success\">ابْنُ</span> <span class=\"quran-arabic-font text-success\">مَرْيَمَ</span> <span class=\"quran-arabic-font text-success\">مَثَلاً</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">قَوْمُكَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">يَصِدُّونَ</span><br />\r\n<br />\r\n(மர்யமின் மகன் ஓர் உதாரணமாகக் கூறப்பட்டபோது, இதோ, உம்முடைய சமூகத்தார் (அதைக் கேட்டு) ஆரவாரம் செய்கிறார்கள்.) இப்னு அப்பாஸ் (ரழி), முஜாஹித், இக்ரிமா, அஸ்-ஸுத்தீ மற்றும் அத்-தஹ்ஹாக் ஆகியோர், \"அவர்கள் சிரித்தார்கள்; அதாவது, அவர்கள் அதனால் வியப்படைந்தார்கள்\" என்று கூறியதாகப் பலரும் அறிவிக்கிறார்கள். கத்தாதா அவர்கள், \"அவர்கள் அதைக் கண்டு வெறுப்படைந்து சிரித்தார்கள்\" என்று கூறினார்கள். இப்ராஹீம் அந்-நகஈ அவர்கள், \"அவர்கள் புறக்கணித்துத் திரும்பிக் கொண்டனர்\" என்று கூறினார்கள். இதற்கான காரணத்தை முஹம்மது பின் இஸ்ஹாக் அவர்கள் 'அஸ்-ஸீரா'வில் குறிப்பிட்டுள்ளார்கள். அவர் கூறினார்கள்: \"எனக்குக் கிடைத்த தகவலின்படி, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஒரு நாள் மஸ்ஜிதில் அல்-வலீத் பின் அல்-முஃகீராவுடன் அமர்ந்திருந்தார்கள். அப்போது அந்-நள்ரு பின் அல்-ஹாரித் வந்து அவர்களுடன் அமர்ந்தார். அந்தச் சபையில் குறைஷிகளைச் சேர்ந்த வேறு சில ஆண்களும் இருந்தனர். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் உரையாற்றினார்கள். அப்போது அந்-நள்ரு பின் அல்-ஹாரித் அவர்களிடம் வந்தார். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் வாதத்தில் அவரைத் தோற்கடிக்கும் வரை அவரிடம் பேசினார்கள். பிறகு அவருக்கும் அங்கிருந்தவர்களுக்கும் பின்வரும் வசனத்தை ஓதிக்காட்டினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَعْبُدُونَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">حَصَبُ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">وَارِدُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக நீங்களும், அல்லாஹ்வையன்றி நீங்கள் வணங்குபவையும் நரகத்தின் எரிபொருட்களே! நீங்கள் அனைவரும் அதில் நுழைவீர்கள்.) (<a href=\"qurandisp.php?sura=21&ayah=98\" class=\"link\">21:98</a>) பிறகு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் எழுந்து சென்று அப்துல்லாஹ் பின் அஸ்-ஸபஅரீ அஸ்-ஸஹ்மீயுடன் அமர்ந்தார்கள். அல்-வலீத் பின் அல்-முஃகீரா அவரிடம், 'அல்லாஹ்வின் மீது ஆணையாக, வாதத்தில் அப்துல் முத்தலிபின் மகனுக்கு (முஹம்மது (ஸல்) அவர்களுக்கு) அந்-நள்ரு பின் அல்-ஹாரித்தால் ஈடுகொடுக்க முடியவில்லை. நாமும் நாம் வணங்கும் இந்தத் தெய்வங்களும் நரகத்தின் எரிபொருட்கள் என்று முஹம்மது (ஸல்) அவர்கள் கூறுகிறார்கள்' என்றார். அப்துல்லாஹ் பின் அஸ்-ஸபஅரீ, 'அல்லாஹ்வின் மீது ஆணையாக, நான் அவரைச் சந்தித்தால் வாதத்தில் அவரைத் தோற்கடித்து விடுவேன். அல்லாஹ்வையன்றி வணங்கப்படும் அனைவரும், அவர்களை வணங்கியவர்களுடன் நரகத்தில் இருப்பார்களா என்று முஹம்மது (ஸல்) அவர்களிடம் கேளுங்கள். ஏனெனில் நாம் வானவர்களை வணங்குகிறோம், யூதர்கள் உஸைரை (அலை) வணங்குகிறார்கள், கிறிஸ்தவர்கள் மஸீஹ் ஈஸா பின் மர்யமை (அலை) வணங்குகிறார்கள்' என்றார். அப்துல்லாஹ் பின் அஸ்-ஸபஅரீ கூறியதைக் கேட்டு அல்-வலீதும் அங்கிருந்த மற்றவர்களும் வியப்படைந்தனர். அவர் ஒரு வலுவான வாதத்தை முன்வைத்ததாக அவர்கள் எண்ணினார்கள். இது அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கூறப்பட்டபோது, அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَحَبَّ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يُعْبَدَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">مَعَ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">عَبَدَهُ،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">يَعْبُدُونَ</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَانَ</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَمَرَهُمْ</span> <span class=\"quran-arabic-font text-success\">بِعِبَادَتِه</span>»<br />\r\n<br />\r\n(அல்லாஹ்வையன்றி தான் வணங்கப்படுவதை யார் விரும்புகிறாரோ, அவர் தன்னை வணங்கியவருடன் இருப்பார். ஏனெனில், அவர்கள் உண்மையில் ஷைத்தானையும், அந்த நபரை வணங்கும்படி அவர்களுக்குக் கட்டளையிட்டவனையுமே வணங்குகிறார்கள்.)\" பின்னர் அல்லாஹ் இந்த வார்த்தைகளை வஹீ (இறைச்செய்தி)யாக அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">سَبَقَتْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَّا</span> <span class=\"quran-arabic-font text-success\">الْحُسْنَى</span> <span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">عَنْهَا</span> <span class=\"quran-arabic-font text-success\">مُبْعَدُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக, எவர்களுக்கு நம்மிடமிருந்து நற்பேறு முந்திவிட்டதோ, அவர்கள் நரகத்தை விட்டு வெகுதூரம் அப்புறப்படுத்தப்படுவார்கள்.) (<a href=\"qurandisp.php?sura=21&ayah=101\" class=\"link\">21:101</a>). அதாவது, மக்களால் வணங்கப்பட்ட ஈஸா (அலை), உஸைர் (அலை) மற்றும் அல்லாஹ்வுக்குப் பணிந்து வாழ்ந்த அறிஞர்களும் துறவிகளும் இதில் அடங்குவர். அவர்களுக்குப் பின் வந்த வழிகெட்ட மக்கள், அல்லாஹ்வையன்றி அவர்களைத் தெய்வங்களாக எடுத்துக் கொண்டனர். வானவர்களை அல்லாஹ்வின் மகள்களாகக் கருதி வணங்குவது குறித்துப் பின்வரும் வசனம் வஹீ (இறைச்செய்தி)யாக அருளப்பட்டது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">اتَّخَذَ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنُ</span> <span class=\"quran-arabic-font text-success\">وَلَداً</span> <span class=\"quran-arabic-font text-success\">سُبْحَانَهُ</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">عِبَادٌ</span> <span class=\"quran-arabic-font text-success\">مُّكْرَمُونَ</span><br />\r\n<br />\r\n(மேலும், \"அளவற்ற அருளாளன் ஒரு மகனை (அல்லது சந்ததியை) ஏற்படுத்திக் கொண்டான்\" என்று அவர்கள் கூறுகிறார்கள். அவன் மிகவும் தூய்மையானவன்! மாறாக, அவர்கள் (வானவர்கள்) கண்ணியப்படுத்தப்பட்ட அடியார்களே ஆவர்.) (<a href=\"qurandisp.php?sura=21&ayah=26\" class=\"link\">21:26</a>) ஈஸா பின் மர்யம் (அலை) அவர்கள் அல்லாஹ்வையன்றி வணங்கப்படுவதைப் பற்றியும், அந்தத் தர்க்கத்தின் போது வலீத் மற்றும் அங்கிருந்தவர்களின் வியப்பைப் பற்றியும் பின்வரும் வசனம் அருளப்பட்டது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَمَّا</span> <span class=\"quran-arabic-font text-success\">ضُرِبَ</span> <span class=\"quran-arabic-font text-success\">ابْنُ</span> <span class=\"quran-arabic-font text-success\">مَرْيَمَ</span> <span class=\"quran-arabic-font text-success\">مَثَلاً</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">قَوْمُكَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">يَصِدُّونَ</span><br />\r\n<br />\r\n(மர்யமின் மகன் ஓர் உதாரணமாகக் கூறப்பட்டபோது, இதோ, உம்முடைய சமூகத்தார் (அதைக் கேட்டு) ஆரவாரம் செய்கிறார்கள்.) அதாவது, உமது தூதுச் செய்தியை நிராகரிப்பதற்கு இந்த வாதத்தை அவர்கள் ஒரு சாக்காக எடுத்துக் கொள்கிறார்கள். பிறகு அல்லாஹ் ஈஸா பின் மர்யம் (அலை) அவர்களைப் பற்றிக் குறிப்பிடுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَبْدٌ</span> <span class=\"quran-arabic-font text-success\">أَنْعَمْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">وَجَعَلْنَـهُ</span> <span class=\"quran-arabic-font text-success\">مَثَلاً</span> <span class=\"quran-arabic-font text-success\">لِّبَنِى</span> <span class=\"quran-arabic-font text-success\">إِسْرَءِيلَ</span> - <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">نَشَآءُ</span> <span class=\"quran-arabic-font text-success\">لَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِنكُمْ</span> <span class=\"quran-arabic-font text-success\">مَّلَـئِكَةً</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">يَخْلُفُونَ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَعِلْمٌ</span> <span class=\"quran-arabic-font text-success\">لِّلسَّاعَةِ</span><br />\r\n<br />\r\n(அவர் ஓர் அடியாரே தவிர வேறில்லை. அவருக்கு நாம் அருள்புரிந்தோம்; அவரை இஸ்ரவேலர்களுக்கு ஓர் உதாரணமாகவும் ஆக்கினோம். நாம் நாடியிருந்தால், உங்களுக்குப் பதிலாக பூமியில் வசிப்பதற்கு வானவர்களையே ஏற்படுத்தியிருப்போம். நிச்சயமாக அவர் (ஈஸா (அலை)) மறுமை நாளுக்கான ஒரு அடையாளமாவார்.) அதாவது, அவர் மூலமாக நிகழ்ந்த இறந்தவர்களை உயிர்ப்பித்தல், நோயாளிகளைக் குணப்படுத்துதல் போன்ற அற்புதங்களே மறுமை நாள் நெருங்குவதற்கான அடையாளங்களாகப் போதுமானவை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">تَمْتَرُنَّ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">وَاتَّبِعُونِ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">صِرَطٌ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقِيمٌ</span><br />\r\n<br />\r\n(எனவே, அதைப் பற்றி நீங்கள் சந்தேகம் கொள்ளாதீர்கள். என்னைப் பின்பற்றுங்கள். இதுவே நேரான வழியாகும்.) இப்னு ஜரீர் அவர்கள் பதிவு செய்துள்ளதாவது: அல்-அவ்ஃபீ அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து இந்த வசனம் குறித்து அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَمَّا</span> <span class=\"quran-arabic-font text-success\">ضُرِبَ</span> <span class=\"quran-arabic-font text-success\">ابْنُ</span> <span class=\"quran-arabic-font text-success\">مَرْيَمَ</span> <span class=\"quran-arabic-font text-success\">مَثَلاً</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">قَوْمُكَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">يَصِدُّونَ</span><br />\r\n<br />\r\n(மர்யமின் மகன் ஓர் உதாரணமாகக் கூறப்பட்டபோது, இதோ, உம்முடைய சமூகத்தார் (அதைக் கேட்டு) ஆரவாரம் செய்கிறார்கள்.) \"இதன் பொருள் குறைஷிகள்; அவர்களிடம் பின்வரும் வசனம் ஓதப்பட்டபோது:\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَعْبُدُونَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">حَصَبُ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">وَارِدُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக நீங்களும், அல்லாஹ்வையன்றி நீங்கள் வணங்குபவையும் நரகத்தின் எரிபொருட்களே! நீங்கள் அனைவரும் அதில் நுழைவீர்கள்.) (<a href=\"qurandisp.php?sura=21&ayah=98\" class=\"link\">21:98</a>) குறைஷிகள் அவரிடம், 'ஈஸா பின் மர்யமின் நிலை என்ன?' என்று கேட்டார்கள். அதற்கு அவர் கூறினார்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">ذَاكَ</span> <span class=\"quran-arabic-font text-success\">عَبْدُاللهِ</span> <span class=\"quran-arabic-font text-success\">وَرَسُولُه</span>»<br />\r\n<br />\r\n(அவர் அல்லாஹ்வின் அடியாரும் அவனது தூதரும் ஆவார்.) அதற்கு அவர்கள், 'அல்லாஹ்வின் மீது ஆணையாக! கிறிஸ்தவர்கள் ஈஸா பின் மர்யமைத் தங்கள் இறைவனாக எடுத்துக் கொண்டது போல, நாமும் இவரை இறைவனாக எடுத்துக் கொள்ள வேண்டும் என்றுதான் இவர் விரும்புகிறார்' என்று கூறினார்கள். பின்னர் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">ضَرَبُوهُ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">جَدَلاَ</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">خَصِمُونَ</span><br />\r\n<br />\r\n(அவர்கள் இந்த உதாரணத்தை உமக்குக் கூறியதெல்லாம் தர்க்கத்திற்காகவேயன்றி வேறில்லை. இல்லை, அவர்கள் வீண் விவாதம் செய்யும் கூட்டத்தினரே!)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">ءَأَالِهَتُنَا</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span><br />\r\n<br />\r\n(மேலும், \"எங்கள் தெய்வங்கள் சிறந்தவையா அல்லது அவரா?\" என்று அவர்கள் கேட்கிறார்கள்.) கத்தாதா அவர்கள், \"எங்கள் தெய்வங்கள் அவரை விடச் சிறந்தவை என்று அவர்கள் கூறி வந்தனர்\" என்றார். மேலும் கத்தாதா அவர்கள், \"இப்னு மஸ்ஊத் (ரழி) அவர்கள் (<span class=\"quran-arabic-font text-success\">أَآلِهَتُنَا</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">هذَا</span>) - 'எங்கள் தெய்வங்கள் சிறந்தவையா அல்லது இவரா?' என்று ஓதினார்கள்\" எனக் குறிப்பிடுகிறார். இதன் மூலம் அவர்கள் முஹம்மது (ஸல்) அவர்களைக் குறிப்பிடுகிறார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">ضَرَبُوهُ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">جَدَلاَ</span><br />\r\n<br />\r\n(அவர்கள் இந்த உதாரணத்தை உமக்குக் கூறியதெல்லாம் தர்க்கத்திற்காகவேயன்றி வேறில்லை.) அதாவது, பிடிவாதமான விவாதத்திற்காகவே அவர்கள் அப்படிச் சொன்னார்கள். ஏனெனில் அந்த வசனத்தில் (<a href=\"qurandisp.php?sura=21&ayah=98\" class=\"link\">21:98</a>) ஈஸா (அலை) அவர்கள் உள்ளடக்கப்படவில்லை என்பது அவர்களுக்குத் தெரியும்; ஏனெனில் அவ்வாறு கூறுவது அர்த்தமற்றது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَعْبُدُونَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">حَصَبُ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span><br />\r\n<br />\r\n(நிச்சயமாக நீங்களும், அல்லாஹ்வையன்றி நீங்கள் வணங்குபவையும் நரகத்தின் எரிபொருட்களே!) (<a href=\"qurandisp.php?sura=21&ayah=98\" class=\"link\">21:98</a>) என்ற வசனம் குறைஷிகளை நோக்கியே அருளப்பட்டது. ஏனெனில் அவர்கள் சிலைகளையும் பொய்த் தெய்வங்களையுமே வணங்கினர்; அவர்கள் மஸீஹை வணங்கவில்லை. அப்படியிருக்க அவர் ஏன் அந்த வசனத்தில் சேர்க்கப்பட வேண்டும்? அவர்கள் கூறியது வெறும் தர்க்கத்திற்காகவே தவிர, அவர்கள் அதை உண்மையாக நம்பிச் சொல்லவில்லை. இமாம் அஹ்மத் (ரஹ்) அவர்கள் பதிவு செய்துள்ள ஹதீஸில், அபூ உமாமா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">ضَلَّ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">بَعْدَ</span> <span class=\"quran-arabic-font text-success\">هُدًى</span> <span class=\"quran-arabic-font text-success\">كَانُوا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ،</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">أُوْرِثُوا</span> <span class=\"quran-arabic-font text-success\">الْجَدَل</span>»<br />\r\n<br />\r\n(நேர்வழி பெற்ற ஒரு சமூகம் வழிகெட்டுப் போவதற்கு, அவர்களுக்குள் ஏற்படும் வீண் தர்க்கமே காரணமாகிறது.) பிறகு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இந்த வசனத்தை ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">ضَرَبُوهُ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">جَدَلاَ</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">خَصِمُونَ</span><br />\r\n<br />\r\n(அவர்கள் இந்த உதாரணத்தை உமக்குக் கூறியதெல்லாம் தர்க்கத்திற்காகவேயன்றி வேறில்லை. இல்லை, அவர்கள் வீண் விவாதம் செய்யும் கூட்டத்தினரே!)\" இது அத்-திர்மிதீ, இப்னு மாஜா மற்றும் இப்னு ஜரீர் ஆகியோராலும் பதிவு செய்யப்பட்டுள்ளது. அத்-திர்மிதீ அவர்கள், \"இது ஒரு ஹஸன் ஸஹீஹான ஹதீஸ். ஹஜ்ஜாஜ் பின் தீனார் அறிவிக்கும் இந்த வழியைத் தவிர வேறு வழியில் இதை நாம் அறியவில்லை\" என்று கூறியுள்ளார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَبْدٌ</span> <span class=\"quran-arabic-font text-success\">أَنْعَمْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span><br />\r\n<br />\r\n(அவர் (ஈஸா (அலை)) ஓர் அடியாரே தவிர வேறில்லை. அவருக்கு நாம் அருள்புரிந்தோம்.) அதாவது, ஈஸா (அலை) அவர்கள்; அல்லாஹ் நபித்துவத்தாலும் தூதுத்துவத்தாலும் கௌரவித்த அவனது அடியார்களில் ஒருவரே அன்றி வேறில்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلْنَـهُ</span> <span class=\"quran-arabic-font text-success\">مَثَلاً</span> <span class=\"quran-arabic-font text-success\">لِّبَنِى</span> <span class=\"quran-arabic-font text-success\">إِسْرَءِيلَ</span><br />\r\n<br />\r\n(அவரை இஸ்ரவேலர்களுக்கு ஓர் உதாரணமாகவும் ஆக்கினோம்.) அதாவது, 'நாம் நாடியதைச் செய்ய வல்லவர்கள் என்பதற்கு அவரை ஓர் அடையாளமாகவும் சான்றாகவும் ஆக்கினோம்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">نَشَآءُ</span> <span class=\"quran-arabic-font text-success\">لَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِنكُمْ</span> <span class=\"quran-arabic-font text-success\">مَّلَـئِكَةً</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">يَخْلُفُونَ</span><br />\r\n<br />\r\n(நாம் நாடியிருந்தால், உங்களுக்குப் பதிலாக பூமியில் வசிப்பதற்கு வானவர்களையே ஏற்படுத்தியிருப்போம்.) அஸ்-ஸுத்தீ அவர்கள், \"அவர்கள் பூமியில் உங்கள் இடத்தைப் பிடித்திருப்பார்கள்\" என்றார். இப்னு அப்பாஸ் (ரழி) மற்றும் கத்தாதா ஆகியோர், \"நீங்கள் ஒருவருக்கொருவர் பின்வருவது போல அவர்களும் ஒருவருக்கொருவர் பின் வந்திருப்பார்கள்\" என்றனர். இது முந்தைய கருத்தையே வலியுறுத்துகிறது. முஜாஹித் அவர்கள், \"உங்களுக்குப் பதிலாக வானவர்களே பூமியில் குடியமர்த்தப்பட்டிருப்பார்கள்\" என்று கூறினார். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَعِلْمٌ</span> <span class=\"quran-arabic-font text-success\">لِّلسَّاعَةِ</span><br />\r\n<br />\r\n(நிச்சயமாக அவர் (ஈஸா (அலை)) மறுமை நாளுக்கான ஒரு அடையாளமாவார்.) இது குறித்துச் சரியான கருத்து என்னவென்றால், இது மறுமை நாளுக்கு முன்னதாக அவர் பூமிக்கு இறங்குவதைக் குறிக்கிறது. அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْكِتَـبِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">لَيُؤْمِنَنَّ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">مَوْتِهِ</span><br />\r\n<br />\r\n(வேதக்காரர்களில் எவரும் அவரது மரணத்திற்கு முன்னதாக அவரை விசுவாசிக்காமல் இருக்க மாட்டார்கள்) (<a href=\"qurandisp.php?sura=4&ayah=159\" class=\"link\">4:159</a>). அதாவது, ஈஸா (அலை) அவர்களின் மரணத்திற்கு முன்னதாக.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَـمَةِ</span> <span class=\"quran-arabic-font text-success\">يَكُونُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">شَهِيداً</span><br />\r\n<br />\r\n(மேலும், மறுமை நாளில் அவர் அவர்களுக்கு எதிராகச் சாட்சியாக இருப்பார்) (<a href=\"qurandisp.php?sura=4&ayah=159\" class=\"link\">4:159</a>). இந்த வசனத்தின் மற்றொரு ஓதுதல் முறையான (<span class=\"quran-arabic-font text-success\">وَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَعَلَمٌ</span> <span class=\"quran-arabic-font text-success\">لِلسَّاعَةِ</span>) என்பதும் இதற்கு ஆதரவாக உள்ளது. அதாவது, மறுமை நாள் நிச்சயமாக வரும் என்பதற்கான அத்தாட்சி அவர். முஜாஹித் அவர்கள் கூறுகையில்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَعِلْمٌ</span> <span class=\"quran-arabic-font text-success\">لِّلسَّاعَةِ</span><br />\r\n<br />\r\n(நிச்சயமாக அவர் மறுமை நாளுக்கான ஓர் அடையாளமாவார்.) அதாவது, \"மறுமை நாளின் அடையாளங்களில் ஒன்று, மறுமை நாளுக்கு முன்னதாக ஈஸா பின் மர்யம் (அலை) அவர்கள் தோன்றுவது ஆகும்.\" இதே போன்ற கருத்து அபூ ஹுரைரா (ரழி), இப்னு அப்பாஸ் (ரழி), அபூ அல்-ஆலியா, அபூ மாலிக், இக்ரிமா, அல்-ஹஸன், கத்தாதா, அத்-தஹ்ஹாக் மற்றும் பலரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. மறுமை நாளுக்கு முன்னதாக ஈஸா (அலை) அவர்கள் ஒரு நீதியான ஆட்சியாளராகவும் நேர்மையான நீதிபதியாகவும் இறங்குவார்கள் என்பது குறித்த பல முதவாதிர் ஹதீஸ்கள் வந்துள்ளன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">تَمْتَرُنَّ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span><br />\r\n<br />\r\n(எனவே, அதைப் பற்றி நீங்கள் சந்தேகம் கொள்ளாதீர்கள்.) அதாவது, அது (மறுமை) நிச்சயமாக நிகழும் என்பதில் சந்தேகம் கொள்ளாதீர்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاتَّبِعُونِ</span><br />\r\n<br />\r\n(என்னைப் பின்பற்றுங்கள்.) அதாவது, 'நான் அதைப் பற்றி உங்களுக்குக் கூறுவதில்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">صِرَطٌ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقِيمٌ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَصُدَّنَّكُمُ</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَـنُ</span><br />\r\n<br />\r\n(இதுவே நேரான வழியாகும். ஷைத்தான் உங்களைத் தடுத்துவிட வேண்டாம்.) அதாவது, சத்தியத்தைப் பின்பற்றுவதிலிருந்து.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">عَدُوٌّ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٌ</span> <span class=\"quran-arabic-font text-success\">وَلَمَّا</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">عِيسَى</span> <span class=\"quran-arabic-font text-success\">بِالْبَيِّنَـتِ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">جِئْتُكُم</span> <span class=\"quran-arabic-font text-success\">بِالْحِكْمَةِ</span><br />\r\n<br />\r\n(நிச்சயமாக அவன் (ஷைத்தான்) உங்களுக்கு வெளிப்படையான எதிரியாவான். ஈஸா (அலை) தெளிவான சான்றுகளுடன் வந்தபோது கூறினார்: \"நான் உங்களிடம் ஞானத்துடன் (அல்-ஹிக்மா) வந்துள்ளேன்.\") அதாவது நபித்துவத்துடன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلأُبَيِّنَ</span> <span class=\"quran-arabic-font text-success\">لَكُم</span> <span class=\"quran-arabic-font text-success\">بَعْضَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">تَخْتَلِفُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span><br />\r\n<br />\r\n(நீங்கள் கருத்து வேறுபாடு கொண்டுள்ள சிலவற்றை உங்களுக்குத் தெளிவுபடுத்துவதற்காகவும் வந்துள்ளேன்.) இப்னு ஜரீர் அவர்கள், \"இது மார்க்க விவகாரங்களைக் குறிக்கிறது, உலக விவகாரங்களை அல்ல\" என்று கூறுகிறார். இது ஒரு சிறந்த விளக்கமாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاتَّقُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span><br />\r\n<br />\r\n(எனவே, அல்லாஹ்விடம் தக்வா (பயபக்தி) கொள்ளுங்கள்) அதாவது, 'நான் உங்களுக்குக் கட்டளையிடுபவற்றில்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَطِيعُونِ</span><br />\r\n<br />\r\n(எனக்குக் கீழ்ப்படியுங்கள்.) அதாவது, 'நான் உங்களிடம் கொண்டு வந்த மார்க்கக் கட்டளைகளில்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">رَبِّى</span> <span class=\"quran-arabic-font text-success\">وَرَبُّكُمْ</span> <span class=\"quran-arabic-font text-success\">فَاعْبُدُوهُ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">صِرَطٌ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقِيمٌ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ்வே எனது இறைவனும் உங்கள் இறைவனுமாவான். எனவே அவனையே வணங்குங்கள். இதுவே நேரான வழியாகும்.) அதாவது, 'நானும் நீங்களும் அவனுக்கே அடிமைகள், அவனது தேவையுள்ளவர்கள். அவனுக்கு எதையும் இணையாக்காமல் அவனை மட்டுமே வணங்குவதில் நாம் அனைவரும் ஒன்றுபட்டிருக்கிறோம்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">صِرَطٌ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقِيمٌ</span><br />\r\n<br />\r\n(இதுவே நேரான வழியாகும்) அதாவது, 'நான் உங்களிடம் கொண்டு வந்த இந்த ஏகத்துவமே நேரான வழியாகும்; அதாவது உயர்ந்தவனாகிய இறைவனை மட்டுமே வணங்குவதாகும்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاخْتَلَفَ</span> <span class=\"quran-arabic-font text-success\">الْأَحْزَابُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَيْنِهِمْ</span><br />\r\n<br />\r\n(இருப்பினும் அவர்களிடையே இருந்த பிரிவினர் தங்களுக்குள் மாறுபட்டனர்.) அதாவது, அவர்கள் கருத்து வேறுபாடு கொண்டு குழுக்களாகவும் பிரிவுகளாகவும் மாறினர். அவர்களில் சிலர், அவர் (ஈஸா (அலை)) அல்லாஹ்வின் அடியாரும் தூதரும் என்று கூறினர் - இதுவே உண்மையாகும். மற்றவர்களோ, அவர் அல்லாஹ்வின் மகன் என்றோ அல்லது அவரே அல்லாஹ் என்றோ வாதிட்டனர் - அவர்கள் கூறுவதை விட்டும் அல்லாஹ் மிகவும் தூய்மையானவனும் உயர்ந்தவனுமாவான். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَوَيْلٌ</span> <span class=\"quran-arabic-font text-success\">لِّلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ظَلَمُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عَذَابِ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">أَلِيمٍ</span><br />\r\n<br />\r\n(எனவே, அநியாயம் செய்தவர்களுக்கு நோவினை தரும் நாளின் வேதனையினால் அழிவுதான்!)<br />\r\n<br />","text":"மர்யமின் மகன் விஷயத்தில் குறைஷிகளின் ஏளனமும், அல்லாஹ்விடம் அவருக்குள்ள உண்மையான அந்தஸ்தும்\n\r\n\n\r\nகுறைஷிகள் எவ்வாறு தங்களது இறைநிராகரிப்பிலும், பிடிவாதமான தர்க்கங்களிலும் நிலைத்திருந்தனர் என்பதை அல்லாஹ் நமக்குக் கூறுகிறான்:\n\r\n\n\r\nوَلَمَّا ضُرِبَ ابْنُ مَرْيَمَ مَثَلاً إِذَا قَوْمُكَ مِنْهُ يَصِدُّونَ\n\r\n\n\r\n(மர்யமின் மகன் ஓர் உதாரணமாகக் கூறப்பட்டபோது, இதோ, உம்முடைய சமூகத்தார் (அதைக் கேட்டு) ஆரவாரம் செய்கிறார்கள்.) இப்னு அப்பாஸ் (ரழி), முஜாஹித், இக்ரிமா, அஸ்-ஸுத்தீ மற்றும் அத்-தஹ்ஹாக் ஆகியோர், \"அவர்கள் சிரித்தார்கள்; அதாவது, அவர்கள் அதனால் வியப்படைந்தார்கள்\" என்று கூறியதாகப் பலரும் அறிவிக்கிறார்கள். கத்தாதா அவர்கள், \"அவர்கள் அதைக் கண்டு வெறுப்படைந்து சிரித்தார்கள்\" என்று கூறினார்கள். இப்ராஹீம் அந்-நகஈ அவர்கள், \"அவர்கள் புறக்கணித்துத் திரும்பிக் கொண்டனர்\" என்று கூறினார்கள். இதற்கான காரணத்தை முஹம்மது பின் இஸ்ஹாக் அவர்கள் 'அஸ்-ஸீரா'வில் குறிப்பிட்டுள்ளார்கள். அவர் கூறினார்கள்: \"எனக்குக் கிடைத்த தகவலின்படி, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஒரு நாள் மஸ்ஜிதில் அல்-வலீத் பின் அல்-முஃகீராவுடன் அமர்ந்திருந்தார்கள். அப்போது அந்-நள்ரு பின் அல்-ஹாரித் வந்து அவர்களுடன் அமர்ந்தார். அந்தச் சபையில் குறைஷிகளைச் சேர்ந்த வேறு சில ஆண்களும் இருந்தனர். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் உரையாற்றினார்கள். அப்போது அந்-நள்ரு பின் அல்-ஹாரித் அவர்களிடம் வந்தார். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் வாதத்தில் அவரைத் தோற்கடிக்கும் வரை அவரிடம் பேசினார்கள். பிறகு அவருக்கும் அங்கிருந்தவர்களுக்கும் பின்வரும் வசனத்தை ஓதிக்காட்டினார்கள்:\n\r\n\n\r\nإِنَّكُمْ وَمَا تَعْبُدُونَ مِن دُونِ اللَّهِ حَصَبُ جَهَنَّمَ أَنتُمْ لَهَا وَارِدُونَ\n\r\n\n\r\n(நிச்சயமாக நீங்களும், அல்லாஹ்வையன்றி நீங்கள் வணங்குபவையும் நரகத்தின் எரிபொருட்களே! நீங்கள் அனைவரும் அதில் நுழைவீர்கள்.) (21:98) பிறகு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் எழுந்து சென்று அப்துல்லாஹ் பின் அஸ்-ஸபஅரீ அஸ்-ஸஹ்மீயுடன் அமர்ந்தார்கள். அல்-வலீத் பின் அல்-முஃகீரா அவரிடம், 'அல்லாஹ்வின் மீது ஆணையாக, வாதத்தில் அப்துல் முத்தலிபின் மகனுக்கு (முஹம்மது (ஸல்) அவர்களுக்கு) அந்-நள்ரு பின் அல்-ஹாரித்தால் ஈடுகொடுக்க முடியவில்லை. நாமும் நாம் வணங்கும் இந்தத் தெய்வங்களும் நரகத்தின் எரிபொருட்கள் என்று முஹம்மது (ஸல்) அவர்கள் கூறுகிறார்கள்' என்றார். அப்துல்லாஹ் பின் அஸ்-ஸபஅரீ, 'அல்லாஹ்வின் மீது ஆணையாக, நான் அவரைச் சந்தித்தால் வாதத்தில் அவரைத் தோற்கடித்து விடுவேன். அல்லாஹ்வையன்றி வணங்கப்படும் அனைவரும், அவர்களை வணங்கியவர்களுடன் நரகத்தில் இருப்பார்களா என்று முஹம்மது (ஸல்) அவர்களிடம் கேளுங்கள். ஏனெனில் நாம் வானவர்களை வணங்குகிறோம், யூதர்கள் உஸைரை (அலை) வணங்குகிறார்கள், கிறிஸ்தவர்கள் மஸீஹ் ஈஸா பின் மர்யமை (அலை) வணங்குகிறார்கள்' என்றார். அப்துல்லாஹ் பின் அஸ்-ஸபஅரீ கூறியதைக் கேட்டு அல்-வலீதும் அங்கிருந்த மற்றவர்களும் வியப்படைந்தனர். அவர் ஒரு வலுவான வாதத்தை முன்வைத்ததாக அவர்கள் எண்ணினார்கள். இது அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கூறப்பட்டபோது, அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«كُلُّ مَنْ أَحَبَّ أَنْ يُعْبَدَ مِنْ دُونِ اللهِ فَهُوَ مَعَ مَنْ عَبَدَهُ، فَإِنَّهُمْ إِنَّمَا يَعْبُدُونَ الشَّيْطَانَ وَمَنْ أَمَرَهُمْ بِعِبَادَتِه»\n\r\n\n\r\n(அல்லாஹ்வையன்றி தான் வணங்கப்படுவதை யார் விரும்புகிறாரோ, அவர் தன்னை வணங்கியவருடன் இருப்பார். ஏனெனில், அவர்கள் உண்மையில் ஷைத்தானையும், அந்த நபரை வணங்கும்படி அவர்களுக்குக் கட்டளையிட்டவனையுமே வணங்குகிறார்கள்.)\" பின்னர் அல்லாஹ் இந்த வார்த்தைகளை வஹீ (இறைச்செய்தி)யாக அருளினான்:\n\r\n\n\r\nإِنَّ الَّذِينَ سَبَقَتْ لَهُمْ مِّنَّا الْحُسْنَى أُوْلَـئِكَ عَنْهَا مُبْعَدُونَ\n\r\n\n\r\n(நிச்சயமாக, எவர்களுக்கு நம்மிடமிருந்து நற்பேறு முந்திவிட்டதோ, அவர்கள் நரகத்தை விட்டு வெகுதூரம் அப்புறப்படுத்தப்படுவார்கள்.) (21:101). அதாவது, மக்களால் வணங்கப்பட்ட ஈஸா (அலை), உஸைர் (அலை) மற்றும் அல்லாஹ்வுக்குப் பணிந்து வாழ்ந்த அறிஞர்களும் துறவிகளும் இதில் அடங்குவர். அவர்களுக்குப் பின் வந்த வழிகெட்ட மக்கள், அல்லாஹ்வையன்றி அவர்களைத் தெய்வங்களாக எடுத்துக் கொண்டனர். வானவர்களை அல்லாஹ்வின் மகள்களாகக் கருதி வணங்குவது குறித்துப் பின்வரும் வசனம் வஹீ (இறைச்செய்தி)யாக அருளப்பட்டது:\n\r\n\n\r\nوَقَالُواْ اتَّخَذَ الرَّحْمَـنُ وَلَداً سُبْحَانَهُ بَلْ عِبَادٌ مُّكْرَمُونَ\n\r\n\n\r\n(மேலும், \"அளவற்ற அருளாளன் ஒரு மகனை (அல்லது சந்ததியை) ஏற்படுத்திக் கொண்டான்\" என்று அவர்கள் கூறுகிறார்கள். அவன் மிகவும் தூய்மையானவன்! மாறாக, அவர்கள் (வானவர்கள்) கண்ணியப்படுத்தப்பட்ட அடியார்களே ஆவர்.) (21:26) ஈஸா பின் மர்யம் (அலை) அவர்கள் அல்லாஹ்வையன்றி வணங்கப்படுவதைப் பற்றியும், அந்தத் தர்க்கத்தின் போது வலீத் மற்றும் அங்கிருந்தவர்களின் வியப்பைப் பற்றியும் பின்வரும் வசனம் அருளப்பட்டது:\n\r\n\n\r\nوَلَمَّا ضُرِبَ ابْنُ مَرْيَمَ مَثَلاً إِذَا قَوْمُكَ مِنْهُ يَصِدُّونَ\n\r\n\n\r\n(மர்யமின் மகன் ஓர் உதாரணமாகக் கூறப்பட்டபோது, இதோ, உம்முடைய சமூகத்தார் (அதைக் கேட்டு) ஆரவாரம் செய்கிறார்கள்.) அதாவது, உமது தூதுச் செய்தியை நிராகரிப்பதற்கு இந்த வாதத்தை அவர்கள் ஒரு சாக்காக எடுத்துக் கொள்கிறார்கள். பிறகு அல்லாஹ் ஈஸா பின் மர்யம் (அலை) அவர்களைப் பற்றிக் குறிப்பிடுகிறான்:\n\r\n\n\r\nإِنْ هُوَ إِلاَّ عَبْدٌ أَنْعَمْنَا عَلَيْهِ وَجَعَلْنَـهُ مَثَلاً لِّبَنِى إِسْرَءِيلَ - وَلَوْ نَشَآءُ لَجَعَلْنَا مِنكُمْ مَّلَـئِكَةً فِى الْأَرْضِ يَخْلُفُونَ وَإِنَّهُ لَعِلْمٌ لِّلسَّاعَةِ\n\r\n\n\r\n(அவர் ஓர் அடியாரே தவிர வேறில்லை. அவருக்கு நாம் அருள்புரிந்தோம்; அவரை இஸ்ரவேலர்களுக்கு ஓர் உதாரணமாகவும் ஆக்கினோம். நாம் நாடியிருந்தால், உங்களுக்குப் பதிலாக பூமியில் வசிப்பதற்கு வானவர்களையே ஏற்படுத்தியிருப்போம். நிச்சயமாக அவர் (ஈஸா (அலை)) மறுமை நாளுக்கான ஒரு அடையாளமாவார்.) அதாவது, அவர் மூலமாக நிகழ்ந்த இறந்தவர்களை உயிர்ப்பித்தல், நோயாளிகளைக் குணப்படுத்துதல் போன்ற அற்புதங்களே மறுமை நாள் நெருங்குவதற்கான அடையாளங்களாகப் போதுமானவை.\n\r\n\n\r\nفَلاَ تَمْتَرُنَّ بِهَا وَاتَّبِعُونِ هَـذَا صِرَطٌ مُّسْتَقِيمٌ\n\r\n\n\r\n(எனவே, அதைப் பற்றி நீங்கள் சந்தேகம் கொள்ளாதீர்கள். என்னைப் பின்பற்றுங்கள். இதுவே நேரான வழியாகும்.) இப்னு ஜரீர் அவர்கள் பதிவு செய்துள்ளதாவது: அல்-அவ்ஃபீ அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து இந்த வசனம் குறித்து அறிவிக்கிறார்கள்:\n\r\n\n\r\nوَلَمَّا ضُرِبَ ابْنُ مَرْيَمَ مَثَلاً إِذَا قَوْمُكَ مِنْهُ يَصِدُّونَ\n\r\n\n\r\n(மர்யமின் மகன் ஓர் உதாரணமாகக் கூறப்பட்டபோது, இதோ, உம்முடைய சமூகத்தார் (அதைக் கேட்டு) ஆரவாரம் செய்கிறார்கள்.) \"இதன் பொருள் குறைஷிகள்; அவர்களிடம் பின்வரும் வசனம் ஓதப்பட்டபோது:\"\n\r\n\n\r\nإِنَّكُمْ وَمَا تَعْبُدُونَ مِن دُونِ اللَّهِ حَصَبُ جَهَنَّمَ أَنتُمْ لَهَا وَارِدُونَ\n\r\n\n\r\n(நிச்சயமாக நீங்களும், அல்லாஹ்வையன்றி நீங்கள் வணங்குபவையும் நரகத்தின் எரிபொருட்களே! நீங்கள் அனைவரும் அதில் நுழைவீர்கள்.) (21:98) குறைஷிகள் அவரிடம், 'ஈஸா பின் மர்யமின் நிலை என்ன?' என்று கேட்டார்கள். அதற்கு அவர் கூறினார்:\n\r\n\n\r\n«ذَاكَ عَبْدُاللهِ وَرَسُولُه»\n\r\n\n\r\n(அவர் அல்லாஹ்வின் அடியாரும் அவனது தூதரும் ஆவார்.) அதற்கு அவர்கள், 'அல்லாஹ்வின் மீது ஆணையாக! கிறிஸ்தவர்கள் ஈஸா பின் மர்யமைத் தங்கள் இறைவனாக எடுத்துக் கொண்டது போல, நாமும் இவரை இறைவனாக எடுத்துக் கொள்ள வேண்டும் என்றுதான் இவர் விரும்புகிறார்' என்று கூறினார்கள். பின்னர் அல்லாஹ் கூறினான்:\n\r\n\n\r\nمَا ضَرَبُوهُ لَكَ إِلاَّ جَدَلاَ بَلْ هُمْ قَوْمٌ خَصِمُونَ\n\r\n\n\r\n(அவர்கள் இந்த உதாரணத்தை உமக்குக் கூறியதெல்லாம் தர்க்கத்திற்காகவேயன்றி வேறில்லை. இல்லை, அவர்கள் வீண் விவாதம் செய்யும் கூட்டத்தினரே!)\n\r\n\n\r\nوَقَالُواْ ءَأَالِهَتُنَا خَيْرٌ أَمْ هُوَ\n\r\n\n\r\n(மேலும், \"எங்கள் தெய்வங்கள் சிறந்தவையா அல்லது அவரா?\" என்று அவர்கள் கேட்கிறார்கள்.) கத்தாதா அவர்கள், \"எங்கள் தெய்வங்கள் அவரை விடச் சிறந்தவை என்று அவர்கள் கூறி வந்தனர்\" என்றார். மேலும் கத்தாதா அவர்கள், \"இப்னு மஸ்ஊத் (ரழி) அவர்கள் (أَآلِهَتُنَا خَيْرٌ أَمْ هذَا) - 'எங்கள் தெய்வங்கள் சிறந்தவையா அல்லது இவரா?' என்று ஓதினார்கள்\" எனக் குறிப்பிடுகிறார். இதன் மூலம் அவர்கள் முஹம்மது (ஸல்) அவர்களைக் குறிப்பிடுகிறார்கள்.\n\r\n\n\r\nمَا ضَرَبُوهُ لَكَ إِلاَّ جَدَلاَ\n\r\n\n\r\n(அவர்கள் இந்த உதாரணத்தை உமக்குக் கூறியதெல்லாம் தர்க்கத்திற்காகவேயன்றி வேறில்லை.) அதாவது, பிடிவாதமான விவாதத்திற்காகவே அவர்கள் அப்படிச் சொன்னார்கள். ஏனெனில் அந்த வசனத்தில் (21:98) ஈஸா (அலை) அவர்கள் உள்ளடக்கப்படவில்லை என்பது அவர்களுக்குத் தெரியும்; ஏனெனில் அவ்வாறு கூறுவது அர்த்தமற்றது.\n\r\n\n\r\nإِنَّكُمْ وَمَا تَعْبُدُونَ مِن دُونِ اللَّهِ حَصَبُ جَهَنَّمَ\n\r\n\n\r\n(நிச்சயமாக நீங்களும், அல்லாஹ்வையன்றி நீங்கள் வணங்குபவையும் நரகத்தின் எரிபொருட்களே!) (21:98) என்ற வசனம் குறைஷிகளை நோக்கியே அருளப்பட்டது. ஏனெனில் அவர்கள் சிலைகளையும் பொய்த் தெய்வங்களையுமே வணங்கினர்; அவர்கள் மஸீஹை வணங்கவில்லை. அப்படியிருக்க அவர் ஏன் அந்த வசனத்தில் சேர்க்கப்பட வேண்டும்? அவர்கள் கூறியது வெறும் தர்க்கத்திற்காகவே தவிர, அவர்கள் அதை உண்மையாக நம்பிச் சொல்லவில்லை. இமாம் அஹ்மத் (ரஹ்) அவர்கள் பதிவு செய்துள்ள ஹதீஸில், அபூ உமாமா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَا ضَلَّ قَوْمٌ بَعْدَ هُدًى كَانُوا عَلَيْهِ، إِلَّا أُوْرِثُوا الْجَدَل»\n\r\n\n\r\n(நேர்வழி பெற்ற ஒரு சமூகம் வழிகெட்டுப் போவதற்கு, அவர்களுக்குள் ஏற்படும் வீண் தர்க்கமே காரணமாகிறது.) பிறகு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இந்த வசனத்தை ஓதினார்கள்:\n\r\n\n\r\nمَا ضَرَبُوهُ لَكَ إِلاَّ جَدَلاَ بَلْ هُمْ قَوْمٌ خَصِمُونَ\n\r\n\n\r\n(அவர்கள் இந்த உதாரணத்தை உமக்குக் கூறியதெல்லாம் தர்க்கத்திற்காகவேயன்றி வேறில்லை. இல்லை, அவர்கள் வீண் விவாதம் செய்யும் கூட்டத்தினரே!)\" இது அத்-திர்மிதீ, இப்னு மாஜா மற்றும் இப்னு ஜரீர் ஆகியோராலும் பதிவு செய்யப்பட்டுள்ளது. அத்-திர்மிதீ அவர்கள், \"இது ஒரு ஹஸன் ஸஹீஹான ஹதீஸ். ஹஜ்ஜாஜ் பின் தீனார் அறிவிக்கும் இந்த வழியைத் தவிர வேறு வழியில் இதை நாம் அறியவில்லை\" என்று கூறியுள்ளார்.\n\r\n\n\r\nإِنْ هُوَ إِلاَّ عَبْدٌ أَنْعَمْنَا عَلَيْهِ\n\r\n\n\r\n(அவர் (ஈஸா (அலை)) ஓர் அடியாரே தவிர வேறில்லை. அவருக்கு நாம் அருள்புரிந்தோம்.) அதாவது, ஈஸா (அலை) அவர்கள்; அல்லாஹ் நபித்துவத்தாலும் தூதுத்துவத்தாலும் கௌரவித்த அவனது அடியார்களில் ஒருவரே அன்றி வேறில்லை.\n\r\n\n\r\nوَجَعَلْنَـهُ مَثَلاً لِّبَنِى إِسْرَءِيلَ\n\r\n\n\r\n(அவரை இஸ்ரவேலர்களுக்கு ஓர் உதாரணமாகவும் ஆக்கினோம்.) அதாவது, 'நாம் நாடியதைச் செய்ய வல்லவர்கள் என்பதற்கு அவரை ஓர் அடையாளமாகவும் சான்றாகவும் ஆக்கினோம்.'\n\r\n\n\r\nوَلَوْ نَشَآءُ لَجَعَلْنَا مِنكُمْ مَّلَـئِكَةً فِى الْأَرْضِ يَخْلُفُونَ\n\r\n\n\r\n(நாம் நாடியிருந்தால், உங்களுக்குப் பதிலாக பூமியில் வசிப்பதற்கு வானவர்களையே ஏற்படுத்தியிருப்போம்.) அஸ்-ஸுத்தீ அவர்கள், \"அவர்கள் பூமியில் உங்கள் இடத்தைப் பிடித்திருப்பார்கள்\" என்றார். இப்னு அப்பாஸ் (ரழி) மற்றும் கத்தாதா ஆகியோர், \"நீங்கள் ஒருவருக்கொருவர் பின்வருவது போல அவர்களும் ஒருவருக்கொருவர் பின் வந்திருப்பார்கள்\" என்றனர். இது முந்தைய கருத்தையே வலியுறுத்துகிறது. முஜாஹித் அவர்கள், \"உங்களுக்குப் பதிலாக வானவர்களே பூமியில் குடியமர்த்தப்பட்டிருப்பார்கள்\" என்று கூறினார். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَإِنَّهُ لَعِلْمٌ لِّلسَّاعَةِ\n\r\n\n\r\n(நிச்சயமாக அவர் (ஈஸா (அலை)) மறுமை நாளுக்கான ஒரு அடையாளமாவார்.) இது குறித்துச் சரியான கருத்து என்னவென்றால், இது மறுமை நாளுக்கு முன்னதாக அவர் பூமிக்கு இறங்குவதைக் குறிக்கிறது. அல்லாஹ் கூறுவது போல:\n\r\n\n\r\nوَإِن مِّنْ أَهْلِ الْكِتَـبِ إِلاَّ لَيُؤْمِنَنَّ بِهِ قَبْلَ مَوْتِهِ\n\r\n\n\r\n(வேதக்காரர்களில் எவரும் அவரது மரணத்திற்கு முன்னதாக அவரை விசுவாசிக்காமல் இருக்க மாட்டார்கள்) (4:159). அதாவது, ஈஸா (அலை) அவர்களின் மரணத்திற்கு முன்னதாக.\n\r\n\n\r\nوَيَوْمَ الْقِيَـمَةِ يَكُونُ عَلَيْهِمْ شَهِيداً\n\r\n\n\r\n(மேலும், மறுமை நாளில் அவர் அவர்களுக்கு எதிராகச் சாட்சியாக இருப்பார்) (4:159). இந்த வசனத்தின் மற்றொரு ஓதுதல் முறையான (وَإِنَّهُ لَعَلَمٌ لِلسَّاعَةِ) என்பதும் இதற்கு ஆதரவாக உள்ளது. அதாவது, மறுமை நாள் நிச்சயமாக வரும் என்பதற்கான அத்தாட்சி அவர். முஜாஹித் அவர்கள் கூறுகையில்:\n\r\n\n\r\nوَإِنَّهُ لَعِلْمٌ لِّلسَّاعَةِ\n\r\n\n\r\n(நிச்சயமாக அவர் மறுமை நாளுக்கான ஓர் அடையாளமாவார்.) அதாவது, \"மறுமை நாளின் அடையாளங்களில் ஒன்று, மறுமை நாளுக்கு முன்னதாக ஈஸா பின் மர்யம் (அலை) அவர்கள் தோன்றுவது ஆகும்.\" இதே போன்ற கருத்து அபூ ஹுரைரா (ரழி), இப்னு அப்பாஸ் (ரழி), அபூ அல்-ஆலியா, அபூ மாலிக், இக்ரிமா, அல்-ஹஸன், கத்தாதா, அத்-தஹ்ஹாக் மற்றும் பலரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. மறுமை நாளுக்கு முன்னதாக ஈஸா (அலை) அவர்கள் ஒரு நீதியான ஆட்சியாளராகவும் நேர்மையான நீதிபதியாகவும் இறங்குவார்கள் என்பது குறித்த பல முதவாதிர் ஹதீஸ்கள் வந்துள்ளன.\n\r\n\n\r\nفَلاَ تَمْتَرُنَّ بِهَا\n\r\n\n\r\n(எனவே, அதைப் பற்றி நீங்கள் சந்தேகம் கொள்ளாதீர்கள்.) அதாவது, அது (மறுமை) நிச்சயமாக நிகழும் என்பதில் சந்தேகம் கொள்ளாதீர்கள்.\n\r\n\n\r\nوَاتَّبِعُونِ\n\r\n\n\r\n(என்னைப் பின்பற்றுங்கள்.) அதாவது, 'நான் அதைப் பற்றி உங்களுக்குக் கூறுவதில்.'\n\r\n\n\r\nهَـذَا صِرَطٌ مُّسْتَقِيمٌ وَلاَ يَصُدَّنَّكُمُ الشَّيْطَـنُ\n\r\n\n\r\n(இதுவே நேரான வழியாகும். ஷைத்தான் உங்களைத் தடுத்துவிட வேண்டாம்.) அதாவது, சத்தியத்தைப் பின்பற்றுவதிலிருந்து.\n\r\n\n\r\nإِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ وَلَمَّا جَآءَ عِيسَى بِالْبَيِّنَـتِ قَالَ قَدْ جِئْتُكُم بِالْحِكْمَةِ\n\r\n\n\r\n(நிச்சயமாக அவன் (ஷைத்தான்) உங்களுக்கு வெளிப்படையான எதிரியாவான். ஈஸா (அலை) தெளிவான சான்றுகளுடன் வந்தபோது கூறினார்: \"நான் உங்களிடம் ஞானத்துடன் (அல்-ஹிக்மா) வந்துள்ளேன்.\") அதாவது நபித்துவத்துடன்.\n\r\n\n\r\nوَلأُبَيِّنَ لَكُم بَعْضَ الَّذِى تَخْتَلِفُونَ فِيهِ\n\r\n\n\r\n(நீங்கள் கருத்து வேறுபாடு கொண்டுள்ள சிலவற்றை உங்களுக்குத் தெளிவுபடுத்துவதற்காகவும் வந்துள்ளேன்.) இப்னு ஜரீர் அவர்கள், \"இது மார்க்க விவகாரங்களைக் குறிக்கிறது, உலக விவகாரங்களை அல்ல\" என்று கூறுகிறார். இது ஒரு சிறந்த விளக்கமாகும்.\n\r\n\n\r\nفَاتَّقُواْ اللَّهَ\n\r\n\n\r\n(எனவே, அல்லாஹ்விடம் தக்வா (பயபக்தி) கொள்ளுங்கள்) அதாவது, 'நான் உங்களுக்குக் கட்டளையிடுபவற்றில்.'\n\r\n\n\r\nوَأَطِيعُونِ\n\r\n\n\r\n(எனக்குக் கீழ்ப்படியுங்கள்.) அதாவது, 'நான் உங்களிடம் கொண்டு வந்த மார்க்கக் கட்டளைகளில்.'\n\r\n\n\r\nإِنَّ اللَّهَ هُوَ رَبِّى وَرَبُّكُمْ فَاعْبُدُوهُ هَـذَا صِرَطٌ مُّسْتَقِيمٌ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ்வே எனது இறைவனும் உங்கள் இறைவனுமாவான். எனவே அவனையே வணங்குங்கள். இதுவே நேரான வழியாகும்.) அதாவது, 'நானும் நீங்களும் அவனுக்கே அடிமைகள், அவனது தேவையுள்ளவர்கள். அவனுக்கு எதையும் இணையாக்காமல் அவனை மட்டுமே வணங்குவதில் நாம் அனைவரும் ஒன்றுபட்டிருக்கிறோம்.'\n\r\n\n\r\nهَـذَا صِرَطٌ مُّسْتَقِيمٌ\n\r\n\n\r\n(இதுவே நேரான வழியாகும்) அதாவது, 'நான் உங்களிடம் கொண்டு வந்த இந்த ஏகத்துவமே நேரான வழியாகும்; அதாவது உயர்ந்தவனாகிய இறைவனை மட்டுமே வணங்குவதாகும்.'\n\r\n\n\r\nفَاخْتَلَفَ الْأَحْزَابُ مِن بَيْنِهِمْ\n\r\n\n\r\n(இருப்பினும் அவர்களிடையே இருந்த பிரிவினர் தங்களுக்குள் மாறுபட்டனர்.) அதாவது, அவர்கள் கருத்து வேறுபாடு கொண்டு குழுக்களாகவும் பிரிவுகளாகவும் மாறினர். அவர்களில் சிலர், அவர் (ஈஸா (அலை)) அல்லாஹ்வின் அடியாரும் தூதரும் என்று கூறினர் - இதுவே உண்மையாகும். மற்றவர்களோ, அவர் அல்லாஹ்வின் மகன் என்றோ அல்லது அவரே அல்லாஹ் என்றோ வாதிட்டனர் - அவர்கள் கூறுவதை விட்டும் அல்லாஹ் மிகவும் தூய்மையானவனும் உயர்ந்தவனுமாவான். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَوَيْلٌ لِّلَّذِينَ ظَلَمُواْ مِنْ عَذَابِ يَوْمٍ أَلِيمٍ\n\r\n\n\r\n(எனவே, அநியாயம் செய்தவர்களுக்கு நோவினை தரும் நாளின் வேதனையினால் அழிவுதான்!)"},"66":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=73\" class=\"link\">43:73</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:73 ஐ பார்க்கவும்"},"67":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=73\" class=\"link\">43:73</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:73 ஐ பார்க்கவும்"},"68":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=73\" class=\"link\">43:73</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:73 ஐ பார்க்கவும்"},"69":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=73\" class=\"link\">43:73</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:73 ஐ பார்க்கவும்"},"70":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=73\" class=\"link\">43:73</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:73 ஐ பார்க்கவும்"},"71":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=73\" class=\"link\">43:73</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:73 ஐ பார்க்கவும்"},"72":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=73\" class=\"link\">43:73</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:73 ஐ பார்க்கவும்"},"73":{"html":"<strong>மறுமை நாள் திடீரென வரும்; அந்நாளில் நிராகரிப்பாளர்களிடையே நெருங்கிய நண்பர்களுக்கு இடையில் பகைமை ஏற்படும்</strong><br />\r\n<br />\r\n\"தூதர்களை நிராகரிக்கும் இந்த இணைவைப்பாளர்கள் எதை எதிர்பார்க்கிறார்கள்?\" என்று அல்லாஹ் கூறுகிறான். <span class=\"quran-arabic-font text-success\">﴾إِلاَّ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَأْتِيَهُمْ</span> <span class=\"quran-arabic-font text-success\">بَغْتَةً</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَشْعُرُونَ﴿</span><br />\r\n<br />\r\n(அவர்கள் உணராத நிலையில் திடீரென அந்த மறுமை நாள் அவர்கள் முன் வருவதையல்லாமல் வேறெதையும் அவர்கள் எதிர்பார்க்கிறார்களா?) அதாவது, அது உண்மையானது, நிச்சயமாக நிகழக்கூடியது. ஆனால் இந்த அஜாக்கிரதையான மக்கள் அதற்குத் தயாராக இல்லை. அது வரும்போது, அவர்களை அறியாத நிலையிலேயே பிடித்துக்கொள்ளும். அந்நாளில் அவர்கள் பெரும் கைசேதத்தை உணர்வார்கள்; ஆனால் அந்த வருத்தம் அவர்களுக்குச் சிறிதளவும் பயனளிக்காது, எவ்வித பாதுகாப்பையும் வழங்காது. <span class=\"quran-arabic-font text-success\">﴾الْأَخِلَّاءُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">بَعْضُهُمْ</span> <span class=\"quran-arabic-font text-success\">لِبَعْضٍ</span> <span class=\"quran-arabic-font text-success\">عَدُوٌّ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الْمُتَّقِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அந்நாளில் 'தக்வா' (இறையச்சம்) உடையவர்களைத் தவிர, நண்பர்கள் ஒருவருக்கொருவர் எதிரிகளாகி விடுவார்கள்.) அதாவது, அல்லாஹ்வுக்காக அன்றி வேறொரு நோக்கத்திற்காக வளர்க்கப்பட்ட ஒவ்வொரு நட்பும் மறுமை நாளில் பகையாக மாறும். அல்லாஹ்வுக்காக ஏற்படுத்தப்பட்ட நட்பு மட்டுமே என்றென்றும் நிலைத்திருக்கும். இது இப்ராஹீம் (அலை) அவர்கள் தம் மக்களிடம் கூறியதைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">اتَّخَذْتُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أَوْثَـناً</span> <span class=\"quran-arabic-font text-success\">مَّوَدَّةَ</span> <span class=\"quran-arabic-font text-success\">بَيْنِكُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَـمَةِ</span> <span class=\"quran-arabic-font text-success\">يَكْفُرُ</span> <span class=\"quran-arabic-font text-success\">بَعْضُكُمْ</span> <span class=\"quran-arabic-font text-success\">بِبَعْضٍ</span> <span class=\"quran-arabic-font text-success\">وَيَلْعَنُ</span> <span class=\"quran-arabic-font text-success\">بَعْضُكُمْ</span> <span class=\"quran-arabic-font text-success\">بَعْضاً</span> <span class=\"quran-arabic-font text-success\">وَمَأْوَاكُمُ</span> <span class=\"quran-arabic-font text-success\">النَّارُ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">نَّـصِرِينَ﴿</span><br />\r\n<br />\r\n(நீங்கள் அல்லாஹ்வைத் தவிர்த்துச் சிலைகளை (வணக்கத்திற்காக) ஏற்றுக்கொண்டீர்கள். உங்களுக்கிடையேயான அன்பு இவ்வுலக வாழ்க்கையோடு முடிந்துவிடும். ஆனால் மறுமை நாளில், நீங்கள் ஒருவரையொருவர் மறுப்பீர்கள், சபித்துக் கொள்வீர்கள். உங்கள் தங்குமிடம் நரகமாகும்; உங்களுக்கு உதவியாளர் எவரும் இருக்கமாட்டார்கள்.) (<a href=\"qurandisp.php?sura=29&ayah=25\" class=\"link\">29:25</a>)<br />\r\n<br />\r\n<strong>மறுமை நாளில் தக்வா உடையவர்களுக்கு நற்செய்தியும் அவர்கள் சொர்க்கத்தில் நுழைவதும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يَا</span> <span class=\"quran-arabic-font text-success\">عِبَادِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">خَوْفٌ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمُ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَحْزَنُونَ﴿</span><br />\r\n<br />\r\n(என் அடியார்களே! இன்றைய தினம் உங்களுக்கு எந்தப் பயமும் இல்லை, நீங்கள் கவலைப்படவும் மாட்டீர்கள்.) பின்னர் அவன் அவர்களுக்கு நற்செய்தி வழங்குவான்: <span class=\"quran-arabic-font text-success\">﴾الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">بِـَايَـتِنَا</span> <span class=\"quran-arabic-font text-success\">وَكَانُواْ</span> <span class=\"quran-arabic-font text-success\">مُسْلِمِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எங்களுடைய வசனங்களை (ஆயத்துகளை) ஈமான் கொண்டு, முஸ்லிம்களாக இருந்தவர்களே!) அதாவது, அவர்களின் உள்ளங்கள் ஈமான் கொண்டிருந்தன; மேலும் அவர்கள் உள்ளத்தாலும் உடலாலும் அல்லாஹ்வின் சட்டங்களுக்குப் பணிந்து நடந்தார்கள். அல்-முஃதமிர் பின் சுலைமான் அவர்கள் தம் தந்தை கூறியதாக அறிவிக்கிறார்கள்: \"மறுமை நாள் வந்து மக்கள் உயிர் கொடுத்து எழுப்பப்படும்போது, அச்சத்தில் ஆழ்ந்து விடாத மனிதர்களே இருக்க மாட்டார்கள். அப்போது ஓர் அழைப்பாளர் இவ்வாறு முழங்குவார்: <span class=\"quran-arabic-font text-success\">﴾يَا</span> <span class=\"quran-arabic-font text-success\">عِبَادِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">خَوْفٌ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمُ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَحْزَنُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(என் அடியார்களே! இன்றைய தினம் உங்களுக்கு எந்தப் பயமும் இல்லை, நீங்கள் கவலைப்படவும் மாட்டீர்கள்.) இதைக் கேட்டதும் மக்கள் அனைவரும் நம்பிக்கையூட்டப்படுவார்கள். ஆனால் அதைத் தொடர்ந்து இவ்வார்த்தைகள் வரும்: <span class=\"quran-arabic-font text-success\">﴾الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">بِـَايَـتِنَا</span> <span class=\"quran-arabic-font text-success\">وَكَانُواْ</span> <span class=\"quran-arabic-font text-success\">مُسْلِمِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எங்களுடைய வசனங்களை ஈமான் கொண்டு, முஸ்லிம்களாக இருந்தவர்களே!) அப்போது முஃமின்களைத் தவிர மற்ற மனிதர்கள் அனைவரும் நம்பிக்கையிழந்து விடுவார்கள்.\" <span class=\"quran-arabic-font text-success\">﴾ادْخُلُواْ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةَ﴿</span><br />\r\n<br />\r\n(சொர்க்கத்தில் நுழையுங்கள்) அதாவது, அவர்கள் சொர்க்கத்தில் நுழையுமாறு பணிக்கப்படுவார்கள். <span class=\"quran-arabic-font text-success\">﴾أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَزْوَاجُكُمْ﴿</span><br />\r\n<br />\r\n(நீங்களும் உங்கள் மனைவியரும்) அதாவது உங்களுக்கு இணையானவர்களும். <span class=\"quran-arabic-font text-success\">﴾تُحْبَرُونَ﴿</span><br />\r\n<br />\r\n(மகிழ்ச்சியூட்டப்பட்டவர்களாக - துஹ்பரூன்) அதாவது, பேரானந்தத்திலும் களிப்பிலும் திளைத்தவர்களாக. <span class=\"quran-arabic-font text-success\">﴾يُطَافُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">بِصِحَافٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">ذَهَبٍ</span> <span class=\"quran-arabic-font text-success\">وَأَكْوَابٍ﴿</span><br />\r\n<br />\r\n(தங்கத் தட்டுகளும் கிண்ணங்களும் அவர்களைச் சுற்றிக் கொண்டு வரப்படும்;) அதாவது, கைப்பிடிகளோ அல்லது மூக்குகளோ இல்லாத, உணவு மற்றும் பானங்கள் நிறைந்த நேர்த்தியான தங்கப் பாத்திரங்கள். <span class=\"quran-arabic-font text-success\">﴾وَفِيهَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَشْتَهِيهِ</span> <span class=\"quran-arabic-font text-success\">الأَنفُسُ﴿</span> (அதில் அவர்களின் மனங்கள் விரும்பக்கூடிய அனைத்தும் இருக்கும்). இமாம் அஹ்மத் (ரஹ்) அவர்கள் அறிவிக்கிறார்கள்: ஒரு கிராமவாசி நபி (ஸல்) அவர்களிடம், \"அல்லாஹ்வின் தூதரே! நான் ஒட்டகங்களை விரும்புகிறேன். சொர்க்கத்தில் ஒட்டகங்கள் இருக்குமா?\" என்று கேட்டார். அதற்கு நபி (ஸல்) அவர்கள், \"அல்லாஹ்வின் அடியாரே! நீர் சொர்க்கத்தில் நுழைந்தால், அங்கே உனது மனம் விரும்புவதும் உனது கண்கள் குளிர்ச்சியடைவதும் உமக்குக் கிடைக்கும்\" என்று கூறினார்கள். அவர்களில் சிலர் <span class=\"quran-arabic-font text-success\">﴾مَا</span> <span class=\"quran-arabic-font text-success\">تَشْتَهِي</span> <span class=\"quran-arabic-font text-success\">الأَنفُسُ﴿</span> என்று ('ஹ்' இன்றி) ஓதினார்கள்.<br />\r\n<br />\r\n(அவர்களின் ஆத்மாக்கள் இச்சிக்கும்...) <span class=\"quran-arabic-font text-success\">﴾وَتَلَذُّ</span> <span class=\"quran-arabic-font text-success\">الْأَعْيُنُ﴿</span><br />\r\n<br />\r\n(மேலும் கண்கள் குளிர்ச்சியடையும் அனைத்தும்) அதாவது சிறந்த உணவுகள், நறுமணங்கள் மற்றும் அழகான காட்சிகள். <span class=\"quran-arabic-font text-success\">﴾وَأَنتُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا﴿</span><br />\r\n<br />\r\n(மேலும் நீங்கள் அதில்) அதாவது சொர்க்கத்தில் <span class=\"quran-arabic-font text-success\">﴾خَـلِدُونَ﴿</span><br />\r\n<br />\r\n(என்றென்றும் தங்குவீர்கள்.) அதாவது நீங்கள் அதை ஒருபோதும் விட்டு வெளியேற மாட்டீர்கள்; வேறு எதற்கும் மாற்றவும் விரும்பமாட்டீர்கள். பிறகு, அல்லாஹ்வின் அருட்கொடைகளையும் கிருபையையும் அவர்களுக்கு நினைவூட்டும் விதமாக இவ்வாறு கூறப்படும்: <span class=\"quran-arabic-font text-success\">﴾وَتِلْكَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةُ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">أُورِثْتُمُوهَا</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நீங்கள் செய்து கொண்டிருந்த நற்செயல்களின் காரணமாக நீங்கள் வாரிசாகப் பெற்ற சொர்க்கம் இதுவேயாகும்.) அதாவது, நீங்கள் அல்லாஹ்வின் கருணையைப் பெறுவதற்குக் காரணமாக இருந்த நற்செயல்கள். ஏனெனில், எவரும் தமது செயல்களினால் மட்டும் சொர்க்கத்தில் நுழைந்து விட முடியாது; அல்லாஹ்வின் கருணையினாலும் கிருபையினாலும் மட்டுமே அது சாத்தியம். இருப்பினும், சொர்க்கத்தின் பல்வேறு அந்தஸ்துகளும் நிலைகளும் ஒருவரது நற்செயல்களுக்கு ஏற்பவே அமையும். <span class=\"quran-arabic-font text-success\">﴾لَكُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">فَـكِهَةٌ</span> <span class=\"quran-arabic-font text-success\">كَثِيرَةٌ﴿</span><br />\r\n<br />\r\n(அதில் உங்களுக்கு ஏராளமான பழங்கள் இருக்கும்.) அதாவது எல்லா வகைப் பழங்களும். <span class=\"quran-arabic-font text-success\">﴾مِّنْهَا</span> <span class=\"quran-arabic-font text-success\">تَأْكُلُونَ﴿</span><br />\r\n<br />\r\n(அவற்றிலிருந்து நீங்கள் உண்பீர்கள்.) அதாவது நீங்கள் விரும்பியதைத் தேர்ந்தெடுத்து உண்பீர்கள். உணவும் பானமும் குறிப்பிடப்படும் இடங்களில், அருட்கொடைகளின் முழுமையை உணர்த்த பழங்களும் சேர்த்தே குறிப்பிடப்படுகின்றன. அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />","text":"மறுமை நாள் திடீரென வரும்; அந்நாளில் நிராகரிப்பாளர்களிடையே நெருங்கிய நண்பர்களுக்கு இடையில் பகைமை ஏற்படும்\n\r\n\n\r\n\"தூதர்களை நிராகரிக்கும் இந்த இணைவைப்பாளர்கள் எதை எதிர்பார்க்கிறார்கள்?\" என்று அல்லாஹ் கூறுகிறான். ﴾إِلاَّ السَّاعَةَ أَن تَأْتِيَهُمْ بَغْتَةً وَهُمْ لاَ يَشْعُرُونَ﴿\n\r\n\n\r\n(அவர்கள் உணராத நிலையில் திடீரென அந்த மறுமை நாள் அவர்கள் முன் வருவதையல்லாமல் வேறெதையும் அவர்கள் எதிர்பார்க்கிறார்களா?) அதாவது, அது உண்மையானது, நிச்சயமாக நிகழக்கூடியது. ஆனால் இந்த அஜாக்கிரதையான மக்கள் அதற்குத் தயாராக இல்லை. அது வரும்போது, அவர்களை அறியாத நிலையிலேயே பிடித்துக்கொள்ளும். அந்நாளில் அவர்கள் பெரும் கைசேதத்தை உணர்வார்கள்; ஆனால் அந்த வருத்தம் அவர்களுக்குச் சிறிதளவும் பயனளிக்காது, எவ்வித பாதுகாப்பையும் வழங்காது. ﴾الْأَخِلَّاءُ يَوْمَئِذٍ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلاَّ الْمُتَّقِينَ ﴿\n\r\n\n\r\n(அந்நாளில் 'தக்வா' (இறையச்சம்) உடையவர்களைத் தவிர, நண்பர்கள் ஒருவருக்கொருவர் எதிரிகளாகி விடுவார்கள்.) அதாவது, அல்லாஹ்வுக்காக அன்றி வேறொரு நோக்கத்திற்காக வளர்க்கப்பட்ட ஒவ்வொரு நட்பும் மறுமை நாளில் பகையாக மாறும். அல்லாஹ்வுக்காக ஏற்படுத்தப்பட்ட நட்பு மட்டுமே என்றென்றும் நிலைத்திருக்கும். இது இப்ராஹீம் (அலை) அவர்கள் தம் மக்களிடம் கூறியதைப் போன்றது: ﴾إِنَّمَا اتَّخَذْتُمْ مِّن دُونِ اللَّهِ أَوْثَـناً مَّوَدَّةَ بَيْنِكُمْ فِى الْحَيَوةِ الدُّنْيَا ثُمَّ يَوْمَ الْقِيَـمَةِ يَكْفُرُ بَعْضُكُمْ بِبَعْضٍ وَيَلْعَنُ بَعْضُكُمْ بَعْضاً وَمَأْوَاكُمُ النَّارُ وَمَا لَكُمْ مِّن نَّـصِرِينَ﴿\n\r\n\n\r\n(நீங்கள் அல்லாஹ்வைத் தவிர்த்துச் சிலைகளை (வணக்கத்திற்காக) ஏற்றுக்கொண்டீர்கள். உங்களுக்கிடையேயான அன்பு இவ்வுலக வாழ்க்கையோடு முடிந்துவிடும். ஆனால் மறுமை நாளில், நீங்கள் ஒருவரையொருவர் மறுப்பீர்கள், சபித்துக் கொள்வீர்கள். உங்கள் தங்குமிடம் நரகமாகும்; உங்களுக்கு உதவியாளர் எவரும் இருக்கமாட்டார்கள்.) (29:25)\n\r\n\n\r\nமறுமை நாளில் தக்வா உடையவர்களுக்கு நற்செய்தியும் அவர்கள் சொர்க்கத்தில் நுழைவதும்\n\r\n\n\r\n﴾يَا عِبَادِ لاَ خَوْفٌ عَلَيْكُمُ الْيَوْمَ وَلاَ أَنتُمْ تَحْزَنُونَ﴿\n\r\n\n\r\n(என் அடியார்களே! இன்றைய தினம் உங்களுக்கு எந்தப் பயமும் இல்லை, நீங்கள் கவலைப்படவும் மாட்டீர்கள்.) பின்னர் அவன் அவர்களுக்கு நற்செய்தி வழங்குவான்: ﴾الَّذِينَ ءَامَنُواْ بِـَايَـتِنَا وَكَانُواْ مُسْلِمِينَ ﴿\n\r\n\n\r\n(எங்களுடைய வசனங்களை (ஆயத்துகளை) ஈமான் கொண்டு, முஸ்லிம்களாக இருந்தவர்களே!) அதாவது, அவர்களின் உள்ளங்கள் ஈமான் கொண்டிருந்தன; மேலும் அவர்கள் உள்ளத்தாலும் உடலாலும் அல்லாஹ்வின் சட்டங்களுக்குப் பணிந்து நடந்தார்கள். அல்-முஃதமிர் பின் சுலைமான் அவர்கள் தம் தந்தை கூறியதாக அறிவிக்கிறார்கள்: \"மறுமை நாள் வந்து மக்கள் உயிர் கொடுத்து எழுப்பப்படும்போது, அச்சத்தில் ஆழ்ந்து விடாத மனிதர்களே இருக்க மாட்டார்கள். அப்போது ஓர் அழைப்பாளர் இவ்வாறு முழங்குவார்: ﴾يَا عِبَادِ لاَ خَوْفٌ عَلَيْكُمُ الْيَوْمَ وَلاَ أَنتُمْ تَحْزَنُونَ ﴿\n\r\n\n\r\n(என் அடியார்களே! இன்றைய தினம் உங்களுக்கு எந்தப் பயமும் இல்லை, நீங்கள் கவலைப்படவும் மாட்டீர்கள்.) இதைக் கேட்டதும் மக்கள் அனைவரும் நம்பிக்கையூட்டப்படுவார்கள். ஆனால் அதைத் தொடர்ந்து இவ்வார்த்தைகள் வரும்: ﴾الَّذِينَ ءَامَنُواْ بِـَايَـتِنَا وَكَانُواْ مُسْلِمِينَ ﴿\n\r\n\n\r\n(எங்களுடைய வசனங்களை ஈமான் கொண்டு, முஸ்லிம்களாக இருந்தவர்களே!) அப்போது முஃமின்களைத் தவிர மற்ற மனிதர்கள் அனைவரும் நம்பிக்கையிழந்து விடுவார்கள்.\" ﴾ادْخُلُواْ الْجَنَّةَ﴿\n\r\n\n\r\n(சொர்க்கத்தில் நுழையுங்கள்) அதாவது, அவர்கள் சொர்க்கத்தில் நுழையுமாறு பணிக்கப்படுவார்கள். ﴾أَنتُمْ وَأَزْوَاجُكُمْ﴿\n\r\n\n\r\n(நீங்களும் உங்கள் மனைவியரும்) அதாவது உங்களுக்கு இணையானவர்களும். ﴾تُحْبَرُونَ﴿\n\r\n\n\r\n(மகிழ்ச்சியூட்டப்பட்டவர்களாக - துஹ்பரூன்) அதாவது, பேரானந்தத்திலும் களிப்பிலும் திளைத்தவர்களாக. ﴾يُطَافُ عَلَيْهِمْ بِصِحَافٍ مِّن ذَهَبٍ وَأَكْوَابٍ﴿\n\r\n\n\r\n(தங்கத் தட்டுகளும் கிண்ணங்களும் அவர்களைச் சுற்றிக் கொண்டு வரப்படும்;) அதாவது, கைப்பிடிகளோ அல்லது மூக்குகளோ இல்லாத, உணவு மற்றும் பானங்கள் நிறைந்த நேர்த்தியான தங்கப் பாத்திரங்கள். ﴾وَفِيهَا مَا تَشْتَهِيهِ الأَنفُسُ﴿ (அதில் அவர்களின் மனங்கள் விரும்பக்கூடிய அனைத்தும் இருக்கும்). இமாம் அஹ்மத் (ரஹ்) அவர்கள் அறிவிக்கிறார்கள்: ஒரு கிராமவாசி நபி (ஸல்) அவர்களிடம், \"அல்லாஹ்வின் தூதரே! நான் ஒட்டகங்களை விரும்புகிறேன். சொர்க்கத்தில் ஒட்டகங்கள் இருக்குமா?\" என்று கேட்டார். அதற்கு நபி (ஸல்) அவர்கள், \"அல்லாஹ்வின் அடியாரே! நீர் சொர்க்கத்தில் நுழைந்தால், அங்கே உனது மனம் விரும்புவதும் உனது கண்கள் குளிர்ச்சியடைவதும் உமக்குக் கிடைக்கும்\" என்று கூறினார்கள். அவர்களில் சிலர் ﴾مَا تَشْتَهِي الأَنفُسُ﴿ என்று ('ஹ்' இன்றி) ஓதினார்கள்.\n\r\n\n\r\n(அவர்களின் ஆத்மாக்கள் இச்சிக்கும்...) ﴾وَتَلَذُّ الْأَعْيُنُ﴿\n\r\n\n\r\n(மேலும் கண்கள் குளிர்ச்சியடையும் அனைத்தும்) அதாவது சிறந்த உணவுகள், நறுமணங்கள் மற்றும் அழகான காட்சிகள். ﴾وَأَنتُمْ فِيهَا﴿\n\r\n\n\r\n(மேலும் நீங்கள் அதில்) அதாவது சொர்க்கத்தில் ﴾خَـلِدُونَ﴿\n\r\n\n\r\n(என்றென்றும் தங்குவீர்கள்.) அதாவது நீங்கள் அதை ஒருபோதும் விட்டு வெளியேற மாட்டீர்கள்; வேறு எதற்கும் மாற்றவும் விரும்பமாட்டீர்கள். பிறகு, அல்லாஹ்வின் அருட்கொடைகளையும் கிருபையையும் அவர்களுக்கு நினைவூட்டும் விதமாக இவ்வாறு கூறப்படும்: ﴾وَتِلْكَ الْجَنَّةُ الَّتِى أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ ﴿\n\r\n\n\r\n(நீங்கள் செய்து கொண்டிருந்த நற்செயல்களின் காரணமாக நீங்கள் வாரிசாகப் பெற்ற சொர்க்கம் இதுவேயாகும்.) அதாவது, நீங்கள் அல்லாஹ்வின் கருணையைப் பெறுவதற்குக் காரணமாக இருந்த நற்செயல்கள். ஏனெனில், எவரும் தமது செயல்களினால் மட்டும் சொர்க்கத்தில் நுழைந்து விட முடியாது; அல்லாஹ்வின் கருணையினாலும் கிருபையினாலும் மட்டுமே அது சாத்தியம். இருப்பினும், சொர்க்கத்தின் பல்வேறு அந்தஸ்துகளும் நிலைகளும் ஒருவரது நற்செயல்களுக்கு ஏற்பவே அமையும். ﴾لَكُمْ فِيهَا فَـكِهَةٌ كَثِيرَةٌ﴿\n\r\n\n\r\n(அதில் உங்களுக்கு ஏராளமான பழங்கள் இருக்கும்.) அதாவது எல்லா வகைப் பழங்களும். ﴾مِّنْهَا تَأْكُلُونَ﴿\n\r\n\n\r\n(அவற்றிலிருந்து நீங்கள் உண்பீர்கள்.) அதாவது நீங்கள் விரும்பியதைத் தேர்ந்தெடுத்து உண்பீர்கள். உணவும் பானமும் குறிப்பிடப்படும் இடங்களில், அருட்கொடைகளின் முழுமையை உணர்த்த பழங்களும் சேர்த்தே குறிப்பிடப்படுகின்றன. அல்லாஹ்வே மிக அறிந்தவன்."},"74":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=80\" class=\"link\">43:80</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:80 ஐ பார்க்கவும்"},"75":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=80\" class=\"link\">43:80</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:80 ஐ பார்க்கவும்"},"76":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=80\" class=\"link\">43:80</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:80 ஐ பார்க்கவும்"},"77":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=80\" class=\"link\">43:80</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:80 ஐ பார்க்கவும்"},"78":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=80\" class=\"link\">43:80</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:80 ஐ பார்க்கவும்"},"79":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=80\" class=\"link\">43:80</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:80 ஐ பார்க்கவும்"},"80":{"html":"<strong>தண்டனைக்குரியவர்களின் நிலை</strong><br />\r\n<br />\r\nநற்பாக்கியம் பெற்றவர்களின் நிலையை விவரித்த பிறகு, தண்டனைக்குரியவர்களின் நிலையைப் பற்றிய விவரிப்பு வருகிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمِينَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">عَذَابِ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">خَـلِدُونَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُفَتَّرُ</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ</span><br />\r\n<br />\r\n(நிச்சயமாக, குற்றவாளிகள் நரக வேதனையில் என்றென்றும் தங்கியிருப்பார்கள். அவர்களுக்கு அது குறைக்கப்பட மாட்டாது,) அதாவது, ஒரு கணம்கூட (குறைக்கப்பட மாட்டாது).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">مُبْلِسُونَ</span><br />\r\n<br />\r\n(அதில் அவர்கள் ஆழ்ந்த வருத்தத்திலும், துக்கத்திலும், விரக்தியிலும் மூழ்கியிருப்பார்கள்,) அதாவது, அவர்கள் எந்தவொரு நன்மையைப் பற்றிய நம்பிக்கையையும் இழந்துவிடுவார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">ظَلَمْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلَـكِن</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الظَّـلِمِينَ</span><br />\r\n<br />\r\n(நாம் அவர்களுக்கு அநீதி இழைக்கவில்லை; மாறாக, அவர்களே அநியாயக்காரர்களாக இருந்தனர்.) அதாவது, அவர்களுக்கு அத்தாட்சிகள் நிரூபிக்கப்பட்டு, தூதர்கள் அனுப்பப்பட்ட பின்னரும் அவர்கள் பாவம் செய்து, தூதர்களை நிராகரித்து கலகம் செய்ததால், அவர்கள் அதற்கு ஏற்றவாறு தண்டிக்கப்படுகிறார்கள். மேலும், உமது இறைவன் அடியார்களுக்கு அணுவளவும் அநீதி இழைப்பவன் அல்லன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَنَادَوْاْ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مَالِكُ</span><br />\r\n<br />\r\n(அவர்கள், \"மாலிக்கே!\" என்று உரக்கக் கூப்பிடுவார்கள்...) அவர் நரகத்தின் காவலர் ஆவார். இமாம் புகாரி அவர்கள் கூறினார்கள்: \"ஹஜ்ஜாஜ் பின் மின்ஹால் எங்களுக்கு அறிவித்தார்கள்; ஸுஃப்யான் பின் உயைனா எங்களுக்கு அறிவித்தார்கள்; அம்ர் பின் அதாவிடமிருந்து, ஸஃப்வான் பின் யஃலாவிடமிருந்து அவரது தந்தை (ரழி) அவர்கள் கூறினார்கள்: 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மின்பரின் மீது நின்று பின்வருமாறு ஓதுவதை நான் கேட்டேன்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَنَادَوْاْ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مَالِكُ</span> <span class=\"quran-arabic-font text-success\">لِيَقْضِ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span><br />\r\n<br />\r\n(மேலும் அவர்கள், \"மாலிக்கே! உம்முடைய இறைவன் எங்களை முடித்துவிடட்டும் (எங்களுக்கு மரணத்தை அளிக்கட்டும்)\" என்று கூக்குரலிடுவார்கள்.) அதாவது, 'அவன் எங்கள் உயிர்களைப் போக்கி, இந்தத் துன்பகரமான நிலையிலிருந்து எங்களுக்குச் சற்று ஓய்வு அளிக்கட்டும்.' ஆனால் அல்லாஹ் பின்வருமாறு கூறுவது போலத்தான் அது அமையும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُقْضَى</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">فَيَمُوتُواْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يُخَفَّفُ</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عَذَابِهَا</span><br />\r\n<br />\r\n(அவர்களுக்கு மரணம் சம்பவிக்கும் வகையில் அவர்கள் மீது தீர்ப்பளிக்கப்படவும் மாட்டாது; அதன் வேதனையிலிருந்து அவர்களுக்கு ஏதும் குறைக்கப்படவும் மாட்டாது) (<a href=\"qurandisp.php?sura=35&ayah=36\" class=\"link\">35:36</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَتَجَنَّبُهَا</span> <span class=\"quran-arabic-font text-success\">الاٌّشْقَى</span> - <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يَصْلَى</span> <span class=\"quran-arabic-font text-success\">النَّارَ</span> <span class=\"quran-arabic-font text-success\">الْكُبْرَى</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَمُوتُ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَحْيَا</span><br />\r\n<br />\r\n(ஆனால் பெரும் துரதிர்ஷ்டசாலி அதைத் தவிர்ந்து கொள்வான். அவன் மகா நெருப்பில் நுழைவான். பிறகு அதில் அவன் சாகவும் மாட்டான்; (நிம்மதியாக) வாழவும் மாட்டான்.) (<a href=\"qurandisp.php?sura=87&ayah=11\" class=\"link\">87:11</a>-13). அவர்கள் மரணத்தை வேண்டும்போது, மாலிக் அவர்கள் அவர்களுக்குப் பதிலளிப்பார்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">مَّـكِثُونَ</span><br />\r\n<br />\r\n\"நிச்சயமாக நீங்கள் (இங்கேயே) தங்கியிருப்பவர்கள்தாம்\" என்று அவர் கூறுவார். அதாவது, அதிலிருந்து வெளியேற உங்களுக்கு வழியும் இல்லை, புகலிடமும் இல்லை. பிறகு, அவர்கள் ஏன் தண்டிக்கப்படுகிறார்கள் என்பதற்கான காரணம் கூறப்படும்; அது அவர்கள் உண்மையை மிகவும் பிடிவாதமாக எதிர்த்ததே ஆகும். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَقَدْ</span> <span class=\"quran-arabic-font text-success\">جِئْنَـكُم</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் உங்களிடம் சத்தியத்தைக் கொண்டு வந்தோம்,) அதாவது, 'நாம் அதனை உங்களுக்குத் தெளிவாகவும் விரிவாகவும் விளக்கியுள்ளோம்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَـكِنَّ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَكُمْ</span> <span class=\"quran-arabic-font text-success\">لِلْحَقِّ</span> <span class=\"quran-arabic-font text-success\">كَـرِهُونَ</span><br />\r\n<br />\r\n(ஆனால் உங்களில் பெரும்பாலோர் சத்தியத்தை வெறுப்பவர்களாகவே இருந்தீர்கள்.) அதாவது, 'உங்களது இயல்பு அதனை ஏற்றுக்கொள்ளவில்லை, அதனைத் தேடவும் இல்லை; மாறாக, நீங்கள் அசத்தியத்தைப் பின்பற்றி அதைப் போற்றினீர்கள். மேலும், சத்தியத்திற்குத் தடையாக நின்று அதனை மறுத்தீர்கள், அதைப் பின்பற்றுபவர்களை இழிவாகக் கருதினீர்கள்.' எனவே அவர்கள் தங்களையே நொந்துகொள்வார்கள். கைசேதப்படுவதால் எந்தப் பயனும் இல்லாத அந்நேரத்தில் அவர்கள் வருந்துவார்கள். பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">أَبْرَمُواْ</span> <span class=\"quran-arabic-font text-success\">أَمْراً</span> <span class=\"quran-arabic-font text-success\">فَإِنَّا</span> <span class=\"quran-arabic-font text-success\">مُبْرِمُونَ</span><br />\r\n<br />\r\n(அல்லது அவர்கள் ஏதேனும் ஒரு காரியத்தைத் திட்டமிட்டார்களா? அவ்வாறாயின் நாமும் திட்டமிடுகிறோம்.) முஜாஹித் அவர்கள் கூறினார்கள்: \"அவர்கள் ஏதோ ஒரு தீய திட்டத்தைத் தீட்ட விரும்பினார்கள், நாமும் ஒரு திட்டத்தைத் தீட்டினோம்.\" முஜாஹித் அவர்கள் கூறியது இந்த வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَكَرُواْ</span> <span class=\"quran-arabic-font text-success\">مَكْراً</span> <span class=\"quran-arabic-font text-success\">وَمَكَرْنَا</span> <span class=\"quran-arabic-font text-success\">مَكْراً</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَشْعُرُونَ</span><br />\r\n<br />\r\n(அவர்கள் ஒரு சூழ்ச்சி செய்தார்கள்; நாமும் ஒரு சூழ்ச்சி செய்தோம், ஆனால் அவர்கள் அதை உணரவில்லை.) (<a href=\"qurandisp.php?sura=27&ayah=50\" class=\"link\">27:50</a>). இணைவைப்பாளர்கள் அசத்தியத்தைக் கொண்டு சத்தியத்தை முறியடிப்பதற்கான வழிகளைக் கண்டறியத் தங்களால் இயன்றவரை முயற்சி செய்தார்கள். ஆனால் அதன் விளைவுகள் அவர்களுக்கே எதிராகத் திரும்பும்படி அல்லாஹ் திட்டமிட்டான். அவன் அதனை மறுத்துக் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">يَحْسَبُونَ</span> <span class=\"quran-arabic-font text-success\">أَنَّا</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">نَسْمَعُ</span> <span class=\"quran-arabic-font text-success\">سِرَّهُمْ</span> <span class=\"quran-arabic-font text-success\">وَنَجْوَهُم</span><br />\r\n<br />\r\n(அல்லது நாம் அவர்களுடைய இரகசியங்களையும், அவர்களுடைய அந்தரங்க ஆலோசனைகளையும் கேட்கவில்லை என்று அவர்கள் எண்ணுகிறார்களா?) அதாவது, அவர்கள் இரகசியமாகவும் வெளிப்படையாகவும் பேசுவதை (நாம் கேட்கிறோம்).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلَى</span> <span class=\"quran-arabic-font text-success\">وَرُسُلُنَا</span> <span class=\"quran-arabic-font text-success\">لَدَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">يَكْتُبُونَ</span><br />\r\n<br />\r\n(ஆம்! (நாம் கேட்கிறோம்), நம்முடைய தூதர்கள் (வானவர்கள்) அவர்களிடம் இருந்து அனைத்தையும் பதிவு செய்கிறார்கள்.) அதாவது, 'அவர்கள் என்ன செய்கிறார்கள் என்பதை நாம் அறிவோம்; வானவர்களும் அவர்களது சிறிய மற்றும் பெரிய செயல்களைப் பதிவு செய்கிறார்கள்.'<br />\r\n<br />\r\n<strong>அல்லாஹ்வுக்குச் சந்ததி இல்லை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">لِلرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">وَلَدٌ</span> <span class=\"quran-arabic-font text-success\">فَأَنَاْ</span> <span class=\"quran-arabic-font text-success\">أَوَّلُ</span> <span class=\"quran-arabic-font text-success\">الْعَـبِدِينَ</span><br />\r\n<br />\r\n(நபியே!) கூறுவீராக: \"அளவற்ற அருளாளனுக்கு ஒரு சந்ததி இருந்திருப்பின், (அவனை) வணங்குவோரில் நானே முதன்மையானவனாக இருந்திருப்பேன்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سُبْحَـنَ</span> <span class=\"quran-arabic-font text-success\">رَبّ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوتِ</span> <span class=\"quran-arabic-font text-success\">وَالاْرْضِ</span> <span class=\"quran-arabic-font text-success\">رَبّ</span> <span class=\"quran-arabic-font text-success\">الْعَرْشِ</span> <span class=\"quran-arabic-font text-success\">عَمَّا</span> <span class=\"quran-arabic-font text-success\">يَصِفُونَ</span><br />\r\n<br />\r\n(ஆகவே,) வானங்கள் மற்றும் பூமியின் இறைவனும், அர்ஷின் இறைவனுமானவன், அவர்கள் வர்ணிப்பதை விட்டும் மிகவும் தூய்மையானவன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَذَرْهُمْ</span> <span class=\"quran-arabic-font text-success\">يَخُوضُواْ</span> <span class=\"quran-arabic-font text-success\">وَيَلْعَبُواْ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يُلَـقُواْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَهُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يُوعَدُونَ</span><br />\r\n<br />\r\nஆகவே, அவர்களுக்கு வாக்களிக்கப்பட்ட அவர்களுடைய (அந்த) நாளை அவர்கள் சந்திக்கும் வரையில் அவர்களை (வீணானவற்றில்) மூழ்கிக்கிடக்கவும், விளையாடவும் விட்டுவிடுவீராக!<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">السَّمآء</span> <span class=\"quran-arabic-font text-success\">إِلَـهٌ</span> <span class=\"quran-arabic-font text-success\">وَفِى</span> <span class=\"quran-arabic-font text-success\">الاْرْضِ</span> <span class=\"quran-arabic-font text-success\">إِلَـهٌ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْحَكِيمُ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيمُ</span><br />\r\n<br />\r\nமேலும், அவன்தான் வானத்திலும் இறைவன்; பூமியிலும் இறைவன். அவனே ஞானமிக்கவன்; நன்கறிந்தவன்.<br />\r\n<br />","text":"தண்டனைக்குரியவர்களின் நிலை\n\r\n\n\r\nநற்பாக்கியம் பெற்றவர்களின் நிலையை விவரித்த பிறகு, தண்டனைக்குரியவர்களின் நிலையைப் பற்றிய விவரிப்பு வருகிறது.\n\r\n\n\r\nإِنَّ الْمُجْرِمِينَ فِى عَذَابِ جَهَنَّمَ خَـلِدُونَ لاَ يُفَتَّرُ عَنْهُمْ\n\r\n\n\r\n(நிச்சயமாக, குற்றவாளிகள் நரக வேதனையில் என்றென்றும் தங்கியிருப்பார்கள். அவர்களுக்கு அது குறைக்கப்பட மாட்டாது,) அதாவது, ஒரு கணம்கூட (குறைக்கப்பட மாட்டாது).\n\r\n\n\r\nوَهُمْ فِيهِ مُبْلِسُونَ\n\r\n\n\r\n(அதில் அவர்கள் ஆழ்ந்த வருத்தத்திலும், துக்கத்திலும், விரக்தியிலும் மூழ்கியிருப்பார்கள்,) அதாவது, அவர்கள் எந்தவொரு நன்மையைப் பற்றிய நம்பிக்கையையும் இழந்துவிடுவார்கள்.\n\r\n\n\r\nوَمَا ظَلَمْنَـهُمْ وَلَـكِن كَانُواْ هُمُ الظَّـلِمِينَ\n\r\n\n\r\n(நாம் அவர்களுக்கு அநீதி இழைக்கவில்லை; மாறாக, அவர்களே அநியாயக்காரர்களாக இருந்தனர்.) அதாவது, அவர்களுக்கு அத்தாட்சிகள் நிரூபிக்கப்பட்டு, தூதர்கள் அனுப்பப்பட்ட பின்னரும் அவர்கள் பாவம் செய்து, தூதர்களை நிராகரித்து கலகம் செய்ததால், அவர்கள் அதற்கு ஏற்றவாறு தண்டிக்கப்படுகிறார்கள். மேலும், உமது இறைவன் அடியார்களுக்கு அணுவளவும் அநீதி இழைப்பவன் அல்லன்.\n\r\n\n\r\nوَنَادَوْاْ يَا مَالِكُ\n\r\n\n\r\n(அவர்கள், \"மாலிக்கே!\" என்று உரக்கக் கூப்பிடுவார்கள்...) அவர் நரகத்தின் காவலர் ஆவார். இமாம் புகாரி அவர்கள் கூறினார்கள்: \"ஹஜ்ஜாஜ் பின் மின்ஹால் எங்களுக்கு அறிவித்தார்கள்; ஸுஃப்யான் பின் உயைனா எங்களுக்கு அறிவித்தார்கள்; அம்ர் பின் அதாவிடமிருந்து, ஸஃப்வான் பின் யஃலாவிடமிருந்து அவரது தந்தை (ரழி) அவர்கள் கூறினார்கள்: 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மின்பரின் மீது நின்று பின்வருமாறு ஓதுவதை நான் கேட்டேன்:\n\r\n\n\r\nوَنَادَوْاْ يَا مَالِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ\n\r\n\n\r\n(மேலும் அவர்கள், \"மாலிக்கே! உம்முடைய இறைவன் எங்களை முடித்துவிடட்டும் (எங்களுக்கு மரணத்தை அளிக்கட்டும்)\" என்று கூக்குரலிடுவார்கள்.) அதாவது, 'அவன் எங்கள் உயிர்களைப் போக்கி, இந்தத் துன்பகரமான நிலையிலிருந்து எங்களுக்குச் சற்று ஓய்வு அளிக்கட்டும்.' ஆனால் அல்லாஹ் பின்வருமாறு கூறுவது போலத்தான் அது அமையும்:\n\r\n\n\r\nلاَ يُقْضَى عَلَيْهِمْ فَيَمُوتُواْ وَلاَ يُخَفَّفُ عَنْهُمْ مِّنْ عَذَابِهَا\n\r\n\n\r\n(அவர்களுக்கு மரணம் சம்பவிக்கும் வகையில் அவர்கள் மீது தீர்ப்பளிக்கப்படவும் மாட்டாது; அதன் வேதனையிலிருந்து அவர்களுக்கு ஏதும் குறைக்கப்படவும் மாட்டாது) (35:36).\n\r\n\n\r\nوَيَتَجَنَّبُهَا الاٌّشْقَى - الَّذِى يَصْلَى النَّارَ الْكُبْرَى - ثُمَّ لاَ يَمُوتُ فِيهَا وَلاَ يَحْيَا\n\r\n\n\r\n(ஆனால் பெரும் துரதிர்ஷ்டசாலி அதைத் தவிர்ந்து கொள்வான். அவன் மகா நெருப்பில் நுழைவான். பிறகு அதில் அவன் சாகவும் மாட்டான்; (நிம்மதியாக) வாழவும் மாட்டான்.) (87:11-13). அவர்கள் மரணத்தை வேண்டும்போது, மாலிக் அவர்கள் அவர்களுக்குப் பதிலளிப்பார்:\n\r\n\n\r\nقَالَ إِنَّكُمْ مَّـكِثُونَ\n\r\n\n\r\n\"நிச்சயமாக நீங்கள் (இங்கேயே) தங்கியிருப்பவர்கள்தாம்\" என்று அவர் கூறுவார். அதாவது, அதிலிருந்து வெளியேற உங்களுக்கு வழியும் இல்லை, புகலிடமும் இல்லை. பிறகு, அவர்கள் ஏன் தண்டிக்கப்படுகிறார்கள் என்பதற்கான காரணம் கூறப்படும்; அது அவர்கள் உண்மையை மிகவும் பிடிவாதமாக எதிர்த்ததே ஆகும். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nلَقَدْ جِئْنَـكُم بِالْحَقِّ\n\r\n\n\r\n(நிச்சயமாக நாம் உங்களிடம் சத்தியத்தைக் கொண்டு வந்தோம்,) அதாவது, 'நாம் அதனை உங்களுக்குத் தெளிவாகவும் விரிவாகவும் விளக்கியுள்ளோம்.'\n\r\n\n\r\nوَلَـكِنَّ أَكْثَرَكُمْ لِلْحَقِّ كَـرِهُونَ\n\r\n\n\r\n(ஆனால் உங்களில் பெரும்பாலோர் சத்தியத்தை வெறுப்பவர்களாகவே இருந்தீர்கள்.) அதாவது, 'உங்களது இயல்பு அதனை ஏற்றுக்கொள்ளவில்லை, அதனைத் தேடவும் இல்லை; மாறாக, நீங்கள் அசத்தியத்தைப் பின்பற்றி அதைப் போற்றினீர்கள். மேலும், சத்தியத்திற்குத் தடையாக நின்று அதனை மறுத்தீர்கள், அதைப் பின்பற்றுபவர்களை இழிவாகக் கருதினீர்கள்.' எனவே அவர்கள் தங்களையே நொந்துகொள்வார்கள். கைசேதப்படுவதால் எந்தப் பயனும் இல்லாத அந்நேரத்தில் அவர்கள் வருந்துவார்கள். பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَمْ أَبْرَمُواْ أَمْراً فَإِنَّا مُبْرِمُونَ\n\r\n\n\r\n(அல்லது அவர்கள் ஏதேனும் ஒரு காரியத்தைத் திட்டமிட்டார்களா? அவ்வாறாயின் நாமும் திட்டமிடுகிறோம்.) முஜாஹித் அவர்கள் கூறினார்கள்: \"அவர்கள் ஏதோ ஒரு தீய திட்டத்தைத் தீட்ட விரும்பினார்கள், நாமும் ஒரு திட்டத்தைத் தீட்டினோம்.\" முஜாஹித் அவர்கள் கூறியது இந்த வசனத்தைப் போன்றது:\n\r\n\n\r\nوَمَكَرُواْ مَكْراً وَمَكَرْنَا مَكْراً وَهُمْ لاَ يَشْعُرُونَ\n\r\n\n\r\n(அவர்கள் ஒரு சூழ்ச்சி செய்தார்கள்; நாமும் ஒரு சூழ்ச்சி செய்தோம், ஆனால் அவர்கள் அதை உணரவில்லை.) (27:50). இணைவைப்பாளர்கள் அசத்தியத்தைக் கொண்டு சத்தியத்தை முறியடிப்பதற்கான வழிகளைக் கண்டறியத் தங்களால் இயன்றவரை முயற்சி செய்தார்கள். ஆனால் அதன் விளைவுகள் அவர்களுக்கே எதிராகத் திரும்பும்படி அல்லாஹ் திட்டமிட்டான். அவன் அதனை மறுத்துக் கூறுகிறான்:\n\r\n\n\r\nأَمْ يَحْسَبُونَ أَنَّا لاَ نَسْمَعُ سِرَّهُمْ وَنَجْوَهُم\n\r\n\n\r\n(அல்லது நாம் அவர்களுடைய இரகசியங்களையும், அவர்களுடைய அந்தரங்க ஆலோசனைகளையும் கேட்கவில்லை என்று அவர்கள் எண்ணுகிறார்களா?) அதாவது, அவர்கள் இரகசியமாகவும் வெளிப்படையாகவும் பேசுவதை (நாம் கேட்கிறோம்).\n\r\n\n\r\nبَلَى وَرُسُلُنَا لَدَيْهِمْ يَكْتُبُونَ\n\r\n\n\r\n(ஆம்! (நாம் கேட்கிறோம்), நம்முடைய தூதர்கள் (வானவர்கள்) அவர்களிடம் இருந்து அனைத்தையும் பதிவு செய்கிறார்கள்.) அதாவது, 'அவர்கள் என்ன செய்கிறார்கள் என்பதை நாம் அறிவோம்; வானவர்களும் அவர்களது சிறிய மற்றும் பெரிய செயல்களைப் பதிவு செய்கிறார்கள்.'\n\r\n\n\r\nஅல்லாஹ்வுக்குச் சந்ததி இல்லை\n\r\n\n\r\nقُلْ إِن كَانَ لِلرَّحْمَـنِ وَلَدٌ فَأَنَاْ أَوَّلُ الْعَـبِدِينَ\n\r\n\n\r\n(நபியே!) கூறுவீராக: \"அளவற்ற அருளாளனுக்கு ஒரு சந்ததி இருந்திருப்பின், (அவனை) வணங்குவோரில் நானே முதன்மையானவனாக இருந்திருப்பேன்.\"\n\r\n\n\r\nسُبْحَـنَ رَبّ السَّمَـوتِ وَالاْرْضِ رَبّ الْعَرْشِ عَمَّا يَصِفُونَ\n\r\n\n\r\n(ஆகவே,) வானங்கள் மற்றும் பூமியின் இறைவனும், அர்ஷின் இறைவனுமானவன், அவர்கள் வர்ணிப்பதை விட்டும் மிகவும் தூய்மையானவன்.\n\r\n\n\r\nفَذَرْهُمْ يَخُوضُواْ وَيَلْعَبُواْ حَتَّى يُلَـقُواْ يَوْمَهُمُ الَّذِى يُوعَدُونَ\n\r\n\n\r\nஆகவே, அவர்களுக்கு வாக்களிக்கப்பட்ட அவர்களுடைய (அந்த) நாளை அவர்கள் சந்திக்கும் வரையில் அவர்களை (வீணானவற்றில்) மூழ்கிக்கிடக்கவும், விளையாடவும் விட்டுவிடுவீராக!\n\r\n\n\r\nوَهُوَ الَّذِى فِى السَّمآء إِلَـهٌ وَفِى الاْرْضِ إِلَـهٌ وَهُوَ الْحَكِيمُ الْعَلِيمُ\n\r\n\n\r\nமேலும், அவன்தான் வானத்திலும் இறைவன்; பூமியிலும் இறைவன். அவனே ஞானமிக்கவன்; நன்கறிந்தவன்."},"81":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=89\" class=\"link\">43:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:89 ஐ பார்க்கவும்"},"82":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=89\" class=\"link\">43:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:89 ஐ பார்க்கவும்"},"83":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=89\" class=\"link\">43:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:89 ஐ பார்க்கவும்"},"84":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=89\" class=\"link\">43:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:89 ஐ பார்க்கவும்"},"85":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=89\" class=\"link\">43:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:89 ஐ பார்க்கவும்"},"86":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=89\" class=\"link\">43:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:89 ஐ பார்க்கவும்"},"87":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=89\" class=\"link\">43:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:89 ஐ பார்க்கவும்"},"88":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=43&ayah=89\" class=\"link\">43:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 43:89 ஐ பார்க்கவும்"},"89":{"html":"<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حـم</span> - <span class=\"quran-arabic-font text-success\">تَنزِيلُ</span> <span class=\"quran-arabic-font text-success\">الْكِتَـبِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزِ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيمِ</span><br />\r\n<br />\r\n<br />\r\n(ஹா-மீம். தெளிவான இவ்வேதத்தின் மீது சத்தியமாக.) இதன் பொருள், இப் புத்தகம் சொல்லிலும் கருத்திலும் மிகத் தெளிவானது. ஏனெனில் இது அரபு மொழியில் அருளப்பட்டது. மக்களிடையே கருத்துப் பரிமாற்றம் செய்வதற்கு அரபு மொழியே மிகவும் ஆற்றல்மிக்க மொழியாகும். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">جَعَلْنَـهُ</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக நாம் அதனை ஆக்கினோம்) அதாவது, இதனை நாம் அருளினோம்,<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُرْءَاناً</span> <span class=\"quran-arabic-font text-success\">عَرَبِيّاً</span><br />\r\n<br />\r\n<br />\r\n(அரபி மொழியிலான குர்ஆனாக) அதாவது, அரபு மொழியில், தெளிவானதாகவும் அழகானதாகவும்;<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْقِلُونَ</span><br />\r\n<br />\r\n<br />\r\n(நீங்கள் விளங்கிக்கொள்வதற்காக.) அதாவது, நீங்கள் இதனைப் புரிந்து கொண்டு இதன் கருத்துகளைச் சிந்திப்பதற்காக. இது இந்த வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِلِسَانٍ</span> <span class=\"quran-arabic-font text-success\">عَرَبِىٍّ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span><br />\r\n<br />\r\n<br />\r\n(தெளிவான அரபி மொழியில்.) (<a href=\"qurandisp.php?sura=26&ayah=195\" class=\"link\">26:195</a>)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">أُمِّ</span> <span class=\"quran-arabic-font text-success\">الْكِتَـبِ</span> <span class=\"quran-arabic-font text-success\">لَدَيْنَا</span> <span class=\"quran-arabic-font text-success\">لَعَلِىٌّ</span> <span class=\"quran-arabic-font text-success\">حَكِيمٌ</span><br />\r\n<br />\r\n<br />\r\n(மேலும் நிச்சயமாக இது நம்மிடமுள்ள மூல நூலில் இருக்கிறது; மெய்யாகவே இது மிகவும் உயர்ந்ததும், ஞானம் மிக்கதுமாகும்.) இது வானுலகில் உள்ள வானவர்களிடையே குர்ஆனுக்கு இருக்கும் உயர்ந்த அந்தஸ்தை விளக்குகிறது. பூமியிலுள்ள மக்கள் இதனை மதித்து, கண்ணியப்படுத்தி, இதற்குக் கீழ்ப்படிவதற்காக இவ்வாறு கூறப்படுகிறது.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنَّهُ</span><br />\r\n<br />\r\n<br />\r\n(மேலும் நிச்சயமாக இது) அதாவது, இக்குர்ஆன்,<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">أُمِّ</span> <span class=\"quran-arabic-font text-success\">الْكِتَـبِ</span><br />\r\n<br />\r\n<br />\r\n(மூல நூலில் இருக்கிறது) அதாவது, அல்-லவ்ஹுல் மஹ்ஃபூல் (பாதுகாக்கப்பட்ட பலகை). இது இப்னு அப்பாஸ் (ரழி) மற்றும் முஜாஹித் ஆகியோரின் கருத்தாகும்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَدَيْنَآ</span><br />\r\n<br />\r\n<br />\r\n(நம்மிடத்தில்,) அதாவது, நமது முன்னிலையில். இது கத்தாதா (ரஹ்) மற்றும் பலரின் கருத்தாகும்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّعَلِّى</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக உயர்ந்தது) அதாவது, கண்ணியமும் சிறப்பும் மிக்க ஒரு நிலையில் இருக்கிறது. இது கத்தாதாவின் (ரஹ்) கருத்தாகும்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حَكِيمٌ</span><br />\r\n<br />\r\n<br />\r\n(ஞானம் மிக்கது.) அதாவது, எந்தக் குழப்பமும் குறைபாடும் இல்லாத தெளிவானது. இவை அனைத்தும் அதன் மகத்துவத்தைக் காட்டுகின்றன. அல்லாஹ் மற்றோரிடத்தில் கூறுவது போல:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَقُرْءَانٌ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٌ</span> - <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كِتَـبٍ</span> <span class=\"quran-arabic-font text-success\">مَّكْنُونٍ</span> - <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَمَسُّهُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الْمُطَهَّرُونَ</span> - <span class=\"quran-arabic-font text-success\">تَنزِيلٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّ</span> <span class=\"quran-arabic-font text-success\">الْعَـلَمِينَ</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக இது கண்ணியமிக்க ஓதலாகும் (குர்ஆன்). நன்கு பாதுகாக்கப்பட்ட ஒரு புத்தகத்தில் இது இருக்கிறது. தூய்மையானவர்களைத் தவிர வேறு எவரும் இதனைத் தொடமாட்டார்கள். இது அகிலங்களின் இறைவனிடமிருந்து அருளப்பட்ட ஒரு வஹீ (இறைச்செய்தி).) (<a href=\"qurandisp.php?sura=56&ayah=77\" class=\"link\">56:77</a>-80)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَلاَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّهَا</span> <span class=\"quran-arabic-font text-success\">تَذْكِرَةٌ</span> <span class=\"quran-arabic-font text-success\">فَمَن</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">ذَكَرَهُ</span> <span class=\"quran-arabic-font text-success\">فَى</span> <span class=\"quran-arabic-font text-success\">صُحُفٍ</span> <span class=\"quran-arabic-font text-success\">مُّكَرَّمَةٍ</span> <span class=\"quran-arabic-font text-success\">مَّرْفُوعَةٍ</span> <span class=\"quran-arabic-font text-success\">مُّطَهَّرَةٍ</span> <span class=\"quran-arabic-font text-success\">بِأَيْدِى</span> <span class=\"quran-arabic-font text-success\">سَفَرَةٍ</span> <span class=\"quran-arabic-font text-success\">كِرَامٍ</span> <span class=\"quran-arabic-font text-success\">بَرَرَةٍ</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக இது ஒரு நல்லுரையாகும். ஆகவே, யார் விரும்புகிறாரோ அவர் இதனை நினைவில் கொள்ளட்டும். (இது) கண்ணியமிக்க, உயர்ந்த, தூய்மையான ஏடுகளில் உள்ளது. கண்ணியமான, கீழ்ப்படிதலுள்ள வானவர்களின் கைகளால் எழுதப்பட்டது.) (<a href=\"qurandisp.php?sura=80&ayah=11\" class=\"link\">80:11</a>-16)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَنَضْرِبُ</span> <span class=\"quran-arabic-font text-success\">عَنكُمُ</span> <span class=\"quran-arabic-font text-success\">الذِّكْرَ</span> <span class=\"quran-arabic-font text-success\">صَفْحاً</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْماً</span> <span class=\"quran-arabic-font text-success\">مُّسْرِفِينَ</span><br />\r\n<br />\r\n<br />\r\n(நீங்கள் வரம்பு மீறிய மக்களாக இருப்பதற்காக, இந்த நல்லுரையை (குர்ஆனை) உங்களிடமிருந்து நாம் முற்றாக விலக்கி விடுவோமா?) இதன் பொருள்: 'உங்களுக்குக் கட்டளையிடப்பட்டதை நீங்கள் செய்யாதபோது, உங்களைத் தண்டிக்காமல் விட்டுவிடுவோம் என்று கருதுகிறீர்களா?' என்பதாகும். இது இப்னு அப்பாஸ் (ரழி), அபூ ஸாலிஹ், முஜாஹித் மற்றும் அஸ்-ஸுத்தி ஆகியோரின் கருத்தாகும். இக்கருத்தையே இப்னு ஜரீர் (ரஹ்) அவர்களும் விரும்புகிறார்கள்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَنَضْرِبُ</span> <span class=\"quran-arabic-font text-success\">عَنكُمُ</span> <span class=\"quran-arabic-font text-success\">الذِّكْرَ</span> <span class=\"quran-arabic-font text-success\">صَفْحاً</span><br />\r\n<br />\r\n<br />\r\n(இந்த நல்லுரையை (குர்ஆனை) உங்களிடமிருந்து நாம் முற்றாக விலக்கி விடுவோமா?) கத்தாதா (ரஹ்) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் மீது சத்தியமாக! இந்த உம்மத்தின் ஆரம்ப காலத்தவர்கள் குர்ஆனை நிராகரித்தபோது, அல்லாஹ் அதனைத் திரும்பப் பெற்றிருந்தால் அவர்கள் அழிந்திருப்பார்கள். ஆனால் அல்லாஹ் தனது பெருங்கருணையால் தொடர்ந்து குர்ஆனை அனுப்பி, சுமார் இருபது ஆண்டுகள் அவர்களை அதன் பக்கம் அழைத்தான்.\" கத்தாதா (ரஹ்) அவர்கள் கூறியது மிகவும் சிறப்பானது. மனிதர்கள் குர்ஆனைப் புறக்கணித்த போதிலும், அல்லாஹ் தன் அடியார்கள் மீது கொண்ட கருணையால் அவர்களை சத்தியத்தின் பக்கமும், ஞானம் நிறைந்த நினைவூட்டலின் பக்கமும் அழைப்பதை நிறுத்தவில்லை என்பதே இதன் சாராம்சம். நேர்வழி பெற வேண்டும் என்று விதிக்கப்பட்டவர்கள் அதன் மூலம் நேர்வழி பெற வேண்டும் என்பதற்காகவும், மற்றவர்களுக்கு எதிராக ஆதாரம் நிலைநாட்டப்பட வேண்டும் என்பதற்காகவும் அல்லாஹ் இதனை அருளினான்.<br />\r\n<br />\r\n<br />\r\n(அளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.)<br />\r\n<br />\r\n<strong>குறைஷிகளின் நிராகரிப்பிற்காக நபி (ஸல்) அவர்களுக்கு ஆறுதல்</strong><br />\r\n<br />\r\n<br />\r\nபின்னர் அல்லாஹ் தனது நபி (ஸல்) அவர்களுக்கு, அவர்களின் மக்களின் நிராகரிப்பிற்காக ஆறுதல் கூறி, அதனைப் பொறுமையுடன் சகித்துக் கொள்ளுமாறு கட்டளையிடுகிறான்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَمْ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">نَّبِيٍّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّوَّلِينَ</span><br />\r\n<br />\r\n<br />\r\n(முன்னோர்களிடையே நாம் எத்தனையோ நபிமார்களை அனுப்பியிருக்கிறோம்.) அதாவது, முந்தைய சமுதாயத்தினரிடையே.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَأْتِيهِم</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">نَّبِىٍّ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">يَسْتَهْزِءُونَ</span><br />\r\n<br />\r\n<br />\r\n(அவர்களிடம் வந்த எந்த நபியையும் அவர்கள் ஏளனம் செய்யாமல் இருந்ததில்லை.) அதாவது, அவர்கள் அவரை நம்ப மறுத்துப் பரிகசித்தார்கள்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَهْلَكْنَآ</span> <span class=\"quran-arabic-font text-success\">أَشَدَّ</span> <span class=\"quran-arabic-font text-success\">مِنْهُم</span> <span class=\"quran-arabic-font text-success\">بَطْشاً</span><br />\r\n<br />\r\n<br />\r\n(இவர்களை விட அதிக வலிமை வாய்ந்தவர்களை நாம் அழித்தோம்.) இதன் பொருள்: 'முஹம்மதே (ஸல்)! உம்மை நிராகரிக்கும் இவர்களை விட அதிக வலிமை பெற்று, நம் தூதர்களை நிராகரித்த முந்தையவர்களை நாம் அழித்தோம்.' இது இந்த வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَسِيرُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">فَيَنظُرُواْ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَـقِبَةُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِمْ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">أَكْـثَرَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَشَدَّ</span> <span class=\"quran-arabic-font text-success\">قُوَّةً</span><br />\r\n<br />\r\n<br />\r\n(அவர்கள் பூமியில் பயணம் செய்து, தங்களுக்கு முன்னிருந்தவர்களின் முடிவு என்னவானது என்று பார்க்கவில்லையா? அவர்கள் இவர்களை விட எண்ணிக்கையில் அதிகமாகவும், வலிமையில் மிகைத்தவர்களாகவும் இருந்தார்கள்.) (<a href=\"qurandisp.php?sura=40&ayah=82\" class=\"link\">40:82</a>). இதுபோன்ற பல வசனங்கள் குர்ஆனில் உள்ளன.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَضَى</span> <span class=\"quran-arabic-font text-success\">مَثَلُ</span> <span class=\"quran-arabic-font text-success\">الاٌّوَّلِينَ</span><br />\r\n<br />\r\n<br />\r\n(முன்னோர்களின் உதாரணம் கடந்து சென்றுவிட்டது.) முஜாஹித் (ரஹ்) அவர்கள் \"அவர்களின் வாழ்க்கை முறை\" என்றும், கத்தாதா (ரஹ்) அவர்கள் \"அவர்களின் தண்டனை\" என்றும் கூறினார்கள். மற்றவர்கள் \"அவர்களின் படிப்பினை\" என்று கூறினார்கள். அதாவது, பிற்காலத்தவர்களுக்கு அவர்களை ஒரு பாடமாக ஆக்கினோம்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَجَعَلْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">سَلَفاً</span> <span class=\"quran-arabic-font text-success\">وَمَثَلاً</span> <span class=\"quran-arabic-font text-success\">لِّلاٌّخِرِينَ</span><br />\r\n<br />\r\n<br />\r\n(மேலும் நாம் அவர்களை ஒரு முன்மாதிரியாகவும், பிற்கால சந்ததியினருக்கு ஓர் உதாரணமாகவும் ஆக்கினோம்.) (<a href=\"qurandisp.php?sura=43&ayah=56\" class=\"link\">43:56</a>);<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سُنَّةَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">خَلَتْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">عِبَادِهِ</span><br />\r\n<br />\r\n<br />\r\n(இதுவே அல்லாஹ்வின் அடியார்களிடம் அவன் கையாண்டு வந்த வழியாகும்.) (<a href=\"qurandisp.php?sura=40&ayah=85\" class=\"link\">40:85</a>).<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَن</span> <span class=\"quran-arabic-font text-success\">تَجِدَ</span> <span class=\"quran-arabic-font text-success\">لِسُنَّةِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">تَبْدِيلاً</span><br />\r\n<br />\r\n<br />\r\n(மேலும், அல்லாஹ்வின் வழியில் எந்த மாற்றத்தையும் நீர் காணமாட்டீர்.) (<a href=\"qurandisp.php?sura=33&ayah=62\" class=\"link\">33:62</a>)<br />\r\n<br />\r\n<strong>அல்லாஹ்வே படைப்பாளன் என்பதை இணைவைப்பாளர்கள் ஒப்புக்கொள்வதும், அதற்கான மேலதிக ஆதாரங்களும்</strong><br />\r\n<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: 'முஹம்மதே (ஸல்)! அல்லாஹ்வுக்கு இணைகற்பித்து மற்றவர்களை வணங்கும் இவர்களிடம் நீர் கேட்டால்...'<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّنْ</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّرْضَ</span> <span class=\"quran-arabic-font text-success\">لَيَقُولُنَّ</span> <span class=\"quran-arabic-font text-success\">خَلَقَهُنَّ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيمُ</span><br />\r\n<br />\r\n<br />\r\n(\"வானங்களையும் பூமியையும் படைத்தவன் யார்?\" என்று நீர் அவர்களிடம் கேட்டால், \"யாவற்றையும் மிகைத்தோனும், எல்லாம் அறிந்தவனுமே அவற்றைப் படைத்தான்\" என்று அவர்கள் நிச்சயமாகக் கூறுவார்கள்.) அதாவது, அனைத்தையும் படைத்தது அல்லாஹ் ஒருவனே என்பதை அவர்கள் ஒப்புக்கொள்கிறார்கள். இருப்பினும், அவனுடன் சிலைகளையும் போலிக் கடவுள்களையும் சேர்த்து வணங்குகிறார்கள்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمُ</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضَ</span> <span class=\"quran-arabic-font text-success\">مَهْداً</span><br />\r\n<br />\r\n<br />\r\n(அவனே உங்களுக்காகப் பூமியை ஒரு விரிப்பாக ஆக்கினான்,) அதாவது, நீங்கள் அதில் பயணம் செய்யவும், அதன் மேல் நிற்கவும், உறங்கவும், நடக்கவும் வசதியாக அதனை உறுதியானதாக ஆக்கினான். அது தண்ணீரின் மேல் படைக்கப்பட்டிருந்தாலும், அது அசையாமல் இருக்க மலைகளைக் கொண்டு அல்லாஹ் அதனைப் பலப்படுத்தினான்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">سُبُلاً</span><br />\r\n<br />\r\n<br />\r\n(அதில் உங்களுக்காகப் பாதைகளையும் ஆக்கினான்,) அதாவது, மலைகளுக்கும் பள்ளத்தாக்குகளுக்கும் இடையே உள்ள வழிகள்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تَهْتَدُونَ</span><br />\r\n<br />\r\n<br />\r\n(நீங்கள் நேர்வழி பெறுவதற்காக.) அதாவது, ஊர் ஊராகப் பயணம் செய்யும்போது வழிதவறாமல் இருப்பதற்காக.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِى</span> <span class=\"quran-arabic-font text-success\">نَزَّلَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ</span> <span class=\"quran-arabic-font text-success\">مَآءً</span> <span class=\"quran-arabic-font text-success\">بِقَدَرٍ</span><br />\r\n<br />\r\n<br />\r\n(வானத்திலிருந்து குறிப்பிட்ட அளவில் மழையை இறக்குபவனும் அவனே,) அதாவது, உங்கள் பயிர்கள், பழங்கள் மற்றும் உங்கள் கால்நடைகளின் தேவைக்கு போதுமான அளவில்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَنشَرْنَا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">بَلْدَةً</span> <span class=\"quran-arabic-font text-success\">مَّيْتاً</span><br />\r\n<br />\r\n<br />\r\n(பின்னர், அதன் மூலம் காய்ந்து கிடந்த பூமியை நாம் உயிர்ப்பிக்கிறோம்,) அதாவது, ஒரு தரிசு நிலம். மழை பெய்யும்போது அந்த நிலம் செழித்து வளருவதைப் போல, மனிதர்கள் மரித்த பிறகு மறுமை நாளில் அவர்களின் உடல்களை அல்லாஹ் உயிர்ப்பிப்பான் என்பதை இது சுட்டிக்காட்டுகிறது.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">تُخْرَجُونَ</span><br />\r\n<br />\r\n<br />\r\n(இவ்வாறே நீங்களும் எழுப்பப்படுவீர்கள்.) பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِى</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">الأَزْوَجَ</span> <span class=\"quran-arabic-font text-success\">كُلَّهَا</span><br />\r\n<br />\r\n<br />\r\n(அனைத்து ஜோடிகளையும் படைத்தவன் அவனே.) அதாவது, பூமியில் வளரும் தாவரங்கள், பயிர்கள், பழங்கள் மற்றும் விலங்குகள் என அனைத்திலும் உள்ள ஜோடிகள்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْفُلْكِ</span><br />\r\n<br />\r\n<br />\r\n(மேலும், நீங்கள் ஏறிப் பயணம் செய்யக் கப்பல்களையும் ஏற்படுத்தினான்,)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالاٌّنْعَـمِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَرْكَبُونَ</span><br />\r\n<br />\r\n<br />\r\n(நீங்கள் சவாரி செய்யும் கால்நடைகளையும் ஏற்படுத்தினான்.) அதாவது, அவன் அவற்றை உங்களுக்கு வசப்படுத்திக் கொடுத்து, அவற்றின் இறைச்சியை உண்பதற்கும், பால் அருந்துவதற்கும், அதன் முதுகில் சவாரி செய்வதற்கும் உங்களுக்கு எளிதாக்கினான். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِتَسْتَوُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ظُهُورِهِ</span><br />\r\n<br />\r\n<br />\r\n(அதன் முதுகின் மேல் நீங்கள் ஏறி அமர்வதற்காக,) அதாவது, வசதியாகவும் பாதுகாப்பாகவும் அமர,<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ظُهُورِهِ</span><br />\r\n<br />\r\n<br />\r\n(அவற்றின் முதுகுகளில்) அதாவது, இந்த வகையான விலங்குகளின் முதுகுகளில்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">تَذْكُرُواْ</span> <span class=\"quran-arabic-font text-success\">نِعْمَةَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكُمْ</span><br />\r\n<br />\r\n<br />\r\n(பின்னர் உங்கள் இறைவனின் அருளை நீங்கள் நினைவுகூர வேண்டும்.) அதாவது, இந்த விலங்குகள் உங்களுக்கு வசப்படுத்திக் கொடுக்கப்பட்டிருப்பதை எண்ணிப் பார்க்க வேண்டும்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">اسْتَوَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">وَتَقُولُواْ</span> <span class=\"quran-arabic-font text-success\">سُبْحَـنَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">سَخَّرَ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مُقْرِنِينَ</span><br />\r\n<br />\r\n<br />\r\n(அதன் மீது நீங்கள் அமர்ந்ததும்: \"எங்களுக்கு இதனை வசப்படுத்திக் கொடுத்தவன் தூயவன்; நாம் இதனை வசப்படுத்தும் வலிமை உடையவர்களாக இருக்கவில்லை\" என்று கூறுங்கள்.) அதாவது, 'அல்லாஹ் இந்த வசதிகளை நமக்குத் தந்திருக்காவிட்டால், நமது சொந்த பலத்தால் இதனை ஒருபோதும் செய்திருக்க முடியாது.' இப்னு அப்பாஸ் (ரழி), கத்தாதா (ரஹ்), அஸ்-ஸுத்தி மற்றும் இப்னு ஸைத் (ரஹ்) ஆகியோர் இக்கருத்தையே கூறினர்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّنَا</span> <span class=\"quran-arabic-font text-success\">لَمُنقَلِبُونَ</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக நாம் நமது இறைவனிடமே திரும்பிச் செல்பவர்கள்.) அதாவது, 'மரணத்திற்குப் பிறகு நாம் அவனிடமே திரும்புவோம், நமது இறுதி இலக்கு அவனிடமே உள்ளது.' இவ்வுலகப் பயணங்கள் மறுமைப் பயணத்தை நினைவூட்டுகின்றன. உலகப் பயணத்திற்குத் தேவையானவை முக்கியம் என்பதைப் போல, மறுமைப் பயணத்திற்கு 'தக்வா' (இறையச்சம்) எனும் உணவு மிக முக்கியம் என்பதை அல்லாஹ் மற்றோர் இடத்தில் குறிப்பிடுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتَزَوَّدُواْ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">خَيْرَ</span> <span class=\"quran-arabic-font text-success\">الزَّادِ</span> <span class=\"quran-arabic-font text-success\">التَّقْوَى</span><br />\r\n<br />\r\n<br />\r\n(மேலும் பயணத்திற்குத் தேவையானவற்றை எடுத்துக்கொள்ளுங்கள்; ஆனால் சிறந்த தேவையானது தக்வா (இறையச்சம்) ஆகும்.) (<a href=\"qurandisp.php?sura=2&ayah=197\" class=\"link\">2:197</a>). உலக ஆடைகளைப் பற்றிய குறிப்பும் மறுமையின் ஆடைக்கு கவனத்தை ஈர்க்கப் பயன்படுத்தப்படுகிறது:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَرِيشًا</span> <span class=\"quran-arabic-font text-success\">وَلِبَاسُ</span> <span class=\"quran-arabic-font text-success\">التَّقْوَى</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span><br />\r\n<br />\r\n<br />\r\n(மேலும் ஓர் அலங்காரமாகவும்; தக்வாவின் (இறையச்சத்தின்) ஆடையே மிகச் சிறந்தது.) (<a href=\"qurandisp.php?sura=7&ayah=26\" class=\"link\">7:26</a>).<br />\r\n<br />\r\n<strong>அல்லாஹ்வுக்குச் சந்ததி கற்பிக்கும் இணைவைப்பாளர்களுக்குக் கண்டனம்</strong><br />\r\n<br />\r\n<br />\r\nஇங்கு இணைவைப்பாளர்களின் பொய்களைப் பற்றி அல்லாஹ் பேசுகிறான். அவர்கள் விளைச்சலிலும் கால்நடைகளிலும் ஒரு பகுதியை அல்லாஹ்வுக்கும் ஒரு பகுதியைத் தங்கள் போலித் தெய்வங்களுக்கும் ஒதுக்கினார்கள். இதனை அல்லாஹ் ஸூரத்துல் அன்ஆமில் விவரித்துள்ளான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلُواْ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">ذَرَأَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْحَرْثِ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّنْعَامِ</span> <span class=\"quran-arabic-font text-success\">نَصِيباً</span> <span class=\"quran-arabic-font text-success\">فَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">بِزَعْمِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَهَـذَا</span> <span class=\"quran-arabic-font text-success\">لِشُرَكَآئِنَا</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">لِشُرَكَآئِهِمْ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">يَصِلُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">يَصِلُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">شُرَكَآئِهِمْ</span> <span class=\"quran-arabic-font text-success\">سَآءَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَحْكُمُونَ</span><br />\r\n<br />\r\n<br />\r\n(மேலும், அவன் படைத்த விளைநிலங்கள் மற்றும் கால்நடைகளிலிருந்து அல்லாஹ்வுக்கு ஒரு பங்கை அவர்கள் ஒதுக்கி, \"இது அல்லாஹ்வுக்குரியது\" என்றும், \"இது எங்கள் கூட்டாளிகளுக்குரியது\" என்றும் தங்கள் கூற்றுப்படி கூறுகிறார்கள். ஆனால், அவர்களின் கூட்டாளிகளின் பங்கு அல்லாஹ்வைச் சென்றடைவதில்லை; அதேசமயம் அல்லாஹ்வின் பங்கு அவர்களின் கூட்டாளிகளைச் சென்றடைகிறது! அவர்கள் தீர்ப்பளிக்கும் முறை மிகவும் தீயது!) (<a href=\"qurandisp.php?sura=6&ayah=136\" class=\"link\">6:136</a>). இதேபோல், தங்களுக்குப் பிடித்தமான ஆண் குழந்தைகளைத் தங்களுக்கு வைத்துக்கொண்டு, தாங்கள் இழிவாகக் கருதும் பெண் குழந்தைகளை அல்லாஹ்வுக்குச் சொந்தமாக்கினார்கள். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلَكُمُ</span> <span class=\"quran-arabic-font text-success\">الذَّكَرُ</span> <span class=\"quran-arabic-font text-success\">وَلَهُ</span> <span class=\"quran-arabic-font text-success\">الاٍّنثَى</span> - <span class=\"quran-arabic-font text-success\">تِلْكَ</span> <span class=\"quran-arabic-font text-success\">إِذاً</span> <span class=\"quran-arabic-font text-success\">قِسْمَةٌ</span> <span class=\"quran-arabic-font text-success\">ضِيزَى</span><br />\r\n<br />\r\n<br />\r\n(உங்களுக்கு ஆண்களும் அவனுக்குப் பெண்களுமா? இது மிகவும் அநியாயமான பங்கீடாகும்!) (<a href=\"qurandisp.php?sura=53&ayah=21\" class=\"link\">53:21</a>-22) மேலும் அல்லாஹ் இங்கே கூறுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلُواْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عِبَادِهِ</span> <span class=\"quran-arabic-font text-success\">جُزْءًا</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الإنسَـنَ</span> <span class=\"quran-arabic-font text-success\">لَكَفُورٌ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٌ</span><br />\r\n<br />\r\n<br />\r\n(ஆயினும், அவனது அடியார்களில் சிலரை அவனுக்குரிய சந்ததியாக அவர்கள் ஆக்குகிறார்கள். நிச்சயமாக மனிதன் தெளிவான நன்றி கெட்டவனாக இருக்கிறான்!) பின்னர் அவன் கூறுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمِ</span> <span class=\"quran-arabic-font text-success\">اتَّخَذَ</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">يَخْلُقُ</span> <span class=\"quran-arabic-font text-success\">بَنَاتٍ</span> <span class=\"quran-arabic-font text-success\">وَأَصْفَـكُم</span> <span class=\"quran-arabic-font text-success\">بِالْبَنِينَ</span><br />\r\n<br />\r\n<br />\r\n(தான் படைத்தவற்றிலிருந்து பெண் பிள்ளைகளை அவன் எடுத்துக்கொண்டு, உங்களுக்கு ஆண் பிள்ளைகளைத் தேர்ந்தெடுத்திருக்கிறானா?) இது அவர்களின் செயலை மிகக் கடுமையாகக் கண்டிப்பதாகும்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">بُشِّرَ</span> <span class=\"quran-arabic-font text-success\">أَحَدُهُم</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">ضَرَبَ</span> <span class=\"quran-arabic-font text-success\">لِلرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">مَثَلاً</span> <span class=\"quran-arabic-font text-success\">ظَلَّ</span> <span class=\"quran-arabic-font text-success\">وَجْهُهُ</span> <span class=\"quran-arabic-font text-success\">مُسْوَدّاً</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">كَظِيمٌ</span><br />\r\n<br />\r\n<br />\r\n(அளவற்ற அருளாளனுக்கு எதனை அவர்கள் உவமையாகக் கூறுகிறார்களோ (பெண் குழந்தை), அதைப் பற்றி அவர்களில் ஒருவருக்கு நற்செய்தி கூறப்பட்டால், அவனது முகம் கறுத்துவிடுகிறது; அவன் துயரத்தால் நிரம்புகிறான்!) அதாவது, ஒரு பெண் குழந்தை பிறந்துவிட்டது என்று தெரிந்தால், அவன் அதனை வெறுக்கிறான். வெட்கத்தினால் மக்களிடமிருந்து மறைந்து கொள்கிறான். அல்லாஹ் கேட்கிறான்: அவர்கள் அவ்வளவு வெறுக்கும் ஒன்றை எவ்வாறு அல்லாஹ்வுக்குக் கற்பிக்கிறார்கள்?<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوَمَن</span> <span class=\"quran-arabic-font text-success\">يُنَشَّأُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْحِلْيَةِ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْخِصَامِ</span> <span class=\"quran-arabic-font text-success\">غَيْرُ</span> <span class=\"quran-arabic-font text-success\">مُبِينٍ</span><br />\r\n<br />\r\n<br />\r\n(ஆபரணங்களில் வளர்க்கப்பட்டு, வாதத்தின்போது தன்னைத் தெளிவாக வெளிப்படுத்த முடியாத ஒரு படைப்பையா (அல்லாஹ்வுக்குக் கற்பிக்கிறார்கள்?)) அதாவது, பெண்கள் பொதுவாக ஆபரணங்களால் தங்களை அழகுபடுத்திக் கொள்கிறார்கள், மேலும் வாதத்தின்போது தங்களைத் தற்காத்துப் பேசும் வலிமை குறைந்தவர்களாகக் கருதப்படுகிறார்கள். இத்தகையவர்களை எவ்வாறு அல்லாஹ்வுக்குச் சொந்தமாக்க முடியும்?<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلُواْ</span> <span class=\"quran-arabic-font text-success\">الْمَلَـئِكَةَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">عِبَادُ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">إِنَـثاً</span><br />\r\n<br />\r\n<br />\r\n(மேலும், அளவற்ற அருளாளனின் அடியார்களான வானவர்களை அவர்கள் பெண்களாகக் கருதுகிறார்கள்.) அல்லாஹ் இதனைக் கண்டித்துக் கேட்கிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَشَهِدُواْ</span> <span class=\"quran-arabic-font text-success\">خَلْقَهُمْ</span><br />\r\n<br />\r\n<br />\r\n(அவர்கள் படைக்கப்பட்டபோது இவர்கள் சாட்சியாக இருந்தார்களா?)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَتُكْتَبُ</span> <span class=\"quran-arabic-font text-success\">شَهَـدَتُهُمْ</span><br />\r\n<br />\r\n<br />\r\n(அவர்களின் சாட்சியம் பதிவு செய்யப்படும்,)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيُسْـَلُونَ</span><br />\r\n<br />\r\n<br />\r\n(மேலும் அவர்கள் விசாரிக்கப்படுவார்கள்!) மறுமை நாளில் அவர்கள் இது குறித்துக் கேள்வி கேட்கப்படுவார்கள். இது ஒரு கடுமையான எச்சரிக்கையாகும்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">عَبَدْنَـهُمْ</span><br />\r\n<br />\r\n<br />\r\n(மேலும் அவர்கள் கூறினார்கள்: \"அளவற்ற அருளாளன் நாடியிருந்தால், நாங்கள் இவற்றை வணங்கியிருக்க மாட்டோம்.\") இவ்வாறு கூறுவதன் மூலம் அவர்கள் பல தவறுகளைச் செய்கிறார்கள்: முதலாவது: அல்லாஹ்வுக்குச் சந்ததி கற்பித்தது. இரண்டாவது: வானங்களைப் பெண்கள் எனக் கூறியது. மூன்றாவது: எந்த ஆதாரமும் இன்றி மனோ இச்சையின் அடிப்படையில் வணங்கியது. நான்காவது: தங்கள் அறியாமைக்கு அல்லாஹ்வின் விதியைக் காரணமாகக் காட்டியது. அல்லாஹ் தூதர்களை அனுப்பி, தன்னை மட்டுமே வணங்குமாறு கட்டளையிட்டுள்ளான். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">بَعَثْنَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">أُمَّةٍ</span> <span class=\"quran-arabic-font text-success\">رَّسُولاً</span> <span class=\"quran-arabic-font text-success\">أَنِ</span> <span class=\"quran-arabic-font text-success\">اعْبُدُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَاجْتَنِبُواْ</span> <span class=\"quran-arabic-font text-success\">الْطَّـغُوتَ</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக நாம் ஒவ்வொரு சமுதாயத்திலும் ஒரு தூதரை அனுப்பினோம் (அவர் அறிவித்தார்): \"அல்லாஹ்வை வணங்குங்கள், போலி தெய்வங்களைத் தவிர்ந்து கொள்ளுங்கள்.\") (<a href=\"qurandisp.php?sura=16&ayah=36\" class=\"link\">16:36</a>)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاسْئلْ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِكَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رُّسُلِنَآ</span> <span class=\"quran-arabic-font text-success\">أَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">ءَالِهَةً</span> <span class=\"quran-arabic-font text-success\">يُعْبَدُونَ</span><br />\r\n<br />\r\n<br />\r\n(மேலும், உமக்கு முன்னர் நாம் அனுப்பிய தூதர்களிடம் கேளும்: \"அளவற்ற அருளாளனைத் தவிர வணங்கப்படுவதற்குரிய கடவுள்களை நாம் எப்போதாவது நியமித்தோமா?\") (<a href=\"qurandisp.php?sura=43&ayah=45\" class=\"link\">43:45</a>) மேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">لَهُم</span> <span class=\"quran-arabic-font text-success\">بِذَلِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عِلْمٍ</span><br />\r\n<br />\r\n<br />\r\n(அவர்களுக்கு அது பற்றி எந்த அறிவும் இல்லை.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنْ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">يَخْرُصُونَ</span><br />\r\n<br />\r\n<br />\r\n(அவர்கள் பொய் சொல்வதைத் தவிர வேறொன்றும் செய்வதில்லை!)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">لَهُم</span> <span class=\"quran-arabic-font text-success\">بِذَلِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عِلْمٍ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">يَخْرُصُونَ</span><br />\r\n<br />\r\n<br />\r\n(அவர்களுக்கு அது பற்றி எந்த அறிவும் இல்லை. அவர்கள் வெறும் யூகத்தையே பேசுகிறார்கள்!) முஜாஹித் (ரஹ்) அவர்கள் கூறினார்கள்: \"அவர்கள் அல்லாஹ்வின் வல்லமையை உணருவதில்லை.\"<br />\r\n<br />\r\n<strong>இணைவைப்பாளர்களிடம் எந்த ஆதாரமும் இல்லை</strong><br />\r\n<br />\r\n<br />\r\nஅல்லாஹ்வை விடுத்து மற்றவர்களை வணங்குவதற்கு இணைவைப்பாளர்களிடம் எந்த ஆதாரமும் இல்லை என்பதற்காக அல்லாஹ் அவர்களைக் கண்டிக்கிறான்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">ءَاتَيْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">كِتَـباً</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِ</span><br />\r\n<br />\r\n<br />\r\n(அல்லது இதற்கு முன்னர் நாம் அவர்களுக்கு ஏதேனும் ஒரு வேதத்தைக் கொடுத்திருக்கிறோமா?)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَهُم</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مُسْتَمْسِكُونَ</span><br />\r\n<br />\r\n<br />\r\n(அதனை அவர்கள் உறுதியாகப் பற்றிக் கொண்டிருக்கிறார்களா?) நிலைமை அப்படியில்லை. இது இந்த வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">أَنزَلْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">سُلْطَـناً</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">يَتَكَلَّمُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">يُشْرِكُونَ</span><br />\r\n<br />\r\n<br />\r\n(அல்லது, நாம் அவர்களுக்கு ஓர் அதிகாரத்தை (ஒரு வேதத்தை) அருளியிருக்கிறோமா, அது அவர்கள் இணைவைப்பதைப் பற்றிப் பேசுகிறதா?) (<a href=\"qurandisp.php?sura=30&ayah=35\" class=\"link\">30:35</a>).<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">وَجَدْنَآ</span> <span class=\"quran-arabic-font text-success\">ءَابَآءَنَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أُمَّةٍ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ءَاثَـرِهِم</span> <span class=\"quran-arabic-font text-success\">مُّهْتَدُونَ</span><br />\r\n<br />\r\n<br />\r\n(இல்லை! மாறாக அவர்கள் கூறுகிறார்கள்: \"நாங்கள் எங்கள் மூதாதையரை ஒரு வழியில் கண்டோம்; நாங்கள் அவர்களின் அடிச்சுவடுகளையே பின்பற்றுகிறோம்.\") அதாவது, தங்கள் முன்னோர்களைக் கண்மூடித்தனமாகப் பின்பற்றுவதைத் தவிர இவர்களிடம் வேறு எந்த ஆதாரமும் இல்லை. 'உம்மத்' என்ற வார்த்தை இதேபோல மற்றோர் இடத்திலும் பயன்படுத்தப்பட்டுள்ளது:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَـذِهِ</span> <span class=\"quran-arabic-font text-success\">أُمَّتُكُمْ</span> <span class=\"quran-arabic-font text-success\">أُمَّةً</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةً</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக, உங்கள் இந்த மார்க்கம் (உம்மத்) ஒரே மார்க்கமாகும்.) (<a href=\"qurandisp.php?sura=23&ayah=52\" class=\"link\">23:52</a>).<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مُّهْتَدُونَ</span><br />\r\n<br />\r\n<br />\r\n(நாங்கள் வழிகாட்டப்படுகிறோம்) என்பது அவர்களின் வெறும் கூற்று மட்டுமே. தூதர்களை நிராகரித்த முந்தைய சமுதாயத்தினர் கூறியதையே இவர்களும் கூறுகிறார்கள்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَتَى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّسُولٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">سَـحِرٌ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مَجْنُونٌ</span> - <span class=\"quran-arabic-font text-success\">أَتَوَاصَوْاْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">طَـغُونَ</span><br />\r\n<br />\r\n<br />\r\n(இவ்வாறே, இவர்களுக்கு முன் இருந்தவர்களிடம் எந்தத் தூதரும் வரவில்லை, ஆனால் அவர்கள், \"ஒரு சூனியக்காரர் அல்லது ஒரு பைத்தியக்காரர்!\" என்று கூறினர். அவர்கள் இந்தப் பொய்ச் சொல்லை ஒருவருக்கொருவர் விட்டுச் சென்றார்களா? இல்லை, அவர்கள் தாங்களாகவே வரம்பு மீறும் மக்களாக இருக்கிறார்கள்!) (<a href=\"qurandisp.php?sura=51&ayah=52\" class=\"link\">51:52</a>-53).<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِكَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قَرْيَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">نَّذِيرٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">مُتْرَفُوهَآ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">وَجَدْنَآ</span> <span class=\"quran-arabic-font text-success\">ءَابَآءَنَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أُمَّةٍ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ءَاثَـرِهِم</span> <span class=\"quran-arabic-font text-success\">مُّقْتَدُونَ</span><br />\r\n<br />\r\n<br />\r\n(இதேபோல், உமக்கு முன்னர் நாம் எந்த ஊருக்கும் ஓர் எச்சரிக்கையாளரை அனுப்பவில்லை, ஆனால் அங்குள்ள செல்வந்தர்கள் கூறினார்கள்: \"நாங்கள் எங்கள் மூதாதையரை ஒரு வழியில் கண்டோம், நிச்சயமாக நாங்கள் அவர்களின் அடிச்சுவடுகளையே பின்பற்றுவோம்.\") பின்னர் அவன் கூறுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span><br />\r\n<br />\r\n<br />\r\n(கூறுவீராக) -- 'முஹம்மதே (ஸல்), இந்த இணைவைப்பாளர்களிடம் --'<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوَلَوْ</span> <span class=\"quran-arabic-font text-success\">جِئْتُكُمْ</span> <span class=\"quran-arabic-font text-success\">بِأَهْدَى</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">وَجَدتُّمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">ءَابَآءَكُمْ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">بِمَآ</span> <span class=\"quran-arabic-font text-success\">أُرْسِلْتُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">كَـفِرُونَ</span><br />\r\n<br />\r\n<br />\r\n(\"உங்கள் மூதாதையர் பின்பற்றியதை விடச் சிறந்த வழிகாட்டுதலை நான் உங்களுக்குக் கொண்டு வந்தாலும் கூடவா?\" அதற்கு அவர்கள்: \"நிச்சயமாக, நீங்கள் எதனுடன் அனுப்பப்பட்டிருக்கிறீர்களோ அதனை நாங்கள் நிராகரிக்கிறோம்\" என்று கூறினர்.) அவர்கள் சத்தியத்தை உணர்ந்தாலும், தங்கள் ஆணவத்தினால் அதைப் பின்பற்ற மாட்டார்கள்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَانتَقَمْنَا</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span><br />\r\n<br />\r\n<br />\r\n(எனவே நாம் அவர்களிடம் பழிவாங்கினோம்) அதாவது, நிராகரித்த அந்தத் தேசங்களை நாம் அழித்தோம்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَانظُرْ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَـقِبَةُ</span> <span class=\"quran-arabic-font text-success\">الْمُكَذِّبِينَ</span><br />\r\n<br />\r\n<br />\r\n(சத்தியத்தை மறுத்தவர்களின் முடிவு என்னவானது என்பதை நீர் பாரும்.) அல்லாஹ் அவர்களை எவ்வாறு அழித்தான், நம்பிக்கையாளர்களை எவ்வாறு காப்பாற்றினான் என்பதைப் பாரும்.<br />\r\n<br />\r\n<strong>இப்ராஹீம் (அலை) அவர்களின் ஏகத்துவப் பிரகடனம்</strong><br />\r\n<br />\r\n<br />\r\nஅல்லாஹ் தனது அடியாரும், தூதரும், உற்ற நண்பருமான இப்ராஹீம் (அலை) அவர்களைப் பற்றி நமக்குக் கூறுகிறான். குறைஷிகள் தாங்கள் இவருடைய வழியில் நடப்பதாகவே கூறிக்கொண்டனர். அவர் தன் தந்தையிடமும் மக்களிடமும் கூறினார்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذْ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">إِبْرَهِيمُ</span> <span class=\"quran-arabic-font text-success\">لاًّبِيهِ</span> <span class=\"quran-arabic-font text-success\">وَقَوْمِهِ</span> <span class=\"quran-arabic-font text-success\">إِنَّنِى</span> <span class=\"quran-arabic-font text-success\">بَرَآءٌ</span> <span class=\"quran-arabic-font text-success\">مِّمَّا</span> <span class=\"quran-arabic-font text-success\">تَعْبُدُونَ</span> - <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">فَطَرَنِى</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">سَيَهْدِينِ</span> <span class=\"quran-arabic-font text-success\">وَجَعَلَهَا</span> <span class=\"quran-arabic-font text-success\">كَلِمَةً</span> <span class=\"quran-arabic-font text-success\">بَـقِيَةً</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">عَقِبِهِ</span><br />\r\n<br />\r\n<br />\r\n(\"நிச்சயமாக, நீங்கள் வணங்குபவற்றிலிருந்து நான் விலகிக் கொள்கிறேன்; என்னைப் படைத்தவனைத் தவிர. நிச்சயமாக அவன் எனக்கு நேர்வழி காட்டுவான்.\" மேலும் அவர் அதனைத் தனது சந்ததியினரிடையே நிலைத்திருக்கும் ஒரு வார்த்தையாக ஆக்கினார்.) அந்த வார்த்தை என்பது 'லா இலாஹ இல்லல்லாஹ்' (அல்லாஹ்வைத் தவிர வேறு இறைவனில்லை) என்பதாகும்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَعَلَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَرْجِعُونَ</span><br />\r\n<br />\r\n<br />\r\n(அவர்கள் இதன் பக்கம் திரும்பி வரக்கூடும் என்பதற்காக.) இப்னு அப்பாஸ் (ரழி) மற்றும் பலர் \"இந்த வார்த்தையைச் சொல்பவர்கள் இன்றும் அவரது சந்ததியினரில் இருக்கிறார்கள்\" என்று விளக்கமளித்தனர்.<br />\r\n<br />\r\n<strong>மக்கா வாசிகள் தூதரைப் புறக்கணித்ததும், அதற்கு அவருடைய பதிலும்</strong><br />\r\n<br />\r\n<br />\r\nமேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">مَتَّعْتُ</span> <span class=\"quran-arabic-font text-success\">هَـؤُلاَءِ</span><br />\r\n<br />\r\n<br />\r\n(மாறாக, இவர்களுக்கு நான் வசதிகளைக் கொடுத்தேன்) அதாவது, இணைவைப்பாளர்களுக்கு,<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَءَابَآءَهُمْ</span><br />\r\n<br />\r\n<br />\r\n(இவர்களுடைய மூதாதையர்களுக்கும்) அவர்கள் நீண்ட காலம் வழிகேட்டில் வாழ்ந்தார்கள்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">جَآءَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">وَرَسُولٌ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٌ</span><br />\r\n<br />\r\n<br />\r\n(சத்தியமும் தெளிவான தூதரும் அவர்களிடம் வரும்வரை.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَمَّا</span> <span class=\"quran-arabic-font text-success\">جَآءَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">سِحْرٌ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">كَـفِرُونَ</span><br />\r\n<br />\r\n<br />\r\n(சத்தியம் அவர்களிடம் வந்தபோது, அவர்கள் கூறினார்கள்: \"இது சூனியம், நாங்கள் இதனை நிராகரிக்கிறோம்.\") அவர்கள் ஆணவத்தாலும் பொறாமையாலும் அதனைப் புறக்கணித்தனர்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالُواْ</span><br />\r\n<br />\r\n<br />\r\n(மேலும் அவர்கள் கூறுகிறார்கள்) அல்லாஹ் அருளிய செய்திக்கு எதிர்ப்பு தெரிவித்து,<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَوْلاَ</span> <span class=\"quran-arabic-font text-success\">نُزِّلَ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَجُلٍ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْقَرْيَتَيْنِ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٍ</span><br />\r\n<br />\r\n<br />\r\n(இந்தக் குர்ஆன் மக்கா அல்லது தாயிஃப் ஆகிய இரு நகரங்களில் உள்ள ஏதேனும் ஒரு பெரிய மனிதர் மீது இறக்கப்பட்டிருக்கக் கூடாதா?) ஏன் உலகியலில் செல்வாக்கு மிக்க ஒருவரிடம் இது அருளப்படவில்லை என்பது அவர்களின் வாதம். குறைஷிகள் இதன் மூலம் அல்-வலீத் பின் அல்-முகீரா அல்லது உர்வா பின் மஸ்ஊத் அத்-தகஃபீயைக் குறிப்பிட்டனர். அல்லாஹ் இதற்கு இவ்வாறு பதிலளித்தான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَقْسِمُونَ</span> <span class=\"quran-arabic-font text-success\">رَحْمَةَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span><br />\r\n<br />\r\n<br />\r\n(உமது இறைவனின் அருளை இவர்களா பங்கிடுகிறார்கள்?) இந்த விஷயத்தில் அவர்களுக்கு எந்த அதிகாரமும் இல்லை; அதனைத் தீர்மானிப்பது அல்லாஹ்வே. வஹீயை (இறைச்செய்தியை) யாரிடம் அனுப்ப வேண்டும் என்பதை அல்லாஹ் நன்கு அறிவான். அவன் உள்ளத்தாலும் ஆன்மாவாலும் தூய்மையானவர்களிடமே அதனை அருளுகிறான். பின்னர் அல்லாஹ் தனது படைப்புகளிடையே வாழ்வாதாரத்தையும் மற்ற பலங்களையும் எவ்வாறு பிரித்துக் கொடுத்துள்ளான் என்பதைச் சுட்டிக்காட்டுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">قَسَمْنَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّعِيشَتَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span><br />\r\n<br />\r\n<br />\r\n(நாமே இவ்வுலக வாழ்க்கையில் அவர்களிடையே வாழ்வாதாரத்தைப் பங்கிட்டுள்ளோம்,)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِّيَتَّخِذَ</span> <span class=\"quran-arabic-font text-success\">بَعْضُهُم</span> <span class=\"quran-arabic-font text-success\">بَعْضاً</span> <span class=\"quran-arabic-font text-success\">سُخْرِيّاً</span><br />\r\n<br />\r\n<br />\r\n(அவர்களில் சிலர் மற்றவர்களைத் தங்கள் வேலையில் பயன்படுத்திக் கொள்ளும் பொருட்டு.) ஒருவருக்கு மற்றவர் தேவைப்படுகிறார் என்பதே இதன் பொருள்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَرَحْمَةُ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">مِّمَّا</span> <span class=\"quran-arabic-font text-success\">يَجْمَعُونَ</span><br />\r\n<br />\r\n<br />\r\n(ஆனால் உமது இறைவனின் அருள் அவர்கள் சேகரித்து வைத்திருப்பவற்றை விடச் சிறந்தது.) அதாவது, அல்லாஹ்வின் அருள் அவர்கள் வைத்திருக்கும் உலகச் செல்வங்களை விட மிகவும் மேலானது.<br />\r\n<br />\r\n<strong>செல்வம் என்பது இறைப் பொருத்தத்தின் அடையாளம் அல்ல</strong><br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْلاَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَكُونَ</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">أُمَّةً</span> <span class=\"quran-arabic-font text-success\">وَحِدَةً</span><br />\r\n<br />\r\n<br />\r\n(மனிதர்கள் அனைவரும் (செல்வத்திற்காக) ஒரே மாதிரியான நிராகரிப்பாளர்களாக ஆகிவிடுவார்கள் என்ற அச்சம் இல்லையென்றால்...) அதாவது, செல்வம் கிடைப்பதாலேயே அல்லாஹ் ஒருவரை நேசிக்கிறான் என்று மக்கள் தவறாக எண்ணி, செல்வத்திற்காக அனைவரும் நிராகரிப்பில் ஒன்றுபட்டு விடுவார்கள் என்ற நிலை இல்லையென்றால், நிராகரிப்பாளர்களுக்கு அவர்கள் கற்பனை செய்ய முடியாத அளவு உலக வசதிகளை நாம் வழங்கியிருப்போம்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">لِمَن</span> <span class=\"quran-arabic-font text-success\">يَكْفُرُ</span> <span class=\"quran-arabic-font text-success\">بِالرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">لِبُيُوتِهِمْ</span> <span class=\"quran-arabic-font text-success\">سُقُفاً</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">فِضَّةٍ</span> <span class=\"quran-arabic-font text-success\">وَمَعَارِجَ</span><br />\r\n<br />\r\n<br />\r\n(அளவற்ற அருளாளனை நிராகரிப்பவர்களுக்கு, அவர்களின் வீடுகளுக்கு வெள்ளி மேற்கூரைகளையும், வெள்ளிப் படிக்கட்டுகளையும் நாம் ஆக்கியிருப்போம்.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَلَيْهَا</span> <span class=\"quran-arabic-font text-success\">يَظْهَرُونَ</span><br />\r\n<br />\r\n<br />\r\n(அதன் மீது அவர்கள் ஏறுவார்கள்.) மேலும் அவர்களின் வீடுகளுக்கு வெள்ளி வாசல்கள், வெள்ளிச் சிம்மாசனங்கள் மற்றும் தங்க அலங்காரங்களையும் நாம் வழங்கியிருப்போம்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لَمَّا</span> <span class=\"quran-arabic-font text-success\">مَتَـعُ</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span><br />\r\n<br />\r\n<br />\r\n(ஆயினும், இவை அனைத்தும் இவ்வுலக வாழ்க்கையின் அற்ப இன்பமே தவிர வேறில்லை.) இவை அனைத்தும் அல்லாஹ்விடம் அற்பமானவை. நிராகரிப்பாளர்களின் நற்செயல்களுக்குரிய கூலியை அல்லாஹ் இவ்வுலகிலேயே சுகபோகங்களாக வழங்கிவிடுகிறான். அதனால் மறுமையில் அவர்களுக்கு நன்மைகள் எதுவும் இருக்காது.<br />\r\n<br />\r\n<br />\r\nநபியவர்கள் கூறினார்கள்: \"அல்லாஹ்விடம் இவ்வுலகிற்கு ஒரு கொசுவின் இறக்கை அளவு மதிப்பு இருந்திருக்குமானால், அவன் ஒரு நிராகரிப்பாளனுக்கு ஒரு மிடறு தண்ணீர் கூட கொடுத்திருக்க மாட்டான்\" (திர்மிதி).<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالاٌّخِرَةُ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">لِلْمُتَّقِينَ</span><br />\r\n<br />\r\n<br />\r\n(மறுமை உமது இறைவனிடம் இறையச்சம் உடையவர்களுக்கு மட்டுமே உரியது.) உமர் (ரழி) அவர்கள் நபியவர்களின் எளிய வாழ்வைக் கண்டு அழுதபோது, நபி (ஸல்) அவர்கள் கூறினார்கள்: \"அவர்களுக்கு இவ்வுலகம் இருப்பதும், நமக்கு மறுமை இருப்பதும் உமக்கு மகிழ்ச்சியளிக்கவில்லையா?\"<br />\r\n<br />\r\n<strong>அர்-ரஹ்மானின் நினைவை விட்டு விலகுபவருக்கு ஷைத்தானே தோழன்</strong><br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَعْشُ</span><br />\r\n<br />\r\n<br />\r\n(யார் குருட்டுத்தனமாக விலகுகிறாரோ) அதாவது, யார் வேண்டுமென்றே புறக்கணிக்கிறாரோ,<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">ذِكْرِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span><br />\r\n<br />\r\n<br />\r\n(அளவற்ற அருளாளனின் நினைவை விட்டு,) 'அல்-அஷா' என்பது பார்வைக் குறைபாட்டைக் குறிக்கும். இங்கு இதன் பொருள் அகப்பார்வை பலவீனமடைவதாகும்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نُقَيِّضْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">شَيْطَاناً</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">قَرِينٌ</span><br />\r\n<br />\r\n<br />\r\n(அவருக்கு நாம் ஒரு ஷைத்தானைத் தோழனாக நியமிக்கிறோம்.) இது அல்லாஹ்வின் மற்ற வசனங்களைப் போன்றது.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَيَصُدُّونَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">السَّبِيلِ</span> <span class=\"quran-arabic-font text-success\">وَيَحْسَبُونَ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُم</span> <span class=\"quran-arabic-font text-success\">مُّهْتَدُونَ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">جَآءَنَا</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக அந்த ஷைத்தான்கள் அவர்களை நேர்வழியை விட்டுத் தடுப்பார்கள், இருப்பினும் அவர்கள் தாங்கள் நேர்வழியில் இருப்பதாகவே எண்ணிக் கொள்வார்கள். இறுதியில் அவன் நம்மிடம் வரும்போது...) அந்த நபர் தன் தோழனான ஷைத்தானைப் பார்த்து வருந்துவான்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">يلَيْتَ</span> <span class=\"quran-arabic-font text-success\">بَيْنِي</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَكَ</span> <span class=\"quran-arabic-font text-success\">بُعْدَ</span> <span class=\"quran-arabic-font text-success\">الْمَشْرِقَيْنِ</span> <span class=\"quran-arabic-font text-success\">فَبِئْسَ</span> <span class=\"quran-arabic-font text-success\">الْقَرِينُ</span><br />\r\n<br />\r\n<br />\r\n(அவன் கூறுவான்: \"எனக்கும் உனக்கும் இடையே இரண்டு கிழக்குகளுக்கு இடையிலான தொலைவு இருந்திருக்கக் கூடாதா! நீ மிகவும் கெட்ட தோழன்!\") பின்னர் அல்லாஹ் கூறுவான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَن</span> <span class=\"quran-arabic-font text-success\">يَنفَعَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">إِذ</span> <span class=\"quran-arabic-font text-success\">ظَّلَمْتُمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">مُشْتَرِكُونَ</span><br />\r\n<br />\r\n<br />\r\n(நீங்கள் அநீதி இழைத்ததால், இன்று நீங்கள் தண்டனையில் கூட்டாளிகளாக இருப்பது உங்களுக்கு எந்தப் பயனும் தராது.) அதாவது, நரகத்தில் நீங்கள் ஒன்றாக இருப்பது உங்கள் வேதனையைக் குறைக்காது.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَأَنتَ</span> <span class=\"quran-arabic-font text-success\">تُسْمِعُ</span> <span class=\"quran-arabic-font text-success\">الصُّمَّ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">تَهْدِى</span> <span class=\"quran-arabic-font text-success\">الْعُمْىَ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ضَلَـلٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span><br />\r\n<br />\r\n<br />\r\n(செவிடர்களை நீர் கேட்கச் செய்ய முடியுமா? அல்லது குருடர்களையும் தெளிவான வழிகேட்டில் இருப்பவர்களையும் நீர் நேர்வழிப்படுத்த முடியுமா?) நபியே! உமது கடமை செய்தியை எட்டவைப்பதே தவிர அவர்களை நேர்வழிப்படுத்துவது அல்ல.<br />\r\n<br />\r\n<strong>நபியின் எதிரிகள் மீது அல்லாஹ்வின் பழிவாங்கல் நிச்சயமாக நிகழும்</strong><br />\r\n<br />\r\n<br />\r\nமேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِمَّا</span> <span class=\"quran-arabic-font text-success\">نَذْهَبَنَّ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّا</span> <span class=\"quran-arabic-font text-success\">مِنْهُم</span> <span class=\"quran-arabic-font text-success\">مُّنتَقِمُونَ</span><br />\r\n<br />\r\n<br />\r\n(உம்மை நாம் மரணிக்கச் செய்தாலும், நிச்சயமாக நாம் அவர்களைப் பழிவாங்குவோம்.) அதாவது, அவர்கள் தண்டிக்கப்படுவது உறுதி.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">نُرِيَنَّكَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">وَعَدْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">مُّقْتَدِرُونَ</span><br />\r\n<br />\r\n<br />\r\n(அல்லது நாம் அவர்களுக்கு அச்சுறுத்தியதை உமக்குக் காட்டினாலும், நாம் அவர்கள் மீது முழு ஆற்றல் உடையவர்கள்.) அல்லாஹ் தனது தூதரை மரணிக்கச் செய்வதற்கு முன், அவருடைய எதிரிகள் தாழ்த்தப்படுவதையும் அவருக்கு வெற்றியையும் வழங்கினான்.<br />\r\n<br />\r\n<strong>குர்ஆனை உறுதியாகப் பற்றுதல்</strong><br />\r\n<br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاسْتَمْسِكْ</span> <span class=\"quran-arabic-font text-success\">بِالَّذِى</span> <span class=\"quran-arabic-font text-success\">أُوحِىَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">صِرَطٍ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقِيمٍ</span><br />\r\n<br />\r\n<br />\r\n(ஆகவே, உமக்கு வஹீயாக அருளப்படுவதை நீர் உறுதியாகப் பற்றிப் பிடித்துக் கொள்ளும். நிச்சயமாக நீர் நேரான பாதையில் இருக்கிறீர்.) குர்ஆனை உறுதியாகப் பிடித்துக் கொள்ளுமாறு இது ஏவுகிறது.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَذِكْرٌ</span> <span class=\"quran-arabic-font text-success\">لَّكَ</span> <span class=\"quran-arabic-font text-success\">وَلِقَوْمِكَ</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக இது உமக்கும் உமது மக்களுக்கும் ஒரு கண்ணியமாகும்.) ஏனெனில் இது அவர்களின் மொழியில் அருளப்பட்டது.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَسَوْفَ</span> <span class=\"quran-arabic-font text-success\">تُسْـَلُونَ</span><br />\r\n<br />\r\n<br />\r\n(விரைவில் நீங்கள் விசாரிக்கப்படுவீர்கள்.) இந்த குர்ஆனை எவ்வாறு பின்பற்றினீர்கள் என்பது குறித்து நீங்கள் கேட்கப்படுவீர்கள்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاسْئلْ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِكَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رُّسُلِنَآ</span> <span class=\"quran-arabic-font text-success\">أَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">ءَالِهَةً</span> <span class=\"quran-arabic-font text-success\">يُعْبَدُونَ</span><br />\r\n<br />\r\n<br />\r\n(உமக்கு முன்னர் நாம் அனுப்பிய தூதர்களிடம் கேளும்: \"அளவற்ற அருளாளனைத் தவிர வணங்கப்படும் தெய்வங்களை நாம் எப்போதாவது நியமித்தோமா?\") அனைத்து தூதர்களும் அல்லாஹ் ஒருவனையே வணங்குமாறு அழைப்பு விடுத்தனர் என்பதே இதன் பொருள்.<br />\r\n<br />\r\n<strong>மூஸா (அலை) அவர்கள் ஃபிர்அவ்னிடம் அனுப்பப்பட்டது</strong><br />\r\n<br />\r\n<br />\r\nஅல்லாஹ் தன் தூதர் மூஸா (அலை) அவர்களை ஃபிர்அவ்னிடம் பல அத்தாட்சிகளுடன் அனுப்பினான். ஆனால் அவர்கள் ஏளனம் செய்தனர். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">نُرِيِهِم</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">ءَايَةٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هِىَ</span> <span class=\"quran-arabic-font text-success\">أَكْبَرُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أُخْتِهَا</span><br />\r\n<br />\r\n<br />\r\n(நாம் அவர்களுக்குக் காட்டிய ஒவ்வோர் அத்தாட்சியும் அதன் முந்தையதை விடப் பெரியதாகவே இருந்தது.) இருப்பினும் அவர்கள் திருந்தவில்லை. துன்பம் வரும்போதெல்லாம், \"அறிஞரே! (சூனியக்காரரே!) உமது இறைவனிடம் எங்களுக்காகப் பிரார்த்தனை செய்யும்\" என்று மூஸா (அலை) அவர்களிடம் கெஞ்சினர். ஆனால் துன்பம் நீங்கியதும் வாக்குறுதியை மீறினர்.<br />\r\n<br />\r\n<strong>ஃபிர்அவ்ன் தன் மக்களிடம் ஆற்றிய உரையும், அவனுக்குக் கிடைத்த தண்டனையும்</strong><br />\r\n<br />\r\n<br />\r\nஃபிர்அவ்ன் தன் மக்களின் முன் மார்தட்டினான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">مُلْكُ</span> <span class=\"quran-arabic-font text-success\">مِصْرَ</span> <span class=\"quran-arabic-font text-success\">وَهَـذِهِ</span> <span class=\"quran-arabic-font text-success\">الاٌّنْهَـرُ</span> <span class=\"quran-arabic-font text-success\">تَجْرِى</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">تَحْتِى</span><br />\r\n<br />\r\n<br />\r\n(இந்த எகிப்தின் ஆட்சி எனக்குரியதல்லவா? எனக்குக் கீழே ஆறுகள் ஓடவில்லையா?) அவன் மூஸா (அலை) அவர்களைப் பலவீனமானவர் என்றும், சரியாகப் பேசத் தெரியாதவர் என்றும் இழிவுபடுத்தினான்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاسْتَخَفَّ</span> <span class=\"quran-arabic-font text-success\">قَوْمَهُ</span> <span class=\"quran-arabic-font text-success\">فَأَطَاعُوهُ</span><br />\r\n<br />\r\n<br />\r\n(இவ்வாறு அவன் தன் மக்களை முட்டாளாக்கினான்; அவர்களும் அவனுக்குக் கீழ்ப்படிந்தார்கள்.) அவர்கள் பாவம் செய்பவர்களாக இருந்ததால் அவனுக்குக் கீழ்ப்படிந்தனர்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلَمَّآ</span> <span class=\"quran-arabic-font text-success\">ءَاسَفُونَا</span> <span class=\"quran-arabic-font text-success\">انتَقَمْنَا</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">فَأَغْرَقْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْمَعِينَ</span><br />\r\n<br />\r\n<br />\r\n(அவர்கள் நம்மைக் கோபப்படுத்தியபோது, நாம் அவர்களைப் பழிவாங்கி அனைவரையும் மூழ்கடித்தோம்.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَجَعَلْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">سَلَفاً</span> <span class=\"quran-arabic-font text-success\">وَمَثَلاً</span> <span class=\"quran-arabic-font text-success\">لِّلاٌّخِرِينَ</span><br />\r\n<br />\r\n<br />\r\n(மேலும், நாம் அவர்களை முற்கால முன்னுதாரணமாகவும், பிற்காலத்தவருக்கு ஓர் எடுத்துக்காட்டாகவும் ஆக்கினோம்.)<br />\r\n<br />\r\n<strong>மர்யமுடைய மகனை குறைஷிகள் இழிவாகக் கருதியதும், அல்லாஹ்விடம் அவருடைய தகுதியும்</strong><br />\r\n<br />\r\n<br />\r\nகுறைஷிகள் நபியவர்களிடம் விதண்டாவாதம் செய்தனர்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَمَّا</span> <span class=\"quran-arabic-font text-success\">ضُرِبَ</span> <span class=\"quran-arabic-font text-success\">ابْنُ</span> <span class=\"quran-arabic-font text-success\">مَرْيَمَ</span> <span class=\"quran-arabic-font text-success\">مَثَلاً</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">قَوْمُكَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">يَصِدُّونَ</span><br />\r\n<br />\r\n<br />\r\n(மர்யமுடைய மகன் ஓர் உதாரணமாகக் கூறப்பட்டபோது, உமது மக்கள் ஆரவாரம் செய்கின்றனர்.) நபியவர்கள் \"நீங்களும் நீங்கள் வணங்குபவையும் நரகத்தின் எரிபொருள்கள்\" (<a href=\"qurandisp.php?sura=21&ayah=98\" class=\"link\">21:98</a>) என்ற வசனத்தை ஓதியபோது, குறைஷிகள் \"அப்படியானால் கிறிஸ்தவர்கள் வணங்கும் ஈஸாவும் நரகிற்குச் செல்வாரா?\" என்று தர்க்கம் செய்தனர்.<br />\r\n<br />\r\n<br />\r\nஅல்லாஹ் இதற்குப் பதிலளிக்கிறான்: ஈஸா (அலை) அவர்கள் அல்லாஹ்வின் கண்ணியமிக்க அடியார். குறைஷிகள் விதண்டாவாதத்திற்காகவே இதனைப் பேசுகின்றனர்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَبْدٌ</span> <span class=\"quran-arabic-font text-success\">أَنْعَمْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">وَجَعَلْنَـهُ</span> <span class=\"quran-arabic-font text-success\">مَثَلاً</span> <span class=\"quran-arabic-font text-success\">لِّبَنِى</span> <span class=\"quran-arabic-font text-success\">إِسْرَءِيلَ</span><br />\r\n<br />\r\n<br />\r\n(அவர் ஓர் அடியாரே தவிர வேறில்லை. நாம் அவர் மீது நமது அருளைப் பொழிந்தோம், மேலும் இஸ்ரவேலின் சந்ததியினருக்கு அவரை ஓர் உதாரணமாக ஆக்கினோம்.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">نَشَآءُ</span> <span class=\"quran-arabic-font text-success\">لَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِنكُمْ</span> <span class=\"quran-arabic-font text-success\">مَّلَـئِكَةً</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">يَخْلُفُونَ</span><br />\r\n<br />\r\n<br />\r\n(மேலும், நாம் நாடியிருந்தால் உங்களுக்குப் பதிலாக பூமியில் வானவர்களை நாம் படைத்திருப்போம்.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَعِلْمٌ</span> <span class=\"quran-arabic-font text-success\">لِّلسَّاعَةِ</span><br />\r\n<br />\r\n<br />\r\n(மேலும் நிச்சயமாக அவர் (ஈஸா) மறுமை நாளுக்கான ஓர் அடையாளமாவார்.) அவர் உலகிற்கு மீண்டும் இறங்குவது இறுதி நாள் நெருங்குவதைக் குறிக்கும்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">تَمْتَرُنَّ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">وَاتَّبِعُونِ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">صِرَطٌ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقِيمٌ</span><br />\r\n<br />\r\n<br />\r\n(ஆகவே, அது குறித்து சந்தேகம் கொள்ளாதீர்கள். மேலும் என்னைப் பின்பற்றுங்கள்! இதுவே நேரான வழியாகும்.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">ءَأَالِهَتُنَا</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span><br />\r\n<br />\r\n<br />\r\n(அவர்கள் கேட்கிறார்கள்: \"எங்கள் தெய்வங்கள் சிறந்தவையா அல்லது அவரா?\")<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">ضَرَبُوهُ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">جَدَلاَ</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">خَصِمُونَ</span><br />\r\n<br />\r\n<br />\r\n(அவர்கள் இந்த உதாரணத்தை உமக்குக் கூறியது தர்க்கத்திற்காகவே தவிர வேறில்லை. இல்லை! மாறாக, அவர்கள் சண்டையிடும் மக்களாவர்.)<br />\r\n<br />\r\n<br />\r\nஈஸா (அலை) அவர்களும் \"அல்லாஹ்வே என் இறைவனும் உங்கள் இறைவனுமாவான்; அவனையே வணங்குங்கள்\" என்றே கூறினார்கள்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاخْتَلَفَ</span> <span class=\"quran-arabic-font text-success\">الاٌّحْزَابُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَيْنِهِمْ</span> <span class=\"quran-arabic-font text-success\">فَوَيْلٌ</span> <span class=\"quran-arabic-font text-success\">لِّلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ظَلَمُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عَذَابِ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">أَلِيمٍ</span><br />\r\n<br />\r\n<br />\r\n(ஆனால் அவர்களிடையே இருந்த பிரிவினர் கருத்து வேறுபாடு கொண்டனர். ஆகவே அநீதி இழைத்தவர்களுக்கு வேதனையான தண்டனை உண்டு.)<br />\r\n<br />\r\n<strong>மறுமை நாள் திடீரென வரும்; நண்பர்களிடையே பகைமை உண்டாகும்</strong><br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَأْتِيَهُمْ</span> <span class=\"quran-arabic-font text-success\">بَغْتَةً</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَشْعُرُونَ</span><br />\r\n<br />\r\n<br />\r\n(அவர்கள் உணராத நிலையில் திடீரென அவர்களிடம் மறுமை நாள் வருவதை மட்டுமே அவர்கள் எதிர்பார்க்கிறார்களா?)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الاٌّخِلاَءُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">بَعْضُهُمْ</span> <span class=\"quran-arabic-font text-success\">لِبَعْضٍ</span> <span class=\"quran-arabic-font text-success\">عَدُوٌّ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الْمُتَّقِينَ</span><br />\r\n<br />\r\n<br />\r\n(இறையச்சம் உடையவர்களைத் தவிர, மற்ற நண்பர்கள் அந்நாளில் ஒருவருக்கொருவர் எதிரிகளாகி விடுவார்கள்.) அல்லாஹ்வுக்காக ஏற்பட்ட நட்பு மட்டுமே அன்று நீடிக்கும்.<br />\r\n<br />\r\n<strong>இறையச்சம் உடையவர்களுக்கு நற்செய்தியும், சுவர்க்கமும்</strong><br />\r\n<br />\r\n<br />\r\nஇறையச்சம் உடையவர்களுக்குக் கூறப்படும்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يعِبَادِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">خَوْفٌ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمُ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَحْزَنُونَ</span><br />\r\n<br />\r\n<br />\r\n(என் அடியார்களே! இந்நாளில் உங்களுக்கு எந்தப் பயமும் இல்லை, நீங்கள் கவலைப்படவும் மாட்டீர்கள்.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">بِـَايَـتِنَا</span> <span class=\"quran-arabic-font text-success\">وَكَانُواْ</span> <span class=\"quran-arabic-font text-success\">مُسْلِمِينَ</span><br />\r\n<br />\r\n<br />\r\n(யார் நமது வசனங்களை நம்பி, முற்றிலும் கீழ்ப்படிந்து (முஸ்லிம்களாக) இருந்தார்களோ அவர்களுக்கு இது கூறப்படும்.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ادْخُلُواْ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةَ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَزْوَجُكُمْ</span> <span class=\"quran-arabic-font text-success\">تُحْبَرُونَ</span><br />\r\n<br />\r\n<br />\r\n(நீங்களும் உங்கள் இணையர்களும் மகிழ்ச்சியுடன் சுவர்க்கத்தில் நுழையுங்கள்.)<br />\r\n<br />\r\n<br />\r\nஅங்கு அவர்களுக்குத் தங்கத் தட்டுகளும் கோப்பைகளும் கொண்டு வரப்படும்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَفِيهَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَشْتَهِي</span> <span class=\"quran-arabic-font text-success\">الْأَنْفُسُ</span> <span class=\"quran-arabic-font text-success\">وَتَلَذُّ</span> <span class=\"quran-arabic-font text-success\">الاٌّعْيُنُ</span> <span class=\"quran-arabic-font text-success\">وَأَنتُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">خَـلِدُونَ</span><br />\r\n<br />\r\n<br />\r\n(அங்கு மனங்கள் விரும்புவதும் கண்கள் கண்டு மகிழ்வதும் இருக்கும். நீங்கள் அங்கு என்றென்றும் தங்கியிருப்பீர்கள்.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتِلْكَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةُ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">أُورِثْتُمُوهَا</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span><br />\r\n<br />\r\n<br />\r\n(நீங்கள் செய்து கொண்டிருந்த நற்செயல்களின் காரணமாகவே இந்தச் சுவர்க்கத்திற்கு நீங்கள் வாரிசாக்கப்பட்டுள்ளீர்கள்.)<br />\r\n<br />\r\n<strong>குற்றவாளிகளுக்குக் காத்திருக்கும் தண்டனை</strong><br />\r\n<br />\r\n<br />\r\nஇறையச்சம் உடையவர்களின் நிலையைத் தொடர்ந்து குற்றவாளிகளின் நிலை விவரிக்கப்படுகிறது.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمِينَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">عَذَابِ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">خَـلِدُونَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُفَتَّرُ</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">مُبْلِسُونَ</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக குற்றவாளிகள் நரக வேதனையில் என்றென்றும் தங்கியிருப்பார்கள். அது அவர்களுக்கு ஒருபோதும் இலேசாக்கப்பட மாட்டாது. அவர்கள் அங்கு விரக்தியுற்ற நிலையில் இருப்பார்கள்.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">ظَلَمْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلَـكِن</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الظَّـلِمِينَ</span><br />\r\n<br />\r\n<br />\r\n(நாம் அவர்களுக்கு அநீதி இழைக்கவில்லை, ஆனால் அவர்களே அநீதி இழைத்தவர்களாக இருந்தார்கள்.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَنَادَوْاْ</span> <span class=\"quran-arabic-font text-success\">يَامَـلِكُ</span> <span class=\"quran-arabic-font text-success\">لِيَقْضِ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span><br />\r\n<br />\r\n<br />\r\n(அவர்கள் நரகக் காவலரான 'மாலிக்'கை அழைத்து, \"உமது இறைவன் எங்களை முடித்துவிடட்டும்\" என்று கதறுவார்கள்.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">مَّـكِثُونَ</span><br />\r\n<br />\r\n<br />\r\n(அதற்கு அவர், \"நிச்சயமாக நீங்கள் இங்கேயே தங்க வேண்டியவர்கள்\" என்று கூறுவார்.)<br />\r\n<br />\r\n<br />\r\nஉண்மை உங்களிடம் வந்தபோது நீங்கள் அதனை வெறுத்ததே இதற்குக் காரணம்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">أَبْرَمُواْ</span> <span class=\"quran-arabic-font text-success\">أَمْراً</span> <span class=\"quran-arabic-font text-success\">فَإِنَّا</span> <span class=\"quran-arabic-font text-success\">مُبْرِمُونَ</span><br />\r\n<br />\r\n<br />\r\n(அல்லது அவர்கள் ஏதேனும் சூழ்ச்சி செய்கிறார்களா? நாமும் சூழ்ச்சி செய்கிறோம்.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">يَحْسَبُونَ</span> <span class=\"quran-arabic-font text-success\">أَنَّا</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">نَسْمَعُ</span> <span class=\"quran-arabic-font text-success\">سِرَّهُمْ</span> <span class=\"quran-arabic-font text-success\">وَنَجْوَهُم</span> <span class=\"quran-arabic-font text-success\">بَلَى</span> <span class=\"quran-arabic-font text-success\">وَرُسُلُنَا</span> <span class=\"quran-arabic-font text-success\">لَدَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">يَكْتُبُونَ</span><br />\r\n<br />\r\n<br />\r\n(அவர்களுடைய இரகசியங்களையும் ஆலோசனைகளையும் நாம் கேட்பதில்லை என்று அவர்கள் நினைக்கிறார்களா? ஆம், நாம் கேட்கிறோம்; நம் தூதர்கள் (வானவர்கள்) அவற்றை உடனுக்குடன் பதிவு செய்கிறார்கள்.)<br />\r\n<br />\r\n<strong>அல்லாஹ்வுக்குச் சந்ததி இல்லை</strong><br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">لِلرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">وَلَدٌ</span> <span class=\"quran-arabic-font text-success\">فَأَنَاْ</span> <span class=\"quran-arabic-font text-success\">أَوَّلُ</span> <span class=\"quran-arabic-font text-success\">الْعَـبِدِينَ</span><br />\r\n<br />\r\n<br />\r\n(நபியே! நீர் கூறும்: \"அளவற்ற அருளாளனுக்கு ஒரு மகன் இருந்திருப்பின், அவனை வணங்குவோரில் நானே முதன்மையானவனாக இருந்திருப்பேன்.\") அதாவது, அல்லாஹ்வுக்குச் சந்ததி இருப்பது சாத்தியமே இல்லை.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سُبْحَـنَ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">الْعَرْشِ</span> <span class=\"quran-arabic-font text-success\">عَمَّا</span> <span class=\"quran-arabic-font text-success\">يَصِفُونَ</span><br />\r\n<br />\r\n<br />\r\n(வானங்கள் மற்றும் பூமியின் இறைவன், அர்ஷின் இறைவன் தூய்மையானவன்! அவர்கள் வர்ணிக்கும் பண்புகளை விட்டு அவன் உயர்ந்தவன்.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَذَرْهُمْ</span> <span class=\"quran-arabic-font text-success\">يَخُوضُواْ</span> <span class=\"quran-arabic-font text-success\">وَيَلْعَبُواْ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يُلَـقُواْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَهُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يُوعَدُونَ</span><br />\r\n<br />\r\n<br />\r\n(ஆகவே அவர்களை விட்டுவிடும்; அவர்கள் வாக்களிக்கப்பட்ட நாளைச் சந்திக்கும் வரை வீண் தர்க்கத்திலும் விளையாட்டிலும் மூழ்கிக் கிடக்கட்டும்.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">السَّمآءِ</span> <span class=\"quran-arabic-font text-success\">إِلَـهٌ</span> <span class=\"quran-arabic-font text-success\">وَفِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">إِلَـهٌ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْحَكِيمُ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيمُ</span><br />\r\n<br />\r\n<br />\r\n(வானத்திலும் இறைவனாக இருப்பவன் அவனே; பூமியிலும் இறைவனாக இருப்பவன் அவனே. அவன் ஞானமிக்கவன்; எல்லாம் அறிந்தவன்.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتَبَارَكَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مُلْكُ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمَا</span> <span class=\"quran-arabic-font text-success\">وَعِندَهُ</span> <span class=\"quran-arabic-font text-success\">عِلْمُ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةِ</span> <span class=\"quran-arabic-font text-success\">وَإِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">تُرْجَعُونَ</span><br />\r\n<br />\r\n<br />\r\n(வானங்கள் மற்றும் பூமியின் ஆட்சியும், அவற்றுக்கு இடையே உள்ள அனைத்தும் எவனுக்குச் சொந்தமோ அவன் பாக்கியம் மிக்கவன். அவனிடமே மறுமை பற்றிய அறிவு உள்ளது. அவனிடமே நீங்கள் அனைவரும் கொண்டு வரப்படுவீர்கள்.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَمْلِكُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَدْعُونَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِهِ</span> <span class=\"quran-arabic-font text-success\">الشَّفَـعَةَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">شَهِدَ</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ</span><br />\r\n<br />\r\n<br />\r\n(அல்லாஹ்வையன்றி அவர்கள் யாரை அழைக்கிறார்களோ அவர்களுக்குப் பரிந்துரை செய்யும் அதிகாரம் இல்லை; சத்தியத்தை அறிந்து சாட்சி சொன்னவர்களைத் தவிர.)<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَئِن</span> <span class=\"quran-arabic-font text-success\">سَأَلْتَهُم</span> <span class=\"quran-arabic-font text-success\">مَّنْ</span> <span class=\"quran-arabic-font text-success\">خَلَقَهُمْ</span> <span class=\"quran-arabic-font text-success\">لَيَقُولُنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">فَأَنَّى</span> <span class=\"quran-arabic-font text-success\">يُؤْفَكُونَ</span><br />\r\n<br />\r\n<br />\r\n(அவர்களைப் படைத்தது யார் என்று நீர் கேட்டால், \"அல்லாஹ்\" என்றே கூறுவார்கள். அவ்வாறிருக்க அவர்கள் எங்கு திசை திருப்பப்படுகிறார்கள்?)<br />\r\n<br />\r\n<strong>நபியின் முறையீடு</strong><br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقِيلِهِ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَـؤُلاَءِ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span><br />\r\n<br />\r\n<br />\r\n(நபியின் முறையீடு: \"என் இறைவா! நிச்சயமாக இவர்கள் நம்பிக்கை கொள்ளாத மக்களாக இருக்கிறார்கள்.\")<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاصْفَحْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ</span> <span class=\"quran-arabic-font text-success\">وَقُلْ</span> <span class=\"quran-arabic-font text-success\">سَلَامٌ</span> <span class=\"quran-arabic-font text-success\">فَسَوْفَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ</span><br />\r\n<br />\r\n<br />\r\n(ஆகவே நீர் அவர்களைப் புறக்கணித்துவிட்டு \"ஸலாம்\" (சாந்தி உண்டாகட்டும்) என்று கூறும்; விரைவில் அவர்கள் அறிந்து கொள்வார்கள்.) இது அவர்களுக்குரிய எச்சரிக்கையாகும். இது, ஜிஹாத் (புனிதப் போர்) கடமையாக்கப்படுவதற்கு முன்னர் அருளப்பட்டதாகும். பின்னர் அல்லாஹ் அவர்களை எதிர்த்துப் போரிடுமாறு கட்டளையிட்டான்; நபியவர்களுக்குப் பின்னர் வெற்றி கிடைத்தது, மக்கள் திரள் திரளாக இஸ்லாத்தில் இணைந்தனர். அல்லாஹ்வே மிக அறிந்தவன். இத்துடன் ஸூரத்துல் அஸ்-ஸுக்ருஃபின் தஃப்ஸீர் நிறைவு பெற்றது.<br />\r\n<br />\r\n<br />\r\n<br />","text":"بِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\r\n\n\r\n\n\r\nحـم - تَنزِيلُ الْكِتَـبِ مِنَ اللَّهِ الْعَزِيزِ الْعَلِيمِ\n\r\n\n\r\n\n\r\n(ஹா-மீம். தெளிவான இவ்வேதத்தின் மீது சத்தியமாக.) இதன் பொருள், இப் புத்தகம் சொல்லிலும் கருத்திலும் மிகத் தெளிவானது. ஏனெனில் இது அரபு மொழியில் அருளப்பட்டது. மக்களிடையே கருத்துப் பரிமாற்றம் செய்வதற்கு அரபு மொழியே மிகவும் ஆற்றல்மிக்க மொழியாகும். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n\n\r\nإِنَّا جَعَلْنَـهُ\n\r\n\n\r\n\n\r\n(நிச்சயமாக நாம் அதனை ஆக்கினோம்) அதாவது, இதனை நாம் அருளினோம்,\n\r\n\n\r\n\n\r\nقُرْءَاناً عَرَبِيّاً\n\r\n\n\r\n\n\r\n(அரபி மொழியிலான குர்ஆனாக) அதாவது, அரபு மொழியில், தெளிவானதாகவும் அழகானதாகவும்;\n\r\n\n\r\n\n\r\nلَعَلَّكُمْ تَعْقِلُونَ\n\r\n\n\r\n\n\r\n(நீங்கள் விளங்கிக்கொள்வதற்காக.) அதாவது, நீங்கள் இதனைப் புரிந்து கொண்டு இதன் கருத்துகளைச் சிந்திப்பதற்காக. இது இந்த வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\n\n\r\nبِلِسَانٍ عَرَبِىٍّ مُّبِينٍ\n\r\n\n\r\n\n\r\n(தெளிவான அரபி மொழியில்.) (26:195)\n\r\n\n\r\n\n\r\nوَإِنَّهُ فِى أُمِّ الْكِتَـبِ لَدَيْنَا لَعَلِىٌّ حَكِيمٌ\n\r\n\n\r\n\n\r\n(மேலும் நிச்சயமாக இது நம்மிடமுள்ள மூல நூலில் இருக்கிறது; மெய்யாகவே இது மிகவும் உயர்ந்ததும், ஞானம் மிக்கதுமாகும்.) இது வானுலகில் உள்ள வானவர்களிடையே குர்ஆனுக்கு இருக்கும் உயர்ந்த அந்தஸ்தை விளக்குகிறது. பூமியிலுள்ள மக்கள் இதனை மதித்து, கண்ணியப்படுத்தி, இதற்குக் கீழ்ப்படிவதற்காக இவ்வாறு கூறப்படுகிறது.\n\r\n\n\r\n\n\r\nوَأَنَّهُ\n\r\n\n\r\n\n\r\n(மேலும் நிச்சயமாக இது) அதாவது, இக்குர்ஆன்,\n\r\n\n\r\n\n\r\nفِى أُمِّ الْكِتَـبِ\n\r\n\n\r\n\n\r\n(மூல நூலில் இருக்கிறது) அதாவது, அல்-லவ்ஹுல் மஹ்ஃபூல் (பாதுகாக்கப்பட்ட பலகை). இது இப்னு அப்பாஸ் (ரழி) மற்றும் முஜாஹித் ஆகியோரின் கருத்தாகும்.\n\r\n\n\r\n\n\r\nلَدَيْنَآ\n\r\n\n\r\n\n\r\n(நம்மிடத்தில்,) அதாவது, நமது முன்னிலையில். இது கத்தாதா (ரஹ்) மற்றும் பலரின் கருத்தாகும்.\n\r\n\n\r\n\n\r\nلَّعَلِّى\n\r\n\n\r\n\n\r\n(நிச்சயமாக உயர்ந்தது) அதாவது, கண்ணியமும் சிறப்பும் மிக்க ஒரு நிலையில் இருக்கிறது. இது கத்தாதாவின் (ரஹ்) கருத்தாகும்.\n\r\n\n\r\n\n\r\nحَكِيمٌ\n\r\n\n\r\n\n\r\n(ஞானம் மிக்கது.) அதாவது, எந்தக் குழப்பமும் குறைபாடும் இல்லாத தெளிவானது. இவை அனைத்தும் அதன் மகத்துவத்தைக் காட்டுகின்றன. அல்லாஹ் மற்றோரிடத்தில் கூறுவது போல:\n\r\n\n\r\n\n\r\nإِنَّهُ لَقُرْءَانٌ كَرِيمٌ - فِى كِتَـبٍ مَّكْنُونٍ - لاَّ يَمَسُّهُ إِلاَّ الْمُطَهَّرُونَ - تَنزِيلٌ مِّن رَّبِّ الْعَـلَمِينَ\n\r\n\n\r\n\n\r\n(நிச்சயமாக இது கண்ணியமிக்க ஓதலாகும் (குர்ஆன்). நன்கு பாதுகாக்கப்பட்ட ஒரு புத்தகத்தில் இது இருக்கிறது. தூய்மையானவர்களைத் தவிர வேறு எவரும் இதனைத் தொடமாட்டார்கள். இது அகிலங்களின் இறைவனிடமிருந்து அருளப்பட்ட ஒரு வஹீ (இறைச்செய்தி).) (56:77-80)\n\r\n\n\r\n\n\r\nكَلاَّ إِنَّهَا تَذْكِرَةٌ فَمَن شَآءَ ذَكَرَهُ فَى صُحُفٍ مُّكَرَّمَةٍ مَّرْفُوعَةٍ مُّطَهَّرَةٍ بِأَيْدِى سَفَرَةٍ كِرَامٍ بَرَرَةٍ\n\r\n\n\r\n\n\r\n(நிச்சயமாக இது ஒரு நல்லுரையாகும். ஆகவே, யார் விரும்புகிறாரோ அவர் இதனை நினைவில் கொள்ளட்டும். (இது) கண்ணியமிக்க, உயர்ந்த, தூய்மையான ஏடுகளில் உள்ளது. கண்ணியமான, கீழ்ப்படிதலுள்ள வானவர்களின் கைகளால் எழுதப்பட்டது.) (80:11-16)\n\r\n\n\r\n\n\r\nأَفَنَضْرِبُ عَنكُمُ الذِّكْرَ صَفْحاً أَن كُنتُمْ قَوْماً مُّسْرِفِينَ\n\r\n\n\r\n\n\r\n(நீங்கள் வரம்பு மீறிய மக்களாக இருப்பதற்காக, இந்த நல்லுரையை (குர்ஆனை) உங்களிடமிருந்து நாம் முற்றாக விலக்கி விடுவோமா?) இதன் பொருள்: 'உங்களுக்குக் கட்டளையிடப்பட்டதை நீங்கள் செய்யாதபோது, உங்களைத் தண்டிக்காமல் விட்டுவிடுவோம் என்று கருதுகிறீர்களா?' என்பதாகும். இது இப்னு அப்பாஸ் (ரழி), அபூ ஸாலிஹ், முஜாஹித் மற்றும் அஸ்-ஸுத்தி ஆகியோரின் கருத்தாகும். இக்கருத்தையே இப்னு ஜரீர் (ரஹ்) அவர்களும் விரும்புகிறார்கள்.\n\r\n\n\r\n\n\r\nأَفَنَضْرِبُ عَنكُمُ الذِّكْرَ صَفْحاً\n\r\n\n\r\n\n\r\n(இந்த நல்லுரையை (குர்ஆனை) உங்களிடமிருந்து நாம் முற்றாக விலக்கி விடுவோமா?) கத்தாதா (ரஹ்) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் மீது சத்தியமாக! இந்த உம்மத்தின் ஆரம்ப காலத்தவர்கள் குர்ஆனை நிராகரித்தபோது, அல்லாஹ் அதனைத் திரும்பப் பெற்றிருந்தால் அவர்கள் அழிந்திருப்பார்கள். ஆனால் அல்லாஹ் தனது பெருங்கருணையால் தொடர்ந்து குர்ஆனை அனுப்பி, சுமார் இருபது ஆண்டுகள் அவர்களை அதன் பக்கம் அழைத்தான்.\" கத்தாதா (ரஹ்) அவர்கள் கூறியது மிகவும் சிறப்பானது. மனிதர்கள் குர்ஆனைப் புறக்கணித்த போதிலும், அல்லாஹ் தன் அடியார்கள் மீது கொண்ட கருணையால் அவர்களை சத்தியத்தின் பக்கமும், ஞானம் நிறைந்த நினைவூட்டலின் பக்கமும் அழைப்பதை நிறுத்தவில்லை என்பதே இதன் சாராம்சம். நேர்வழி பெற வேண்டும் என்று விதிக்கப்பட்டவர்கள் அதன் மூலம் நேர்வழி பெற வேண்டும் என்பதற்காகவும், மற்றவர்களுக்கு எதிராக ஆதாரம் நிலைநாட்டப்பட வேண்டும் என்பதற்காகவும் அல்லாஹ் இதனை அருளினான்.\n\r\n\n\r\n\n\r\n(அளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.)\n\r\n\n\r\nகுறைஷிகளின் நிராகரிப்பிற்காக நபி (ஸல்) அவர்களுக்கு ஆறுதல்\n\r\n\n\r\n\n\r\nபின்னர் அல்லாஹ் தனது நபி (ஸல்) அவர்களுக்கு, அவர்களின் மக்களின் நிராகரிப்பிற்காக ஆறுதல் கூறி, அதனைப் பொறுமையுடன் சகித்துக் கொள்ளுமாறு கட்டளையிடுகிறான்.\n\r\n\n\r\n\n\r\nوَكَمْ أَرْسَلْنَا مِن نَّبِيٍّ فِى الاٌّوَّلِينَ\n\r\n\n\r\n\n\r\n(முன்னோர்களிடையே நாம் எத்தனையோ நபிமார்களை அனுப்பியிருக்கிறோம்.) அதாவது, முந்தைய சமுதாயத்தினரிடையே.\n\r\n\n\r\n\n\r\nوَمَا يَأْتِيهِم مِّنْ نَّبِىٍّ إِلاَّ كَانُواْ بِهِ يَسْتَهْزِءُونَ\n\r\n\n\r\n\n\r\n(அவர்களிடம் வந்த எந்த நபியையும் அவர்கள் ஏளனம் செய்யாமல் இருந்ததில்லை.) அதாவது, அவர்கள் அவரை நம்ப மறுத்துப் பரிகசித்தார்கள்.\n\r\n\n\r\n\n\r\nفَأَهْلَكْنَآ أَشَدَّ مِنْهُم بَطْشاً\n\r\n\n\r\n\n\r\n(இவர்களை விட அதிக வலிமை வாய்ந்தவர்களை நாம் அழித்தோம்.) இதன் பொருள்: 'முஹம்மதே (ஸல்)! உம்மை நிராகரிக்கும் இவர்களை விட அதிக வலிமை பெற்று, நம் தூதர்களை நிராகரித்த முந்தையவர்களை நாம் அழித்தோம்.' இது இந்த வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\n\n\r\nأَفَلَمْ يَسِيرُواْ فِى الاٌّرْضِ فَيَنظُرُواْ كَيْفَ كَانَ عَـقِبَةُ الَّذِينَ مِن قَبْلِهِمْ كَانُواْ أَكْـثَرَ مِنْهُمْ وَأَشَدَّ قُوَّةً\n\r\n\n\r\n\n\r\n(அவர்கள் பூமியில் பயணம் செய்து, தங்களுக்கு முன்னிருந்தவர்களின் முடிவு என்னவானது என்று பார்க்கவில்லையா? அவர்கள் இவர்களை விட எண்ணிக்கையில் அதிகமாகவும், வலிமையில் மிகைத்தவர்களாகவும் இருந்தார்கள்.) (40:82). இதுபோன்ற பல வசனங்கள் குர்ஆனில் உள்ளன.\n\r\n\n\r\n\n\r\nوَمَضَى مَثَلُ الاٌّوَّلِينَ\n\r\n\n\r\n\n\r\n(முன்னோர்களின் உதாரணம் கடந்து சென்றுவிட்டது.) முஜாஹித் (ரஹ்) அவர்கள் \"அவர்களின் வாழ்க்கை முறை\" என்றும், கத்தாதா (ரஹ்) அவர்கள் \"அவர்களின் தண்டனை\" என்றும் கூறினார்கள். மற்றவர்கள் \"அவர்களின் படிப்பினை\" என்று கூறினார்கள். அதாவது, பிற்காலத்தவர்களுக்கு அவர்களை ஒரு பாடமாக ஆக்கினோம்.\n\r\n\n\r\n\n\r\nفَجَعَلْنَـهُمْ سَلَفاً وَمَثَلاً لِّلاٌّخِرِينَ\n\r\n\n\r\n\n\r\n(மேலும் நாம் அவர்களை ஒரு முன்மாதிரியாகவும், பிற்கால சந்ததியினருக்கு ஓர் உதாரணமாகவும் ஆக்கினோம்.) (43:56);\n\r\n\n\r\n\n\r\nسُنَّةَ اللَّهِ الَّتِى قَدْ خَلَتْ فِى عِبَادِهِ\n\r\n\n\r\n\n\r\n(இதுவே அல்லாஹ்வின் அடியார்களிடம் அவன் கையாண்டு வந்த வழியாகும்.) (40:85).\n\r\n\n\r\n\n\r\nوَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلاً\n\r\n\n\r\n\n\r\n(மேலும், அல்லாஹ்வின் வழியில் எந்த மாற்றத்தையும் நீர் காணமாட்டீர்.) (33:62)\n\r\n\n\r\nஅல்லாஹ்வே படைப்பாளன் என்பதை இணைவைப்பாளர்கள் ஒப்புக்கொள்வதும், அதற்கான மேலதிக ஆதாரங்களும்\n\r\n\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: 'முஹம்மதே (ஸல்)! அல்லாஹ்வுக்கு இணைகற்பித்து மற்றவர்களை வணங்கும் இவர்களிடம் நீர் கேட்டால்...'\n\r\n\n\r\n\n\r\nمَّنْ خَلَقَ السَّمَـوَتِ وَالاٌّرْضَ لَيَقُولُنَّ خَلَقَهُنَّ الْعَزِيزُ الْعَلِيمُ\n\r\n\n\r\n\n\r\n(\"வானங்களையும் பூமியையும் படைத்தவன் யார்?\" என்று நீர் அவர்களிடம் கேட்டால், \"யாவற்றையும் மிகைத்தோனும், எல்லாம் அறிந்தவனுமே அவற்றைப் படைத்தான்\" என்று அவர்கள் நிச்சயமாகக் கூறுவார்கள்.) அதாவது, அனைத்தையும் படைத்தது அல்லாஹ் ஒருவனே என்பதை அவர்கள் ஒப்புக்கொள்கிறார்கள். இருப்பினும், அவனுடன் சிலைகளையும் போலிக் கடவுள்களையும் சேர்த்து வணங்குகிறார்கள்.\n\r\n\n\r\n\n\r\nالَّذِى جَعَلَ لَكُمُ الاٌّرْضَ مَهْداً\n\r\n\n\r\n\n\r\n(அவனே உங்களுக்காகப் பூமியை ஒரு விரிப்பாக ஆக்கினான்,) அதாவது, நீங்கள் அதில் பயணம் செய்யவும், அதன் மேல் நிற்கவும், உறங்கவும், நடக்கவும் வசதியாக அதனை உறுதியானதாக ஆக்கினான். அது தண்ணீரின் மேல் படைக்கப்பட்டிருந்தாலும், அது அசையாமல் இருக்க மலைகளைக் கொண்டு அல்லாஹ் அதனைப் பலப்படுத்தினான்.\n\r\n\n\r\n\n\r\nوَجَعَلَ لَكُمْ فِيهَا سُبُلاً\n\r\n\n\r\n\n\r\n(அதில் உங்களுக்காகப் பாதைகளையும் ஆக்கினான்,) அதாவது, மலைகளுக்கும் பள்ளத்தாக்குகளுக்கும் இடையே உள்ள வழிகள்.\n\r\n\n\r\n\n\r\nلَعَلَّكُمْ تَهْتَدُونَ\n\r\n\n\r\n\n\r\n(நீங்கள் நேர்வழி பெறுவதற்காக.) அதாவது, ஊர் ஊராகப் பயணம் செய்யும்போது வழிதவறாமல் இருப்பதற்காக.\n\r\n\n\r\n\n\r\nوَالَّذِى نَزَّلَ مِنَ السَّمَآءِ مَآءً بِقَدَرٍ\n\r\n\n\r\n\n\r\n(வானத்திலிருந்து குறிப்பிட்ட அளவில் மழையை இறக்குபவனும் அவனே,) அதாவது, உங்கள் பயிர்கள், பழங்கள் மற்றும் உங்கள் கால்நடைகளின் தேவைக்கு போதுமான அளவில்.\n\r\n\n\r\n\n\r\nفَأَنشَرْنَا بِهِ بَلْدَةً مَّيْتاً\n\r\n\n\r\n\n\r\n(பின்னர், அதன் மூலம் காய்ந்து கிடந்த பூமியை நாம் உயிர்ப்பிக்கிறோம்,) அதாவது, ஒரு தரிசு நிலம். மழை பெய்யும்போது அந்த நிலம் செழித்து வளருவதைப் போல, மனிதர்கள் மரித்த பிறகு மறுமை நாளில் அவர்களின் உடல்களை அல்லாஹ் உயிர்ப்பிப்பான் என்பதை இது சுட்டிக்காட்டுகிறது.\n\r\n\n\r\n\n\r\nكَذَلِكَ تُخْرَجُونَ\n\r\n\n\r\n\n\r\n(இவ்வாறே நீங்களும் எழுப்பப்படுவீர்கள்.) பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n\n\r\nوَالَّذِى خَلَقَ الأَزْوَجَ كُلَّهَا\n\r\n\n\r\n\n\r\n(அனைத்து ஜோடிகளையும் படைத்தவன் அவனே.) அதாவது, பூமியில் வளரும் தாவரங்கள், பயிர்கள், பழங்கள் மற்றும் விலங்குகள் என அனைத்திலும் உள்ள ஜோடிகள்.\n\r\n\n\r\n\n\r\nوَجَعَلَ لَكُمْ مِّنَ الْفُلْكِ\n\r\n\n\r\n\n\r\n(மேலும், நீங்கள் ஏறிப் பயணம் செய்யக் கப்பல்களையும் ஏற்படுத்தினான்,)\n\r\n\n\r\n\n\r\nوَالاٌّنْعَـمِ مَا تَرْكَبُونَ\n\r\n\n\r\n\n\r\n(நீங்கள் சவாரி செய்யும் கால்நடைகளையும் ஏற்படுத்தினான்.) அதாவது, அவன் அவற்றை உங்களுக்கு வசப்படுத்திக் கொடுத்து, அவற்றின் இறைச்சியை உண்பதற்கும், பால் அருந்துவதற்கும், அதன் முதுகில் சவாரி செய்வதற்கும் உங்களுக்கு எளிதாக்கினான். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n\n\r\nلِتَسْتَوُواْ عَلَى ظُهُورِهِ\n\r\n\n\r\n\n\r\n(அதன் முதுகின் மேல் நீங்கள் ஏறி அமர்வதற்காக,) அதாவது, வசதியாகவும் பாதுகாப்பாகவும் அமர,\n\r\n\n\r\n\n\r\nعَلَى ظُهُورِهِ\n\r\n\n\r\n\n\r\n(அவற்றின் முதுகுகளில்) அதாவது, இந்த வகையான விலங்குகளின் முதுகுகளில்.\n\r\n\n\r\n\n\r\nثُمَّ تَذْكُرُواْ نِعْمَةَ رَبِّكُمْ\n\r\n\n\r\n\n\r\n(பின்னர் உங்கள் இறைவனின் அருளை நீங்கள் நினைவுகூர வேண்டும்.) அதாவது, இந்த விலங்குகள் உங்களுக்கு வசப்படுத்திக் கொடுக்கப்பட்டிருப்பதை எண்ணிப் பார்க்க வேண்டும்.\n\r\n\n\r\n\n\r\nإِذَا اسْتَوَيْتُمْ عَلَيْهِ وَتَقُولُواْ سُبْحَـنَ الَّذِى سَخَّرَ لَنَا هَـذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ\n\r\n\n\r\n\n\r\n(அதன் மீது நீங்கள் அமர்ந்ததும்: \"எங்களுக்கு இதனை வசப்படுத்திக் கொடுத்தவன் தூயவன்; நாம் இதனை வசப்படுத்தும் வலிமை உடையவர்களாக இருக்கவில்லை\" என்று கூறுங்கள்.) அதாவது, 'அல்லாஹ் இந்த வசதிகளை நமக்குத் தந்திருக்காவிட்டால், நமது சொந்த பலத்தால் இதனை ஒருபோதும் செய்திருக்க முடியாது.' இப்னு அப்பாஸ் (ரழி), கத்தாதா (ரஹ்), அஸ்-ஸுத்தி மற்றும் இப்னு ஸைத் (ரஹ்) ஆகியோர் இக்கருத்தையே கூறினர்.\n\r\n\n\r\n\n\r\nوَإِنَّآ إِلَى رَبِّنَا لَمُنقَلِبُونَ\n\r\n\n\r\n\n\r\n(நிச்சயமாக நாம் நமது இறைவனிடமே திரும்பிச் செல்பவர்கள்.) அதாவது, 'மரணத்திற்குப் பிறகு நாம் அவனிடமே திரும்புவோம், நமது இறுதி இலக்கு அவனிடமே உள்ளது.' இவ்வுலகப் பயணங்கள் மறுமைப் பயணத்தை நினைவூட்டுகின்றன. உலகப் பயணத்திற்குத் தேவையானவை முக்கியம் என்பதைப் போல, மறுமைப் பயணத்திற்கு 'தக்வா' (இறையச்சம்) எனும் உணவு மிக முக்கியம் என்பதை அல்லாஹ் மற்றோர் இடத்தில் குறிப்பிடுகிறான்:\n\r\n\n\r\n\n\r\nوَتَزَوَّدُواْ فَإِنَّ خَيْرَ الزَّادِ التَّقْوَى\n\r\n\n\r\n\n\r\n(மேலும் பயணத்திற்குத் தேவையானவற்றை எடுத்துக்கொள்ளுங்கள்; ஆனால் சிறந்த தேவையானது தக்வா (இறையச்சம்) ஆகும்.) (2:197). உலக ஆடைகளைப் பற்றிய குறிப்பும் மறுமையின் ஆடைக்கு கவனத்தை ஈர்க்கப் பயன்படுத்தப்படுகிறது:\n\r\n\n\r\n\n\r\nوَرِيشًا وَلِبَاسُ التَّقْوَى ذَلِكَ خَيْرٌ\n\r\n\n\r\n\n\r\n(மேலும் ஓர் அலங்காரமாகவும்; தக்வாவின் (இறையச்சத்தின்) ஆடையே மிகச் சிறந்தது.) (7:26).\n\r\n\n\r\nஅல்லாஹ்வுக்குச் சந்ததி கற்பிக்கும் இணைவைப்பாளர்களுக்குக் கண்டனம்\n\r\n\n\r\n\n\r\nஇங்கு இணைவைப்பாளர்களின் பொய்களைப் பற்றி அல்லாஹ் பேசுகிறான். அவர்கள் விளைச்சலிலும் கால்நடைகளிலும் ஒரு பகுதியை அல்லாஹ்வுக்கும் ஒரு பகுதியைத் தங்கள் போலித் தெய்வங்களுக்கும் ஒதுக்கினார்கள். இதனை அல்லாஹ் ஸூரத்துல் அன்ஆமில் விவரித்துள்ளான்:\n\r\n\n\r\n\n\r\nوَجَعَلُواْ لِلَّهِ مِمَّا ذَرَأَ مِنَ الْحَرْثِ وَالاٌّنْعَامِ نَصِيباً فَقَالُواْ هَـذَا لِلَّهِ بِزَعْمِهِمْ وَهَـذَا لِشُرَكَآئِنَا فَمَا كَانَ لِشُرَكَآئِهِمْ فَلاَ يَصِلُ إِلَى اللَّهِ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَى شُرَكَآئِهِمْ سَآءَ مَا يَحْكُمُونَ\n\r\n\n\r\n\n\r\n(மேலும், அவன் படைத்த விளைநிலங்கள் மற்றும் கால்நடைகளிலிருந்து அல்லாஹ்வுக்கு ஒரு பங்கை அவர்கள் ஒதுக்கி, \"இது அல்லாஹ்வுக்குரியது\" என்றும், \"இது எங்கள் கூட்டாளிகளுக்குரியது\" என்றும் தங்கள் கூற்றுப்படி கூறுகிறார்கள். ஆனால், அவர்களின் கூட்டாளிகளின் பங்கு அல்லாஹ்வைச் சென்றடைவதில்லை; அதேசமயம் அல்லாஹ்வின் பங்கு அவர்களின் கூட்டாளிகளைச் சென்றடைகிறது! அவர்கள் தீர்ப்பளிக்கும் முறை மிகவும் தீயது!) (6:136). இதேபோல், தங்களுக்குப் பிடித்தமான ஆண் குழந்தைகளைத் தங்களுக்கு வைத்துக்கொண்டு, தாங்கள் இழிவாகக் கருதும் பெண் குழந்தைகளை அல்லாஹ்வுக்குச் சொந்தமாக்கினார்கள். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n\n\r\nأَلَكُمُ الذَّكَرُ وَلَهُ الاٍّنثَى - تِلْكَ إِذاً قِسْمَةٌ ضِيزَى\n\r\n\n\r\n\n\r\n(உங்களுக்கு ஆண்களும் அவனுக்குப் பெண்களுமா? இது மிகவும் அநியாயமான பங்கீடாகும்!) (53:21-22) மேலும் அல்லாஹ் இங்கே கூறுகிறான்:\n\r\n\n\r\n\n\r\nوَجَعَلُواْ لَهُ مِنْ عِبَادِهِ جُزْءًا إِنَّ الإنسَـنَ لَكَفُورٌ مُّبِينٌ\n\r\n\n\r\n\n\r\n(ஆயினும், அவனது அடியார்களில் சிலரை அவனுக்குரிய சந்ததியாக அவர்கள் ஆக்குகிறார்கள். நிச்சயமாக மனிதன் தெளிவான நன்றி கெட்டவனாக இருக்கிறான்!) பின்னர் அவன் கூறுகிறான்:\n\r\n\n\r\n\n\r\nأَمِ اتَّخَذَ مِمَّا يَخْلُقُ بَنَاتٍ وَأَصْفَـكُم بِالْبَنِينَ\n\r\n\n\r\n\n\r\n(தான் படைத்தவற்றிலிருந்து பெண் பிள்ளைகளை அவன் எடுத்துக்கொண்டு, உங்களுக்கு ஆண் பிள்ளைகளைத் தேர்ந்தெடுத்திருக்கிறானா?) இது அவர்களின் செயலை மிகக் கடுமையாகக் கண்டிப்பதாகும்.\n\r\n\n\r\n\n\r\nوَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحْمَـنِ مَثَلاً ظَلَّ وَجْهُهُ مُسْوَدّاً وَهُوَ كَظِيمٌ\n\r\n\n\r\n\n\r\n(அளவற்ற அருளாளனுக்கு எதனை அவர்கள் உவமையாகக் கூறுகிறார்களோ (பெண் குழந்தை), அதைப் பற்றி அவர்களில் ஒருவருக்கு நற்செய்தி கூறப்பட்டால், அவனது முகம் கறுத்துவிடுகிறது; அவன் துயரத்தால் நிரம்புகிறான்!) அதாவது, ஒரு பெண் குழந்தை பிறந்துவிட்டது என்று தெரிந்தால், அவன் அதனை வெறுக்கிறான். வெட்கத்தினால் மக்களிடமிருந்து மறைந்து கொள்கிறான். அல்லாஹ் கேட்கிறான்: அவர்கள் அவ்வளவு வெறுக்கும் ஒன்றை எவ்வாறு அல்லாஹ்வுக்குக் கற்பிக்கிறார்கள்?\n\r\n\n\r\n\n\r\nأَوَمَن يُنَشَّأُ فِى الْحِلْيَةِ وَهُوَ فِى الْخِصَامِ غَيْرُ مُبِينٍ\n\r\n\n\r\n\n\r\n(ஆபரணங்களில் வளர்க்கப்பட்டு, வாதத்தின்போது தன்னைத் தெளிவாக வெளிப்படுத்த முடியாத ஒரு படைப்பையா (அல்லாஹ்வுக்குக் கற்பிக்கிறார்கள்?)) அதாவது, பெண்கள் பொதுவாக ஆபரணங்களால் தங்களை அழகுபடுத்திக் கொள்கிறார்கள், மேலும் வாதத்தின்போது தங்களைத் தற்காத்துப் பேசும் வலிமை குறைந்தவர்களாகக் கருதப்படுகிறார்கள். இத்தகையவர்களை எவ்வாறு அல்லாஹ்வுக்குச் சொந்தமாக்க முடியும்?\n\r\n\n\r\n\n\r\nوَجَعَلُواْ الْمَلَـئِكَةَ الَّذِينَ هُمْ عِبَادُ الرَّحْمَـنِ إِنَـثاً\n\r\n\n\r\n\n\r\n(மேலும், அளவற்ற அருளாளனின் அடியார்களான வானவர்களை அவர்கள் பெண்களாகக் கருதுகிறார்கள்.) அல்லாஹ் இதனைக் கண்டித்துக் கேட்கிறான்:\n\r\n\n\r\n\n\r\nأَشَهِدُواْ خَلْقَهُمْ\n\r\n\n\r\n\n\r\n(அவர்கள் படைக்கப்பட்டபோது இவர்கள் சாட்சியாக இருந்தார்களா?)\n\r\n\n\r\n\n\r\nسَتُكْتَبُ شَهَـدَتُهُمْ\n\r\n\n\r\n\n\r\n(அவர்களின் சாட்சியம் பதிவு செய்யப்படும்,)\n\r\n\n\r\n\n\r\nوَيُسْـَلُونَ\n\r\n\n\r\n\n\r\n(மேலும் அவர்கள் விசாரிக்கப்படுவார்கள்!) மறுமை நாளில் அவர்கள் இது குறித்துக் கேள்வி கேட்கப்படுவார்கள். இது ஒரு கடுமையான எச்சரிக்கையாகும்.\n\r\n\n\r\n\n\r\nوَقَالُواْ لَوْ شَآءَ الرَّحْمَـنُ مَا عَبَدْنَـهُمْ\n\r\n\n\r\n\n\r\n(மேலும் அவர்கள் கூறினார்கள்: \"அளவற்ற அருளாளன் நாடியிருந்தால், நாங்கள் இவற்றை வணங்கியிருக்க மாட்டோம்.\") இவ்வாறு கூறுவதன் மூலம் அவர்கள் பல தவறுகளைச் செய்கிறார்கள்: முதலாவது: அல்லாஹ்வுக்குச் சந்ததி கற்பித்தது. இரண்டாவது: வானங்களைப் பெண்கள் எனக் கூறியது. மூன்றாவது: எந்த ஆதாரமும் இன்றி மனோ இச்சையின் அடிப்படையில் வணங்கியது. நான்காவது: தங்கள் அறியாமைக்கு அல்லாஹ்வின் விதியைக் காரணமாகக் காட்டியது. அல்லாஹ் தூதர்களை அனுப்பி, தன்னை மட்டுமே வணங்குமாறு கட்டளையிட்டுள்ளான். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n\n\r\nوَلَقَدْ بَعَثْنَا فِى كُلِّ أُمَّةٍ رَّسُولاً أَنِ اعْبُدُواْ اللَّهَ وَاجْتَنِبُواْ الْطَّـغُوتَ\n\r\n\n\r\n\n\r\n(நிச்சயமாக நாம் ஒவ்வொரு சமுதாயத்திலும் ஒரு தூதரை அனுப்பினோம் (அவர் அறிவித்தார்): \"அல்லாஹ்வை வணங்குங்கள், போலி தெய்வங்களைத் தவிர்ந்து கொள்ளுங்கள்.\") (16:36)\n\r\n\n\r\n\n\r\nوَاسْئلْ مَنْ أَرْسَلْنَا مِن قَبْلِكَ مِن رُّسُلِنَآ أَجَعَلْنَا مِن دُونِ الرَّحْمَـنِ ءَالِهَةً يُعْبَدُونَ\n\r\n\n\r\n\n\r\n(மேலும், உமக்கு முன்னர் நாம் அனுப்பிய தூதர்களிடம் கேளும்: \"அளவற்ற அருளாளனைத் தவிர வணங்கப்படுவதற்குரிய கடவுள்களை நாம் எப்போதாவது நியமித்தோமா?\") (43:45) மேலும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n\n\r\nمَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ\n\r\n\n\r\n\n\r\n(அவர்களுக்கு அது பற்றி எந்த அறிவும் இல்லை.)\n\r\n\n\r\n\n\r\nوَإِنْ هُمْ إِلاَّ يَخْرُصُونَ\n\r\n\n\r\n\n\r\n(அவர்கள் பொய் சொல்வதைத் தவிர வேறொன்றும் செய்வதில்லை!)\n\r\n\n\r\n\n\r\nمَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلاَّ يَخْرُصُونَ\n\r\n\n\r\n\n\r\n(அவர்களுக்கு அது பற்றி எந்த அறிவும் இல்லை. அவர்கள் வெறும் யூகத்தையே பேசுகிறார்கள்!) முஜாஹித் (ரஹ்) அவர்கள் கூறினார்கள்: \"அவர்கள் அல்லாஹ்வின் வல்லமையை உணருவதில்லை.\"\n\r\n\n\r\nஇணைவைப்பாளர்களிடம் எந்த ஆதாரமும் இல்லை\n\r\n\n\r\n\n\r\nஅல்லாஹ்வை விடுத்து மற்றவர்களை வணங்குவதற்கு இணைவைப்பாளர்களிடம் எந்த ஆதாரமும் இல்லை என்பதற்காக அல்லாஹ் அவர்களைக் கண்டிக்கிறான்.\n\r\n\n\r\n\n\r\nأَمْ ءَاتَيْنَـهُمْ كِتَـباً مِّن قَبْلِهِ\n\r\n\n\r\n\n\r\n(அல்லது இதற்கு முன்னர் நாம் அவர்களுக்கு ஏதேனும் ஒரு வேதத்தைக் கொடுத்திருக்கிறோமா?)\n\r\n\n\r\n\n\r\nفَهُم بِهِ مُسْتَمْسِكُونَ\n\r\n\n\r\n\n\r\n(அதனை அவர்கள் உறுதியாகப் பற்றிக் கொண்டிருக்கிறார்களா?) நிலைமை அப்படியில்லை. இது இந்த வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\n\n\r\nأَمْ أَنزَلْنَا عَلَيْهِمْ سُلْطَـناً فَهُوَ يَتَكَلَّمُ بِمَا كَانُواْ بِهِ يُشْرِكُونَ\n\r\n\n\r\n\n\r\n(அல்லது, நாம் அவர்களுக்கு ஓர் அதிகாரத்தை (ஒரு வேதத்தை) அருளியிருக்கிறோமா, அது அவர்கள் இணைவைப்பதைப் பற்றிப் பேசுகிறதா?) (30:35).\n\r\n\n\r\n\n\r\nبَلْ قَالُواْ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى ءَاثَـرِهِم مُّهْتَدُونَ\n\r\n\n\r\n\n\r\n(இல்லை! மாறாக அவர்கள் கூறுகிறார்கள்: \"நாங்கள் எங்கள் மூதாதையரை ஒரு வழியில் கண்டோம்; நாங்கள் அவர்களின் அடிச்சுவடுகளையே பின்பற்றுகிறோம்.\") அதாவது, தங்கள் முன்னோர்களைக் கண்மூடித்தனமாகப் பின்பற்றுவதைத் தவிர இவர்களிடம் வேறு எந்த ஆதாரமும் இல்லை. 'உம்மத்' என்ற வார்த்தை இதேபோல மற்றோர் இடத்திலும் பயன்படுத்தப்பட்டுள்ளது:\n\r\n\n\r\n\n\r\nإِنَّ هَـذِهِ أُمَّتُكُمْ أُمَّةً وَاحِدَةً\n\r\n\n\r\n\n\r\n(நிச்சயமாக, உங்கள் இந்த மார்க்கம் (உம்மத்) ஒரே மார்க்கமாகும்.) (23:52).\n\r\n\n\r\n\n\r\nمُّهْتَدُونَ\n\r\n\n\r\n\n\r\n(நாங்கள் வழிகாட்டப்படுகிறோம்) என்பது அவர்களின் வெறும் கூற்று மட்டுமே. தூதர்களை நிராகரித்த முந்தைய சமுதாயத்தினர் கூறியதையே இவர்களும் கூறுகிறார்கள்.\n\r\n\n\r\n\n\r\nكَذَلِكَ مَآ أَتَى الَّذِينَ مِن قَبْلِهِمْ مِّن رَّسُولٍ إِلاَّ قَالُواْ سَـحِرٌ أَوْ مَجْنُونٌ - أَتَوَاصَوْاْ بِهِ بَلْ هُمْ قَوْمٌ طَـغُونَ\n\r\n\n\r\n\n\r\n(இவ்வாறே, இவர்களுக்கு முன் இருந்தவர்களிடம் எந்தத் தூதரும் வரவில்லை, ஆனால் அவர்கள், \"ஒரு சூனியக்காரர் அல்லது ஒரு பைத்தியக்காரர்!\" என்று கூறினர். அவர்கள் இந்தப் பொய்ச் சொல்லை ஒருவருக்கொருவர் விட்டுச் சென்றார்களா? இல்லை, அவர்கள் தாங்களாகவே வரம்பு மீறும் மக்களாக இருக்கிறார்கள்!) (51:52-53).\n\r\n\n\r\n\n\r\nوَكَذَلِكَ مَآ أَرْسَلْنَا مِن قَبْلِكَ فِى قَرْيَةٍ مِّن نَّذِيرٍ إِلاَّ قَالَ مُتْرَفُوهَآ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى ءَاثَـرِهِم مُّقْتَدُونَ\n\r\n\n\r\n\n\r\n(இதேபோல், உமக்கு முன்னர் நாம் எந்த ஊருக்கும் ஓர் எச்சரிக்கையாளரை அனுப்பவில்லை, ஆனால் அங்குள்ள செல்வந்தர்கள் கூறினார்கள்: \"நாங்கள் எங்கள் மூதாதையரை ஒரு வழியில் கண்டோம், நிச்சயமாக நாங்கள் அவர்களின் அடிச்சுவடுகளையே பின்பற்றுவோம்.\") பின்னர் அவன் கூறுகிறான்:\n\r\n\n\r\n\n\r\nقُلْ\n\r\n\n\r\n\n\r\n(கூறுவீராக) -- 'முஹம்மதே (ஸல்), இந்த இணைவைப்பாளர்களிடம் --'\n\r\n\n\r\n\n\r\nأَوَلَوْ جِئْتُكُمْ بِأَهْدَى مِمَّا وَجَدتُّمْ عَلَيْهِ ءَابَآءَكُمْ قَالُواْ إِنَّا بِمَآ أُرْسِلْتُمْ بِهِ كَـفِرُونَ\n\r\n\n\r\n\n\r\n(\"உங்கள் மூதாதையர் பின்பற்றியதை விடச் சிறந்த வழிகாட்டுதலை நான் உங்களுக்குக் கொண்டு வந்தாலும் கூடவா?\" அதற்கு அவர்கள்: \"நிச்சயமாக, நீங்கள் எதனுடன் அனுப்பப்பட்டிருக்கிறீர்களோ அதனை நாங்கள் நிராகரிக்கிறோம்\" என்று கூறினர்.) அவர்கள் சத்தியத்தை உணர்ந்தாலும், தங்கள் ஆணவத்தினால் அதைப் பின்பற்ற மாட்டார்கள்.\n\r\n\n\r\n\n\r\nفَانتَقَمْنَا مِنْهُمْ\n\r\n\n\r\n\n\r\n(எனவே நாம் அவர்களிடம் பழிவாங்கினோம்) அதாவது, நிராகரித்த அந்தத் தேசங்களை நாம் அழித்தோம்.\n\r\n\n\r\n\n\r\nفَانظُرْ كَيْفَ كَانَ عَـقِبَةُ الْمُكَذِّبِينَ\n\r\n\n\r\n\n\r\n(சத்தியத்தை மறுத்தவர்களின் முடிவு என்னவானது என்பதை நீர் பாரும்.) அல்லாஹ் அவர்களை எவ்வாறு அழித்தான், நம்பிக்கையாளர்களை எவ்வாறு காப்பாற்றினான் என்பதைப் பாரும்.\n\r\n\n\r\nஇப்ராஹீம் (அலை) அவர்களின் ஏகத்துவப் பிரகடனம்\n\r\n\n\r\n\n\r\nஅல்லாஹ் தனது அடியாரும், தூதரும், உற்ற நண்பருமான இப்ராஹீம் (அலை) அவர்களைப் பற்றி நமக்குக் கூறுகிறான். குறைஷிகள் தாங்கள் இவருடைய வழியில் நடப்பதாகவே கூறிக்கொண்டனர். அவர் தன் தந்தையிடமும் மக்களிடமும் கூறினார்:\n\r\n\n\r\n\n\r\nوَإِذْ قَالَ إِبْرَهِيمُ لاًّبِيهِ وَقَوْمِهِ إِنَّنِى بَرَآءٌ مِّمَّا تَعْبُدُونَ - إِلاَّ الَّذِى فَطَرَنِى فَإِنَّهُ سَيَهْدِينِ وَجَعَلَهَا كَلِمَةً بَـقِيَةً فِى عَقِبِهِ\n\r\n\n\r\n\n\r\n(\"நிச்சயமாக, நீங்கள் வணங்குபவற்றிலிருந்து நான் விலகிக் கொள்கிறேன்; என்னைப் படைத்தவனைத் தவிர. நிச்சயமாக அவன் எனக்கு நேர்வழி காட்டுவான்.\" மேலும் அவர் அதனைத் தனது சந்ததியினரிடையே நிலைத்திருக்கும் ஒரு வார்த்தையாக ஆக்கினார்.) அந்த வார்த்தை என்பது 'லா இலாஹ இல்லல்லாஹ்' (அல்லாஹ்வைத் தவிர வேறு இறைவனில்லை) என்பதாகும்.\n\r\n\n\r\n\n\r\nلَعَلَّهُمْ يَرْجِعُونَ\n\r\n\n\r\n\n\r\n(அவர்கள் இதன் பக்கம் திரும்பி வரக்கூடும் என்பதற்காக.) இப்னு அப்பாஸ் (ரழி) மற்றும் பலர் \"இந்த வார்த்தையைச் சொல்பவர்கள் இன்றும் அவரது சந்ததியினரில் இருக்கிறார்கள்\" என்று விளக்கமளித்தனர்.\n\r\n\n\r\nமக்கா வாசிகள் தூதரைப் புறக்கணித்ததும், அதற்கு அவருடைய பதிலும்\n\r\n\n\r\n\n\r\nமேலும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n\n\r\nبَلْ مَتَّعْتُ هَـؤُلاَءِ\n\r\n\n\r\n\n\r\n(மாறாக, இவர்களுக்கு நான் வசதிகளைக் கொடுத்தேன்) அதாவது, இணைவைப்பாளர்களுக்கு,\n\r\n\n\r\n\n\r\nوَءَابَآءَهُمْ\n\r\n\n\r\n\n\r\n(இவர்களுடைய மூதாதையர்களுக்கும்) அவர்கள் நீண்ட காலம் வழிகேட்டில் வாழ்ந்தார்கள்.\n\r\n\n\r\n\n\r\nحَتَّى جَآءَهُمُ الْحَقُّ وَرَسُولٌ مُّبِينٌ\n\r\n\n\r\n\n\r\n(சத்தியமும் தெளிவான தூதரும் அவர்களிடம் வரும்வரை.)\n\r\n\n\r\n\n\r\nوَلَمَّا جَآءَهُمُ الْحَقُّ قَالُواْ هَـذَا سِحْرٌ وَإِنَّا بِهِ كَـفِرُونَ\n\r\n\n\r\n\n\r\n(சத்தியம் அவர்களிடம் வந்தபோது, அவர்கள் கூறினார்கள்: \"இது சூனியம், நாங்கள் இதனை நிராகரிக்கிறோம்.\") அவர்கள் ஆணவத்தாலும் பொறாமையாலும் அதனைப் புறக்கணித்தனர்.\n\r\n\n\r\n\n\r\nوَقَالُواْ\n\r\n\n\r\n\n\r\n(மேலும் அவர்கள் கூறுகிறார்கள்) அல்லாஹ் அருளிய செய்திக்கு எதிர்ப்பு தெரிவித்து,\n\r\n\n\r\n\n\r\nلَوْلاَ نُزِّلَ هَـذَا الْقُرْءَانُ عَلَى رَجُلٍ مِّنَ الْقَرْيَتَيْنِ عَظِيمٍ\n\r\n\n\r\n\n\r\n(இந்தக் குர்ஆன் மக்கா அல்லது தாயிஃப் ஆகிய இரு நகரங்களில் உள்ள ஏதேனும் ஒரு பெரிய மனிதர் மீது இறக்கப்பட்டிருக்கக் கூடாதா?) ஏன் உலகியலில் செல்வாக்கு மிக்க ஒருவரிடம் இது அருளப்படவில்லை என்பது அவர்களின் வாதம். குறைஷிகள் இதன் மூலம் அல்-வலீத் பின் அல்-முகீரா அல்லது உர்வா பின் மஸ்ஊத் அத்-தகஃபீயைக் குறிப்பிட்டனர். அல்லாஹ் இதற்கு இவ்வாறு பதிலளித்தான்:\n\r\n\n\r\n\n\r\nأَهُمْ يَقْسِمُونَ رَحْمَةَ رَبِّكَ\n\r\n\n\r\n\n\r\n(உமது இறைவனின் அருளை இவர்களா பங்கிடுகிறார்கள்?) இந்த விஷயத்தில் அவர்களுக்கு எந்த அதிகாரமும் இல்லை; அதனைத் தீர்மானிப்பது அல்லாஹ்வே. வஹீயை (இறைச்செய்தியை) யாரிடம் அனுப்ப வேண்டும் என்பதை அல்லாஹ் நன்கு அறிவான். அவன் உள்ளத்தாலும் ஆன்மாவாலும் தூய்மையானவர்களிடமே அதனை அருளுகிறான். பின்னர் அல்லாஹ் தனது படைப்புகளிடையே வாழ்வாதாரத்தையும் மற்ற பலங்களையும் எவ்வாறு பிரித்துக் கொடுத்துள்ளான் என்பதைச் சுட்டிக்காட்டுகிறான்:\n\r\n\n\r\n\n\r\nنَحْنُ قَسَمْنَا بَيْنَهُمْ مَّعِيشَتَهُمْ فِى الْحَيَوةِ الدُّنْيَا\n\r\n\n\r\n\n\r\n(நாமே இவ்வுலக வாழ்க்கையில் அவர்களிடையே வாழ்வாதாரத்தைப் பங்கிட்டுள்ளோம்,)\n\r\n\n\r\n\n\r\nلِّيَتَّخِذَ بَعْضُهُم بَعْضاً سُخْرِيّاً\n\r\n\n\r\n\n\r\n(அவர்களில் சிலர் மற்றவர்களைத் தங்கள் வேலையில் பயன்படுத்திக் கொள்ளும் பொருட்டு.) ஒருவருக்கு மற்றவர் தேவைப்படுகிறார் என்பதே இதன் பொருள்.\n\r\n\n\r\n\n\r\nوَرَحْمَةُ رَبِّكَ خَيْرٌ مِّمَّا يَجْمَعُونَ\n\r\n\n\r\n\n\r\n(ஆனால் உமது இறைவனின் அருள் அவர்கள் சேகரித்து வைத்திருப்பவற்றை விடச் சிறந்தது.) அதாவது, அல்லாஹ்வின் அருள் அவர்கள் வைத்திருக்கும் உலகச் செல்வங்களை விட மிகவும் மேலானது.\n\r\n\n\r\nசெல்வம் என்பது இறைப் பொருத்தத்தின் அடையாளம் அல்ல\n\r\n\n\r\n\n\r\nوَلَوْلاَ أَن يَكُونَ النَّاسُ أُمَّةً وَحِدَةً\n\r\n\n\r\n\n\r\n(மனிதர்கள் அனைவரும் (செல்வத்திற்காக) ஒரே மாதிரியான நிராகரிப்பாளர்களாக ஆகிவிடுவார்கள் என்ற அச்சம் இல்லையென்றால்...) அதாவது, செல்வம் கிடைப்பதாலேயே அல்லாஹ் ஒருவரை நேசிக்கிறான் என்று மக்கள் தவறாக எண்ணி, செல்வத்திற்காக அனைவரும் நிராகரிப்பில் ஒன்றுபட்டு விடுவார்கள் என்ற நிலை இல்லையென்றால், நிராகரிப்பாளர்களுக்கு அவர்கள் கற்பனை செய்ய முடியாத அளவு உலக வசதிகளை நாம் வழங்கியிருப்போம்.\n\r\n\n\r\n\n\r\nلَّجَعَلْنَا لِمَن يَكْفُرُ بِالرَّحْمَـنِ لِبُيُوتِهِمْ سُقُفاً مِّن فِضَّةٍ وَمَعَارِجَ\n\r\n\n\r\n\n\r\n(அளவற்ற அருளாளனை நிராகரிப்பவர்களுக்கு, அவர்களின் வீடுகளுக்கு வெள்ளி மேற்கூரைகளையும், வெள்ளிப் படிக்கட்டுகளையும் நாம் ஆக்கியிருப்போம்.)\n\r\n\n\r\n\n\r\nعَلَيْهَا يَظْهَرُونَ\n\r\n\n\r\n\n\r\n(அதன் மீது அவர்கள் ஏறுவார்கள்.) மேலும் அவர்களின் வீடுகளுக்கு வெள்ளி வாசல்கள், வெள்ளிச் சிம்மாசனங்கள் மற்றும் தங்க அலங்காரங்களையும் நாம் வழங்கியிருப்போம்.\n\r\n\n\r\n\n\r\nوَإِن كُلُّ ذَلِكَ لَمَّا مَتَـعُ الْحَيَوةِ الدُّنْيَا\n\r\n\n\r\n\n\r\n(ஆயினும், இவை அனைத்தும் இவ்வுலக வாழ்க்கையின் அற்ப இன்பமே தவிர வேறில்லை.) இவை அனைத்தும் அல்லாஹ்விடம் அற்பமானவை. நிராகரிப்பாளர்களின் நற்செயல்களுக்குரிய கூலியை அல்லாஹ் இவ்வுலகிலேயே சுகபோகங்களாக வழங்கிவிடுகிறான். அதனால் மறுமையில் அவர்களுக்கு நன்மைகள் எதுவும் இருக்காது.\n\r\n\n\r\n\n\r\nநபியவர்கள் கூறினார்கள்: \"அல்லாஹ்விடம் இவ்வுலகிற்கு ஒரு கொசுவின் இறக்கை அளவு மதிப்பு இருந்திருக்குமானால், அவன் ஒரு நிராகரிப்பாளனுக்கு ஒரு மிடறு தண்ணீர் கூட கொடுத்திருக்க மாட்டான்\" (திர்மிதி).\n\r\n\n\r\n\n\r\nوَالاٌّخِرَةُ عِندَ رَبِّكَ لِلْمُتَّقِينَ\n\r\n\n\r\n\n\r\n(மறுமை உமது இறைவனிடம் இறையச்சம் உடையவர்களுக்கு மட்டுமே உரியது.) உமர் (ரழி) அவர்கள் நபியவர்களின் எளிய வாழ்வைக் கண்டு அழுதபோது, நபி (ஸல்) அவர்கள் கூறினார்கள்: \"அவர்களுக்கு இவ்வுலகம் இருப்பதும், நமக்கு மறுமை இருப்பதும் உமக்கு மகிழ்ச்சியளிக்கவில்லையா?\"\n\r\n\n\r\nஅர்-ரஹ்மானின் நினைவை விட்டு விலகுபவருக்கு ஷைத்தானே தோழன்\n\r\n\n\r\n\n\r\nوَمَن يَعْشُ\n\r\n\n\r\n\n\r\n(யார் குருட்டுத்தனமாக விலகுகிறாரோ) அதாவது, யார் வேண்டுமென்றே புறக்கணிக்கிறாரோ,\n\r\n\n\r\n\n\r\nعَن ذِكْرِ الرَّحْمَـنِ\n\r\n\n\r\n\n\r\n(அளவற்ற அருளாளனின் நினைவை விட்டு,) 'அல்-அஷா' என்பது பார்வைக் குறைபாட்டைக் குறிக்கும். இங்கு இதன் பொருள் அகப்பார்வை பலவீனமடைவதாகும்.\n\r\n\n\r\n\n\r\nنُقَيِّضْ لَهُ شَيْطَاناً فَهُوَ لَهُ قَرِينٌ\n\r\n\n\r\n\n\r\n(அவருக்கு நாம் ஒரு ஷைத்தானைத் தோழனாக நியமிக்கிறோம்.) இது அல்லாஹ்வின் மற்ற வசனங்களைப் போன்றது.\n\r\n\n\r\n\n\r\nوَإِنَّهُمْ لَيَصُدُّونَهُمْ عَنِ السَّبِيلِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ حَتَّى إِذَا جَآءَنَا\n\r\n\n\r\n\n\r\n(நிச்சயமாக அந்த ஷைத்தான்கள் அவர்களை நேர்வழியை விட்டுத் தடுப்பார்கள், இருப்பினும் அவர்கள் தாங்கள் நேர்வழியில் இருப்பதாகவே எண்ணிக் கொள்வார்கள். இறுதியில் அவன் நம்மிடம் வரும்போது...) அந்த நபர் தன் தோழனான ஷைத்தானைப் பார்த்து வருந்துவான்.\n\r\n\n\r\n\n\r\nقَالَ يلَيْتَ بَيْنِي وَبَيْنَكَ بُعْدَ الْمَشْرِقَيْنِ فَبِئْسَ الْقَرِينُ\n\r\n\n\r\n\n\r\n(அவன் கூறுவான்: \"எனக்கும் உனக்கும் இடையே இரண்டு கிழக்குகளுக்கு இடையிலான தொலைவு இருந்திருக்கக் கூடாதா! நீ மிகவும் கெட்ட தோழன்!\") பின்னர் அல்லாஹ் கூறுவான்:\n\r\n\n\r\n\n\r\nوَلَن يَنفَعَكُمُ الْيَوْمَ إِذ ظَّلَمْتُمْ أَنَّكُمْ فِى الْعَذَابِ مُشْتَرِكُونَ\n\r\n\n\r\n\n\r\n(நீங்கள் அநீதி இழைத்ததால், இன்று நீங்கள் தண்டனையில் கூட்டாளிகளாக இருப்பது உங்களுக்கு எந்தப் பயனும் தராது.) அதாவது, நரகத்தில் நீங்கள் ஒன்றாக இருப்பது உங்கள் வேதனையைக் குறைக்காது.\n\r\n\n\r\n\n\r\nأَفَأَنتَ تُسْمِعُ الصُّمَّ أَوْ تَهْدِى الْعُمْىَ وَمَن كَانَ فِى ضَلَـلٍ مُّبِينٍ\n\r\n\n\r\n\n\r\n(செவிடர்களை நீர் கேட்கச் செய்ய முடியுமா? அல்லது குருடர்களையும் தெளிவான வழிகேட்டில் இருப்பவர்களையும் நீர் நேர்வழிப்படுத்த முடியுமா?) நபியே! உமது கடமை செய்தியை எட்டவைப்பதே தவிர அவர்களை நேர்வழிப்படுத்துவது அல்ல.\n\r\n\n\r\nநபியின் எதிரிகள் மீது அல்லாஹ்வின் பழிவாங்கல் நிச்சயமாக நிகழும்\n\r\n\n\r\n\n\r\nமேலும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n\n\r\nفَإِمَّا نَذْهَبَنَّ بِكَ فَإِنَّا مِنْهُم مُّنتَقِمُونَ\n\r\n\n\r\n\n\r\n(உம்மை நாம் மரணிக்கச் செய்தாலும், நிச்சயமாக நாம் அவர்களைப் பழிவாங்குவோம்.) அதாவது, அவர்கள் தண்டிக்கப்படுவது உறுதி.\n\r\n\n\r\n\n\r\nأَوْ نُرِيَنَّكَ الَّذِى وَعَدْنَـهُمْ فَإِنَّا عَلَيْهِمْ مُّقْتَدِرُونَ\n\r\n\n\r\n\n\r\n(அல்லது நாம் அவர்களுக்கு அச்சுறுத்தியதை உமக்குக் காட்டினாலும், நாம் அவர்கள் மீது முழு ஆற்றல் உடையவர்கள்.) அல்லாஹ் தனது தூதரை மரணிக்கச் செய்வதற்கு முன், அவருடைய எதிரிகள் தாழ்த்தப்படுவதையும் அவருக்கு வெற்றியையும் வழங்கினான்.\n\r\n\n\r\nகுர்ஆனை உறுதியாகப் பற்றுதல்\n\r\n\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n\n\r\nفَاسْتَمْسِكْ بِالَّذِى أُوحِىَ إِلَيْكَ إِنَّكَ عَلَى صِرَطٍ مُّسْتَقِيمٍ\n\r\n\n\r\n\n\r\n(ஆகவே, உமக்கு வஹீயாக அருளப்படுவதை நீர் உறுதியாகப் பற்றிப் பிடித்துக் கொள்ளும். நிச்சயமாக நீர் நேரான பாதையில் இருக்கிறீர்.) குர்ஆனை உறுதியாகப் பிடித்துக் கொள்ளுமாறு இது ஏவுகிறது.\n\r\n\n\r\n\n\r\nوَإِنَّهُ لَذِكْرٌ لَّكَ وَلِقَوْمِكَ\n\r\n\n\r\n\n\r\n(நிச்சயமாக இது உமக்கும் உமது மக்களுக்கும் ஒரு கண்ணியமாகும்.) ஏனெனில் இது அவர்களின் மொழியில் அருளப்பட்டது.\n\r\n\n\r\n\n\r\nوَسَوْفَ تُسْـَلُونَ\n\r\n\n\r\n\n\r\n(விரைவில் நீங்கள் விசாரிக்கப்படுவீர்கள்.) இந்த குர்ஆனை எவ்வாறு பின்பற்றினீர்கள் என்பது குறித்து நீங்கள் கேட்கப்படுவீர்கள்.\n\r\n\n\r\n\n\r\nوَاسْئلْ مَنْ أَرْسَلْنَا مِن قَبْلِكَ مِن رُّسُلِنَآ أَجَعَلْنَا مِن دُونِ الرَّحْمَـنِ ءَالِهَةً يُعْبَدُونَ\n\r\n\n\r\n\n\r\n(உமக்கு முன்னர் நாம் அனுப்பிய தூதர்களிடம் கேளும்: \"அளவற்ற அருளாளனைத் தவிர வணங்கப்படும் தெய்வங்களை நாம் எப்போதாவது நியமித்தோமா?\") அனைத்து தூதர்களும் அல்லாஹ் ஒருவனையே வணங்குமாறு அழைப்பு விடுத்தனர் என்பதே இதன் பொருள்.\n\r\n\n\r\nமூஸா (அலை) அவர்கள் ஃபிர்அவ்னிடம் அனுப்பப்பட்டது\n\r\n\n\r\n\n\r\nஅல்லாஹ் தன் தூதர் மூஸா (அலை) அவர்களை ஃபிர்அவ்னிடம் பல அத்தாட்சிகளுடன் அனுப்பினான். ஆனால் அவர்கள் ஏளனம் செய்தனர். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n\n\r\nوَمَا نُرِيِهِم مِّنْ ءَايَةٍ إِلاَّ هِىَ أَكْبَرُ مِنْ أُخْتِهَا\n\r\n\n\r\n\n\r\n(நாம் அவர்களுக்குக் காட்டிய ஒவ்வோர் அத்தாட்சியும் அதன் முந்தையதை விடப் பெரியதாகவே இருந்தது.) இருப்பினும் அவர்கள் திருந்தவில்லை. துன்பம் வரும்போதெல்லாம், \"அறிஞரே! (சூனியக்காரரே!) உமது இறைவனிடம் எங்களுக்காகப் பிரார்த்தனை செய்யும்\" என்று மூஸா (அலை) அவர்களிடம் கெஞ்சினர். ஆனால் துன்பம் நீங்கியதும் வாக்குறுதியை மீறினர்.\n\r\n\n\r\nஃபிர்அவ்ன் தன் மக்களிடம் ஆற்றிய உரையும், அவனுக்குக் கிடைத்த தண்டனையும்\n\r\n\n\r\n\n\r\nஃபிர்அவ்ன் தன் மக்களின் முன் மார்தட்டினான்:\n\r\n\n\r\n\n\r\nأَلَيْسَ لِى مُلْكُ مِصْرَ وَهَـذِهِ الاٌّنْهَـرُ تَجْرِى مِن تَحْتِى\n\r\n\n\r\n\n\r\n(இந்த எகிப்தின் ஆட்சி எனக்குரியதல்லவா? எனக்குக் கீழே ஆறுகள் ஓடவில்லையா?) அவன் மூஸா (அலை) அவர்களைப் பலவீனமானவர் என்றும், சரியாகப் பேசத் தெரியாதவர் என்றும் இழிவுபடுத்தினான்.\n\r\n\n\r\n\n\r\nفَاسْتَخَفَّ قَوْمَهُ فَأَطَاعُوهُ\n\r\n\n\r\n\n\r\n(இவ்வாறு அவன் தன் மக்களை முட்டாளாக்கினான்; அவர்களும் அவனுக்குக் கீழ்ப்படிந்தார்கள்.) அவர்கள் பாவம் செய்பவர்களாக இருந்ததால் அவனுக்குக் கீழ்ப்படிந்தனர்.\n\r\n\n\r\n\n\r\nفَلَمَّآ ءَاسَفُونَا انتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَـهُمْ أَجْمَعِينَ\n\r\n\n\r\n\n\r\n(அவர்கள் நம்மைக் கோபப்படுத்தியபோது, நாம் அவர்களைப் பழிவாங்கி அனைவரையும் மூழ்கடித்தோம்.)\n\r\n\n\r\n\n\r\nفَجَعَلْنَـهُمْ سَلَفاً وَمَثَلاً لِّلاٌّخِرِينَ\n\r\n\n\r\n\n\r\n(மேலும், நாம் அவர்களை முற்கால முன்னுதாரணமாகவும், பிற்காலத்தவருக்கு ஓர் எடுத்துக்காட்டாகவும் ஆக்கினோம்.)\n\r\n\n\r\nமர்யமுடைய மகனை குறைஷிகள் இழிவாகக் கருதியதும், அல்லாஹ்விடம் அவருடைய தகுதியும்\n\r\n\n\r\n\n\r\nகுறைஷிகள் நபியவர்களிடம் விதண்டாவாதம் செய்தனர்:\n\r\n\n\r\n\n\r\nوَلَمَّا ضُرِبَ ابْنُ مَرْيَمَ مَثَلاً إِذَا قَوْمُكَ مِنْهُ يَصِدُّونَ\n\r\n\n\r\n\n\r\n(மர்யமுடைய மகன் ஓர் உதாரணமாகக் கூறப்பட்டபோது, உமது மக்கள் ஆரவாரம் செய்கின்றனர்.) நபியவர்கள் \"நீங்களும் நீங்கள் வணங்குபவையும் நரகத்தின் எரிபொருள்கள்\" (21:98) என்ற வசனத்தை ஓதியபோது, குறைஷிகள் \"அப்படியானால் கிறிஸ்தவர்கள் வணங்கும் ஈஸாவும் நரகிற்குச் செல்வாரா?\" என்று தர்க்கம் செய்தனர்.\n\r\n\n\r\n\n\r\nஅல்லாஹ் இதற்குப் பதிலளிக்கிறான்: ஈஸா (அலை) அவர்கள் அல்லாஹ்வின் கண்ணியமிக்க அடியார். குறைஷிகள் விதண்டாவாதத்திற்காகவே இதனைப் பேசுகின்றனர்.\n\r\n\n\r\n\n\r\nإِنْ هُوَ إِلاَّ عَبْدٌ أَنْعَمْنَا عَلَيْهِ وَجَعَلْنَـهُ مَثَلاً لِّبَنِى إِسْرَءِيلَ\n\r\n\n\r\n\n\r\n(அவர் ஓர் அடியாரே தவிர வேறில்லை. நாம் அவர் மீது நமது அருளைப் பொழிந்தோம், மேலும் இஸ்ரவேலின் சந்ததியினருக்கு அவரை ஓர் உதாரணமாக ஆக்கினோம்.)\n\r\n\n\r\n\n\r\nوَلَوْ نَشَآءُ لَجَعَلْنَا مِنكُمْ مَّلَـئِكَةً فِى الاٌّرْضِ يَخْلُفُونَ\n\r\n\n\r\n\n\r\n(மேலும், நாம் நாடியிருந்தால் உங்களுக்குப் பதிலாக பூமியில் வானவர்களை நாம் படைத்திருப்போம்.)\n\r\n\n\r\n\n\r\nوَإِنَّهُ لَعِلْمٌ لِّلسَّاعَةِ\n\r\n\n\r\n\n\r\n(மேலும் நிச்சயமாக அவர் (ஈஸா) மறுமை நாளுக்கான ஓர் அடையாளமாவார்.) அவர் உலகிற்கு மீண்டும் இறங்குவது இறுதி நாள் நெருங்குவதைக் குறிக்கும்.\n\r\n\n\r\n\n\r\nفَلاَ تَمْتَرُنَّ بِهَا وَاتَّبِعُونِ هَـذَا صِرَطٌ مُّسْتَقِيمٌ\n\r\n\n\r\n\n\r\n(ஆகவே, அது குறித்து சந்தேகம் கொள்ளாதீர்கள். மேலும் என்னைப் பின்பற்றுங்கள்! இதுவே நேரான வழியாகும்.)\n\r\n\n\r\n\n\r\nوَقَالُواْ ءَأَالِهَتُنَا خَيْرٌ أَمْ هُوَ\n\r\n\n\r\n\n\r\n(அவர்கள் கேட்கிறார்கள்: \"எங்கள் தெய்வங்கள் சிறந்தவையா அல்லது அவரா?\")\n\r\n\n\r\n\n\r\nمَا ضَرَبُوهُ لَكَ إِلاَّ جَدَلاَ بَلْ هُمْ قَوْمٌ خَصِمُونَ\n\r\n\n\r\n\n\r\n(அவர்கள் இந்த உதாரணத்தை உமக்குக் கூறியது தர்க்கத்திற்காகவே தவிர வேறில்லை. இல்லை! மாறாக, அவர்கள் சண்டையிடும் மக்களாவர்.)\n\r\n\n\r\n\n\r\nஈஸா (அலை) அவர்களும் \"அல்லாஹ்வே என் இறைவனும் உங்கள் இறைவனுமாவான்; அவனையே வணங்குங்கள்\" என்றே கூறினார்கள்.\n\r\n\n\r\n\n\r\nفَاخْتَلَفَ الاٌّحْزَابُ مِن بَيْنِهِمْ فَوَيْلٌ لِّلَّذِينَ ظَلَمُواْ مِنْ عَذَابِ يَوْمٍ أَلِيمٍ\n\r\n\n\r\n\n\r\n(ஆனால் அவர்களிடையே இருந்த பிரிவினர் கருத்து வேறுபாடு கொண்டனர். ஆகவே அநீதி இழைத்தவர்களுக்கு வேதனையான தண்டனை உண்டு.)\n\r\n\n\r\nமறுமை நாள் திடீரென வரும்; நண்பர்களிடையே பகைமை உண்டாகும்\n\r\n\n\r\n\n\r\nإِلاَّ السَّاعَةَ أَن تَأْتِيَهُمْ بَغْتَةً وَهُمْ لاَ يَشْعُرُونَ\n\r\n\n\r\n\n\r\n(அவர்கள் உணராத நிலையில் திடீரென அவர்களிடம் மறுமை நாள் வருவதை மட்டுமே அவர்கள் எதிர்பார்க்கிறார்களா?)\n\r\n\n\r\n\n\r\nالاٌّخِلاَءُ يَوْمَئِذٍ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلاَّ الْمُتَّقِينَ\n\r\n\n\r\n\n\r\n(இறையச்சம் உடையவர்களைத் தவிர, மற்ற நண்பர்கள் அந்நாளில் ஒருவருக்கொருவர் எதிரிகளாகி விடுவார்கள்.) அல்லாஹ்வுக்காக ஏற்பட்ட நட்பு மட்டுமே அன்று நீடிக்கும்.\n\r\n\n\r\nஇறையச்சம் உடையவர்களுக்கு நற்செய்தியும், சுவர்க்கமும்\n\r\n\n\r\n\n\r\nஇறையச்சம் உடையவர்களுக்குக் கூறப்படும்:\n\r\n\n\r\n\n\r\nيعِبَادِ لاَ خَوْفٌ عَلَيْكُمُ الْيَوْمَ وَلاَ أَنتُمْ تَحْزَنُونَ\n\r\n\n\r\n\n\r\n(என் அடியார்களே! இந்நாளில் உங்களுக்கு எந்தப் பயமும் இல்லை, நீங்கள் கவலைப்படவும் மாட்டீர்கள்.)\n\r\n\n\r\n\n\r\nالَّذِينَ ءَامَنُواْ بِـَايَـتِنَا وَكَانُواْ مُسْلِمِينَ\n\r\n\n\r\n\n\r\n(யார் நமது வசனங்களை நம்பி, முற்றிலும் கீழ்ப்படிந்து (முஸ்லிம்களாக) இருந்தார்களோ அவர்களுக்கு இது கூறப்படும்.)\n\r\n\n\r\n\n\r\nادْخُلُواْ الْجَنَّةَ أَنتُمْ وَأَزْوَجُكُمْ تُحْبَرُونَ\n\r\n\n\r\n\n\r\n(நீங்களும் உங்கள் இணையர்களும் மகிழ்ச்சியுடன் சுவர்க்கத்தில் நுழையுங்கள்.)\n\r\n\n\r\n\n\r\nஅங்கு அவர்களுக்குத் தங்கத் தட்டுகளும் கோப்பைகளும் கொண்டு வரப்படும்.\n\r\n\n\r\n\n\r\nوَفِيهَا مَا تَشْتَهِي الْأَنْفُسُ وَتَلَذُّ الاٌّعْيُنُ وَأَنتُمْ فِيهَا خَـلِدُونَ\n\r\n\n\r\n\n\r\n(அங்கு மனங்கள் விரும்புவதும் கண்கள் கண்டு மகிழ்வதும் இருக்கும். நீங்கள் அங்கு என்றென்றும் தங்கியிருப்பீர்கள்.)\n\r\n\n\r\n\n\r\nوَتِلْكَ الْجَنَّةُ الَّتِى أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ\n\r\n\n\r\n\n\r\n(நீங்கள் செய்து கொண்டிருந்த நற்செயல்களின் காரணமாகவே இந்தச் சுவர்க்கத்திற்கு நீங்கள் வாரிசாக்கப்பட்டுள்ளீர்கள்.)\n\r\n\n\r\nகுற்றவாளிகளுக்குக் காத்திருக்கும் தண்டனை\n\r\n\n\r\n\n\r\nஇறையச்சம் உடையவர்களின் நிலையைத் தொடர்ந்து குற்றவாளிகளின் நிலை விவரிக்கப்படுகிறது.\n\r\n\n\r\n\n\r\nإِنَّ الْمُجْرِمِينَ فِى عَذَابِ جَهَنَّمَ خَـلِدُونَ لاَ يُفَتَّرُ عَنْهُمْ وَهُمْ فِيهِ مُبْلِسُونَ\n\r\n\n\r\n\n\r\n(நிச்சயமாக குற்றவாளிகள் நரக வேதனையில் என்றென்றும் தங்கியிருப்பார்கள். அது அவர்களுக்கு ஒருபோதும் இலேசாக்கப்பட மாட்டாது. அவர்கள் அங்கு விரக்தியுற்ற நிலையில் இருப்பார்கள்.)\n\r\n\n\r\n\n\r\nوَمَا ظَلَمْنَـهُمْ وَلَـكِن كَانُواْ هُمُ الظَّـلِمِينَ\n\r\n\n\r\n\n\r\n(நாம் அவர்களுக்கு அநீதி இழைக்கவில்லை, ஆனால் அவர்களே அநீதி இழைத்தவர்களாக இருந்தார்கள்.)\n\r\n\n\r\n\n\r\nوَنَادَوْاْ يَامَـلِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ\n\r\n\n\r\n\n\r\n(அவர்கள் நரகக் காவலரான 'மாலிக்'கை அழைத்து, \"உமது இறைவன் எங்களை முடித்துவிடட்டும்\" என்று கதறுவார்கள்.)\n\r\n\n\r\n\n\r\nقَالَ إِنَّكُمْ مَّـكِثُونَ\n\r\n\n\r\n\n\r\n(அதற்கு அவர், \"நிச்சயமாக நீங்கள் இங்கேயே தங்க வேண்டியவர்கள்\" என்று கூறுவார்.)\n\r\n\n\r\n\n\r\nஉண்மை உங்களிடம் வந்தபோது நீங்கள் அதனை வெறுத்ததே இதற்குக் காரணம்.\n\r\n\n\r\n\n\r\nأَمْ أَبْرَمُواْ أَمْراً فَإِنَّا مُبْرِمُونَ\n\r\n\n\r\n\n\r\n(அல்லது அவர்கள் ஏதேனும் சூழ்ச்சி செய்கிறார்களா? நாமும் சூழ்ச்சி செய்கிறோம்.)\n\r\n\n\r\n\n\r\nأَمْ يَحْسَبُونَ أَنَّا لاَ نَسْمَعُ سِرَّهُمْ وَنَجْوَهُم بَلَى وَرُسُلُنَا لَدَيْهِمْ يَكْتُبُونَ\n\r\n\n\r\n\n\r\n(அவர்களுடைய இரகசியங்களையும் ஆலோசனைகளையும் நாம் கேட்பதில்லை என்று அவர்கள் நினைக்கிறார்களா? ஆம், நாம் கேட்கிறோம்; நம் தூதர்கள் (வானவர்கள்) அவற்றை உடனுக்குடன் பதிவு செய்கிறார்கள்.)\n\r\n\n\r\nஅல்லாஹ்வுக்குச் சந்ததி இல்லை\n\r\n\n\r\n\n\r\nقُلْ إِن كَانَ لِلرَّحْمَـنِ وَلَدٌ فَأَنَاْ أَوَّلُ الْعَـبِدِينَ\n\r\n\n\r\n\n\r\n(நபியே! நீர் கூறும்: \"அளவற்ற அருளாளனுக்கு ஒரு மகன் இருந்திருப்பின், அவனை வணங்குவோரில் நானே முதன்மையானவனாக இருந்திருப்பேன்.\") அதாவது, அல்லாஹ்வுக்குச் சந்ததி இருப்பது சாத்தியமே இல்லை.\n\r\n\n\r\n\n\r\nسُبْحَـنَ رَبِّ السَّمَـوَتِ وَالاٌّرْضِ رَبِّ الْعَرْشِ عَمَّا يَصِفُونَ\n\r\n\n\r\n\n\r\n(வானங்கள் மற்றும் பூமியின் இறைவன், அர்ஷின் இறைவன் தூய்மையானவன்! அவர்கள் வர்ணிக்கும் பண்புகளை விட்டு அவன் உயர்ந்தவன்.)\n\r\n\n\r\n\n\r\nفَذَرْهُمْ يَخُوضُواْ وَيَلْعَبُواْ حَتَّى يُلَـقُواْ يَوْمَهُمُ الَّذِى يُوعَدُونَ\n\r\n\n\r\n\n\r\n(ஆகவே அவர்களை விட்டுவிடும்; அவர்கள் வாக்களிக்கப்பட்ட நாளைச் சந்திக்கும் வரை வீண் தர்க்கத்திலும் விளையாட்டிலும் மூழ்கிக் கிடக்கட்டும்.)\n\r\n\n\r\n\n\r\nوَهُوَ الَّذِى فِى السَّمآءِ إِلَـهٌ وَفِى الاٌّرْضِ إِلَـهٌ وَهُوَ الْحَكِيمُ الْعَلِيمُ\n\r\n\n\r\n\n\r\n(வானத்திலும் இறைவனாக இருப்பவன் அவனே; பூமியிலும் இறைவனாக இருப்பவன் அவனே. அவன் ஞானமிக்கவன்; எல்லாம் அறிந்தவன்.)\n\r\n\n\r\n\n\r\nوَتَبَارَكَ الَّذِى لَهُ مُلْكُ السَّمَـوَتِ وَالاٌّرْضِ وَمَا بَيْنَهُمَا وَعِندَهُ عِلْمُ السَّاعَةِ وَإِلَيْهِ تُرْجَعُونَ\n\r\n\n\r\n\n\r\n(வானங்கள் மற்றும் பூமியின் ஆட்சியும், அவற்றுக்கு இடையே உள்ள அனைத்தும் எவனுக்குச் சொந்தமோ அவன் பாக்கியம் மிக்கவன். அவனிடமே மறுமை பற்றிய அறிவு உள்ளது. அவனிடமே நீங்கள் அனைவரும் கொண்டு வரப்படுவீர்கள்.)\n\r\n\n\r\n\n\r\nوَلاَ يَمْلِكُ الَّذِينَ يَدْعُونَ مِن دُونِهِ الشَّفَـعَةَ إِلاَّ مَن شَهِدَ بِالْحَقِّ وَهُمْ يَعْلَمُونَ\n\r\n\n\r\n\n\r\n(அல்லாஹ்வையன்றி அவர்கள் யாரை அழைக்கிறார்களோ அவர்களுக்குப் பரிந்துரை செய்யும் அதிகாரம் இல்லை; சத்தியத்தை அறிந்து சாட்சி சொன்னவர்களைத் தவிர.)\n\r\n\n\r\n\n\r\nوَلَئِن سَأَلْتَهُم مَّنْ خَلَقَهُمْ لَيَقُولُنَّ اللَّهُ فَأَنَّى يُؤْفَكُونَ\n\r\n\n\r\n\n\r\n(அவர்களைப் படைத்தது யார் என்று நீர் கேட்டால், \"அல்லாஹ்\" என்றே கூறுவார்கள். அவ்வாறிருக்க அவர்கள் எங்கு திசை திருப்பப்படுகிறார்கள்?)\n\r\n\n\r\nநபியின் முறையீடு\n\r\n\n\r\n\n\r\nوَقِيلِهِ يَا رَبِّ إِنَّ هَـؤُلاَءِ قَوْمٌ لاَّ يُؤْمِنُونَ\n\r\n\n\r\n\n\r\n(நபியின் முறையீடு: \"என் இறைவா! நிச்சயமாக இவர்கள் நம்பிக்கை கொள்ளாத மக்களாக இருக்கிறார்கள்.\")\n\r\n\n\r\n\n\r\nفَاصْفَحْ عَنْهُمْ وَقُلْ سَلَامٌ فَسَوْفَ يَعْلَمُونَ\n\r\n\n\r\n\n\r\n(ஆகவே நீர் அவர்களைப் புறக்கணித்துவிட்டு \"ஸலாம்\" (சாந்தி உண்டாகட்டும்) என்று கூறும்; விரைவில் அவர்கள் அறிந்து கொள்வார்கள்.) இது அவர்களுக்குரிய எச்சரிக்கையாகும். இது, ஜிஹாத் (புனிதப் போர்) கடமையாக்கப்படுவதற்கு முன்னர் அருளப்பட்டதாகும். பின்னர் அல்லாஹ் அவர்களை எதிர்த்துப் போரிடுமாறு கட்டளையிட்டான்; நபியவர்களுக்குப் பின்னர் வெற்றி கிடைத்தது, மக்கள் திரள் திரளாக இஸ்லாத்தில் இணைந்தனர். அல்லாஹ்வே மிக அறிந்தவன். இத்துடன் ஸூரத்துல் அஸ்-ஸுக்ருஃபின் தஃப்ஸீர் நிறைவு பெற்றது."}}};})(self);
